INSERT INTO dbo.LexiconType (TypeId, TypeName) VALUES
    (1, 'Vocabulary'),
    (2, 'Idiom'),
    (3, 'Phrasal Verb');
INSERT INTO dbo.LexiconGroup (GroupId, Theme, Description) VALUES
    (1, 'Education', 'Words commonly seen in education topics'),
    (2, 'Everyday Idioms', 'Common daily expressions'),
    (3, 'Daily Life', 'Common everyday phrasal verbs'),
    (4, 'All Idioms ', 'A collection of all idioms'),
    (5, 'All Phrasal Verbs', 'A collection of all phrasal verbs');
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1, '(I''ll) tell you what', 'used to suggest a plan:', 'I''ll tell you what - we''ll split the money between us.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (2, '(I''m so hungry), I could eat a horse', 'used to say that you are extremely hungry', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (3, '(I''m) just saying', 'used when you are making a criticism or complaint, to make it less likely to offend someone:', 'I''m just saying I think it could have been done a little more carefully, that''s all.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4, 'I''m just saying', 'used when saying something negative or something that other people might not like or might find unusual, without trying to defend or give reasons for what you say:', 'I don''t want to insult anybody, but I''m just saying ...
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5, '(I''m) pleased to meet you', 'a polite way of greeting someone when you meet them for the first time', '', 'idiom', 'A2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6, '(I) beg your pardon', 'could you please repeat what you just said:', '"Are you feeling better?" "I beg your pardon?" "I said: Are you feeling better?"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7, '(I) beg your pardon', '(I) beg your pardon also means I am sorry:', 'I beg your pardon – can I just get past you?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8, '(I) tell you what', 'I will make you this offer:', 'I tell you what, we’ll pay for your plane ticket.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9, '(I) told you (so)!', 'said when something bad happens after you warned someone that it would happen', '', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (10, '(Oh) boy!', 'used to express excitement or say something with emphasis:', 'Boy, that was good cake!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (11, '(a) penny for your thoughts', 'said when you want to know what another person is thinking, usually because they have been quiet for a while', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (12, '(a) sort of', 'used to describe something approximately:', 'It''s a sort of pale orange colour.', 'idiom', 'B1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (13, 'sort of', 'in some way or to some degree:', 'I was sort of hoping to leave early today.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (14, '(a) word to the wise', 'used when you are about to give a piece of advice or information to someone in an informal way:', 'A word to the wise: always check opening hours in advance.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (15, '(all) hot and bothered', 'worried or angry, and sometimes physically hot', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (16, '(all) in one piece', 'not damaged:', 'The radio had been stolen, but otherwise we got the car back (all) in one piece.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (17, '(all) in one piece', 'as a single thing and not divided into smaller pieces:', 'We want to sell the business in one piece.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (18, '(all) rolled into one', 'combined:', 'He is a businessman, community leader, and family man all rolled into one.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (19, '(almost) burst a blood vessel', 'to become very angry about something:', 'Mum almost burst a blood vessel when I told her what happened.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (20, '(and) all the rest', 'used at the end of a phrase or list to refer to other things or people that belong to the same set or group and that you have not had time to mention:', 'Karen and Laura and all the rest are coming to dinner tonight.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (21, '(and) no messing', 'said to emphasize that you want something to be done:', 'I want you both in bed by nine o''clock, no messing!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (22, '(as) ... as hell', 'used to emphasize a description of an unpleasant characteristic:', 'She''s really quite unpleasant about other people and she''s as mean as hell.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (23, '(as) blind as a bat', 'unable to see well:', 'I''m as blind as a bat without my glasses.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (24, '(as) bold as brass', 'with extreme confidence or without the respect or politeness people usually show:', 'She marched into the store, as bold as brass, and demanded her money back.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (25, '(as) clean as a (new) pin', 'extremely clean', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (26, '(as) clear as a bell', 'very easy to hear:', 'Clear as a bell, from the back of the theatre came a child''s voice saying, "I want to go home".', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (27, '(as) clear as day', 'very easy to understand:', 'The instructions were as clear as day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (28, '(as) clear as day', 'certain:', 'It''s as clear as day that the government is going to win the election.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (29, '(as) clear as mud', 'very difficult to understand:', 'His instructions were as clear as mud.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (30, '(as) cool as a cucumber', 'very calm or very calmly, especially when this is surprising:', 'She walked in as cool as a cucumber, as if nothing had happened.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (31, '(as) dead as a doornail', 'completely dead:', 'The fox in the road was as dead as a doornail.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (32, '(as) deaf as a post', 'completely deaf:', 'Grandad''s as deaf as a post.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (33, '(as) easy as pie', 'very easy:', 'For Judy, getting a pilot’s license was easy as pie – she seemed to have a natural talent for it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (34, '(as) easy as pie/ABC/anything/falling off a log', 'extremely easy', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (35, '(as) flat as a pancake', 'very level:', 'In some parts of the West, the land is as flat as a pancake .', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (36, '(as) free as a bird', 'completely free to do as you want', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (37, '(as) keen as mustard', 'very eager and interested in everything', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (38, '(as) large as life', 'used as a way of describing a person you see, and are surprised to see, in a particular place:', 'I looked up from my newspaper and there he was, as large as life, Tim Trotter!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (39, '(as) light as a feather', 'very light', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (40, '(as) long as your arm', 'very long:', 'There was a list of complaints as long as your arm.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (41, '(as) mad as a hatter/March hare', 'extremely silly or stupid', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (42, '(as) man to man', 'If two men talk (as) man to man, they talk seriously and honestly together on an equal level.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (43, '(as) pleased as Punch', 'very pleased:', 'She was as pleased as Punch about the news.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (44, '(as) proud as Lucifer', 'extremely proud or satisfied with yourself:', 'Jones was once described by a friend as being as proud as Lucifer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (45, '(as) proud as a peacock', 'extremely proud:', 'He returns about three hours later looking as proud as a peacock as he carefully backs his big red car in the driveway.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (46, '(as) regular as clockwork', 'never late or always at the same time:', 'In this country the trains are regular as clockwork.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (47, '(as) slow as molasses', 'extremely slow:', 'The browser was slow as molasses, but it worked.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (48, '(as) stiff/straight as a ramrod', 'very straight:', 'The old lady''s back is still as straight as a ramrod.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (49, '(as) straight as a die', 'extremely straight:', 'The road runs (as) straight as a die for 50 or so miles.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (50, '(as) straight as a die', 'completely honest:', 'She''s as straight as a die, I can trust her to tell me what she''s really thinking.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (51, '(as) sure as eggs is eggs', 'for certain:', 'One day he''ll realize that I was right, as sure as eggs is eggs.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (52, '(as) sure as hell', 'used for emphasis:', 'There better be another way in - I''m sure as hell not climbing up all those steps.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (53, '(as) thick as two short planks', 'very stupid:', 'He''s a very skilled football player but he''s as thick as two short planks.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (54, '(as) tough as nails', 'strong and very determined:', 'She is a warm and friendly person, but she is also as tough as nails at work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (55, '(as) tough as old boots', 'very strong, and not easily made weaker:', 'He might be in his eighties but he''s tough as old boots, that man.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (56, '(as) tough as old boots', 'Tough food is very difficult to cut or eat.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (57, '(as) white as a sheet', 'If someone is (as) white as a sheet, their face is very pale, usually because of illness, shock, or fear.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (58, '(at) daggers drawn', 'If two people, countries, etc. are at daggers drawn, they are in a state of extreme unfriendliness and do not trust each other:', 'The two sides have been at daggers drawn for some months now with no sign of improvement in relations.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (59, '(at) full blast', 'as loud as possible:', 'He had the television on at full blast.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (60, '(at) full speed/tilt/pelt', 'as fast as possible:', 'He was driving at full speed down the motorway when it happened.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (61, '(at) full steam', '(of a steam engine) using the greatest possible amount of steam, in order to travel as fast as possible, or work as hard as possible:', 'At full steam, the ship could move from the tropics to the Arctic in a matter of weeks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (62, '(at) full steam', 'working as hard as possible:', 'The company is pressing ahead at full steam with development of the electric car.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (63, '(at) full stretch', 'working as hard as possible, so that you could not manage to do any more:', 'The emergency services are working at full stretch today to cope with the accident.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (64, '(at) full throttle', 'moving or progressing as fast as possible:', 'She was roaring up the freeway at full throttle.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (65, '(back) on your feet', 'healthy again:', 'The doctor said he’d be back on his feet again soon.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (66, '(do you) know/see what I''m saying?', 'used to ask if someone understands or agrees with you, especially if you have not expressed yourself very clearly:', 'It''s just the best feeling, know what I''m saying?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (67, '(do you) see what I mean?', 'used to ask if someone understands what you are trying to explain:', 'You have to hold the bar down while you lock it – do you see what I mean?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (68, '(do) you feel me?', 'do you understand what I am saying?:', 'He addresses the men in the audience, saying, "Come on, fellas. Do you feel me?"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (69, '(down) in the dumps', 'unhappy:', 'She''s a bit down in the dumps because she failed one of her exams.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (70, '(down) to the last ...', 'including all of the thing mentioned, used to emphasize what you are saying:', 'The model of the village is accurate down to the last detail.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (71, '(every) now and then/again', 'sometimes, but not very often:', 'We meet up for lunch now and then, but not as often as we used to.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (72, '(from) cover to cover', 'read all the way through from the beginning to the end:', 'I read that book from cover to cover in one day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (73, '(from) hour to hour', 'If something changes from hour to hour, it is different every hour.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (74, '(from) soup to nuts', 'from the beginning to the end; including everything:', 'This is how you do a film campaign from soup to nuts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (75, '(from) under your nose', 'used about something bad that happens in an obvious way but in a way that you do not notice or cannot prevent:', 'She stole the shoes from under the assistant''s nose.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (76, '(give a/the) thumbs down', 'a sign of disapproval or opposition:', 'We applied for a loan, but the bank gave us the thumbs down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (77, '(give a/the) thumbs up', 'a sign of approval or support:', 'Legislators gave the thumbs up to new tax credits.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (78, '(go and) take a running jump', 'said to someone when you want them to go away and stop annoying you:', 'He kept following me around, so I just told him to go and take a running jump.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (79, '(great) with child', '(very) pregnant', '', 'idiom', '', 'old use', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (80, '(hard) on the heels of something', 'close behind or soon after something:', 'A second mistake followed hard on the heels of the first one.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (81, '(hot) on someone’s heels', 'following closely behind someone:', 'The two men were running with a police officer hot on their heels.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (82, '(how much) do you want to bet?', 'said in answer to something that someone has said, meaning that you are certain that they are wrong:', '"Surely she won''t be late this time." "How much do you want to bet?"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (83, '(if you''ve) seen one, you''ve seen them all', 'used to say that all the things of a particular type are very similar:', 'If you''ve seen one episode of that show, you''ve seen them all.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (84, '(in) any way, shape, or form', 'in any way at all:', 'I have never been involved in any way, shape, or form with criminal activities.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (85, '(in) between times', 'during the periods between the separate events mentioned:', 'If you only go to the supermarket once a month, what do you do (in) between times?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (86, '(in) care of', 'at the address of:', 'You can write me in care of my grandmother.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (87, '(in) the middle of nowhere', 'far away from any towns and cities and where few people live:', 'He lives in a tiny house in the middle of nowhere.', 'idiom', 'B2', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (88, '(it''s) about time', '(it is) past the time when something should have happened:', 'It’s about time she got a job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (89, '(it''s) business as usual', 'said when things are continuing as they always do, despite a difficult situation', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (90, '(it''s) just as well (that)', 'it is a good thing:', 'It''s beginning to rain - it''s just as well that we brought our umbrellas.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (91, '(it''s) too bad that', 'it is sad that:', 'It''s too bad that more parents don''t know how much reading to children can help them.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (92, '(it’s a) good thing', 'it is lucky:', 'Good thing they didn’t go camping last weekend – the weather was terrible.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (93, '(it’s) high time', 'infml (it is) past the time when something should have happened:', 'It’s high time you got that bad knee looked at by a doctor!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (94, '(just) around the corner', 'not far away, or going to happen soon:', 'There''s a great restaurant just around the corner.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (95, '(just) between you and me', 'used to tell someone that what you are about to say should be kept secret:', 'Between you and me, I don''t think she''ll stay in this job very long.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (96, '(just) in the nick of time', 'at the last possible moment:', 'She fell in the river and was rescued in the nick of time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (97, '(just) one of those things', 'said to mean that there was no way of planning to avoid something:', 'The road was blocked, so we missed the meeting - it was just one of those things.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (98, '(just) to be on the safe side', 'being especially careful in order to avoid something unpleasant:', 'I''m sure it won''t rain, but I''ll take an umbrella (just) to be on the safe side (= to be ready if it does rain).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (99, '(just) you wait', 'used as a way of threatening someone:', 'Just you wait, Maria, till I get my hands on you!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (100, '(let''s) say', 'used to introduce a suggestion or possible example of something:', 'Try and finish the work by, let''s say, Friday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (101, '(like) water off a duck''s back', 'criticisms of or warnings to a particular person that have no effect on that person:', 'I''ve told him that he''s heading for trouble, but he doesn''t listen - it''s just water off a duck''s back.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (102, '(not) make heads or tails of something', 'to not be able to understand something at all:', 'We couldn’t make heads or tails of your directions.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (103, '(oh my) God!', 'used to emphasize how surprised, angry, shocked, etc. you are:', 'My God, what a mess!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (104, '(oh) Lord', 'used to express surprise, shock, or worry:', 'Oh Lord! I''ve forgotten the tickets!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (105, '(only) time will tell', 'used to say that the truth or a result will only be known in the future after events have happened:', 'Only time will tell whether we made the right decision.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (106, '(out) in left field', 'strange, unusual, or completely wrong:', 'I wouldn''t vote for him – his ideas are way out in left field.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (107, '(out) in the middle of nowhere', 'in a place that is far from where most people live:', 'They spend their vacations, out in the middle of nowhere, in a cabin in the woods.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (108, '(right) down to', 'even including the following small or unimportant things or people:', 'Amalie was dressed completely in black, right down to black lipstick and a black earring.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (109, '(right) here and now', 'in this place at this time:', 'We''re going to solve this problem right here and now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (110, '(right) on cue', 'as if planned to happen exactly at that moment:', 'We were just about to say "I do" when, right on cue, my little cousin started crying.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (111, '(right) on the money', 'exact or correct:', 'Her prediction was right on the money.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (112, '(right/just) around the corner', 'very close to the place that you are:', 'There’s a deli around the corner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (113, '(right/just) around the corner', 'A time or event that is just around the corner is coming very soon:', 'It''s still cold today, but spring is just around the corner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (114, '(something) to go', 'packed or wrapped so that you can take it with you:', 'I’d like a cheeseburger and a strawberry milk shake to go, please.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (115, '(somewhere) in the region of', 'approximately:', 'The temperature yesterday was somewhere in the region of 30°.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (116, '(still) going strong', 'to still be successful after having existed for a long time:', 'After one hundred years of service as a public institution, the state university system is still going strong.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (117, '(still) going strong', 'Someone who is still going strong is healthy even though the person is old or has been ill:', 'He’s still going strong at 94!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (118, '(straight) from the horse''s mouth', 'If you hear something (straight) from the horse''s mouth, you hear it from the person who has direct personal knowledge of it.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (119, '(stuck) in a rut', 'too fixed in one particular type of job, activity, method, etc., and needing to change:', 'I need to change jobs - after 15 years here I feel I''m (stuck) in a rut.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (120, '(that''s) a likely story!', 'said when you do not believe something:', '"He said he bought them all very cheaply from some guy he knows." "That''s a likely story!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (121, '(that''s) too bad', 'I am sorry:', '"I failed the test." "Oh, that''s too bad – can you take it again?"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (122, '(that''s) too bad', 'Too bad is sometimes used to say you do not care:', '“He says he''s sorry and he won''t do it again.” “Too bad – he''s not getting another chance with me.”', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (123, '(that''s) your hard luck', 'said if you think that it is someone''s own fault that something bad has happened to them:', 'Well, if you missed the presentation because you couldn''t be bothered to turn up on time, that''s your hard luck!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (124, '(that) Monday morning feeling', 'the way people feel after the weekend when they do not want to go to work or school:', 'I''ve got that Monday morning feeling.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (125, '(the) chances are', 'it is likely:', 'Chances are (that) they''ll be late anyway.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (126, '(the) shit hits the fan', 'When the shit hits the fan or when the shit flies, a situation suddenly causes a lot of trouble for someone:', 'I don''t want to be here when the shit hits the fan.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (127, '(the) word is', 'used to refer to something that has been reported but not officially stated:', 'The word is (that) more hostages will be released over the next few weeks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (128, '(the) word is/gets out', 'a piece of news is known, especially if it was secret or if it will cause changes:', 'The word is out that superstar Candice is to marry towards the end of this year.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (129, '(the/a pot of gold at) the end of the rainbow', 'something that is very attractive that you will probably never achieve:', 'At the moment, finding a good plumber is like finding a pot of gold at the end of the rainbow.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (130, '(there is) one born every minute', 'used to say that there are many people who are stupid or easy to deceive:', '"Too good to be true" deals are currently all over the Internet, providing proof that there is one born every minute.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (131, '(there''s) no two ways about it.', 'something that you say in order to emphasize that something is true:', 'Without that drug I''d have died - there''s no two ways about it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (132, '(to give) credit where credit''s due', 'an expression that means that you should praise someone who deserves it, although you might dislike some things about them:', 'I don''t especially like the woman but, credit where credit''s due, she''s very efficient.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (133, '(to) give the devil his due', 'said when you admit that someone you do not like or admire does have some good qualities:', 'I don''t like the man but - give the devil his due - he works incredibly hard.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (134, '(up) to the hilt', 'Something that is done (up) to the hilt is done completely and without any limits:', 'The government is already borrowing up to the hilt.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (135, '(upon) my word!', 'used to express surprise or to emphasize something:', 'My word! Is that Jenkins on the roof?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (136, '(well) I''ll be damned!', 'an expression of complete surprise:', 'She''s marrying a man who she met two months ago? - Well, I''ll be damned!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (137, '(well) what do you know!', 'something you say when you are surprised by a piece of information. This phrase is often used humorously to mean the opposite:', 'So they''re getting married, are they? Well, what do you know!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (138, '(you can) depend on/upon it', 'you can be certain:', 'You haven''t heard the last of this, depend upon it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (139, '(you) do the math', 'used for telling someone that when they consider all the facts and figures, something cannot succeed or be possible', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (140, '(you) do the maths', 'used for telling someone that when they consider all the facts and figures, something cannot succeed or be possible', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (141, '(you) know what I mean', 'used when you think that the person listening understands and so you do not need to say any more:', 'You''ve got to give him a chance, you know what I mean?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (142, '(you) mark my words!', 'something that you say when you tell someone about something that you are certain will happen in the future:', 'He''ll cause trouble - you mark my words!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (143, '(your) every move', 'everything that you do:', 'I''d hate to be someone really famous with the press reporting my every move.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (144, '(your) every word', 'all the things that you say:', 'She''s such a fascinating lecturer - I was hanging on to her every word.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (145, '(your) mileage may vary', 'used for saying that someone might have a different experience in a particular situation :', 'I actually love working from home, but your mileage may vary.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (146, '... at that', 'in addition to that:', 'It''s too expensive, and probably out-of-date at that.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (147, '...and counting', 'used to say that a time, distance, number, etc. is still increasing or is more than a particular amount:', 'His book has topped the best-seller list for 12 weeks and counting.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (148, 'Bank of Mum and Dad', 'used to refer to a person''s parents, considered as a place from which the person can get money:', 'The cheapest way to get around waiting for your loan to arrive is to borrow from the Bank of Mum and Dad.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (149, 'Can I interest you in something', 'Would you like to buy or take something:', 'Can I interest you in a cup of coffee?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (150, 'Cut it out!', 'infml stop doing that:', 'Cut it out, you two – I''m tired of listening to you argue!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (151, 'God bless (you)!', 'said when saying goodbye to someone, to say that you hope good things will happen to them :', 'Good night everyone, and God bless.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (152, 'God bless (you)!', 'said when someone sneezes, to say that you hope they have good health:', '"Achoo!" "God bless you."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (153, 'God forbid', 'a way of saying that you hope something does not happen:', 'God forbid (that) his parents should ever find out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (154, 'God help someone', 'used to give force to a statement of the danger or seriousness of a situation or action:', 'God help us if they attack now while we''re still unprepared.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (155, 'God helps those who help themselves', 'said to show you believe that if you make an effort to achieve something, you will be successful', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (156, 'God knows', 'used to emphasize that you do not understand something at all or have no knowledge of something at all:', 'God knows where he put the keys!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (157, 'God only knows', 'it is impossible to say:', 'God only knows how he managed to find out where I live.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (158, 'God willing', 'used to say you hope everything happens in the way you want:', 'We''ll be there tomorrow, God willing!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (159, 'God/Christ almighty!', 'an expression of anger or surprise. Some people consider this offensive.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (160, 'Goodness/God/Heaven/Christ knows', 'used to mean "I don''t know" or to emphasize a statement. Some people may find this use offensive:', 'God only knows what''ll happen next!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (161, 'I am not my brother''s keeper', 'used as a way of saying that you are not responsible for what someone else does or for what happens to them', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (162, 'I ask you!', 'something that you say in order to show your surprise or anger at something someone has done:', 'They stayed for a month and left without even saying thank you! Well, I ask you!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (163, 'I beg to differ/disagree', 'a way of saying "I do not agree" that is polite, but may sound unfriendly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (164, 'I bet', 'said to show that you understand why someone has a particular opinion or feels a particular way:', '"I''m so annoyed with her." "I''ll bet."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (165, 'I can''t even', 'used for saying that you are so shocked, angry, happy, disappointed, etc. about a situation that you do not know what to say:', 'Cindy''s dating Brad?! I can''t even.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (166, 'I can''t think', 'I do not know:', 'I can''t think why she hasn''t phoned.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (167, 'I declare', 'used to express surprise:', 'Well, I declare!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (168, 'I don''t know', 'used to express that you do not understand or are angry at something that someone has done:', 'I don''t know, however many notices I put up, people still park in my space.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (169, 'I don''t know about you but...', 'used to mean "whatever you are going to do" or "whatever you think":', 'I don''t know about you, but I''m going to bed.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (170, 'I don''t know how, what, why, etc.', 'used to add force to criticisms, expressions of surprise, etc.:', 'I don''t know how you can eat that revolting stuff!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (171, 'I don''t mind if I do', 'said to politely accept an offer of food or drink:', '"There''s plenty more cake if you''d like another piece." "I don''t mind if I do."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (172, 'I feel you', 'I understand; I agree with what you have said:', 'Michelle, I feel you! I need coffee too.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (173, 'I feel your/his, etc. pain', 'used to say that you understand why someone is upset and that you feel sorry for them; sometimes used humorously when someone has no good reason to be upset:', 'When you say your cats destroy furniture, I feel your pain. I''ve had dogs do the same thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (174, 'I know', 'said when you suddenly think of a good idea, an answer, or a solution:', 'I know - let''s go to the beach!', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (175, 'I know', 'said to show you agree with something someone has just said:', '"But he''s so awful." "I know - he''s dreadful."', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (176, 'I know, right?', 'said to show that you agree with something that someone has just said:', '"I have no idea what''s going on." "I know, right?"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (177, 'I mean', 'used to correct what you have just said or to add more information:', 'I really do love him - as a friend, I mean.', 'idiom', 'A2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (178, 'I mean', 'something that people often say before they start or continue their sentence:', 'I mean, he''s a good teacher, but I just don''t like him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (179, 'I might have known', 'said when you are not surprised at a situation or someone''s behaviour, because you expected it:', 'I might have known (that) he''d still be in bed at noon.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (180, 'I must be hearing things', 'said when you cannot believe something because it is so unlikely:', 'He''s offered to wash the dishes - I must be hearing things.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (181, 'I must say', 'I must admit:', 'I must say, I don''t think much of her dress.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (182, 'I need hardly do something', 'used to say that what you are going to say is obvious:', 'I need hardly say what a pleasure it is to introduce our speaker.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (183, 'I owe you (one)', 'said to thank someone for helping you and as a way of saying that you will do something for them in the future:', 'Thanks for the help, Bill - I owe you one.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (184, 'I rest my case', 'said when you believe that something that has just happened or been said proves that you are right or telling the truth:', 'When told of Smith''s angry response to her claim, she said simply, "I rest my case." (= his response proves that what I say is true)', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (185, 'I rest my case', 'said by lawyers in a law court when they have finished the explanation of their case', '', 'idiom', '', 'specialized', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (186, 'I should hope/say/think so/not', 'used to emphasize your agreement or your opinion:', '"Will Beth be there?" "I should hope not! She was so horrible to you."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (187, 'I should think not/so (too)!', 'said when you think what has been suggested is certainly not, or certainly is, the correct and expected thing:', '"I bought her some flowers to say thank you." "I should think so too."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (188, 'I shouldn''t wonder', 'probably:', '"Where''s Mark been recently?" "Up to no good, I shouldn''t wonder."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (189, 'I shudder to think', 'said when you are worried about something unpleasant that might happen or might have happened:', 'I shudder to think what my parents will say when I tell them I''ve failed my exams.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (190, 'I stand corrected', 'used to admit that something you have said or done was wrong:', 'I stand corrected - the date of foundation was 1411, and not 1412 as I had written.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (191, 'I take it', 'said if you think that what you say is likely to be true, although it is not proved:', 'You''ll be staying the night, I take it?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (192, 'I take/plead the Fifth (Amendment)', 'something that you say in order to tell someone you are not going to answer a question:', '"So, who do you like best, Jenny or Kim?" "Sorry, I take the Fifth on that."', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (193, 'I tell a lie', 'something you say when you have just said something wrong and want to correct it:', 'Her name is Paula, no, I tell a lie (= I''m wrong) - it''s Pauline.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (194, 'I think not', 'a formal way of disagreeing or saying no:', '"Will you be going tonight, James?" "I think not."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (195, 'I thought as much', 'used to say that you are not surprised by what someone has said or done:', '"I came to ask you a favour." "I thought as much."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (196, 'I would give anything/a lot', 'used to say that you would like to have or to do something very much:', 'I''d give anything to see the Taj Mahal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (197, 'I wouldn''t say no', 'used to say that you would like something that is offered to you:', '"Would you like another drink?" "I wouldn''t say no."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (198, 'I wouldn''t trust someone as far as I could throw them', 'something you say that means you do not trust someone at all:', 'He''s very charming but I wouldn''t trust him as far as I could throw him.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (199, 'I wouldn’t put it past someone (to do something)', 'infml I would not be surprised if someone did something:', 'I wouldn’t put it past Helena to tell a secret, especially if it helped her in some way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (200, 'I''d like to see...', 'said to mean that you do not believe someone can do something:', 'He said women have an easier life than men, did he? - I''d like to see him bring up children and go to work at the same time.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (201, 'I''ll be a monkey''s uncle!', 'used to show you are very surprised', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (202, 'I''ll be blowed!', 'an expression of great surprise:', '"Kate''s getting married." "Well, I''ll be blowed!"', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (203, 'I''ll be hanged if I know', 'used to say that you certainly do not know', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (204, 'I''ll be hanged if...', 'used to express your determination not to do something or not to allow someone else to do something:', 'I''ll be hanged if I''m going to clean up after him!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (205, 'I''ll be jiggered', 'I''m surprised:', '"Did you know that Ann was pregnant?" "Well, I''ll be jiggered!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (206, 'I''ll eat my hat', 'used to say that you are sure something will not happen:', 'If she actually marries him I''ll eat my hat.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (207, 'I''ll say!', 'used to show that you agree very strongly with what has been said:', '"Does he eat a lot?" "I''ll say!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (208, 'I''ll thank you to do something', 'used to ask someone, in an annoyed way, to do something:', 'I''ll thank you to leave my private papers alone.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (209, 'I''ll wring your/his/her neck!', 'something you say when you are angry with someone:', 'I''ll wring his neck if he does that again!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (210, 'I''ll, he''ll, etc. have you know', 'used to emphasize something that you are telling someone:', 'She''s a very nice person, I''ll have you know.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (211, 'I''ll/we''ll cross that bridge when I/we come/get to it', 'an expression that means you will not worry about a possible future problem but will deal with it if it happens', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (212, 'I''m a Dutchman', 'said after describing or hearing something that is very obviously not true:', 'If that''s his real hair, then I''m a Dutchman.', 'idiom', '', 'humorous, old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (213, 'I''m buggered if...', 'used to show that you certainly will not or cannot do something:', 'I''m buggered if I''m going to lend him any more money.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (214, 'I''m damned if', 'used to say that you will certainly not do something:', 'I''m polite to his ex-wife when I meet her, but I''m damned if I''m going to invite her over for dinner.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (215, 'I''m easy', 'used to say that you do not mind which choice is made:', '"Shall we go to the Indian restaurant, or would you prefer Chinese food?" "I''m easy."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (216, 'I''m just looking', 'said to a person working in a shop when they offer to help you but you are not ready to buy something and do not want help', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (217, 'I''m not fussy/fussed', 'something that you say when you would be satisfied with either choice that is offered you:', '"Red wine or white?" "I''m not fussy."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (218, 'I''m not saying..., but...', 'used as a polite or humorous way of making a comment or criticism :', 'I''m not saying it was your fault. I just think you could have checked.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (219, 'I''m telling you', 'used to emphasize that what you are saying is true, and should be believed:', 'I''m telling you, he''s the best player in the American League.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (220, 'I/I''ve got this', 'used to tell someone that you can or will deal with something:', 'It''s OK, I got this. Go back to what you were doing.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (221, 'I/we''ll (have to) see', 'used to say that you will make a decision about something later:', '"Do you think there''ll be time to stop and eat?" "We''ll see."', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (222, 'I/you wouldn''t wish something on anyone/my/your worst enemy', 'something you say in order to emphasize that something is extremely unpleasant:', 'The effects of this disease are horrible. You wouldn''t wish them on your worst enemy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (223, 'Lamb of God', 'in the Christian religion, a name for Christ', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (224, 'Lord knows', 'used to say that you do not know:', 'Lord knows where we''re going to get the money from.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (225, 'Monday-morning quarterback', 'someone who says how an event or problem should have been dealt with by others after it has already been dealt with', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (226, 'Respectfully yours', 'a very formal and polite way of ending a letter', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (227, 'Rome wasn''t built in a day', 'said to emphasize that you cannot expect to do important things in a short period of time', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (228, 'Scout''s honour', 'said when you are trying to make someone believe that you are telling the truth:', 'I didn''t break it. Scout''s honour!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (229, 'That''s not saying much.', 'used to show that you do not think what someone has said is special', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (230, 'a (heavy) cross to bear', 'an unpleasant or painful situation or person that you have to accept and deal with, although you find it very difficult', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (231, 'a (quick/brisk) trot through something', 'an occasion when you examine or explain the whole of a subject, method, or piece of work quickly without stopping or getting slower:', 'In this book, John Pemble takes a brisk trot through the history and mysteries of Venice.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (232, 'a (whole) heap of something', 'a lot of something:', 'I''ve got a whole heap of work to do.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (233, 'a bad workman blames his tools', 'said when someone has blamed a mistake or failure on the things that they use to work', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (234, 'a banner year/season/month/week', 'a particularly good or successful period of time:', '2004 was a banner year for astronomy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (235, 'a baptism of/by fire', 'a very difficult first experience of something:', 'I was given a million-dollar project to manage in my first month - it was a real baptism of fire.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (236, 'a big ask', 'something you ask someone to do that will be difficult for them:', 'It''s a big ask, I know, but we need the project finished by June.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (237, 'a big/great girl''s blouse', 'a weak and cowardly (= not brave) man:', 'He''s just a big girl''s blouse.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (238, 'a bird in the hand (is worth two in the bush)', 'said when you recognize that you should not risk losing something you already have by trying to get something you think might be better', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (239, 'a bird''s eye view', 'a view from a very high place that allows you to see a large area:', 'Climb to the top of the Eiffel Tower if you want a bird''s eye view of Paris.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (240, 'a bit of a lad', 'a young man who has sex with a lot of different women', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (241, 'a bit of fluff/stuff/skirt', 'a sexually attractive woman:', 'Have you seen his latest bit of skirt?', 'idiom', '', 'slang, old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (242, 'a bit of rough', 'a sexual partner, usually a man, from a low social class:', 'Jenny''s chatting up the barman again. She likes a bit of rough.', 'idiom', '', 'humorous, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (243, 'a bit on the side', 'a sexual relationship with someone who is not married to you, or the person you have the relationship with:', 'We''ve thought for a while that he was having a bit on the side.', 'idiom', '', 'humorous, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (244, 'a bite (to eat)', 'some food:', 'You''ll feel better once you''ve had a bite to eat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (245, 'a bitter pill (to swallow)', 'something that is very unpleasant but must be accepted:', 'Losing to a younger player was a bitter pill to swallow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (246, 'a blanket of something', 'a thick covering of something:', 'The ground was covered by a thick blanket of snow.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (247, 'a blast from the past', 'something or someone that surprises you because you had almost forgotten about it', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (248, 'a blessing in disguise', 'something that seems bad or unlucky at first, but results in something good happening later:', 'Losing that job was a blessing in disguise really.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (249, 'a blinding flash', 'an idea or answer that suddenly becomes obvious:', 'The answer came to her in a blinding flash.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (250, 'a blitz on something', 'a great effort to improve something or do something that needs to be done:', 'We had a blitz on the house at the weekend and cleaned it completely.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (251, 'a blot on someone''s character', 'a fault that spoils someone''s reputation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (252, 'a blot on the landscape', 'something such as an ugly building that spoils a pleasant view', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (253, 'a bolt from the blue', 'something important or unusual that happens suddenly or unexpectedly:', 'The resignation of the chairman came like a bolt from the blue.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (254, 'a bolt from/out of the blue', 'something completely unexpected that surprises you very much:', 'The news of his marriage was a bolt from the blue.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (255, 'a bone of contention', 'something that two or more people argue about strongly over a long period of time', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (256, 'a boot/kick up the/your backside', 'the act of telling someone forcefully to start doing something more quickly or actively:', 'She''s so lazy - she needs a good boot up the backside.', 'idiom', '', 'very informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (257, 'a breath of fresh air', 'someone or something that is new and different and makes everything seem more exciting:', 'Angela''s so cheerful and lively - she''s like a breath of fresh air when she visits.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (258, 'a brown study', 'a mood in which you are very involved in your own thoughts and not paying attention to anything else:', 'I could see she was in a brown study.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (259, 'a bump in the road', 'something, usually something not very serious, that delays a process or prevents it from developing:', 'As with any new programme, there are going to be bumps in the road.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (260, 'a bunch of fives', 'If you give someone a bunch of fives, you hit them hard with your hand closed.', '', 'idiom', '', 'old-fashioned, slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (261, 'a bundle of laughs', 'a funny, entertaining person or situation:', 'He''s not exactly a bundle of laughs, is he?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (262, 'a bundle of nerves', 'someone who is extremely nervous and worried:', 'Sorry for shouting - I''m a bundle of nerves these days.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (263, 'a change is as good as a rest', 'You can get as much good from changing the work you do as from having a rest.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (264, 'a cheap shot', 'a criticism or attack on someone that is unfair:', 'I think her making fun of his wife was a cheap shot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (265, 'a chicken and egg situation', 'a situation in which it is impossible to say which of two things existed first and which caused the other one', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (266, 'a chip off the old block', 'someone who is very similar in character to their father or mother', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (267, 'a chip on your shoulder', 'an angry attitude from someone who feels unfairly treated:', 'She’s not going to make any friends if she walks around with a chip on her shoulder like that.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (268, 'a chorus of something', 'an opinion given by a large group of people at the same time, or a large group of people giving their opinion:', 'The publication of the book was greeted with a chorus of acclaim.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (269, 'a clean bill of health', 'a decision by a doctor that someone is healthy:', 'He''s been given a clean bill of health by the doctor.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (270, 'a clean bill of health', 'a decision by someone in authority that a particular thing is in good condition:', 'Of 30 countries inspected for airline safety, only 17 received a clean bill of health.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (271, 'a clean slate', 'a state in which you are starting an activity or process again, not considering what has happened in the past at all:', 'The previous negotiations did not go anywhere, and we intend to start them again next week with a clean slate.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (272, 'a close/near thing', 'something bad that almost happened:', 'The car just missed the child but it was a very close thing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (273, 'a cloud hanging over someone', 'a situation or future event that makes you worry or feel unhappy:', 'When you''re waiting for an operation, you feel like there''s a cloud hanging over you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (274, 'a cloud on the horizon', 'something that threatens to cause problems or unhappiness in the future:', 'The only cloud on the horizon is the physics exam in June.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (275, 'a cog in a/the machine', 'a member of a large organization whose job, although necessary, makes them feel as if they are not important:', 'I decided to set up my own business because I was tired of just being a cog in a machine.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (276, 'a conflict of interest', 'a situation in which someone cannot make a fair decision because they will be affected by the result:', 'I need to declare a conflict of interest here - one of the candidates for the job is a friend of mine.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (277, 'a credit to someone/something', 'to be so good or successful that the people or things that made you successful should be mentioned:', 'Thomas is a credit to our school system.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (278, 'a crock (of shit)', 'something that is not true:', '"I''m really sorry!" "What a crock - you are not."', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (279, 'a cry for help', 'a way of saying that you need help:', 'Most suicide attempts are really a cry for help.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (280, 'a crying shame', 'a great misfortune:', 'It’s a crying shame that new mothers have to go back to work after six weeks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (281, 'a cut above', 'someone who is of a higher social class:', 'She thinks she''s a cut above her neighbours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (282, 'a damsel in distress', 'a young woman who is in trouble and needs a man''s help', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (283, 'a dime a dozen', 'common and not special:', 'Plastic toys like this are a dime a dozen.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (284, 'a dog in the manger', 'someone who keeps something that they do not want in order to prevent someone else from getting it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (285, 'a dog''s breakfast', 'something or someone that looks extremely untidy, or something that is very badly done', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (286, 'a dog''s life', 'a very unhappy and unpleasant life', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (287, 'a drop in the bucket', 'a very small amount compared to the amount needed:', 'All the money we raised was just a drop in the bucket.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (288, 'a drop in the ocean', 'a very small amount compared to the amount needed:', 'My letter of protest was just a drop in the ocean.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (289, 'a drop too much (to drink)', 'too much alcohol to drink', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (290, 'a drowning man will clutch at a straw', 'said about someone who is in a very difficult situation, and who will take any available opportunity to improve it', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (291, 'a fair crack of the whip', 'an equal chance to do something:', 'It''s only right that all the candidates should be given a fair crack of the whip.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (292, 'a fair shake', 'an equal chance to do something:', 'It''s only right that all the candidates should be given a fair shake.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (293, 'a fate worse than death', 'something you do not want to experience because it is so unpleasant:', 'When you''re 16, an evening at home with your parents seems like a fate worse than death.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (294, 'a feather in your cap', 'an achievement to be proud of:', 'It''s a real feather in our cap to be playing in the state championship.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (295, 'a few well-chosen words', 'a short speech:', 'He introduced the visitors with a few well-chosen words.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (296, 'a few/couple of steps', 'a short distance:', 'The museum is just a few steps from the hotel.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (297, 'a fifth/third wheel', 'a wheel on a vehicle to which you attach a trailer, or the trailer itself', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (298, 'a fifth/third wheel', 'someone who is in a situation where they are not needed or are ignored by most people', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (299, 'a fifty-fifty chance', 'a result is equally likely to happen or not happen:', 'There’s only a fifty-fifty chance that she’ll survive the operation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (300, 'a fight to the finish', 'a situation in which two groups or people intend to fight until one side has been defeated', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (301, 'a figment of your imagination', 'something imagined or created by your mind:', 'The dinosaurs he said he saw were figments of his imagination.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (302, 'a fine figure of a man/woman', 'a person who is tall, with a large, physically attractive body', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (303, 'a fine line', 'If you say that there is a fine line between one thing and another, you mean that they are very similar. You often say this when one thing is acceptable and the other is not:', 'As a parent, I knew that there was a fine line between panic and caution.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (304, 'a firm hand', 'strong control:', 'Reforming these young offenders will require a firm hand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (305, 'a fish out of water', 'a person who feels awkward or unhappy because they are in a situation that is not familiar or because they are different from the people around them:', 'I didn''t have any friends that were like me. I just always felt like a fish out of water.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (306, 'a fishing expedition', 'an attempt to discover the facts about something by collecting a lot of information, often secretly:', 'The investigators'' request for the company''s accounts is simply a fishing expedition - they have no real evidence of wrongdoing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (307, 'a flash in the pan', 'something that happened only once or for a short time and was not repeated:', 'Sadly, their success was just a flash in the pan.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (308, 'a force to be reckoned with', 'an organization or a person with a lot of power and influence:', 'The senator was still a force to be reckoned with, in spite of his age.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (309, 'a free ride', 'an opportunity or advantage that someone gets without having done anything to deserve it:', 'Just because he was the boss''s son didn''t mean Tim got a free ride.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (310, 'a friend in need is a friend indeed', 'This means that a friend who helps you when you really need help is a true friend.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (311, 'a frog in your throat', 'difficulty speaking because your throat feels dry:', 'I had a frog in my throat, and I had to clear my throat several times before I could answer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (312, 'a full ride', 'an offer by a college or university to pay all costs for the studies of a person with great ability:', 'My friend''s nephew just got a full ride to Princeton.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (313, 'a full, good, thick, etc. head of hair', 'a lot of hair:', 'Even as a tiny baby, she had a thick head of hair.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (314, 'a game in hand', 'If a sports team has a game in hand over other teams in a competition, it still has another game to play in which it can gain points:', 'Fulham are third from bottom with two games in hand over the teams below them.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (315, 'a gift from the gods', 'an especially good or lucky thing or person that comes to you', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (316, 'a gleam in your eye', 'an expression in your eyes that shows that you are amused or that you have a secret:', '"I can''t tell you that yet, but I will soon," Grandpa said with a gleam in his eye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (317, 'a good listener', 'someone who gives you a lot of attention when you are talking about your problems or things that worry you, and tries to understand and support you', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (318, 'a good many', 'a lot of:', 'There were a good many people at the concert.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (319, 'a good time was had by all', 'said to mean that everyone enjoyed themselves', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (320, 'a good/bad turn', 'an action that helps/harms someone:', 'That''s my good turn for the day!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (321, 'a hair''s breadth', 'a very small distance or amount:', 'His finger was within a hair''s breadth of touching the alarm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (322, 'a hard/tough nut to crack', 'a problem that is very difficult to solve or a person who is very difficult to understand', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (323, 'a hard/tough row to hoe', 'a difficult situation to deal with:', 'Teachers have a tough row to hoe in today''s schools.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (324, 'a head of steam', 'the force produced by a large amount of steam in a closed space', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (325, 'a head of steam', 'a situation in which a person or an activity starts to become very active or successful:', 'They''re really beginning to build up a head of steam for their campaign.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (326, 'a heart of gold', 'a kind and generous character:', 'He plays the part of a tough cop on TV who really has a heart of gold.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (327, 'a heavy date', 'a planned meeting between two people who are very interested in having a romantic or sexual relationship:', 'I think Carol has a heavy date - she''s been in the bathroom for over an hour.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (328, 'a heavy heart', 'a feeling of unhappiness:', 'With a heavy heart, she turned to wave goodbye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (329, 'a heck of a something/someone', 'used for emphasis to mean "very":', 'It''s a heck of a long way to the nearest shop from here.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (330, 'a heck of a something/someone', 'a surprisingly good person or thing:', '20 dollars for that is a heck of a good deal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (331, 'a hive of activity/industry', 'a place where a lot of people are working very hard:', 'The whole house was a hive of activity on the day before the wedding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (332, 'a hole in one', 'in golf, an occasion when someone''s ball goes into the hole the first time they hit it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (333, 'a hop, skip, and a jump', 'a series of short, quick jumping movements:', 'Then it is time to race down, which you have to do in a hop, skip, and a jump because the path is so steep.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (334, 'a hop, skip, and a jump', 'a very short distance:', 'We''re just a hop, skip, and a jump away.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (335, 'a hop, skip, and a jump', 'a situation that is very close to achieving something or very similar to something:', 'From there, it is a hop, skip and a jump to killing people who don''t have a good quality of life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (336, 'a hundred/thousand/million and one', 'very many:', 'I can''t talk right now - I have a hundred and one things to do this morning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (337, 'a kick in the butt/pants', 'If you give someone a kick in the butt, you do or say something to try to stop him or her being lazy.', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (338, 'a kick in the pants', 'something that makes you improve your behavior:', 'He needs a good kick in the pants.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (339, 'a kick up the arse/backside', 'If you give someone a kick up the arse, you do or say something to try to stop them being lazy.', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (340, 'a kick/boot in the/your backside', 'the act of telling someone forcefully to start doing something more quickly or actively:', 'She''s so lazy - she needs a good kick in the backside.', 'idiom', '', 'very informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (341, 'a king''s ransom', 'a large amount of money:', 'That diamond necklace must have cost a king''s ransom.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (342, 'a knight in shining armour', 'someone who saves you from a difficult or dangerous situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (343, 'a knockout blow', 'an event or action that causes someone or something to fail:', 'Already out of training, the latest illness has dealt her hopes of a gold medal a knockout blow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (344, 'a laundry list', 'a long list of subjects:', 'It wasn''t much of a speech - just a laundry list of accusations against the government.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (345, 'a leap in the dark', 'something you do without being certain what will happen as a result:', 'I had very little information about the company, so writing to them was a leap in the dark.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (346, 'a leap of faith', 'an act of believing something that is not easily believed:', 'It took a big leap of faith to decide to quit my job and try something new.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (347, 'a leopard can''t/doesn''t change its spots', 'something you say that means a person''s character, especially if it is bad, will not change, even if they pretend that it will', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (348, 'a level playing field', 'a situation in which everyone has the same chance of succeeding:', 'If the tax systems are different in each European country, how can industries start on a level playing field?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (349, 'a lick and a promise', 'a quick and careless act of cleaning or washing', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (350, 'a list as long as your arm', 'a very long list:', 'I''ve got a list as long as my arm of the things we need to do before we leave.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (351, 'a little bird told me', 'used to say that you have heard a piece of information about someone from someone else:', '"How did you know it was my birthday?" "Α little bird told me."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (352, 'a little bird told me', 'said if you know who gave you the information being discussed but do not want to say who it was:', '"How did you know he was leaving?" "Oh, let''s just say a little bird told me."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (353, 'a load of crap, nonsense, rubbish, etc.', 'something that is not true, or something of very bad quality:', 'Who said they were cheaper - what a load of rubbish!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (354, 'a load of crap, nonsense, trash, etc.', 'something that is not true, or something of very bad quality:', 'Who said they were cheaper - what a load of trash!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (355, 'a load/weight off your mind', 'an occasion when a problem that has been worrying you stops or is dealt with:', 'I''m so relieved that I don''t have to make a speech - it''s such a weight off my mind!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (356, 'a long face', 'If you have a long face, you look sad:', '"Why do you have such a long face?" "My boyfriend doesn''t want to see me any more."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (357, 'a long way to go', 'a lot of work to do or improvements to make:', 'He has a long way to go before he can present the plans to the public.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (358, 'a lump in your throat', 'a tight feeling in your throat because of a strong emotion, esp. sadness:', 'I had a huge lump in my throat as I watched my brother get on the plane.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (359, 'a magic touch', 'a special ability to do something very well:', 'The film''s success will no doubt please the 46-year-old director, who was rumoured to have lost his magic touch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (360, 'a man''s gotta do what a man''s gotta do', 'said to mean that you will do whatever you have to do, even if it is difficult or dangerous', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (361, 'a man''s man', 'a man who enjoys men''s activities and being with other men:', 'Terry''s what you''d call a man''s man - you wouldn''t find him at the ballet too many nights a week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (362, 'a man/woman of action', 'someone who prefers to do things rather than think about and discuss them:', 'He was a man of action who believed that to achieve things in life you had to be prepared to fight for them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (363, 'a man/woman of few words', 'a man/woman who says very little:', 'My father was a man of few words, but when he spoke it was worth listening to.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (364, 'a man/woman of his/her word', 'someone who keeps their promises:', 'You can trust him - he''s a man of his word.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (365, 'a man/woman of the world', 'someone who has a lot of experience of life and people, and can deal with most situations', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (366, 'a matter of life and death', 'a situation that is extremely serious:', 'Don’t worry about missing your bus – it’s not a matter of life and death.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (367, 'a matter of opinion', 'something that depends on personal preference:', 'Choosing the best ballplayer of all time is really a matter of opinion.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (368, 'a matter of something', 'only; just:', 'In a matter of seconds, the building was in flames.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (369, 'a matter/question of time', 'used when you think that something will happen at some point in the near future:', 'If you keep on driving like that, it''ll only be a matter of time before you have an accident.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (370, 'a means to an end', 'something that you do because it will help you to achieve something else:', 'I didn''t particularly like the job - it was just a means to an end.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (371, 'a meeting of minds', 'a situation when two or more people have the same opinions about something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (372, 'a metaphor for something', 'a symbol that represents a particular thing:', 'The author uses disease as a metaphor for the corruption in society.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (373, 'a mile a minute', 'very quickly:', 'Mike was very excited, talking a mile a minute.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (374, 'a mile away', 'If you can see or tell something a mile away, you notice it easily and quickly:', 'She''s lying - you can tell from a mile away.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (375, 'a mile off', 'If you can see or tell something a mile off, you notice it easily and quickly:', 'She''s lying - you can tell it a mile off.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (376, 'a mine of information', 'someone who has a lot of knowledge', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (377, 'a miserable, poor, etc. excuse for something', 'a very bad example of something:', 'It was a miserable excuse for a meal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (378, 'a moment of weakness', 'a short time during which someone makes a bad decision or does something bad that they would not normally do:', 'He kept asking me to help him, and in a moment of weakness I said yes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (379, 'a mouth to feed', 'someone, especially a new baby, who you must provide food for:', 'They''ve got three kids and her husband just lost his job - the last thing they need is another mouth to feed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (380, 'a mug''s game', 'an activity that will not make you happy or successful:', 'She decided that freelancing was a mug''s game.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (381, 'a mystery to me', 'something I do not understand:', 'It’s a mystery to me why she married him in the first place!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (382, 'a narrow squeak', 'a success that was almost a failure:', 'We caught the ferry but it was a narrow squeak.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (383, 'a nasty piece of work', 'a very unpleasant person', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (384, 'a needle in a haystack', 'something that is impossible or extremely difficult to find, especially because the area you have to search is too large:', 'Finding the piece of paper I need in this huge pile of documents is like looking for/trying to find a needle in a haystack', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (385, 'a new broom sweeps clean', 'said when someone new takes control of an organization and makes many changes', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (386, 'a new lease of life', 'an occasion when you become more energetic and active than before:', 'His grandchildren have given him a new lease of life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (387, 'a new lease of life', 'an increase in the period for which something can be used or continued:', 'The project suddenly got a new lease of life when the developers agreed to provide some more funding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (388, 'a new lease on life', 'an occasion when you become more energetic and active than before:', 'His grandchildren have given him a new lease on life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (389, 'a new lease on life', 'an increase in the period for which something can be used or continued:', 'The project suddenly got a new lease on life when the developers agreed to provide some more funding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (390, 'a night on the town', 'an evening when you go to various places and enjoy entertainment such as dancing, eating in a restaurant, or drinking in a bar:', 'UK Let''s have/go for a night on the town to celebrate.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (391, 'a nip (here) and a tuck (there)', 'a series of small reductions:', 'The department made a nip here and a tuck there, but they were still way over budget.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (392, 'a nip and tuck', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (393, 'nip and tuck', 'If a competition is nip and tuck, first one side seems to be winning and then the other, so that the result is not certain:', 'It was nip and tuck as to who would win the playoffs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (394, 'nip and tuck', 'If a situation is nip and tuck, someone or something in that situation comes very close to failing or ending:', 'For several months it was nip and tuck, but we managed to pull the company out of bankruptcy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (395, 'a nip in the air', 'a feeling of cold:', 'There’s a real nip in the air this morning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (396, 'a nod is as good as a wink', 'used to say that only a slight sign is needed for you to understand clearly what is meant by something or what is happening in a situation', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (397, 'a nod to sth', 'If something is a nod to a particular thing, it refers to it:', 'The name San Fransisco 49ers is a nod to the prospectors who flocked to California during the 1849 gold rush.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (398, 'a notch on the/someone''s bedpost', 'someone that a person has sex with, not because they want a serious relationship, but because they want to have sex with as many people as possible:', 'She''s not prepared to be just another notch on the bedpost.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (399, 'a numbers game', 'a situation in which the most important factor is how many of a particular thing there are, especially when you disapprove of this:', 'To me, business is more than just a numbers game.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (400, 'a pack of lies', 'a story, explanation, claim, etc. that is completely untrue:', 'The whole story turned out to be a pack of lies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (401, 'a pack rat', 'someone who collects things that they do not need:', 'For me there could be nothing worse than living with a pack rat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (402, 'a page in/of history', 'an important part of the history of a place, time, or group of people:', 'The signing of the peace treaty will be seen as a glorious page in our country''s history.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (403, 'a pain (in the neck)', 'someone or something that is very annoying:', 'That child is a real pain in the neck.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (404, 'a pain in the arse/backside', 'someone or something that is very annoying:', 'The kids were a real pain in the arse.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (405, 'a pain in the ass/butt', 'someone or something that is very annoying:', 'The kids were a real pain in the ass.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (406, 'a paper chase', 'the activity of dealing with many different documents in order to achieve something:', 'To receive even the smallest amount of financial aid from a college, it''s a real paper chase.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (407, 'a parting of the ways', 'the point at which two people or organizations separate:', 'The parting of the ways came after a series of disagreements between the singer and his song-writer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (408, 'a passing resemblance', 'a slightly similar appearance:', 'He bears more than a passing resemblance to (= he is noticeably similar to) the young Marlon Brando.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (409, 'a pearl of great price', 'something that is very rare and is considered very important:', 'Inexhaustible patience is a pearl of great price.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (410, 'a penny saved is a penny earned', 'something you say that means it is wise to save money:', 'I''d advise anyone to put aside a proportion of their earnings - a penny saved is a penny earned.', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (411, 'a piece of ass', 'used to refer to a woman as a sexually attractive object', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (412, 'a piece of cake', 'something that is very easy to do:', 'The exam was a piece of cake.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (413, 'a piece of the action', 'infml a part of the profits or advantages that come from an activity:', 'When it comes to lawsuits, everyone seems to want a piece of the action.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (414, 'a piece of the pie', 'a share of something:', 'When the business started making money, everyone in his family wanted a piece of the pie.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (415, 'a piece of work', 'a very unkind or unpleasant person:', 'It soon becomes clear that Minty is rather a piece of work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (416, 'a piece/slice of the action', 'involvement in something successful that someone else has started:', 'Now research has proved that the drug is effective, everyone wants a slice of the action.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (417, 'a piece/slice/share of the pie', 'part of the profit or benefit from something, or part of the amount of something that is available:', 'The company plans to acquire new businesses to grab a bigger piece of the pie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (418, 'a pig in a poke', 'something that you buy or accept without first seeing it or finding out if it is good', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (419, 'a place for everything and everything in its place', 'This means that the best way to stay well organized is to keep things in their correct positions.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (420, 'a place in the sun', 'a good or lucky position:', 'He certainly earned his place in the sun.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (421, 'a plum in your mouth', 'a way of speaking that is typical of people of a high social class:', 'She had elocution lessons as a child and as a result now speaks with a plum in her mouth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (422, 'a political football', 'a problem that politicians from different parties argue about and try to use in order to get an advantage for themselves:', 'We don''t want the immigration issue to become a political football.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (423, 'a port in a storm', 'somewhere or someone from which or whom you can get help in a difficult situation:', 'She held on to me as though I were a port in a storm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (424, 'a pretty pass', 'a bad situation:', 'Things have come to a pretty pass when a referee can no longer be trusted.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (425, 'a pretty/fine kettle of fish', 'a very difficult and annoying situation', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (426, 'a problem shared is a problem halved', 'used to say that if you tell someone about a problem, it is easier to deal with', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (427, 'a question mark over something', 'an expression used when doubt exists about a particular thing:', 'A question mark hangs over the future of the company.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (428, 'a quick study', 'someone who is able to learn new things quickly:', 'He lacked foreign policy experience but was a quick study.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (429, 'a rainy day', 'a time when money might unexpectedly be needed:', 'She had saved some money for a rainy day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (430, 'a rap on/over the knuckles', 'the act of speaking to someone severely or angrily because of something they have done or failed to do:', 'I got a rap on the knuckles for not finishing my essay on time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (431, 'a raw deal', 'bad or unfair treatment:', 'He said that many children in the city''s schools were getting/being given a raw deal by being taught in classes that were too large.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (432, 'a reach of the imagination', 'the act of trying very hard to imagine something:', 'It takes (quite) a reach of the imagination to believe that story.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (433, 'a recipe for something', 'an idea, situation, or method that is likely to result in something:', 'Treating teenagers like six-year-olds is a recipe for disaster.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (434, 'a reign of terror', 'a period of time when a ruler controls people in a violent and cruel way', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (435, 'a right one', 'someone very annoying or silly:', 'We''ve got a right one here, eh!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (436, 'a riot of color', 'extremely colorful and bright:', 'Her living room is a riot of color.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (437, 'a riot of colour', 'extremely colourful and bright:', 'Jim''s rose garden is a riot of colour.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (438, 'a ripe old age', 'the condition of being very old; used especially to talk about someone who has a long healthy life:', 'I''m sure he''ll live to a ripe old age.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (439, 'a roaring success', 'something that is very successful:', 'The party was a roaring success.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (440, 'a rolling stone (gathers no moss)', 'said to mean that a person who is always travelling and changing jobs has the advantage of having no responsibilities, but also has disadvantages such as having no permanent place to live:', 'Hal was a bit of a rolling stone before he married and settled down.', 'idiom', '', 'old-fashioned, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (441, 'a roof over your head', 'a place to live:', 'She gave him enough money to get a roof over his head.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (442, 'a rough ride', 'a difficult time:', 'Government plans to cut sick pay had a rough ride in the House of Commons.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (443, 'a rubber check', 'a cheque (= piece of paper from someone''s bank used as payment) that is not worth anything because the person does not have enough money in the bank', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (444, 'a rum do', 'a strange situation or event', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (445, 'a rung on/of the ladder', 'one of the stages or levels in something such as a process or organization, through which it is possible to rise or make progress:', 'I started my life on the bottom rung of the ladder in this company.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (446, 'a safe pair of hands', 'someone who you can trust to do an important job well, without making mistakes:', 'Colleagues regard her as a safe pair of hands.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (447, 'a screeching halt', 'a sudden stop by a vehicle that makes a long, loud, high noise that is unpleasant to hear:', 'Eventually, the car came to a screeching halt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (448, 'a screeching halt', 'a sudden and unexpected end to something:', 'My young career very nearly came to a screeching halt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (449, 'a shadow of your former self', 'someone or something that is not as strong, powerful, or useful as it once was:', 'Since her accident, she’s become a shadow of her former self.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (450, 'a shot in the arm', 'something that has a sudden and positive effect on something, providing encouragement and new activity:', 'Fresh investment would provide the shot in the arm that this industry so badly needs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (451, 'a shot in the dark', 'an attempt to guess something when you have no information or knowledge about the subject and therefore cannot possibly know what the answer is', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (452, 'a shoulder to cry on', 'someone who is willing to listen to your problems and give you sympathy, emotional support, and encouragement:', 'I wish you''d been here when my mother died and I needed a shoulder to cry on.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (453, 'a sigh of relief', 'a feeling of comfort after worrying about something:', 'Residents in coastal areas are breathing a sigh of relief now that the storm has passed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (454, 'a sight for sore eyes', 'a way of saying that you are very pleased to see someone or that you think someone is very attractive:', 'You''re a sight for sore eyes!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (455, 'a slap in the face', 'an insult, esp. when it comes as a surprise:', 'It was a real slap in the face when they didn''t invite me to the wedding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (456, 'a slap on the wrist', 'a small punishment when a more severe punishment is deserved:', 'They rob someone on the street and they get a slap on the wrist – thirty days in jail.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (457, 'a sledgehammer to crack a nut', 'If you use a sledgehammer to crack a nut, you use much more force than is needed:', '50 police officers to arrest two unarmed men is surely using a sledgehammer to crack a nut.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (458, 'a slice of life', 'A film, piece of literature, or a play might be described as a slice of life if it describes or shows the ordinary details of real life.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (459, 'a small fortune', 'a large amount of money:', 'You''ll have to spend a small fortune in legal fees if you decide to sue for compensation.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (460, 'a snowball effect', 'a situation in which something increases in size or importance at a faster and faster rate:', 'The more successful you become, the more publicity you get and that publicity generates sales. It''s a kind of snowball effect.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (461, 'a spring in your step', 'If you walk with or have a spring in your step, you walk energetically in a way that shows you are feeling happy and confident:', 'There''s been a definite spring in his step ever since he met Joanna.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (462, 'a step backward', 'going back to a worse or less developed state:', 'The changes that have been introduced are being seen as a step backward.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (463, 'a step backwards', 'going back to a worse or less developed state:', 'The changes that have been introduced are being seen as a step backwards.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (464, 'step forward', 'to offer to provide or do something, or to help with something:', 'No one has yet stepped forward to claim responsibility for the attack.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (465, 'a stick to beat someone with', 'something that you can use to criticize, influence, or cause difficulty for someone or something you dislike or disapprove of:', 'The country''s lack of openess was used as a stick to beat it with.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (466, 'a stitch in time (saves nine)', 'said to mean that it is better to act or deal with problems immediately, because if you wait and deal with them later, things will get worse and the problems will take longer to deal with', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (467, 'a stone''s throw', 'a very short distance:', 'The apartment is just a stone''s throw from the sea.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (468, 'a stone’s throw (away)', 'a short distance:', 'The animal was sitting just a stone''s throw away from us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (469, 'a sure thing', 'something that is certain to happen:', 'The president''s re-election is now far from a sure thing.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (470, 'sure thing', 'used to show agreement:', '"Could you give me a ride home tonight?" "Sure thing!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (471, 'a thing of the past', 'something that no longer happens:', 'Giving up your seat to an older person seems to be a thing of the past.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (472, 'a thing or two', 'some matters, facts, or information:', 'I''m having trouble paying attention - I have a thing or two on my mind.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (473, 'a torrid time', 'a period when you experience a lot of problems', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (474, 'a tough act to follow', 'infmlso good that whatever happens next is unlikely to seem as good:', 'The last Bond movie was my favorite - it''ll be a tough act to follow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (475, 'a tough row to hoe', 'a difficult situation to deal with:', 'The candidate has a tough row to hoe – he has limited funds, and his message is not a popular one.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (476, 'a tough/hard nut', 'someone who is very unpleasant and difficult to deal with:', 'As a teenager, Jack was a real hard nut, always getting into fights.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (477, 'a tough/tricky, etc. customer', 'a particular type of person or thing, especially one that is difficult to deal with:', 'David can be a very tough customer when he perceives others as obstacles to achieving his goals.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (478, 'a tower of strength', 'someone or something that remains strong and gives a lot of support in a difficult situation:', 'Andrea was a tower of strength to me when I was ill.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (479, 'a turn of the screw', 'an action that makes a bad situation worse, especially one that forces someone to do something:', 'Each letter from my bank is another turn of the screw.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (480, 'a walk in the park', 'something that is very easy to do, and usually pleasant:', 'He''s used to hard physical work - this is a walk in the park to him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (481, 'watch out', 'used to warn someone of danger or an accident that seems likely to happen:', '"Watch out!" he shouted, but it was too late - she had knocked the whole tray of drinks onto the floor.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (482, 'a week ago (this)', 'last week on:', 'The problem with the TV started a week ago Monday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (483, 'a week from', 'in one week following:', 'The first performance of the play is a week from tomorrow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (484, 'a wet weekend', 'a very boring and disappointing experience or person:', 'He sounds about as much fun as a wet weekend in Carmarthenshire.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (485, 'a whale of a', 'used to refer to a very great amount of something or a very good thing:', 'That''s a whale of a story.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (486, 'a whole lot', 'very much:', 'Things were about to get a whole lot worse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (487, 'a whole lot', 'a large number:', 'I said no, for a whole lot of reasons.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (488, 'the whole lot', 'all of something, or all of the people or things in a group:', 'I offered him some chocolate, and he ate the whole lot.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (489, 'a whole new ballgame', 'a completely different situation, often one that is difficult or that you know little about:', 'We''d done a lot of climbing in Scotland but the Himalayas were a whole new ballgame.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (490, 'a wolf in sheep''s clothing', 'a person with a pleasant and friendly appearance that hides the fact that they are evil', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (491, 'a world of difference', 'If there is a world of difference between two people or things, they are very different:', 'There''s a world of difference between the service in the two hotels.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (492, 'a/the counsel of despair', 'an action or statement that means that you admit you have failed:', 'Building more prisons was the counsel of despair.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (493, 'a/the gathering of the clans', 'an occasion when a large group of family or friends meet, especially in order to enjoy themselves', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (494, 'abide by something', 'to accept or obey an agreement, decision, or rule:', 'Competitors must abide by the judge''s decision.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (495, 'abound in/with something', 'If something abounds in/with other things, it has a lot of them:', 'The coast here abounds with rare plants.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (496, 'above and beyond sth', 'more than a particular amount or level:', 'We have faced costs far above and beyond what was anticipated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (497, 'above/below the fold', 'the top/bottom half of a newspaper, that can/cannot be seen when it is folded in half and is considered a good/bad place to have an article or advertisement', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (498, 'above/below the fold', 'the part of a web page that can/cannot be seen before you scroll down the page', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (499, 'absence makes the heart grow fonder', 'This means that when people we love are not with us, we love them even more.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (500, 'accede to something', 'to agree to do what people have asked you to do:', 'He graciously acceded to our request.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (501, 'accede to something', 'to become king or queen, or to take a position of power:', 'The diaries were written in 1837, when Queen Victoria acceded to the throne.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (502, 'accept/take something on faith', 'to be willing to believe something without proof', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (503, 'accidentally on purpose', 'If you do something accidentally on purpose, you do it intentionally but pretend it happened by chance:', 'I''ve never liked these glasses of Peter''s. I might drop them one day - accidentally on purpose.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (504, 'accidents will happen', 'said after an accident in order to make it seem less bad', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (505, 'accord with something', 'to be the same as something, or to agree with something:', 'His version of events does not accord with witnesses'' statements.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (506, 'account (to someone) for something', 'to explain the reason for something or the cause of something:', 'Can you account for your absence last Friday?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (507, 'account for something', 'to form the total of something:', 'Students account for the vast majority of our customers.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (508, 'accustom yourself to something', 'to make yourself familiar with new conditions:', 'It''ll take time for me to accustom myself to the changes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (509, 'ache for something', 'to want something very much:', 'He was lonely and aching for love.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (510, 'acquaint someone/yourself with something', 'to make someone or yourself familiar with something:', 'Take time to acquaint yourself with the rules.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (511, 'across country', 'travelling in a direction where roads or public transport do not go, or where main roads or railways do not go:', 'Getting a train across country from Cambridge to Chester can be difficult.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (512, 'act as something', 'to do a particular job, especially one that you do not normally do:', 'He was asked to act as an adviser on the project.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (513, 'act as something', 'to have a particular effect:', 'Some people say that capital punishment acts as a deterrent.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (514, 'act for/on behalf of sb/sth', 'to represent a person, company, etc. in a court of law:', 'There are few exceptions to the rule that a solicitor may not act for both seller and buyer.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (515, 'act for/on behalf of sb/sth', 'to represent a person, company, etc. or deal with their business for them:', 'The Council of Mortgage Lenders claims to act for 98% of lenders.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (516, 'act on sth', 'to do something because you have been advised or told to do it:', 'There have been concerns as to why the Board didn''t act on a recommended pay raise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (517, 'act out', 'to behave badly because you are unhappy or upset, often in ways that you are not aware of:', 'These kids act out because their lives are a mess.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (518, 'act something out', 'to perform the actions and say the words of a situation or story:', 'The children acted out their favourite poem.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (519, 'act something out', 'to express your thoughts, emotions, or ideas in your actions:', 'Children''s negative feelings often get acted out in bad behaviour.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (520, 'act up', 'If a person, especially a child, acts up, they behave badly:', 'Sophie got bored and started acting up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (521, 'act up', 'If a machine or part of the body acts up, it does not perform as well as it should:', 'My car always acts up in cold weather.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (522, 'act/do something on your own responsibility', 'to act without being told to by someone in authority', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (523, 'act/play the goat', 'to behave in a silly way:', 'Stop acting the goat!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (524, 'actions speak louder than words', 'said to emphasize that what you do is more important and shows your intentions and feelings more clearly than what you say', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (525, 'add (something) up', 'to calculate the total of two or more numbers:', 'If you add those four figures up, it comes to over £1,500.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (526, 'add fuel to the fire', 'to make an argument or bad situation worse:', 'The discovery that the government was aware of the cover-up has really added fuel to the fire.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (527, 'add in', 'to include something as part of something else:', 'A loan for $100 could carry annual interest rates of 50% once fees are added in.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (528, 'add on something', 'to include or build something extra:', 'We’ve added on a couple of rooms to the house.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (529, 'add salt to something', 'If you add salt to a subject or conversation, you make it more interesting:', 'You can be sure she''ll always add salt to the conversation!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (530, 'add up to something', 'to become a particular amount:', 'The various building programmes add up to several thousand new homes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (531, 'add up to something', 'to have a particular result or effect:', 'It all added up to a lot of hard work for all of us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (532, 'adhere to something', 'to continue to obey a rule or have a belief:', 'She adhered to her principles/ideals throughout her life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (533, 'adjourn to somewhere', 'to finish doing something and go somewhere, usually for a drink and some food:', 'Shall we adjourn to the sitting room for coffee?', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (534, 'adjourn to somewhere', 'to go to another place, usually after something has ended:', 'After the meeting had ended, they adjourned to the garden.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (535, 'admit of something', 'to allow something or make it possible:', 'The present schedule does not admit of modification (= it cannot be changed).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (536, 'after all', 'despite earlier problems or doubts:', 'The rain has stopped, so the game will go ahead after all.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (537, 'after all', 'used to add information that shows that what you have just said is true:', 'I do like her - after all, she is my sister.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (538, 'after hours', 'after the usual hours of work:', 'I often do some of my own work after hours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (539, 'after hours', 'If you drink in a bar after hours, you drink alcohol at a time when it is not allowed by law:', 'The police are trying to stop after-hours drinking.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (540, 'after your own heart', 'having the same opinions or interests as you:', 'She''s a woman after my own heart.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (541, 'against (all) the odds/against all odds', 'If you do or achieve something against (all) the odds/against all odds, you do or achieve it although there were a lot of problems and you were not likely to succeed:', 'Against all the odds, he recovered.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (542, 'against the clock', 'If you do something against the clock, you do it as fast as possible and try to finish it before a certain time.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (543, 'against the clock', 'When people do something against the clock, the time they take to do it is recorded, in order to find which person or attempt is the fastest.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (544, 'against the run of play', 'If a football team scores a goal against the run of play, they score when the opposing side has been playing better or had more opportunities to score:', 'West Brom scored against the run of play just before half time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (545, 'against time/the clock', 'If you do something against time/the clock, you do it as fast as possible and try to finish it before a certain time:', 'It was a real race against time to get all the costumes sewn for the play.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (546, 'against your better judgment', 'If something is against your better judgment, you think it would be wiser not to do it:', 'Against my better judgment, I gave him the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (547, 'agonize over/about something', 'If you agonize over/about something, you spend time worrying and trying to make a decision about it:', 'She agonized for days about whether she should take the job.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (548, 'agree to differ', 'If two people agree to differ, they accept that they have different opinions about something and stop trying to persuade each other that they are right.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (549, 'agree to something', 'to accept something:', 'Both sides in the conflict have agreed to the terms of the peace treaty.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (550, 'agree with something', 'to think that something is morally acceptable:', 'I don''t agree with hunting.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (551, 'agree with someone', 'If a situation or new conditions agree with you, they make you feel healthy and happy:', 'You look well - the mountain air must agree with you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (552, 'ahead of time', 'in advance:', 'We had a date for lunch, and I said I’d call her ahead of time to decide where.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (553, 'ahead of your time', 'having very modern ideas:', 'He was way ahead of his time in realizing the importance of being able to record sound.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (554, 'aim at something', 'to plan, hope, or intend to achieve something:', 'The talks are aiming at a compromise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (555, 'aim something at someone', 'If information is aimed at a particular group of people, it is made known in a way that influences them or makes them interested in something:', 'These advertisements are specifically aimed at young people.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (556, 'airs and graces', 'false ways of behaving that are intended to make other people feel that you are important and belong to a high social class:', 'He was always putting on airs and graces.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (557, 'align yourself with sth/sb', 'to agree with a person or an organization and work with them or support their ideas:', 'The company has a commitment to align itself closely with specialty retailers.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (558, 'alive and well', 'still full of energy and activity:', 'Traditional jazz is still alive and well in Chicago.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (559, 'alive to something', 'If you are alive to something, you are thinking about it or familiar with it:', 'I ski for the excitement, but I''m also always alive to the risks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (560, 'alive with something', 'full of things that are living and moving:', 'The pond was alive with frogs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (561, 'all along', 'from the very beginning:', 'Do you think he''s been cheating us all along?', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (562, 'all along the line', 'ever since the beginning of a relationship or process:', 'The project''s been plagued with financial problems all along the line.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (563, 'all and sundry', 'everyone:', 'I don''t want all and sundry knowing about our problems.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (564, 'all at once', 'suddenly and unexpectedly:', 'All at once there was a loud crashing sound.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (565, 'all day long', 'used to emphasize how much something is true or how much someone can do something:', 'I could eat this cake all day long.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (566, 'all expenses paid', 'If something is all expenses paid, it means that you do not have to pay for anything yourself:', 'She''s going on a trip to New York, all expenses paid.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (567, 'all eyes are on someone/something', 'If all eyes are on someone or something, everyone is watching that person or thing and waiting to see what will happen:', 'All eyes are on the president to see how he will respond to the challenge to his leadership.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (568, 'all good things (must) come to an end', 'said when you accept that even enjoyable experiences cannot last for ever:', 'It''s been a fantastic couple of weeks but all good things must come to an end.', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (569, 'all hell breaks loose', 'If all hell breaks loose, a situation suddenly becomes violent and noisy, especially with people arguing or fighting:', 'One policeman drew his gun and then suddenly all hell broke loose.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (570, 'all in a day''s work', 'If something difficult, unpleasant, or strange is all in a day''s work for someone, it is a usual part of their job:', 'When you''re a nurse, cleaning up vomit is all in a day''s work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (571, 'all in good time', 'used to tell someone to be patient because the thing they are eager for will happen when the time is right:', 'Be patient, you''ll hear the result all in good time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (572, 'all is well', 'everything is in a good or acceptable state:', 'I hope all is well with Jack.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (573, 'all manner of something', 'a lot of different types:', 'There are all manner of architectural styles in the capital.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (574, 'all of a doodah', 'in a state of confusion:', 'She''s all of a doodah about the wedding arrangements.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (575, 'all of a flutter', 'in a state of nervous excitement:', 'Peter was coming round for dinner and I was all of a flutter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (576, 'all of a sudden', 'very quickly:', 'It seemed to happen all of a sudden - I felt dizzy and I just collapsed.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (577, 'all of something', 'used to emphasize the amount or number of something, usually when something is small in a disappointing or unusual way:', 'In the last two years the book has sold all of 200 copies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (578, 'all or nothing', 'relates to doing something either completely or not at all:', 'She either loves you or hates you - it''s all or nothing with her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (579, 'all over somewhere', 'everywhere in a particular place:', 'Soon the news was all over town.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (580, 'all over the place', 'in a lot of different places or in all parts of a place:', 'You can buy T-shirts like this all over the place.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (581, 'all over the place', 'not correct, regular, or well organized; changing a lot without reason:', 'His drumming was all over the place.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (582, 'all roads lead to Rome', 'said to mean that all the methods of doing something will achieve the same result in the end', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (583, 'all that glitters is not gold', 'said about something that seems to be good on the surface, but might not be when you look at it more closely', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (584, 'all the more', 'even more than before:', 'Several publishers rejected her book, but that just made her all the more determined.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (585, 'all the same', 'despite what has just been said:', 'It rained every day of our holiday - but we had a good time all the same.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (586, 'all the time in the world', 'a large amount of time available:', 'The doctor made me feel as if she had all the time in the world to listen to my problems.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (587, 'all the way', 'as much as possible or completely:', 'If you want to bring it up with the boss, I''ll support you all the way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (588, 'all the way to', 'as far as someone or something at a high level in a process or structure:', 'I''ll take my complaint all the way to the managing director.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (589, 'all the while', 'for all of a period of time:', 'There I was thinking you were hard at work and you were upstairs in bed all the while!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (590, 'all things being equal', 'if everything happens as expected:', 'All things being equal, I''ll be at home on Tuesday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (591, 'all things considered', 'Someone might say that something is good all things considered to mean it was generally good although the situation was not perfect:', 'I think the party was great, all things considered - I mean we didn''t have much time to get ready, but it still went well.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (592, 'all things to all people', 'If you try to be all things to all people, you try to do things that will please everyone.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (593, 'all thumbs', 'very awkward with your hands:', 'Can you untangle this thread for me? I''m all thumbs today.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (594, 'all told', 'as a complete total:', 'There were 550 people at the festival all told.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (595, 'all too', 'more than is desirable:', 'The week passed all too quickly, and it was time to go back home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (596, 'all very well', 'If something is all very well, it is fairly useful or good in some situations but not excellent and not useful or good in every situation:', 'Electric heating is all very well until there''s a power cut.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (597, 'all very well/fine/good', 'You say that something is all very well/fine/good if it seems good by itself but you think that there are problems connected with it:', 'It''s all very well to want to get rich quickly, but it isn''t usually that easy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (598, 'all work and no play (makes Jack a dull boy)', 'said to warn someone that they will not be an interesting person by working all the time', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (599, 'all''s fair in love and war', 'in love and war you do not have to obey the usual rules about reasonable behaviour', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (600, 'all/the four corners of the world/earth', 'many different parts of the world:', 'She had invited relatives from the four corners of the world to her 80th birthday party.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (601, 'allow for something', 'to consider something when you are planning something:', 'We allowed for living expenses of £20 a day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (602, 'allow of something', 'If a rule or situation allows of something, it makes it possible:', 'This rule allows of no exceptions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (603, 'allude to someone/something', 'to mention someone or something without talking about him, her, or it directly:', 'She mentioned some trouble that she''d had at home and I guessed she was alluding to her son.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (604, 'ally yourself to/with someone', 'to start to support someone:', 'He allied himself with the left of the party.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (605, 'almost/nearly die of something', 'to feel a particular feeling extremely strongly:', 'I almost/could have died of embarrassment.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (606, 'along the lines of something', 'similar in type:', 'I was thinking of doing a meal along the lines of that dinner I did for Annie and Dave.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (607, 'along the same lines', 'similar:', 'My sister works in publishing, and I’m hoping to do something along the same lines.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (608, 'along the way', 'during the time that something is happening or that you are doing something:', 'I''ve been in this job for 30 years, and I''ve picked up a good deal of expertise along the way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (609, 'always a bridesmaid, never the bride', 'said about someone who is never the most important person in a situation', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (610, 'amen to that', 'said to show that you agree strongly with something that someone has just said:', '"Thank goodness we didn''t go." "Amen to that!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (611, 'amount to something', 'to become a particular amount:', 'Their annual fuel bills amounted to over £6,000.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (612, 'amount to something', 'to be the same as something, or to have the same effect as something:', 'His behaviour amounted to serious professional misconduct.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (613, 'amp someone up', 'to get someone excited:', 'She amped up the crowd.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (614, 'amp something up', 'to make something stronger, more extreme, or more exciting:', 'They are amping up the pressure on their opponents.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (615, 'an Englishman''s home is his castle', 'used to say that English people believe that they should control what happens in their own homes, and that no one else should tell them what to do there', '', 'idiom', '', 'old-fashioned, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (616, 'an abundance of caution', 'the fact that someone is being extremely careful to avoid a particular risk, even if the risk is small:', 'The airline said that out of an abundance of caution they would temporarily ground their entire fleet of planes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (617, 'an accident waiting to happen', 'a very dangerous situation in which an accident is very likely', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (618, 'an ace up your sleeve', 'secret knowledge or a secret skill that will give you an advantage', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (619, 'an acquired taste', 'something that you dislike at first, but that you start to like after you have tried it a few times:', 'Olives are an acquired taste.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (620, 'an apple a day keeps the doctor away', 'This means that eating an apple each day can help to keep you healthy.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (621, 'an arm and a leg', 'a lot of money:', 'These shoes cost me an arm and a leg.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (622, 'an awful lot', 'a very large amount:', 'That red is an awful lot brighter than the color of your house.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (623, 'an ear for something', 'good at hearing, repeating, or understanding music or languages:', 'He realized he had an ear for languages, and decided to study abroad.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (624, 'an early bath', 'used to refer to a situation in which a football player is ordered to leave the pitch during a game because they have done something wrong:', 'After consulting with his assistant, the referee ordered an early bath for both players.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (625, 'an easy touch', 'someone who you can easily persuade or deceive into giving you something, usually money', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (626, 'an elephant in the room', 'If you say there is an elephant in the room, you mean that there is an obvious problem or difficult situation that people do not want to talk about.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (627, 'an embarrassment of riches', 'so many good things or people that it is impossible to decide which of them you want', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (628, 'an eye for an eye', 'the idea that a person who causes another person to suffer should suffer in an equal amount:', 'I don’t believe in that kind of eye for an eye justice.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (629, 'an eye for an eye (and a tooth for a tooth)', 'said to show that you believe if someone does something wrong, that person should be punished by having the same thing done to them', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (630, 'an iron hand/fist in a velvet glove', 'used to describe someone who seems to be gentle but is in fact forceful and determined', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (631, 'an old/a wise head on young shoulders', 'a child or young person who thinks and talks like an older person who has more experience of life', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (632, 'an ounce of prevention is worth a pound of cure', 'It is better to stop something bad from happening than it is to deal with it after it has happened.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (633, 'and all that jazz', 'used when speaking to mean "and other similar things":', 'They sell televisions and radios and all that jazz.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (634, 'and another thing', 'used to introduce one more in a series of arguments or complaints:', 'And another thing, why didn''t you tell me you were going out?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (635, 'and co.', 'and other people:', 'K. Branagh and co. achieved great success in a very short time.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (636, 'and don''t you forget it', 'used to tell someone that a particular fact is important and it should influence the way they behave:', 'I''ve been in the job longer than you and don''t you forget it!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (637, 'and have done with it', 'to deal with and finish the whole matter:', 'I think I''ll just sell all the furniture and have done with it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (638, 'and no mistake', 'added to the end of something you say to emphasize it:', 'He''s a strange man and no mistake.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (639, 'and so on', 'in addition to other things of the same kind:', 'Economic growth makes us all richer, provides jobs, and so on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (640, 'and that''s flat!', 'used to tell someone that the decision you have just announced will not change even if they try to persuade you to change it:', 'I''m not coming, and that''s flat!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (641, 'and the like', 'and other similar things:', 'There are courts for tennis and badminton and the like.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (642, 'and the same to you with (brass) knobs on', 'used to return an insult forcefully to someone who has insulted you', '', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (643, 'and then some', 'and even more:', 'There were 20,000 people and then some at the demonstration.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (644, 'and what have you', 'and other similar things:', 'There were a couple of bags full of old records, magazines, and what have you.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (645, 'angle for something', 'If someone is angling for something, they are trying to get something without asking for it directly:', 'He''s clearly angling for a job/an invitation.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (646, 'annoy, frighten, scare, etc. the hell out of someone', 'to make someone extremely annoyed, frightened, etc.:', 'He jumped out from behind a wall and scared the hell out of her.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (647, 'another/a second bite at/of the cherry', 'another opportunity to do something:', 'He missed a medal in the 100 metres, but will get a second bite of the cherry in the 400 metres.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (648, 'another/the final nail in the coffin', 'an event that causes the failure of something that had already started to fail:', 'Each successive revelation of incompetence is another nail in the chairman''s coffin.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (649, 'answer (someone) back', 'to speak rudely when answering someone in authority:', 'Don''t you dare answer me back, young lady!', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (650, 'answer back', 'to react to criticism by arguing or explaining:', 'The company criticized in the documentary was given the opportunity to answer back.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (651, 'answer for something', 'to be responsible for something bad, or to be punished for something:', 'I expect parents to answer for their children''s behaviour.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (652, 'answer for someone/something', 'If you say that you can answer for someone or for a quality that they have, you mean that you know from experience that they can be trusted, or that they have that quality:', 'I can certainly answer for her professionalism, and whole-heartedly recommend her to any employer.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (653, 'ante up (something)', 'to give money, often unwillingly:', 'At least 200 people have been persuaded to ante up big money for the charity event.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (654, 'any amount of', 'a very large amount of:', 'We had any amount of people applying for the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (655, 'any more', 'If you do not do something or something does not happen any more, you have stopped doing it or it does not now happen:', 'I don''t do yoga any more.', 'idiom', 'A2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (656, 'any number of things', 'a lot of a particular thing:', 'The Cook''s Shop stocks any number of different kinds of pasta.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (657, 'any port in a storm', 'used to say that in a difficult situation, people get help from wherever or whoever they can:', 'When people want to feel better, to gain a measure of comfort, they''ll choose any port in a storm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (658, 'any publicity is good publicity', 'said to emphasize that it is better that something receives bad publicity than no publicity at all', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (659, 'any way you slice it', 'in whatever way the situation is considered:', 'He shouldn''t have hit her, any way you slice it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (660, 'anyone who is/was anyone', 'all the most famous and important people:', 'In those days anyone who was anyone dined in this exclusive little restaurant.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (661, 'anything but', 'used to mean the opposite of the stated quality:', 'She''s meant to be really nice but she was anything but nice when I met her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (662, 'anything like', 'used with negatives to say that someone or something is not at all similar to someone or something else:', 'The pictures on cereal boxes don’t look anything like the actual stuff you eat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (663, 'anything''s possible', 'anything could happen:', 'Well, if your brother can find a woman who''s willing to marry him, then I suppose anything''s possible.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (664, 'anywhere near', 'close in time, quality, distance, or amount:', 'Are we anywhere near finishing yet or is there still some way to go?', 'idiom', 'C1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (665, 'apart from', 'except for:', 'Apart from the low salary, it’s not a bad job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (666, 'appear for someone', 'If a lawyer appears for someone, he or she acts for and represents the person:', 'Ms Hawley was appearing for the defence.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (667, 'appertain to something', 'to be connected to or belong to:', 'She enjoyed the privileges appertaining to the office of chairman.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (668, 'are my eyes deceiving me?', 'something you say when you cannot believe what you see:', 'Is that snow in May, or are my eyes deceiving me?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (669, 'aren’t I?', 'am I not?:', 'I''m getting better at this, aren''t I?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (670, 'argue the toss', 'to disagree with a decision or statement:', 'It doesn''t matter what you say, he''ll always argue the toss!', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (671, 'arm in arm', 'with your arm resting in the curve of another person’s arm:', 'We walked arm in arm through the park.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (672, 'around Robin Hood''s barn', 'going an indirect way to get to your destination, so that it takes a long time:', 'We got so lost that we ended up going around Robin Hood''s barn to get to Tom and Diane''s new house.', 'idiom', '', 'old-fashioned informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (673, 'around and around', 'moving in circles:', 'The skater twirled around and around.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (674, 'around the bend', 'mentally confused or unable to act in a reasonable way:', 'If I''d stayed there any longer I''d have gone around the bend.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (675, 'arrive at something', 'to reach an agreement about something:', 'We all argued about it for hours and eventually arrived at a decision.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (676, 'arse about/around', 'a rude phrase meaning to act in a silly way or waste time:', 'I wish he''d stop arsing around and actually do some work.', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (677, 'as (if) to the manner born', 'If you do something as (if) to the manner born, you do it very well and very naturally as if it is usual and easy for you.', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (678, 'as American as apple pie', 'very typical and normal in America:', 'He defended his driving, saying "fast cars are as American as apple pie."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (679, 'as a (general) rule', 'usually:', 'As a general rule, I don''t read detective novels.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (680, 'as a last resort', 'if all other methods fail:', 'British police are supposed to use guns only as a last resort.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (681, 'as a matter of course', 'If something is done as a matter of course, it is a usual part of the way in which things are done and is not special:', 'Safety precautions are observed as a matter of course.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (682, 'as a matter of fact', 'used to add something more to what you have just said:', 'The shoes are still stylish, and as a matter of fact , I''m wearing a pair right now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (683, 'as a matter of fact', 'used to say that you do not agree with what someone has just said or that the opposite of what they say is true:', 'We''re not losing population in our town. As a matter of fact, people are moving in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (684, 'as a whole', 'when considered as a group and not in parts:', 'The population as a whole is getting healthier.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (685, 'as against', 'compared to:', 'He earns $80,000 a year, as against my $40,000.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (686, 'as and when', 'at the time that something happens:', 'We don''t own a car - we just rent one as and when we need it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (687, 'as dry as a bone', 'extremely dry:', 'I don''t think he''s been watering these plants - the soil is as dry as a bone.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (688, 'as every schoolboy/schoolchild knows', 'used before you mention a fact that is familiar to everyone, including children:', 'As every schoolboy knows, the earth revolves around the sun.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (689, 'as far as it goes', 'used to say that something has good qualities but could be better:', 'It''s a good essay as far as it goes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (690, 'as far as someone is concerned', 'according to what someone thinks or feels:', 'There’s no reason to wait, as far as I’m concerned.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (691, 'as far as someone knows', 'based on what someone knows:', 'As far as I know, he isn’t coming until tomorrow.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (692, 'as far as the eye can/could see', 'for a long distance until something is so far away and small it cannot be seen any more:', 'The road stretched into the distance as far as the eye could see.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (693, 'as fast as your legs would carry you', 'as quickly as possible:', 'He scuttled back into the house as fast as his legs would carry him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (694, 'as follows', 'the ones named here:', 'The winners were as follows – Smith, Mitchell, Glowser, and Bryce.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (695, 'as for someone/something', 'used to talk about how another person or thing is affected by something:', 'As for Louise, well, who cares what she thinks.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (696, 'as fuck', 'used for emphasizing something:', 'He''s as boring as fuck.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (697, 'as good as', 'almost:', 'The decorating is as good as finished - I just need to finish off the painting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (698, 'as guilty/miserable/ugly as sin', 'very guilty, miserable, or ugly', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (699, 'as husband and wife', 'in the same way as two people who are married:', 'Although never married, they lived together as husband and wife for 50 years.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (700, 'as if it is going out of style', 'very quickly or much more than people normally do:', 'She was gulping down sandwiches and cakes as if they were going out of style.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (701, 'as if you owned the place', 'in a way that is too confident:', 'He walked into the office as if he owned the place.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (702, 'as if!', 'said to show that you do not believe something is possible:', '"Did you get a pay rise?" "As if!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (703, 'as if/as though', 'in a way that seems to show something:', 'She acted as though she had never seen me before, when I''d just met her at lunch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (704, 'as if/though', 'used to describe how a situation seems to be:', 'She looked as if she''d had some bad news.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (705, 'as is', 'in the state that something is in at the present time:', 'Will you wait till it''s finished or take it home as is?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (706, 'as it comes', 'If someone asks how they should prepare your drink and you say as it comes, you mean that any way will be acceptable:', '"How do you like your coffee?" "Oh, as it comes."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (707, 'as it is', 'already:', 'I''m not buying the children anything else today - I''ve spent far too much money as it is.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (708, 'as it were', 'sometimes said after a figurative (= not meaning exactly what it appears to mean) or unusual expression:', 'If he still refuses we could always apply a little pressure, as it were.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (709, 'as long as', 'if:', 'You can have a dog as long as you promise to take care of it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (710, 'as luck would have it', 'by chance:', 'We ran out of petrol on the way home, but as luck would have it, we were very near a garage.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (711, 'as much', 'If you say that you thought/expected/said as much, it means that something bad that you thought/expected/said would happen has happened:', 'I knew he''d fail - I said as much at the time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (712, 'as much', 'the same:', 'Go on, lend me the money - you know I''d do as much for you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (713, 'as much again', 'the same amount again:', 'My fare was £10, and it was almost as much again for the children.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (714, 'as much as', 'almost:', 'He as much as admitted that it was his fault.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (715, 'as much as the next person', 'as much as anyone would:', 'I enjoy winning awards as much as the next guy, but other things are more important to me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (716, 'as much as you can do', 'If you say something is as much as you can do, you manage to do it, but with great difficulty:', 'I felt so ill this morning, it was as much as I could do to get out of bed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (717, 'as never before', 'in a way that has never been possible before:', 'Satellite technology offers the opportunity, as never before, for continuous television coverage of major international events.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (718, 'as of', 'starting from a particular time:', 'As of next month, all the prices will go up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (719, 'as of/from', 'starting from a particular time or date:', 'As of next month, all the airline''s fares will be going up.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (720, 'as old as Methuselah', 'used to say that someone is very old', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (721, 'as old as the hills', 'very old:', 'My grandfather seemed as old as the hills to me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (722, 'as one man', 'If a group of people do something as one man, they do it together at exactly the same time:', 'As one man, the delegates made for the exit.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (723, 'as opposed to', 'rather than; instead of:', 'The box is made of plastic, as opposed to wood.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (724, 'as per instructions', 'according to the instructions:', 'I had two spoonfuls after lunch, as per instructions.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (725, 'as per usual/normal', 'as usual:', 'Carlo turned up without any money, as per usual.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (726, 'as regards', 'fmlabout; relating to:', 'There is no problem as regards the financial arrangements.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (727, 'as safe as houses', 'very safe', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (728, 'as smooth as silk/a baby''s bottom', 'extremely smooth:', 'Her skin was as smooth as silk.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (729, 'as soon as', 'in the shortest possible time:', 'We’ll come as soon as we can.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (730, 'as such', 'using the exact meaning of the word or phrase:', 'There weren’t many vegetarian dishes as such, although there were several different kinds of cheese.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (731, 'as the actress said to the bishop', 'used to show that someone has said something that could have another meaning connected to sex:', 'It slides right into the hole, as the actress said to the bishop.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (732, 'as the crow flies', 'used to say that a distance is measured in a straight line between two points or places', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (733, 'as to', 'about:', 'He was uncertain as to which road to take.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (734, 'as to/for', 'changing the subject to:', 'As to where we''ll get the money from, we''ll talk about that later.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (735, 'as usual', 'in a way that often happens and is expected:', 'As usual, she was wearing jeans.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (736, 'as well', 'also; too:', 'They advertised the new movie on television, and in newspapers as well.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (737, 'as well as', 'in addition; and also:', 'We have a responsibility to our community as well as to our families.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (738, 'as ye sow, so shall ye reap', 'used to mean that the way you behave in life will affect the treatment you will receive from others', '', 'idiom', '', 'literary, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (739, 'as you wish/like', 'used to agree to a request, especially when you do not approve:', '"I think we should leave now." "Very well. As you wish."', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (740, 'as, if, when, etc. the spirit moves someone', 'taking action only when you feel is the right time, not following a plan:', 'It''s impossible to predict what he''ll do - he just acts when the spirit moves him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (741, 'as... as anything', 'used to add emphasis to an adjective or adverb:', 'He''s as fat as anything (= very fat).', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (742, 'ascend the throne', 'to become queen or king', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (743, 'ascribe something to something', 'to believe or say that something is caused by something else:', 'To what do you ascribe your phenomenal success?', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (744, 'ascribe something to someone', 'to believe or claim that something was said, written, or created by a particular person:', 'After years of research, scholars have finally ascribed this anonymous play to Christopher Marlowe.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (745, 'ascribe something to someone/something', 'to believe that a particular quality or feature belongs to or is typical of someone or something:', 'People like to ascribe human feelings to animals.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (746, 'aside from', 'except for; besides:', 'I don’t watch any television, aside from the news.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (747, 'ask about someone', 'to ask for information about someone, especially about his or her health:', 'Tell your father I was asking about him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (748, 'ask after someone', 'to ask for information about someone, especially about their health:', 'Tell your father I was asking after him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (749, 'ask around', 'to ask a lot of different people in order to get information or help:', 'Our babysitter''s just moved away, so we''re asking around for a replacement.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (750, 'ask for someone', 'to say that you would like to see or speak to someone:', 'A young man was here asking for you this morning.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (751, 'ask for someone/something', 'If you say you couldn''t ask for someone or something better, you mean that that person or thing is the best of their type:', 'She''s great to work for - I really couldn''t ask for a better boss.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (752, 'ask sb back', 'to ask someone that you have seen already to come back for a second interview for a job:', 'I made a mess of the interview and I wasn''t asked back.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (753, 'ask someone in', 'to invite someone to come into a building or room, especially your home:', 'I''d ask you in for a coffee but I have to get up early for work in the morning.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (754, 'ask someone out', 'to invite someone to come with you to a place such as the cinema or a restaurant, especially as a way of starting a romantic relationship:', 'She''s asked Steve out to the cinema this evening.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (755, 'asking for trouble', 'behaving in a way that is likely to cause problems for you:', 'If you wear light shoes for a long walk you''re asking for trouble.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (756, 'aspire to something', 'to have a strong wish or hope to do or have something:', 'Few people who aspire to fame ever achieve it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (757, 'assign someone to something', 'to choose someone to do a particular job:', 'Which police officer has been assigned to this case?', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (758, 'associate with someone', 'to spend time with a group of people, especially people who are disapproved of:', 'I don''t want my children associating with drug addicts and alcoholics.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (759, 'at (your) leisure', 'when you want to and when you have time to:', 'You can take the documents home and study them at (your) leisure.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (760, 'at His/Her Majesty''s pleasure', 'Someone who is put in prison at His/Her Majesty''s pleasure is kept there until it is officially decided that it is safe to release them:', 'He was declared insane and ordered to be detained in a mental hospital at Her Majesty''s pleasure.', 'idiom', '', 'specialized', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (761, 'at a loss', 'not knowing what to do:', 'I’m at a loss to explain what happened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (762, 'at a low ebb', 'in a bad or weak state:', 'Consumer confidence is currently at a low ebb.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (763, 'at a moment''s/two hours''/three weeks'', etc. notice', 'used to emphasize how little time someone has to do something or how little warning is given:', 'We can''t be expected to just drop everything and leave at a moment''s notice.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (764, 'at a pinch', 'Something that you can do at a pinch can be done if it is really necessary, but it will be difficult, not perfect, or not what you would really like:', 'I need £2,000 to set up the business, but I suppose £1,500 would do at a pinch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (765, 'at a price', 'for a lot of money:', 'She''ll decorate your house however you want it – at a price.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (766, 'at a push', 'If you can do something at a push, you can do it but it will be difficult:', 'At a push I could be there by eight o''clock.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (767, 'at a rate of knots', 'If someone does something at a rate of knots, they do it very quickly:', 'She got through her work at a rate of knots.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (768, 'at a snail''s pace', 'extremely slowly:', 'The roads were full of traffic and we were travelling at a snail''s pace for two hours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (769, 'at a stretch', 'continuously:', 'Sometimes I work for ten hours at a stretch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (770, 'at a time', 'during any one period:', 'I can only do one thing at a time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (771, 'at all cost(s)', 'If something must be done or avoided at all costs, it must be done or avoided whatever happens:', 'Security during the president''s visit must be maintained at all costs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (772, 'at an angle', 'not straight:', 'The picture was hanging at an angle, so I straightened it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (773, 'at any cost', 'no matter what dangers or difficulties are involved:', 'We realized we had to fight the lawsuit at any cost.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (774, 'at any price', 'If you want something at any price, you are willing to do anything in order to get it:', 'He wanted success at any price.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (775, 'at any rate', 'whatever happens:', 'Well, I''m not going home on foot, at any rate.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (776, 'at any rate', 'something you say to show that you are going to say something more exactly:', 'I don''t think they liked my idea. At any rate, they weren''t very enthusiastic about it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (777, 'at arm’s length', 'as far away from your body as possible:', 'He held the snake at arm''s length.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (778, 'at bat', 'taking your turn to try to hit the ball in a baseball game:', 'I struck out almost every time I was at bat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (779, 'at bat', 'the time when it is your turn to try to hit the ball in a baseball game:', 'In a nine-inning game you might get four or five at bats.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (780, 'at bay', 'If an animal is at bay, it is about to be caught or attacked.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (781, 'at best', 'even if the best possible result happens:', 'If he drops the course now, at best he’ll get an incomplete, and he could fail.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (782, 'at bottom', 'in a basic way:', 'Jealousy is, at bottom, a lack of self-confidence.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (783, 'at close quarters/range', '(from) a short distance away:', 'When you see famous people at close quarters, they always appear much smaller than you imagined them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (784, 'at cost', 'without a profit:', 'We bought the furniture at cost from a friend who works in the furniture business.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (785, 'at each other''s throats', 'If two people are at each other''s throats, they are arguing angrily:', 'Those two are always at each other''s throats.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (786, 'at every turn', 'If something unpleasant happens at every turn, it happens every time you try to do something:', 'They do their best to frustrate my efforts at every turn.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (787, 'at face value', 'for what something appears to be:', 'I took the offer at face value because I didn’t think they would try to trick me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (788, 'at first', 'in or at the beginning:', 'At first, I thought he was joking but then I realized he meant it.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (789, 'at first blush', 'when you first see or experience something:', 'It looks at first blush like a standard smartphone.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (790, 'at first glance', 'when first considering something, before having a chance to look at it carefully:', 'At first glance the deal looked wonderful, but after reading the fine print he wasn’t so sure.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (791, 'at full tilt', 'as fast as possible:', 'The plant is operating at full tilt to cope with demand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (792, 'at full/half throttle', 'at full/half speed or power:', 'He''s working at full throttle (= as hard as he can) to get the job finished.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (793, 'at gunpoint', 'while threatening to use a gun:', 'He was robbed at gunpoint in his shop three years ago.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (794, 'at hand', 'near in time or position:', 'We want to ensure that help is at hand (= easily available) for all children suffering abuse.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (795, 'at heart', 'used to say what someone is really like:', 'He had dozens of friends, but he was a private person at heart.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (796, 'at large', 'generally:', 'This group is not representative of the population at large.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (797, 'at least', 'as much as, or more than, a number or amount:', 'It will cost at least $100.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (798, 'at least', 'used to reduce the effect of a statement:', 'I''ve met the president - at least, he shook my hand once.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (799, 'at least', 'used to emphasize that something is good in a bad situation:', 'It''s a small house but at least there''s a garden.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (800, 'at least', 'used to say that someone should do something small, even if they do nothing else:', 'Even if she didn''t want to send a present, she could at least have sent a card.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (801, 'at long last', 'finally, after much waiting:', 'At long last the government is starting to listen to our problems.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (802, 'at loose ends', 'not knowing what to do, esp. because of an upsetting change:', 'I was at loose ends after finishing school and not being able to find a job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (803, 'at odds (with someone/something)', 'in disagreement:', 'The two brothers were always at odds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (804, 'at once', 'immediately:', 'You have to call him at once .', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (805, 'at once', 'At once also means at the same time:', 'Everything happened at once – she graduated, got a job, and got married, all in June!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (806, 'at one with the world', 'happy because you feel that you belong in the world and generally agree with what happens', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (807, 'at one/this etc. remove', 'separated from something such as an event by an amount of time, by your feelings, or by other events:', 'Charlotte felt she was at one remove from reality.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (808, 'at peace', 'a gentle way of saying that someone is dead:', 'Now she is at peace and her suffering is over.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (809, 'at peace with something/yourself', 'feeling calm and relaxed about something or yourself:', 'She seems at peace with herself .', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (810, 'at sea', 'confused:', 'I''m all/completely at sea with the new computer system.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (811, 'at short notice', 'only a short time before something happens:', 'I can''t cancel my plans at such short notice.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (812, 'at sixes and sevens', 'in a confused, badly organized, or difficult situation:', 'We''ve been at sixes and sevens in the office this week.', 'idiom', '', 'informal, old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (813, 'at someone''s beck and call', 'always willing and able to do whatever someone asks:', 'Go and get it yourself! I''m not at your beck and call, you know.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (814, 'at someone''s elbow', 'close to and a little behind someone:', 'During the visit, the interpreter was always at her elbow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (815, 'at stake', 'If something that is valuable is at stake, it is in a situation where it might be lost:', 'Thousands of lives will be at stake if emergency aid does not arrive in the city soon.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (816, 'at the best of times', 'when everything is going well:', 'Our car is slow even at the best of times.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (817, 'at the coalface', 'doing the work involved in a job, in real working conditions, rather than planning or talking about it:', 'At the coalface with a deadline looming, you sometimes feel under a lot of pressure.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (818, 'at the crack of dawn', 'very early in the morning, especially at the time when the sun first appears:', 'We''ll have to leave at the crack of dawn.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (819, 'at the drop of a hat', 'If you do something at the drop of a hat, you do it immediately without stopping to think about it:', 'People will file lawsuits at the drop of a hat these days.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (820, 'at the end of the day', 'something that you say before you give the most important fact of a situation:', 'Of course I''ll listen to what she has to say but at the end of the day, it''s my decision.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (821, 'at the end of your rope', 'having no strength or patience left:', 'By six o''clock after a busy day I''m at the end of my rope.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (822, 'at the end of your tether', 'having no strength or patience left:', 'By six o''clock after a busy day I''m at the end of my tether.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (823, 'at the expense of someone', 'making another person look silly:', 'Would you stop making jokes at my expense?', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (824, 'at the expense of something', 'If you do one thing at the expense of another, doing the first thing harms the second thing:', 'He had no need to protect their reputation at the expense of his own.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (825, 'at the hands of someone', 'If you suffer at the hands of someone, they hurt you or treat you badly:', 'How many people have died at the hands of terrorist organizations?', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (826, 'at the helm (of something)', 'in control:', 'She is the first woman to be at the helm of this corporation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (827, 'at the push of a button', 'very easily:', 'You can''t expect to get everything you need at the push of a button.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (828, 'at the risk of doing something', 'used before you say something that may seem offensive or stupid:', 'At the risk of seeming rude, I''m afraid I have to leave now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (829, 'at the same time', 'used to mention something that must be considered in addition to what you have just said:', 'No one likes conflict, but at the same time we have to deal with this problem.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (830, 'at the stroke of a pen', 'If something is done at the stroke of a pen, it is done quickly and easily by someone:', 'Politicians know they cannot create a lawful society simply at the stroke of a pen.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (831, 'at the top of your lungs', 'extremely loudly:', 'She shouted his name at the top of her lungs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (832, 'at the top of your voice', 'extremely loudly:', 'She shouted his name at the top of her voice.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (833, 'at this rate', 'if the situation stays as it is:', 'At this rate, we won''t be home until midnight.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (834, 'at variance', 'fml different:', 'The official census count was at variance with the count we had made.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (835, 'at will', 'If you can do something at will, you can do it any time you want:', 'He can cry at will.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (836, 'at work', 'doing a job:', 'Bob’s at work on that software.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (837, 'at your command', 'If you have particular qualities at your command, you are able to use them effectively:', 'As a writer, she has both style and humour at her command.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (838, 'at your command', 'If someone says that they are at your command, that person is willing to do what you ask:', '"I can''t reach my zip - could you unfasten it, please?" "I''m at your command!"', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (839, 'at your disposal', 'able to be used by you; able to help you:', 'I don’t have a car at my disposal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (840, 'at your fingertips', 'If you have information at your fingertips, you can get it and use it very easily:', 'He has all the latest statistics at his fingertips.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (841, 'at your leisure', 'when you want to and have the time:', 'You can study the documents at your leisure.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (842, 'at your mother''s knee', 'If you learned something at your mother''s knee, you learned it when you were a child:', 'I learned to sew at my mother''s knee.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (843, 'at your wits’ end', 'so worried, confused, or annoyed that you do not know what to do next:', 'She was at her wits’ end trying to figure out how to control her 14-year-old son.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (844, 'at your worst', 'less active or intelligent than you are at other times:', 'I''m at my worst first thing in the morning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (845, 'at your worst', 'showing the most unpleasant side of someone''s character:', 'This problem over late payment has shown him at his worst.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (846, 'at worst', 'used to say what the most unpleasant or difficult situation could possibly be:', 'At worst, she can only tell you off for being late.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (847, 'at worst', 'considering someone or something in the most negative or unkind way possible:', 'She is at worst corrupt, and at best has been knowingly breaking the rules.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (848, 'at/for a price', 'If you can buy or get something at/for a price, you either have to pay a lot of money or be involved in something unpleasant in order to get it:', 'You can buy the best of gourmet cuisine here, for a price.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (849, 'at/in one fell swoop', 'If you do something at/in one fell swoop, you do it all at the same time:', 'I got all my Christmas shopping done in one fell swoop.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (850, 'at/in one sitting', 'during one limited period of time, without stopping:', 'I enjoyed the book so much that I read it all in one sitting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (851, 'at/in the back of your mind', 'If something is at/in the back of your mind, you intend to do it, but are not actively thinking about it:', 'It''s been at the back of my mind to call José for several days now, but I haven''t got round to it yet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (852, 'at/on the double', 'very quickly and without any delay', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (853, 'at/on the stroke of something', 'exactly at a particular time:', 'Fireworks started at the stroke of ten.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (854, 'atone for something', 'to do something that shows that you are sorry for something bad that you did:', 'The country''s leader has expressed a wish to atone for his actions in the past.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (855, 'attach something to something', 'To attach a particular quality to something is to consider it to have that quality:', 'I don''t attach any importance/significance to these rumours.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (856, 'attach to someone/something', 'If you say that a particular quality attaches to someone or something, you mean that they have that quality:', 'Don''t worry - it was an accident and no blame attaches to either of you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (857, 'attach yourself to someone/something', 'If you attach yourself to a person or group, you join him, her, or it, usually for a limited period of time:', 'Being on his own, he attached himself to a noisy group at the bar.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (858, 'attend to someone/something', 'to help someone or deal with something:', 'Doctors tried to attend to the worst injured soldiers first.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (859, 'attribute something to someone', 'to think that someone or something has a particular quality or feature:', 'I wouldn''t dream of attributing such a lack of judgment to you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (860, 'attribute something to someone/something', 'to say or think that something is the result or work of something or someone else:', 'The doctors have attributed the cause of the illness to an unknown virus.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (861, 'autumn years', 'Someone''s autumn years are the later years of their life, especially after they have stopped working.', '', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (862, 'avail yourself of something', 'to make use of something:', 'Employees should avail themselves of the opportunity to buy cheap shares in the company.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (863, 'avail of something', 'to make use of something:', 'Near and distant relations from Dublin availed of his hospitality in a constant procession.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (864, 'average out at something', 'to have a particular number or amount as the average:', 'My annual holiday varies, but it averages out at five weeks a year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (865, 'average something out', 'to calculate the average of a set of numbers or amounts:', 'If I average out what I earn a month, it''s about £1,500.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (866, 'average out', 'to be or become equal in amount or number:', 'The highs and lows of life tend to average out in the end.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (867, 'avoid something like the plague', 'to be determined to avoid something completely:', 'I''m not a fan of parties - in fact I avoid them like the plague.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (868, 'awaken (something) in someone', 'If a wish, interest, or emotion awakens or is awakened in you, you notice it for the first time:', 'My holiday in Paris awakened a passion for French food in me.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (869, 'awaken someone to something', 'If you awaken someone to something, you make them notice it or make them remember it:', 'I awakened him to his responsibilities for his children.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (870, 'back and forth', 'moving first in one direction and then in the opposite one:', 'She swayed gently back and forth to the music.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (871, 'back away', 'to move backwards away from something or someone, usually because you are frightened:', 'She saw that he had a gun and backed away.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (872, 'back away', 'to show that you do not support a plan or idea any longer and do not want to be involved with it:', 'The government has backed away from plans to increase taxes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (873, 'back down', 'to admit that you were wrong or that you have been defeated:', 'Eventually, Roberto backed down and apologized.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (874, 'back east', 'to or in the east of the US:', 'Helen lived in Oregon for two years before moving back east.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (875, 'back in the day', 'used for talking about a time in the past, usually when you are remembering nice things about that time:', 'Back in the day, we had an apartment with a swimming pool.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (876, 'back in the saddle', 'doing something that you stopped doing for a period of time', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (877, 'back off', 'to stop being involved in a situation, usually in order to allow other people to deal with it themselves:', 'She started to criticize me, then she suddenly backed off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (878, 'back off', 'to move backwards away from someone, usually because you are frightened:', 'I saw the knife and backed off.', 'phrasal verb', 'B2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (879, 'back onto something', 'If a building backs onto something, its back faces that thing:', 'The house backs onto a narrow alley.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (880, 'back out', 'to decide not to do something that you had said you would do:', 'You agreed to come. You can''t back out now!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (881, 'back out (of sth)', 'to decide not to do something that you had said you would do:', 'The buyer backed out of the deal the day before they were due to sign the contract.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (882, 'back someone up', 'to support or help someone:', 'My family backed me up throughout the court case.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (883, 'back someone up', 'to say that someone is telling the truth:', 'Honestly, that''s exactly what happened - Claire will back me up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (884, 'back something up', 'to prove something is true:', 'His claims are backed up by recent research.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (885, 'back something up', 'to make an extra copy of computer information:', 'Make sure you back up your files.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (886, 'back (something) up', 'to drive backwards', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (887, 'back up', 'If traffic backs up, the vehicles have to wait in a long line because there are too many of them:', 'The traffic is starting to back up on the M25.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (888, 'back the wrong horse', 'to make the wrong decision and support a person or action that is later unsuccessful:', 'In all his years as a book publisher, he rarely backed the wrong horse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (889, 'back then', 'at a particular time in the past that you are talking about:', 'Things were different back then.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (890, 'back to basics', 'returning to the simple and most important things', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (891, 'back to square one', 'If you are back to square one, you have to start working on a plan from the beginning because your previous attempt failed completely:', 'If this doesn''t work we''re back to square one.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (892, 'back to the drawing board', 'back to the beginning of a process to start it again, because it is not working', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (893, 'bad feelings', 'a situation in which people are upset or mad at each other:', 'I''d like to complain to the neighbors about the noise, but I don''t want to cause any bad feelings (between us).', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (894, 'bad/big boy', 'an impressive, big, etc. example of a type of thing:', 'If you''re looking for the tastiest grilled cheese sandwich in town, you will find it with this bad boy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (895, 'bad/hard/tough luck!', 'said to express sympathy with someone when something bad has happened to them:', '"They''ve just run out of tickets." "Oh, bad luck!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (896, 'badge in', 'to show a badge or something similar in order to get into your place of work, etc.:', 'A signal is sent to automatically power up the workstation when an employee badges into the site.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (897, 'bags I...', 'used when you claim the right to have something or do something:', 'Bags I sit in the front seat! (= I said I wanted to do it first, so I should do it, not you.)', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (898, 'bags of something', 'a lot of something:', 'Come and stay with us - we''ve got bags of room.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (899, 'bags under someone''s eyes', 'dark circles, sometimes with loose or swollen skin, under the eyes, usually as a result of being tired or ill:', 'I''d been up late the night before , and I had huge bags under my eyes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (900, 'bah humbug', 'an expression used when someone does not approve of or enjoy something that other people enjoy, especially a special occasion such as Christmas:', '31% of people think we spend too much time shopping for presents. Bah humbug!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (901, 'bail out', 'to jump out of an aircraft with a parachute because the aircraft is going to have an accident:', 'The plane''s engine failed and the pilot was forced to bail out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (902, 'bail out', 'to stop doing or being involved with something:', 'The actor has bailed out of the film after only three weeks'' shooting.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (903, 'bail someone out', 'to pay money to a court so that someone can be released from prison until their trial', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (904, 'bail someone/something out', 'to help a person or organization that is in difficulty, usually by giving or lending them money:', 'She keeps running up huge debts and asking friends to bail her out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (905, 'bail something out', 'to remove water from the bottom of a boat', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (906, 'balance (something) out/up', 'to be equal in amount or value, or to make things equal in amount or value:', 'I spend a lot one month and not so much the next and in the end it balances out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (907, 'balance something against something', 'to compare the advantages and disadvantages of something:', 'The ecological effects of the factory need to be balanced against the employment it generates.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (908, 'balance the budget', 'to make the amount of money spent in a budget (= financial plan) equal the amount of money taken in during a particular period:', 'The government is required to balance the budget.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (909, 'bale out', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (910, 'ball up', 'to form into the shape of a ball:', 'The ants'' nest survives floods by balling up around the queen and rolling until it reaches something dry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (911, 'ball up', 'to sit or lie in a position with your arms and legs close to your body:', 'Unable to open the front door, she flopped down, balled up and threw a tantrum.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (912, 'ball something up', 'to form or wrap something into the shape of a ball:', 'He balled up his fists and shook them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (913, 'ball something up', 'to form your body into a round shape:', 'He was balled up in the corner crying.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (914, 'balls (something) up', 'to spoil something by making a mistake or doing something stupid:', 'Trust me to balls up the interview!', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (915, 'band together', 'to join together as a group in order to be able to do something better:', 'We decided to band together and organize a protest.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (916, 'bandy something about', 'to talk about something without careful consideration:', 'Wild guesses of the value of the painting were being bandied about.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (917, 'bandy something around', 'to mention something often, without considering it carefully:', 'Large figures were bandied around, but no money was ever paid.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (918, 'bandy words', 'to argue:', 'I haven''t come here to bandy words with you.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (919, 'bang for the buck', 'value in return for your money:', 'They’re very careful when they spend money, and they’re going to insist on getting the most bang for their buck.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (920, 'bang goes something', 'said when you have just lost the opportunity to do something:', 'He says I have to work late tonight - so bang goes my trip to the cinema.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (921, 'bang on', 'to talk about something for a long time, especially in a way that is boring to other people:', 'My parents are always banging on about how much better life was 20 years ago.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (922, 'bang someone up', 'to lock someone up, especially in prison:', 'She''s terrified of him and won''t make a statement until he''s banged up in the cells.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (923, 'bang up someone/something', 'to damage or injure someone or something by hitting them:', 'He banged up the car backing out of the garage.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (924, 'bang to rights', 'in the act of doing something wrong or illegal:', 'He was breaking the speed limit and knew he''d been caught bang to rights.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (925, 'bang/beat the drum', 'to speak enthusiastically about a belief or idea in order to persuade other people to support it too:', 'Labour are banging the drum for a united Europe.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (926, 'bank on someone/something', 'to expect something or depend on something happening:', 'Can I bank on your support?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (927, 'bare naked', 'completely naked:', 'He used to walk around the house bare naked.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (928, 'bare your heart/soul', 'to tell someone your secret thoughts and feelings:', 'We don''t know each other that well. I certainly wouldn''t bare my soul to her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (929, 'bargain for/on something', 'to expect or be prepared for something:', 'We hadn''t bargained on such a long wait.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (930, 'bargain on something', 'to expect something to happen:', 'We hadn’t bargained on an entire week of rain.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (931, 'bargain something away', 'to exchange something good for something of less value:', 'I realized that by trying to gain security I had bargained away my freedom.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (932, 'barge in', 'to walk into a room quickly, without being invited:', 'I wish he''d knock instead of just barging in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (933, 'barge in', 'to interrupt rudely:', 'Sorry to barge in, but I couldn''t help overhearing what you were saying.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (934, 'barking up the wrong tree', 'trying to do something in a way that will not work:', 'His attorney suggested that the investigators might be barking up the wrong tree.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (935, 'barrack for someone', 'to shout encouragement to the players in a team', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (936, 'base something on something', 'If you base something on facts or ideas, you use those facts or ideas to develop it:', 'The film is based on a short story by Thomas Mann.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (937, 'bash on', 'to continue doing something that is difficult, boring, or takes a long time:', 'Oh well, that''s enough chatting. I suppose I''d better bash on with this essay.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (938, 'bask in something', 'to take pleasure from something that makes you feel good:', 'He basked in his moment of glory, holding the trophy up to the crowd.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (939, 'bask/bathe in reflected glory', 'to feel successful and admired for something, despite the fact that you did not achieve it yourself but were only connected to it in some way:', 'The government is bathing in the reflected glory of its victorious military forces.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (940, 'bat a thousand', 'to get something completely right; to do something perfectly:', 'We''re batting a thousand, here, since we got both boys to school with time to spare.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (941, 'bat around', 'in baseball, if a team bats around, it continues an inning (= turn to play) so that the player who had the first turn to bat in the inning has another turn before the inning is over:', 'Texas batted around in the fourth inning and scored five runs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (942, 'bat something around', 'to discuss something such as an idea or problem, usually without reaching any definite decision:', 'We spend a couple of hours batting around marketing strategies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (943, 'bat something back', 'to deal easily with something such as a question or criticism, often by replying with your own question or criticism:', 'We admired how he batted back reporters'' questions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (944, 'bat something/someone away', 'to push or hit something or someone away from you, with your hand or with an object:', 'I sat on the porch batting away mosquitoes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (945, 'bat something/someone away', 'to refuse to deal with someone or with something such as a question, criticism, or request:', 'He batted away the suggestion that he should resign.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (946, 'batten down the hatches', 'to fasten the entrances to the lower part of a ship using wooden boards', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (947, 'batten down the hatches', 'to prepare for a difficult situation:', 'When you''re coming down with flu all you can do is batten down the hatches and wait for it to pass.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (948, 'batten on someone', 'to live well by using someone else''s money:', 'He''s spent these last five years battening on a rich aunt of his.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (949, 'battle of wits', 'the situation in which two people or two groups use their intelligence and ability to think quickly to try to defeat each other', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (950, 'bawl someone out', 'to tell someone angrily that something they have done is wrong:', 'He''s always bawling people out in meetings.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (951, 'bay for blood', 'If a group of people are baying for blood, they want someone to be hurt or punished:', 'By now the crowd was baying for blood.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (952, 'be (a) no go', 'to be impossible or not effective, or to not happen:', 'They tried for hours to get her to come down from the roof, but it was a no go.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (953, 'be (a) party to something', 'to be involved in something, especially something bad', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (954, 'be (all) downhill', 'to be much easier:', 'Once we get the preparation done, it''ll be downhill all the way.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (955, 'be (all) downhill', 'to get worse; to be less successful:', 'The job went well at first, but then I got sick and it''s been downhill ever since.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (956, 'be (all) over bar the shouting', 'If an activity is all over bar the shouting, the result of it is known, but it has not been officially finished or announced, so people can still say that a different result is possible:', 'With practically all the results declared, the Nationalist Party has 68 percent of the vote, so it''s all over bar the shouting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (957, 'be (all) part of life''s rich tapestry/pageant', 'to be one of the difficult or bad experiences that is part of a full and interesting life', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (958, 'be (all) sweetness and light', 'to be very peaceful and friendly:', 'They''d had a big argument yesterday, but by this morning it was all sweetness and light again.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (959, 'be (all) the rage', 'to be very popular at a particular time:', 'Long hair for men was all the rage in the 70s.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (960, 'be (as) busy as a bee', 'to be moving about quickly doing many things', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (961, 'be (as) cold as ice', 'to be extremely cold:', 'Feel my toes - they''re as cold as ice.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (962, 'be (as) daft as a brush', 'to be very silly:', 'He''s a nice enough boy, but he''s as daft as a brush.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (963, 'be (as) dead as a/the dodo', 'to not be important or popular any longer:', 'Letter-writing is as dead as the dodo.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (964, 'be (as) dull as ditchwater', 'to be very boring', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (965, 'be (as) fit as a fiddle', 'to be very healthy and strong:', 'My grandmother''s 89, but she''s as fit as a fiddle.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (966, 'be (as) flat as a pancake', 'to be very flat:', 'The land in that area is as flat as a pancake.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (967, 'be (as) good as gold', '(of a child) to behave very well:', 'She''s been as good as gold all morning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (968, 'be (as) good as new', 'to be in very good condition:', 'A coat of paint and it will be as good as new.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (969, 'be (as) light as a feather', 'to be very light in weight', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (970, 'be (as) nutty as a fruitcake', 'to be a very strange or crazy person', '', 'idiom', '', 'informal, offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (971, 'be (as) old as the hills', 'to be very old', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (972, 'be (as) plain as the nose on your face', 'to be very obvious:', 'He''s not happy here - that''s as plain as the nose on your face.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (973, 'be (as) right as rain', 'to feel healthy or well again:', 'You just need a good night''s sleep, and then you''ll be right as rain again.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (974, 'be (as) solid as a rock', 'to be very strong:', 'I always thought their marriage was solid as a rock.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (975, 'be (as) thick as thieves', 'to be very close friends and share secrets, etc.:', 'I''m sure she tells Ruth everything we say - they''re as thick as thieves, those two.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (976, 'be (caught) between a rock and a hard place', 'to be in a very difficult situation and to have to make a hard decision', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (977, 'be (dead) set against something', 'to be determined not to do something:', 'Why are you so set against going to college?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (978, 'be (down) in black and white', 'to be written down:', 'I couldn''t believe it was true, but there it was, in black and white.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (979, 'be (like) a millstone around your neck', 'to be a responsibility that is difficult to bear and causes you trouble:', 'The mortgage on his house had become a millstone around his neck.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (980, 'be (like) catnip to sb/sth', 'to be certain to attract or interest a particular person or type of person:', 'This kind of high school movie is catnip to teenagers.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (981, 'be (like) putty in someone''s hands', 'to be willing to do anything someone wants, because you like them so much', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (982, 'be (like) sheep', 'If a group of people are (like) sheep, they all behave in the same way or all behave as they are told, and cannot or will not act independently.', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (983, 'be (living) in a dream world', 'to have hopes and ideas that are not practical or possible:', 'If he thinks I''ll forgive him, he''s living in a dream world.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (984, 'be (of) (any/some) use', 'to be useful:', 'Maybe his advice will be of use to you when you''re older.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (985, 'be (of) no use', 'to not be useful, helpful, or possible:', 'His advice turned out to be no use at all.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (986, 'be (only) a matter of time', 'If it is (only) a matter of time until something happens, it is certain to happen but you do not know when it will happen:', 'It''s only a matter of time before he''s forced to resign.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (987, 'be (only) flesh and blood', 'to have normal human limits, needs, etc.:', 'When we grow up, we realize that our parents aren''t superhuman - they''re only flesh and blood.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (988, 'be (really) something', 'to be very special or admired:', 'Imagine winning an Olympic medal - now that would be something.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (989, 'be (right) under your nose', 'to be in a place that you can clearly see:', 'I spent all morning looking for the book, and it was right under my nose the whole time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (990, 'be (strictly) for the birds', 'to be stupid or not important', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (991, 'be (stuck) in a groove', 'to be bored because you are doing the same things that you have done for a long time:', 'We never do anything exciting any more - we seem to be stuck in a groove.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (992, 'be a badge of something', 'to be something that shows that you have achieved a particular thing:', 'For Tony, owning a big car was a badge of success.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (993, 'be a barrel of laughs/fun', 'to be funny or enjoyable:', '"He''s a bit serious, isn''t he?" "Yeah, not exactly a barrel of laughs."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (994, 'be a big fish in a small pond', 'to have a lot of influence only over a small area', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (995, 'be a bit much', 'to be a situation, or type of behaviour that is unreasonable, or more than you can deal with:', 'I thought being asked to miss my lunch was a bit much.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (996, 'be a bit of all right', 'to be an attractive person', '', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (997, 'be a chapter of accidents', 'to be a series of unpleasant events:', 'The whole trip was a chapter of accidents.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (998, 'be a dime a dozen', 'to be common and/or of very little value:', 'Books like this are a dime a dozen.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (999, 'be a drag on someone/something', 'to slow down or limit the development of someone or something:', 'She didn''t want a husband who would be a drag on her career.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1000, 'be a fair bet', 'to be something that is likely to happen:', 'It''s a fair bet (that) the government will increase taxes in the coming term.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1001, 'be a far cry from something', 'to be completely different from something:', 'This flat is a far cry from the house they had before.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1002, 'be a game of two halves', 'used, especially in sports reports, to say that in a game of football, one team plays better in each half of the game:', 'It really was a game of two halves, with Spurs dominating the first, only to be outplayed by Arsenal in the second.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1003, 'be a glutton for punishment', 'to be someone who seems to enjoy doing something that you consider unpleasant:', 'He''s a real glutton for punishment, taking on all that extra work without getting paid for it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1004, 'be a glutton for something', 'to like something very much:', 'Sophie is a glutton for books.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1005, 'be a good bet', 'to be something that would be useful, clever, or enjoyable to do:', 'Putting your savings in a high-interest account is a good bet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1006, 'be a great one for something', 'to enjoy or do something a lot:', 'He''s a great one for getting other people to do his work for him!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1007, 'be a hard/tough act to follow', 'to be so good that it is not likely that anyone or anything that comes after will be as good:', 'His presidency was very successful - it''ll be a hard act to follow.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1008, 'be a hit with someone', 'If you are a hit with someone, that person likes you a lot from the time that they first meet you:', 'You were a big hit with my dad - he hasn''t stopped talking about you.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1009, 'be a hoot', 'to be very funny:', 'He''s an absolute hoot.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1010, 'be a law unto yourself', 'to behave in a way that is independent and does not follow the usual rules for a situation:', 'Charlie, of course, never fills in the record forms but then he''s a law unto himself.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1011, 'be a legend in your own lifetime', 'to be very famous while you are still alive:', 'Garbo was a legend in her own lifetime.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1012, 'be a licence to print money', 'If a company or activity is a licence to print money, it causes people to become very rich without having to make any effort.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1013, 'be a license to print money', 'If a company or activity is a license to print money, it causes people to become very rich without having to make any effort.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1014, 'be a martyr to something', 'to often suffer because of an illness or problem:', 'She''s a martyr to migraines!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1015, 'be a matter of life and/or death', 'to be very serious:', 'And if you miss the bus, well, it''s not a matter of life and death.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1016, 'be a matter of opinion', 'If something is a matter of opinion, different people have different opinions about it:', 'Both performances were excellent; it''s simply a matter of opinion as to whose was better.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1017, 'be a matter of record', 'If a fact is a matter of record, it is generally known to be true.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1018, 'be a minority of one', 'to be the only person who has a particular opinion', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1019, 'be a monument to something', 'to be an important and permanent result of an action or characteristic:', 'The annual arts festival is a monument to her vision and hard work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1020, 'be a name to conjure with', 'to be a very important name, or an interesting name that gives you a mental picture of something pleasant or exciting:', 'In those days Churchill was still a name to conjure with.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1021, 'be a nine days'' wonder', 'to be a cause of great excitement or interest for a short time but then quickly forgotten', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1022, 'be a one', 'to be funny in a slightly rude way or in a way that shows no respect:', '"He told me I couldn''t have the job and I told him I never really wanted it in the first place." "Ooh, you are a one."', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1023, 'be a picture', 'to look beautiful:', 'The garden was a picture with all the roses in bloom.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1024, 'be a question of doing something', 'to be necessary to do a particular thing:', 'It''s simply/just a question of working hard for a month and then you can relax.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1025, 'be a recipe for disaster, trouble, success, etc.', 'to be very likely to become a disaster, success, etc.:', 'All those children unsupervised sounds to me like a recipe for disaster.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1026, 'be a reproach to someone/something', 'to be something that should make a person or organization feel ashamed:', 'His immaculate garden was a reproach to all his less organized neighbours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1027, 'be a rich seam to mine', 'to be full of good material and ideas to use:', 'When she started writing novels, she found her time as a judge was a rich seam for her to mine.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1028, 'be a safe bet', 'to be something that you are certain will happen:', 'It''s a safe bet (that) Martin will be the last to arrive.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1029, 'be a shadow of your former self', 'to have less health or strength, or less influence, than you did before:', 'He came home from hospital cured of the disease but a shadow of his former self.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1030, 'be a slam dunk', 'to be a certain winner:', 'Although he''s a strong candidate, he''s not a slam dunk.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1031, 'be a slave to something', 'to be influenced too much by something:', 'She''s a slave to fashion.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1032, 'be a tall order', 'to be something that is difficult to do:', 'Building the bridge in time for the Olympics will be a tall order.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1033, 'be a thing', 'to exist, especially when this is surprising:', 'I didn''t know nose hair extensions were actually a thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1034, 'be a victim of your own success', 'to have problems because of your success:', 'The school has become a victim of its own success, as parents with children who have special needs now actively seek it out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1035, 'be a victory for common sense', 'to be a very reasonable result in a particular situation:', 'There is no doubt that the court''s decision is a victory for common sense.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1036, 'be above someone''s pay grade', 'to be something that a person does not have enough knowledge or authority to do:', 'She declined to comment on the controversial tape, saying "That''s above my pay grade."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1037, 'be above/beyond reproach', 'to not deserve any blame:', 'Your behaviour today has been above reproach.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1038, 'be afraid of your own shadow', 'to be frightened of things in a way that is not reasonable or necessary:', 'They are weak leaders who seem afraid of their own shadows.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1039, 'be after someone''s blood', 'to be very angry with someone and threatening to harm them :', 'You''d better stay out of her way - she''s after your blood.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1040, 'be ahead of the curve', 'to be one of the first to change to a new idea or way of doing something that later becomes generally popular:', 'In equipping its vehicles with mobile WiFi, the company was ahead of the curve.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1041, 'be ahead of the game', 'to know more about the most recent developments in a particular subject or activity than the people or companies you are competing against:', 'A very extensive research and development programme ensures that we''re ahead of the game.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1042, 'be ahead of the pack', 'to be more successful than other people who are trying to achieve the same things as you:', 'At this stage in the campaign, the Democratic candidate is way ahead of the pack.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1043, 'be alive and well/kicking', 'to continue to live or exist and be full of energy:', 'She said she''d seen him last week and he was alive and kicking.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1044, 'be alive and well/kicking', 'to continue to be popular or successful:', 'Despite rumours to the contrary, feminism is alive and well.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1045, 'be all (that) you can do', 'If it is all (that) you can do to do something, you are trying very hard to do it and it is difficult:', 'This is so boring, it''s all I can do to stay awake.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1046, 'be all ears', 'to be waiting eagerly to hear about something:', 'I''m all ears - tell us what they had to say.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1047, 'be all eyes', 'to watch someone or something with a lot of interest:', 'We were all eyes as the celebrity guests emerged from the car.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1048, 'be all fingers and thumbs', 'to move your hands in an awkward way:', 'I''m all fingers and thumbs today. That''s the second plate I''ve dropped this morning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1049, 'be all go', 'If a situation or place is all go, it is extremely busy:', 'It was all go in town today.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1050, 'be all heart', 'to be very kind and generous. This phrase is often used humorously, especially in the UK, to mean the opposite:', 'She''s all heart.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1051, 'be all mouth', 'to talk a lot about doing something but never do it:', 'He says he''s going to complain to the manager, but he''s all mouth.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1052, 'be all over it', 'to be very involved or interested in something:', 'Anything to do with Buddhism and I''m all over it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1053, 'be all over it', 'to be dealing with something with a lot of effort, energy, or success:', '"I hit a serve, he was all over it." said Roddick.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1054, 'be all smiles', 'to look happy and friendly, especially when other people are not expecting you to:', 'She''s never been very friendly, but she was all smiles when she asked me to help her with her homework.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1055, 'be all talk (and no action)', 'used to describe someone who talks about doing something but never does it:', 'She''s all talk when it comes to doing something about the problem.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1056, 'be all the same to someone', 'to not be important to someone which of several things is chosen:', 'I don''t mind whether we eat now or later, it''s all the same to me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1057, 'be all very well', 'used to show that you do not agree with something or that you are annoyed about something:', 'Patience is all very well as long as you don''t have to be patient for too long.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1058, 'be an actor, cook, etc. in the making', 'to have the ability and interest to become an actor, cook, etc. in the future', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1059, 'be an apology for something', 'to be an extremely bad example of something:', 'You''re not coming out because you''re tired? That''s an apology for an excuse!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1060, 'be an artist, professional, etc. to your fingertips', 'to be a perfect or typical example of something:', 'Mark, a professional to his fingertips, insisted that we follow the correct procedures.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1061, 'be an easy mark', 'to be easily deceived:', 'He thought an old lady living alone would be an easy mark.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1062, 'be an item', 'If two people are an item, they are having a romantic relationship:', 'I saw Darren and Emma there. Are they an item?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1063, 'be another matter/thing', 'to be a different situation that is likely to be judged differently:', 'Cars are useful, but their impact on the environment is another matter altogether.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1064, 'be another matter/thing', 'to be very different and likely to involve more problems or difficulties:', 'Wanting to help the homeless is one thing, finding cheap secure accommodation for them is quite another (thing).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1065, 'be another story', 'to be something that you do not want to say more about at this particular time:', 'When we finally got home, we found that we''d been burgled - but that''s another story.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1066, 'be another/a different kettle of fish', 'to be completely different from something or someone else that has been talked about:', 'Having knowledge is one thing but being able to communicate it to others is another kettle of fish.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1067, 'be as crazy, rich, etc. as they come', 'to be very crazy, rich, etc.:', 'He''s as mean as they come.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1068, 'be as dead as a doornail', 'to be clearly and obviously dead', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1069, 'be as fresh as a daisy', 'to be full of energy and enthusiasm:', 'After a good night''s sleep I''ll be as fresh as a daisy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1070, 'be as good as your word', 'to do everything that you promise someone you will:', 'He said he''d call every day and he was as good as his word.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1071, 'be as high as a kite', 'to behave in a silly or excited way because you have taken drugs or drunk a lot of alcohol:', 'I tried to talk to her after the party, but she was as high as a kite.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1072, 'be as high as a kite', 'to feel very happy and excited:', 'I was as high as a kite when I heard I''d got the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1073, 'be as poor as a church mouse', 'to be very poor:', 'They''ll take one look at my clothes and know I''m as poor as a church mouse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1074, 'be as pure as the driven snow', 'to be morally completely good:', 'How dare he criticize me for having an affair? He''s not exactly as pure as the driven snow himself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1075, 'be as sound as a bell', 'to be very healthy or in very good condition', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1076, 'be as stubborn as a mule', 'to be very stubborn', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1077, 'be asking for it/trouble', 'to be behaving stupidly in a way that is likely to cause problems for you:', 'Drinking alcohol before driving is really asking for trouble.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1078, 'be asking for trouble', 'to be likely to cause problems or difficulties for yourself:', 'Giving him such a powerful car when he''s just started driving is asking for trouble.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1079, 'be associated with something', 'If problems or dangers are associated with a particular thing or action, they are caused by it:', 'The cancer risks associated with smoking have been well documented.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1080, 'be at a crossroads', 'to be at a stage in your life when you have to make a very important decision', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1081, 'be at a loose end', 'to have nothing to do:', 'If you find yourself at a loose end, you could always clean the bathroom.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1082, 'be at a loss', 'not to know what to do or say:', 'I''m at a loss to know how I can help you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1083, 'be at a premium', 'to be not common and therefore valuable:', 'Free time is at a premium for working parents.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1084, 'be at death''s door', 'to be very sick', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1085, 'be at it', 'to be involved in doing something:', 'We''ve caught so many people cheating we become convinced everyone is at it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1086, 'be at it again', 'to be doing something that you have done before, often something annoying:', 'Five minutes after they stop arguing, they''re at it again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1087, 'be at large', 'If someone dangerous is at large, that person is free when they should not be:', 'Twelve prisoners are at large following a series of escapes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1088, 'be at odds', 'to disagree:', 'They''re at odds over the funding of the project.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1089, 'be at one', 'to agree:', 'We disagree on most things, but on this question we are at one (with each other).', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1090, 'be at peace with the world', 'to be feeling calm and happy because you are satisfied with your life', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1091, 'be at the bottom of something', 'to be the real reason for or the cause of something:', 'The desire for money is at the bottom of much of the world''s violence.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1092, 'be at the top of your game', 'to be performing extremely well in a sport, job, etc. so that you could not perform any better:', 'I want to beat Andy when he''s at the top of his game.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1093, 'be at work', 'to be working:', 'The labourers were at work in the fields.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1094, 'be at work', 'to be having an effect, usually an obvious or bad effect:', 'It seems as though forces of destruction are increasingly at work throughout society.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1095, 'be at your wits'' end', 'to be so worried, confused, or annoyed that you do not know what to do next:', 'I''m at my wits'' end. I don''t know how to help him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1096, 'be back in harness', 'to have returned to work after being away for a period of time', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1097, 'be back on your feet', 'to be healthy again after a period of illness:', '"We''ll soon have you back on your feet again," said the nurse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1098, 'be backward in coming forward', 'to be shy and not often express wishes or opinions:', 'I''m sure Matt will tell you what he thinks of the idea - he''s not usually backward in coming forward.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1099, 'be bad luck on someone', 'to be a bad thing that happened to someone by chance:', 'It was bad luck on Alex that he was ill on his birthday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1100, 'be bang on', 'to be exactly right:', 'What was your answer? 76? That''s absolutely bang on!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1101, 'be banging, etc. your head against a brick wall', 'to try to do something that is very difficult or impossible to achieve and therefore causes you to feel annoyed:', 'I keep asking her not to park there but it''s like banging your head against a brick wall.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1102, 'be barking up the wrong tree', 'to be wrong about the reason for something or the way to achieve something:', 'She thinks it''ll solve the problem, but I think she''s barking up the wrong tree.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1103, 'be behind someone', 'If a bad experience or your own bad behaviour is behind you, it does not exist or affect your life now:', 'Those dark days are behind me now, I''m glad to say.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1104, 'be behind someone (all the way)', 'to support someone (completely) in what they are doing', '', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1105, 'be behind the curve', 'to change to a new idea or way of doing something later than most others, or to react to something after it has already happened:', 'If you''re not using social media to promote your business, you''re behind the curve.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1106, 'be bent on something/doing something', 'to be determined to do or have something:', 'He was bent on getting married as soon as possible.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1107, 'be beside yourself', 'If you are beside yourself with a particular feeling or emotion, it is so strong that it makes you almost out of control:', 'He was beside himself with grief when she died.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1108, 'be better than sex', 'to be extremely enjoyable or exciting:', 'For me, nothing compares with the thrill of surfing - it''s better than sex.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1109, 'be between jobs/marriages/boyfriends, girlfriends, etc.', 'to no longer have a job, marriage, boyfriend, girlfriend, etc. at the present time, but expect or be likely to get another one:', 'Kelly was between jobs and unsure of what she wanted to do with her life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1110, 'be between the devil and the deep blue sea', 'to have two choices that are both equally unpleasant or not convenient', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1111, 'be big of someone', 'If an action is big of someone, it is kind, good, or helpful. This phrase is usually used humorously or angrily to mean the opposite:', 'You can spare me an hour next week? That''s really big of you!', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1112, 'be big on something', 'to like something very much:', 'I''m not very big on classical music.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1113, 'be blowed if...', 'If someone says that they are blowed if they will do something, they are determined not to do it:', 'I''m blowed if I''m going to pay for his taxi home.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1114, 'be bored, drunk, etc. out of your mind', 'to be extremely bored, drunk, etc.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1115, 'be brought/called to account', 'to be forced to explain something you did wrong, and usually to be punished:', 'We must ensure that the people responsible for the violence are brought to account.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1116, 'be cast away', 'to be left somewhere such as on an island that is far from any towns or people, after escaping from a ship that has sunk:', 'If you were cast away on a desert island, what would you miss most?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1117, 'be cast in the same mold', 'to be very similar in character to someone else:', 'Everyone who works for that firm seems to be cast in the same mold.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1118, 'be cast in the same mould', 'to be very similar in character to someone else:', 'Everyone who works for that firm seems to be cast in the same mould.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1119, 'be caught/taken short', 'to suddenly and unexpectedly need to go to the toilet, especially when it is not convenient for you to do so', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1120, 'be chafing at the bit', 'to be very eager to do something:', 'As soon as the kids saw the pool, they were chafing at the bit to get in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1121, 'be chasing your tail', 'to be busy doing a lot of things but achieving very little', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1122, 'be child''s play', 'to be very easy:', 'Using computers nowadays is child''s play.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1123, 'be chilled/frozen to the marrow', 'to be extremely cold', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1124, 'be climbing the walls', 'to suffer unpleasant feelings, such as worry, in an extreme way:', 'to be climbing the walls with boredom/anger/frustration
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1125, 'be close to the bone', 'If something you say or write is close to the bone, it is close to the truth in a way that might offend some people.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1126, 'be cold comfort', 'When being told a particular thing about a bad situation is cold comfort, it does not make you feel better although it is intended to.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1127, 'be cold enough to freeze the balls off a brass monkey', 'to be very cold', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1128, 'be conspicuous by your absence', 'to be absent when you should be present, in a way that other people notice:', 'Why wasn''t Stephen at the meeting? He was conspicuous by his absence.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1129, 'be convulsed with laughter, rage, etc.', 'to laugh or feel anger, etc. in a way that you cannot control', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1130, 'be cooking', 'to be making progress or doing something well:', 'That''s the way! Now you''re cooking!', 'idiom', '', 'informal old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1131, 'be cooking with gas', 'to be making very good progress or doing something very well:', 'I can see we''re really cooking with gas now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1132, 'be cracked up to be something', 'to be said to be something, either something bad or something good:', 'This new radio station''s not all it''s cracked up to be.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1133, 'be crazy about someone/something', 'to be very interested in something or love someone very much:', 'Both my sons are crazy about football.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1134, 'be cruel to be kind', 'to do or say something that causes someone pain because you believe that it will help them', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1135, 'be curtains for someone', 'used to say someone will die or have to stop doing something:', 'It''ll be curtains for him if he doesn''t do what I tell him!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1136, 'be cut from the same cloth', 'to have very similar qualities to someone or something else:', 'We''re cut from the same cloth, you and I.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1137, 'be cut up', 'to be upset:', 'Philip was very cut up about his grandmother''s death.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1138, 'be damned if you do and damned if you don''t', 'used to say that you cannot escape being criticized, whatever you decide to do', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1139, 'be dancing in the streets', 'to be extremely happy about something that has happened:', 'Not many people will be dancing in the streets about a two percent pay rise.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1140, 'be dead in the water', 'If something is dead in the water, it has failed and it seems impossible that it will be successful in the future:', 'So how does a government revive an economy that is dead in the water?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1141, 'be dead meat', 'If someone is dead meat, they are in a lot of trouble:', 'He''ll be dead meat if his girlfriend finds out.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1142, 'be dead on your feet', 'to be very tired', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1143, 'be dead to the world', 'to be sleeping:', '"Is Georgie up yet?" "I doubt it - she was dead to the world ten minutes ago."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1144, 'be devoured by something', 'to feel an emotion, especially a bad emotion, very strongly so that it strongly influences your behaviour:', 'He was devoured by jealousy/hatred.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1145, 'be done and dusted', 'to be complete and finished:', 'By now the deal was done and dusted.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1146, 'be down in the mouth', 'to be sad', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1147, 'be down on someone', 'to criticize someone:', 'It''s not fair of the boss to be so down on a new employee.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1148, 'be down on your luck', 'to be experiencing a bad situation or to have very little money:', 'He''s been down on his luck recently.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1149, 'be down to someone', 'to be someone''s responsibility or decision:', 'It''s down to me to find a suitable person for the job.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1150, 'be dripping with something', 'to be covered in a lot of a liquid that is falling or running down:', 'Their chins were dripping with juice.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1151, 'be dripping with something', 'to be wearing or covered with a lot of something that hangs down:', 'She was absolutely dripping with gold.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1152, 'be dripping with something', 'to have a lot of a particular quality, often a bad quality:', 'He replied in a voice dripping with sarcasm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1153, 'be dying for/to do something', 'to be extremely eager to have or do something:', 'I''m dying to hear your news.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1154, 'be easy game/meat', 'to be easily deceived:', 'Old ladies living alone are easy game for con-men.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1155, 'be easy prey', 'to be easy to deceive or be taken advantage of:', 'Homeless young people are easy prey for drug-dealers and pimps.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1156, 'be endowed with something', 'to have a particular quality or feature:', 'Some lucky people are endowed with both brains and beauty.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1157, 'be engraved on someone''s memory/mind', 'to be very difficult to forget:', 'That last conversation we had is engraved on my memory forever.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1158, 'be etched on/in someone''s memory', 'to be something that you will continue to remember:', 'The scene will be etched on my memory forever.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1159, 'be etched somewhere', 'If a feeling, emotion, or shape is etched somewhere, it can be seen there very clearly:', 'His face was etched with pain.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1160, 'be fading away/fast', 'to be growing weaker and thinner and to be likely to die soon', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1161, 'be far removed from something', 'to be very different from something:', 'It''s a wonderful experience but it''s far removed from reality.', 'idiom', 'C2', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1162, 'be firing on all cylinders', 'to be operating as powerfully and effectively as possible:', 'Dawson will be firing on all cylinders after two months of fitness training.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1163, 'be fit/ready to drop', 'to be extremely tired:', 'I''d just walked ten miles and was ready to drop.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1164, 'be floating on air', 'to be very happy:', 'When he got his exam results he was floating on air.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1165, 'be flying high', 'If a person or a company is flying high, they are very successful:', 'The company was flying high as a maker of personal computers.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1166, 'be flying high', 'to be very excited or happy:', 'When the winter Olympics came to Canada, the whole country was flying high.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1167, 'be foaming at the mouth', 'to be extremely angry:', 'The Almeida Theatre''s recent staging of the opera had critics foaming at the mouth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1168, 'be for the high jump', 'to be going to be punished for something you have done wrong', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1169, 'be free with your favors', 'to be willing to have sex with a lot of people:', 'She''s rather too free with her favors, from what I hear.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1170, 'be free with your favours', 'to be willing to have sex with a lot of people:', 'She''s rather too free with her favours, from what I hear.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1171, 'be full of beans', 'to have a lot of energy and enthusiasm:', 'I''ve never known anyone be so full of beans before breakfast.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1172, 'be full of the joys of spring', 'to be very happy:', 'He bounced into the office, full of the joys of spring.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1173, 'be gasping', 'to be very thirsty', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1174, 'be gasping for something', 'to want or need something very much:', 'I''m absolutely gasping for a cigarette.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1175, 'be getting somewhere', 'to be achieving something:', 'Right, that''s the printer working. Now we''re getting somewhere!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1176, 'be glued to something', 'to be unable to stop watching something:', 'We were glued to the television watching the election results come in.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1177, 'be going strong', 'to continue to exist and be successful or work well, after a long period:', 'After fifty years, the town''s theatre is still going strong.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1178, 'be gone on someone', 'to like someone a lot:', 'Nicky''s really gone on Marty.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1179, 'be good for something', 'to be able and willing to provide something:', 'Bette is always good for a laugh.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1180, 'good for you!', 'used to show approval for someone''s success or good luck:', 'You passed your exam - good for you!', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1181, 'be good to go', 'to be prepared and ready to do something:', 'Let me grab a jacket and then I''m good to go.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1182, 'be good, and if you can''t be good, be careful', 'used to tell someone to enjoy themselves at an event or during an activity, but not to take risks', '', 'idiom', '', 'humorous, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1183, 'be green around the gills', 'to look ill and pale:', 'Some of the passengers looked kind of green around the gills after the trip!', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1184, 'be green with envy', 'to be very unhappy because someone has something that you want:', 'Chad is heading off to Spain for the week, and I''m green with envy.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1185, 'be gunning for someone', 'to often criticize someone or be trying to cause trouble for them:', 'She''s been gunning for me ever since I got the promotion she wanted.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1186, 'be gunning for something', 'to make a great effort to get or win something:', 'Irwin is gunning for his third straight championship.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1187, 'be half the battle', 'to be the most difficult part of a process so that once you have finished this part, you have almost succeeded:', 'For a lot of jobs, getting an interview is half the battle.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1188, 'be half the dancer, writer, etc. you used to be', 'to be much less good at doing something than you used to be:', 'She''s half the tennis player she used to be.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1189, 'be hanging', 'to be suffering from a hangover (= a feeling of illness after drinking alcohol some time previously):', 'I''m hanging this morning.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1190, 'be hard up (for something)', 'to not have enough of something important or valuable:', 'If you''re so hard up for friends, why don''t you join a club?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1191, 'be having a moment', 'to be very popular or fashionable at a particular time:', 'Right now, oversized sweaters are having a moment.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1192, 'be having a moment', 'to not be acting normally for a short time, for example because you are not thinking about what you are doing, or because you are feeling a strong emotion:', 'He was staring out of the window and he didn''t answer me - I think he was just having a moment.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1193, 'be hearing/imagining/seeing things', 'to think you are experiencing something that is not really happening:', 'I''m sure I saw my glasses on this table, but they''re not here now. I must have been seeing things.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1194, 'be heavily into something', 'to be very interested in and involved with something:', 'When I was younger I was heavily into politics.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1195, 'be heavy on someone', 'to treat or punish someone severely:', 'I think his parents are being a bit heavy on him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1196, 'be hell on wheels', 'to behave in an angry or difficult way:', 'When he was drinking, Ken was hell on wheels.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1197, 'be hell-bent on something', 'to be extremely determined to do something, without considering the risks or possible dangerous results:', 'He was hell-bent on revenge.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1198, 'be here for someone', 'to be available to provide help and support for someone:', 'If you want to talk, I''m here for you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1199, 'be here for something', 'to be interested in or enjoy something; to like something:', 'Like everyone else, I''m here for every detail of the feud between the two stars.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1200, 'be hoist(ed) with/by your own petard', 'to suffer harm from a plan by which you had intended to harm someone else', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1201, 'be holed up', 'to be hiding in a safe place:', 'The robbers were holed up in a deserted warehouse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1202, 'be home and dry', 'to have successfully finished something:', 'We just have to finish this section, then we''re home and dry.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1203, 'be home free', 'to be certain to succeed at something because you have done the most difficult part of it:', 'Once you leave the main road and cross the bridge, you''re home free - we live just three houses further on.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1204, 'be hot on someone''s track/trail', 'to be very close to catching or finding someone', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1205, 'be hot stuff', 'to be very skilful:', 'She''s really hot stuff at baseball.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1206, 'be hot stuff', 'to be very sexually attractive:', 'Man, she''s hot stuff!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1207, 'be hung up on something', 'to be extremely interested in or worried by a particular subject and spend an unreasonably large amount of time thinking about it:', 'Why are you so hung up on getting everything right?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1208, 'be ill at ease', 'to be worried and not relaxed:', 'He seemed ill at ease and not his usual self.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1209, 'be in a (pretty) pickle', 'to be in a difficult situation', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1210, 'be in a bad way', 'to be ill, unhappy, or in a bad state:', 'She was thin and tired-looking and generally in a bad way.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1211, 'be in a different league', 'to be much better than something or someone else:', 'Our last hotel was good but this was in a different league.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1212, 'be in a funk', 'to be very unhappy and without hope:', 'He''s been in a real funk since she left him.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1213, 'be in a hole', 'to be in a difficult or an embarrassing situation:', 'We''ve lost the order and we''re in a bit of a hole.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1214, 'be in a minority of one', 'to be the only person who has a particular opinion', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1215, 'be in a mood', 'to not be friendly to other people because you are feeling angry:', 'Ignore him - he''s in a mood.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (1216, 'be in a mood for something/to do something', 'to want to do or have something:', 'She was dressed up and in a mood to party.
