INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4009, 'get it into your thick head', 'to make someone understand something, especially when you have told them many times before and are annoyed:', 'How can I get it into your thick head that it’s dangerous to swim that far out in the sea?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4010, 'get it on', 'to have sex:', 'Did you get it on with him?', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4011, 'get it through your thick head', 'infml to cause someone to understand something:', 'How can I get it through your thick head that it’s dangerous to swim that far out in the ocean?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4012, 'get it through your thick head', 'to make someone understand something, especially when you have told them many times before and are annoyed:', 'How can I get it through your thick head that it’s dangerous to swim that far out in the ocean?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4013, 'get it together', 'to make a decision or take positive action in your life:', 'Blake has really got it together since I last saw him - he has started a new job and lost a lot of weight.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4014, 'get itchy feet', 'to start to want to travel or do something different:', 'After three years in the job she began to get itchy feet.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4015, 'get knotted!', 'a rude way of telling someone who is annoying you to go away', '', 'idiom', '', 'old-fashioned, slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4016, 'get laid', 'to have sex:', 'He just wanted to get laid.', 'idiom', '', 'very informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
