INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4213, 'give or take', 'possibly a little more or less than the amount or time mentioned:', 'It''ll be ready at 6:00, give or take a few minutes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4214, 'give out', 'If a machine or part of your body gives out, it stops working:', 'At the end of the race his legs gave out and he collapsed on the ground.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4215, 'give out', 'to complain about something:', 'After this win hopefully people will stop giving out to the team and the coach.
