INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4349, 'go arse over tit/tip', 'a rude phrase meaning to lose your balance suddenly and fall over:', 'I fell off my bike and went arse over tit.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4350, 'go ass over (tea)kettle', 'a rude phrase meaning to lose your balance suddenly and fall over', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4351, 'go at someone', 'to attack someone:', 'Suddenly, he went at me with a knife.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4352, 'go at something', 'to start doing something with a lot of energy and enthusiasm:', 'He went at (= ate eagerly) his dinner as if he hadn''t had anything to eat for weeks.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4353, 'go away', 'to leave a place:', 'Go away and leave me alone!', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4354, 'go away', 'to leave your home in order to spend time somewhere else, usually for a holiday:', 'We usually go away for the summer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4355, 'go away', 'to disappear:', 'It was weeks before the bruises went away.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4356, 'go back', 'to return:', 'That restaurant was terrible - I''m never going back there again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4357, 'go back', 'to be returned:', 'When are these library books supposed to go back ?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4358, 'go back', 'to have existed since a time in the past:', 'Their relationship goes back to when they were at college together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4359, 'go back a long way', 'If people go back a long way, they have known each other for a long time.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4360, 'go back on something', 'to fail to keep a promise, or to change a decision or agreement:', 'The government looks likely to go back on its decision to close the mines.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4361, 'go back to sleep!', 'used to tell someone off for not paying attention:', '"Sorry, what did you say?" "Oh, go back to sleep!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4362, 'go back to someone', 'to start a relationship again with a person you had a romantic relationship with in the past:', 'I hear he''s ended the affair and gone back to his wife.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4363, 'go back to something', 'to start doing something again that you were doing before:', 'It''s time to go back to work.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4364, 'go back to the drawing board', 'to start planning something again because the first plan failed', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4365, 'go beet red', 'to have a red face because you are embarrassed:', 'Whenever I talked about his past life, he would go beet red.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4366, 'go begging', 'If something is going begging, it is available to be taken because no one else wants it:', 'If that bottle of wine is going begging, I''ll have it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4367, 'go belly up', 'If a company or plan goes belly up, it fails:', 'The business went belly up after only six months.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4368, 'go blank', 'to forget something that you know, often temporarily:', 'I went blank and couldn''t think of a single example.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4369, 'go by', 'to move past, in space or time:', 'You can watch the trains going by from this window.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4370, 'go by', 'in the past:', 'The house was a train station in days gone by.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4371, 'go by something', 'to follow something or be shown the way by something:', 'I''m sorry, madam, but we have to go by the rules.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4372, 'go by something', 'to base an opinion, decision, or judgment on something:', 'What do you go by when you''re deciding whether or not to employ someone?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4373, 'go by the board', 'to be forgotten or not used:', 'Does this mean our holiday plans will have to go by the board?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4374, 'go cap in hand to someone', 'to ask someone in a polite and sincere way for something, especially money or to be forgiven', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4375, 'go commando', 'to not wear any underwear', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4376, 'go dark', 'to stop all activities or communication, especially temporarily but for a fairly long period:', 'Theatres have gone dark, and arts groups have disbanded.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4377, 'go dark', '(of a spy or secret agent) to stop communicating for a period of time with the people you are secretly working for:', 'She was undercover and thought the gang were onto her, so she went dark.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4378, 'go down', 'to move down to a lower level or place:', 'He went down on his knees and begged for forgiveness.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4379, 'go down', 'to reach or go as far as:', 'Its roots can go down three metres.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4380, 'go down', 'When the sun goes down, it moves down in the sky until it cannot be seen any more:', 'On summer evenings we would sit on the veranda and watch the sun go down.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4381, 'go down', 'to be reduced in price, value, amount, quality, level, or size:', 'The temperature went down to minus ten last night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4382, 'go down', 'to be remembered or recorded in a particular way:', 'Hurricane Katrina will go down in the record books as the costliest storm ever faced by insurers.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4383, 'go down', 'to be received in a particular way:', 'The joke didn''t go down very well.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4384, 'go down', 'to lose or be defeated:', 'England''s unbeaten run of ten games ended last night when they went down 4–2 to France.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4385, 'go down', 'If a football team goes down, it drops to a lower division (= group of teams who play each other):', 'At the end of the season, the three teams at the bottom go down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4386, 'go down', 'to be put in prison:', 'She went down for three years for her part in the robbery.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4387, 'go down', 'If a computer system goes down, it stops working:', 'The battery should prevent the computer system from going down in the event of a power cut.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4388, 'go down', 'If an event such as a crime or a deal goes down, it happens:', 'I tried to tell Tyrell what was going down, but he wouldn''t listen.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4389, 'go down', 'If you go down from a college or university, especially Oxford University or Cambridge University, you leave either permanently or on holiday.', '', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4390, 'go down as/in something', 'to be remembered or recorded in a particular way:', 'Hurricane Katrina will go down as one of the worst storms of this century.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4391, 'go down in the annals', 'to be remembered as an important event, person, etc.:', 'Quite whether he will go down in the annals of American history as a great leader remains to be seen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4392, 'go down like a lead balloon', 'If something that you say or show to people goes down like a lead balloon, they do not like it at all:', 'My joke about the alcoholic went down like a lead balloon.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4393, 'go down on someone', 'to use the tongue and lips to touch someone''s sexual organs in order to give pleasure', '', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4394, 'go down swinging/fighting', 'to continue to fight or to make a strong, determined effort even though you are likely to fail or lose:', 'They beat us in the end, but we went down swinging.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4395, 'go down the gurgler', 'If work or money goes down the gurgler, it is wasted:', 'So say he gives up his training, that''s four thousand dollars down the gurgler.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4396, 'go down the pan', 'to fail or to be lost or destroyed:', 'We don''t want to see our business go down the pan.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4397, 'go down the tubes', 'to fail completely:', 'If business doesn''t pick up soon, the company will go down the tubes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4398, 'go down the wrong way', 'If food or drink goes down the wrong way, it goes down the wrong tube in your throat and causes you to cough or stop breathing for a short time.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4399, 'go down with something', 'to start to suffer from an infectious disease:', 'Half of Martha''s class has gone down with flu.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4400, 'go downhill', 'to gradually become worse:', 'After his wife died, his health started to go downhill.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4401, 'go easy', 'to not take or use too much of something:', 'Go easy on/with the cream - I haven''t had any yet.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4402, 'go easy', 'to treat someone in a gentle way and not criticize them or punish them:', 'Go easy on the new students.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4403, 'go easy on someone', 'to treat someone in a gentle way, esp. when you want to be or should be more severe:', 'Do you think judges should go easy on criminals if they''re teenagers?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4404, 'go easy on something', 'to not take or use too much of something:', 'The doctor told me to go easy on the spicy food for a while.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4405, 'go far', 'to be very successful in the future:', 'She''s a very talented writer - I''m sure she''ll go far.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4406, 'go figure!', 'used when you tell someone a fact and you then want to say that the fact is surprising, strange or stupid:', 'It''s a terrible movie and it made $200 million. Go figure!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4407, 'go fly a kite', 'used to tell someone who is being annoying to go away', '', 'idiom', '', 'informal old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4408, 'go for broke', 'to risk everything in the hope of having great success', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4409, 'go for it', 'to do anything you have to in order to get something:', '"I''m thinking of applying for that job." "Go for it!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4410, 'go for someone', 'to attack someone:', 'Their dog had to be put to sleep after it went for the postwoman.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4411, 'go for something', 'to choose something:', 'Instead of butter, I always go for margarine or a low-fat spread.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4412, 'go for something', 'to like or admire:', 'I don''t go for war films in a big way (= very much).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4413, 'go for something', 'to try to have or achieve something:', 'She tripped me as I went for the ball.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4414, 'go for something', 'If something goes for a certain amount of money, it is sold for that amount:', 'The painting is expected to go for at least a million dollars.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4415, 'go for the jugular', 'to make a serious effort to defeat someone, usually by criticizing or harming them in a cruel way:', 'Cunningham went straight for the jugular, telling him that his work was a complete disaster.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4416, 'go from bad to worse', 'If a situation goes from bad to worse, it was difficult and unpleasant, and is becoming even more so:', 'Things have gone from bad to worse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4417, 'go from strength to strength', 'to gradually become more successful:', 'The firm''s gone from strength to strength since the new factory was built.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4418, 'go gold', 'If a recording of a popular song, or of a collection of popular songs, goes gold, it sells a large number of copies.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4419, 'go great guns', 'to go fast or successfully:', 'For the first 400 metres he was going great guns, but then he fell and that lost him the race.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4420, 'go hand in hand with something', 'If something goes hand in hand with something else, it is closely related to it and happens at the same time as it or as a result of it:', 'Prosperity goes hand in hand with investment.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4421, 'go hang (yourself)', 'You say that someone can go hang (himself or herself) if you do not care what that person says or does about something:', 'If she''s expecting the report by tomorrow, she can go hang.', 'idiom', '', 'informal, old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4422, 'go haywire', 'to stop working correctly:', 'They told us later in the hospital that his heart had gone haywire.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4423, 'go hog wild', 'to become too excited and eager about something, often so that you do too much:', 'There''s no need to go hog wild just because it''s Sarah''s birthday - she won''t want such a fuss.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4424, 'go in', 'to enter a place:', 'I looked through the window, but I didn''t actually go in.', 'phrasal verb', 'A2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4425, 'go in', 'If the sun goes in, it becomes hidden from view by clouds.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4426, 'go in', 'If a fact or piece of information goes in, you understand it or remember it:', 'No matter how many times you tell him something, it never seems to go in.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4427, 'go in for something', 'to do something regularly, or to enjoy something:', 'I''ve never really gone in for classical music, but I love jazz.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4428, 'go in for something', 'to take part in a competition:', 'Are you planning to go in for the 100 metres race?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4429, 'go in on something', 'to be involved in an activity that involves others:', 'He bought a jet for personal use, inviting three friends to go in on it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4430, 'go in one ear and out the other', 'If you say that something you hear goes in one ear and out the other, you mean you quickly forget it:', 'If I have to listen to something I don''t understand, it just goes in one ear and out the other.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4431, 'go into orbit', 'to increase or succeed very quickly or to be in a state of extreme activity:', 'Prices have gone into orbit this year.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4432, 'go into reverse', 'If a situation goes into reverse, it becomes the opposite of what it was before:', 'The trend towards home ownership has gone into reverse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4433, 'go into rhapsodies', 'to express very great enthusiasm and admiration for something:', 'She went into rhapsodies over/about the chocolate cake.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4434, 'go into something', 'to start doing a particular type of work:', 'My son''s planning to go into journalism.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4435, 'go into something', 'to start an activity, or start to be in a particular state or condition:', 'The drug is still being tested and will not go into commercial production for at least two years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4436, 'go into something', 'to discuss, examine, describe, or explain something in a detailed or careful way:', 'This is the first book to go into her personal life as well as her work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4437, 'go into something', 'If time, money, or effort goes into a product or activity, it is used when producing or doing it:', 'A considerable amount of time and effort has gone into this exhibition.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4438, 'go into something', 'If a vehicle goes into something such as a tree or a wall, it hits it:', 'Their car was travelling at 50 miles an hour when it went into the tree.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4439, 'go into/enter the church', 'to become a priest:', 'He was in his thirties when he decided to enter the church.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4440, 'go it alone', 'to do something without other people:', 'He''s decided to leave the band and go it alone as a singer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4441, 'go like a bomb', 'to move very quickly:', 'His new car goes like a bomb.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4442, 'go native', 'If a person who is in a foreign country goes native, they begin to live and/or dress like the people who live there.', '', 'idiom', '', 'disapproving, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4443, 'go nuts', 'to become extremely angry:', 'My sister will go nuts when she finds out I crashed her car.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4444, 'go off', 'If a light or a machine goes off, it stops working:', 'The lights went off in several villages because of the storm.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4445, 'go off', 'If a bomb goes off, it explodes:', 'The bomb went off at midday.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4446, 'go off', 'If a gun goes off, it fires:', 'His gun went off accidentally.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4447, 'go off', 'If food or drink goes off, it is not good to eat or drink any more because it is too old:', 'This bacon smells a bit funny - do you think it''s gone off?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4448, 'go off', 'If a warning device goes off, it starts to ring loudly or make a loud noise:', 'The alarm should go off automatically as soon as smoke is detected.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4449, 'go off', 'to leave a place and go somewhere else:', 'She''s gone off on holiday with Tony.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4450, 'go off', 'to happen in a particular way:', 'The protest march went off peacefully.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4451, 'go off', 'to become worse in quality:', 'That paper''s really gone off since they got that new editor.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4452, 'go off someone/something', 'to stop liking or being interested in someone or something:', 'I went off beefburgers after I got food poisoning from a takeaway.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4453, 'go off on a tangent', 'to suddenly start talking or thinking about a completely new subject:', 'It''s hard to get a firm decision out of him - he''s always going off on a tangent.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4454, 'go off on one', 'to suddenly become very angry and start shouting or behaving violently:', 'He went off on one because he thought I was threatening his dog.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4455, 'go off the boil', 'to lose interest or become less urgent:', 'They were really excited about the project, but now they seem to have gone off the boil.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4456, 'go off the deep end', 'to get very angry about something or lose control of yourself', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4457, 'go off the rails', 'to start behaving in a way that is not generally acceptable, especially dishonestly or illegally:', 'He went off the rails in his first year at university.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4458, 'go off with a bang', 'If a party or event goes off with a bang, it is very exciting and successful.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4459, 'go off with someone', 'to leave a wife, husband, or partner in order to have a sexual or romantic relationship with someone else:', 'Did you know that Hugh had gone off with his sister-in-law?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4460, 'go off with something', 'to take something without getting permission from the owner first:', 'I wish you''d stop going off with my car without asking me beforehand.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4461, 'go off-piste', 'to do something different to what is normal or expected:', 'The presenter went off-piste from the script, with hilarious consequences.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4462, 'go on', 'to happen:', 'I''m sure we never hear about a lot of what goes on in government.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4463, 'go on', 'to continue:', 'Please go on with what you''re doing and don''t let us interrupt you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4464, 'go on', 'to move to the next thing or stage:', '[ + to infinitive ] She admitted her company''s responsibility for the disaster and went on to explain how compensation would be paid to the victims.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4465, 'go on', 'to start operating:', 'The spotlights go on automatically when an intruder is detected in the garden.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4466, 'go on', 'to start talking again after a pause:', 'She paused to have a sip of coffee and then went on with her account of the accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4467, 'go on', 'something that you say to encourage someone to say or do something:', 'Go on, what happened next?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4468, 'go on', 'to talk in an annoying way about something for a long time:', 'He went on and on until I finally interrupted him and told him I had to go.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4469, 'go on', 'used when encouraging someone to do something:', 'Go on, have another drink.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4470, 'go on', 'something that you say in order to agree to do or allow something that you did not want to do or to allow before:', '"Are you sure you don''t want another slice of cake?" "Oh go on then, but just a small one."', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4471, 'go on', 'to continue or pass:', 'Tomorrow will start cold but it should get warmer as the day goes on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4472, 'go on', 'used when you do not believe someone', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4473, 'go on something', 'to use a piece of information in order to help you discover or understand something:', 'I''m only going on what I overheard him saying to Chris, but I think he''s planning to leave next month.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4474, 'go on record', 'If you go on record or if you are on record as saying something, you say it publicly and officially and it is written down.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4475, 'go on the block', 'to be sold at an auction (= public sale)', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4476, 'go on the stage', 'to become an actor:', 'At the age of ten, he decided that he wanted to go on the stage.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4477, 'go one better', 'to do something that is more advanced or more generous than someone else:', 'I gave her a card, but my brother went one better and bought her a present.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4478, 'go out', 'to leave a room or building, especially in order to do something for entertainment:', 'Please close the door as you go out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4479, 'go out', 'to have a romantic and usually sexual relationship with someone:', 'How long have you been going out with him?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4480, 'go out', 'If the tide goes out, it moves back and covers less of the beach.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4481, 'go out', 'If a light or something that is burning goes out, it stops producing light or heat:', 'When I woke up the fire had gone out.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4482, 'go out', 'to lose when you are playing in a sports competition, so that you must stop playing in the competition:', 'England went out to France in the second round of the championship.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4483, 'go out (of) the window', 'If a quality, principle, or idea goes out of the window, it does not exist any more:', 'Then people start drinking and sense goes out of the window.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4484, 'go out for something', 'to try to become part of a sports team:', 'Unable to play ball with his hand in a cast, he went out for track.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4485, 'go out like a light', 'to go to sleep very quickly or to become unconscious very quickly', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4486, 'go out of your way', 'to try very hard to do something, especially for someone else:', 'They really went out of their way to make us feel welcome.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4487, 'go out to someone', 'If your thoughts or sympathies go out to someone in a difficult or sad situation, you think of that person and feel sorry for them:', 'Our deepest sympathies go out to her husband and children.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4488, 'go over', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4489, 'go over something', 'to examine or look at something in a careful or detailed way:', 'Forensic scientists are going over the victim''s flat in a search for clues about the murderer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4490, 'go over something', 'to study or explain something:', 'I always go over my notes just before I go into an exam.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4491, 'go over someone''s head', 'to speak to or ask permission from someone who has more authority than the person who you would normally go to in that situation:', 'Amanda was refusing to give me the week off so I went over her head and spoke to the boss.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4492, 'go over to something', 'to change to something new or to a new way of doing things:', 'Many firms are going over to new technologies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4493, 'go over to something', 'to change to a different person speaking or a different place during a television or radio programme:', 'We''re now going over to Kate Smith speaking live from Baghdad.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4494, 'go overboard', 'to do something too much, or to be too excited or eager about something:', 'I don''t think there''ll be more than six people eating, so I wouldn''t go overboard with the food.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4495, 'go pear-shaped', 'If a plan goes pear-shaped, it fails:', 'We''d planned to go away for the weekend, but it all went pear-shaped.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4496, 'go places', 'to be likely to be successful in the future:', 'They said that the group was clearly going places.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4497, 'go play with yourself!', 'a rude way of telling someone to go away and stop annoying you:', 'Oh, go play with yourself!', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4498, 'go pop', 'to explode:', 'If I eat any more I''m going to go pop!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4499, 'go postal', 'to become very angry and do something violent:', 'The man went postal and shot twelve of his colleagues.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4500, 'go private', 'to pay for private health care or private education:', 'People who can afford to go private can pick and choose the surgeon who operates on them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4501, 'go private', 'of a public company, to become privately owned:', 'None of the companies reverted to state control once they went private.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4502, 'go public', 'to become a company in which anyone can invest:', 'The company went public in 2013.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4503, 'go public (with something)', 'to make something known that was secret before:', 'We will not go public with the results until tomorrow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4504, 'go round', 'to spin like a wheel', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4505, 'go round', 'If there is enough of something to go round, there is enough for everyone in a group of people:', 'Are there enough pencils to go round?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4506, 'go round', 'to spend your time behaving in the stated way:', '[ + -ing verb ] You can''t go round being rude to people.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4507, 'go round', 'to visit someone in their home:', 'I''m just going round to Martha''s for half an hour.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4508, 'go round (somewhere)', 'to go or be given from one person to another, or to move from one place to another:', 'A nasty flu bug is going round (the school) at the moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4509, 'go round something', 'to travel to all, or the main, parts of a place that you are visiting in order to find out what it is like or to learn about it:', 'For a few weeks in the summer, visitors are able to go round the palace.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4510, 'go shares', 'to divide something such as a cost between you:', 'Why don''t we go shares on lunch?', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4511, 'go stag', 'If a man goes stag to an event, he goes without a partner.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4512, 'go steady on something', 'to not use too much of something:', 'Go steady on the milk, Dan - that''s our last bottle.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4513, 'go the distance', 'to manage to continue until the end of a competition', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4514, 'go the extra mile', 'to make more effort than is expected of you:', 'He''s a nice guy, always ready to go the extra mile for his friends.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4515, 'go the whole hog', 'to do something as completely as possible:', 'Having already limited local taxation, why not go the whole hog and abolish it completely?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4516, 'go through', 'If a law, plan, or deal goes through, it is officially accepted or approved:', 'A city council member said that the proposals for the new shopping centre were unlikely to go through.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4517, 'go through something', 'to experience a difficult or unpleasant situation:', 'I''ve been going through a bad patch recently.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4518, 'go through something', 'to examine something that contains a collection of things carefully in order to organize them or find something:', 'I''m going through my wardrobe and throwing out all the clothes I don''t wear any more.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4519, 'go through something', 'to do something in order to practise or as a test:', 'Why don''t we go through the whole demonstration once more?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4520, 'go through something', 'to use a lot of something:', 'Before I gave up coffee, I was going through five cups a day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4521, 'go through a bad/difficult/rough/sticky patch', 'to experience a lot of problems in a period of your life:', 'Andy''s going through a rough patch at the moment - his wife wants a divorce.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4522, 'go through fire and water', 'to experience many difficulties or dangers in order to achieve something', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4523, 'go through the floor', 'to fall to very low levels:', 'House prices have gone through the floor this year.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4524, 'go through the mill', 'to have a lot of problems or difficulties:', 'Many people who have been divorced have been through the mill psychologically.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4525, 'go through the motions', 'to do something without thinking it is very important or having much interest in it:', 'He says he''s been investigating my complaint, but I feel he''s just going through the motions.', 'idiom', 'C2', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4526, 'go through the roof', 'to rise to a very high level:', 'Prices have gone through the roof.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4527, 'go through the roof', 'to get very angry:', 'When I was expelled from school, my parents went through the roof.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4528, 'go through the wringer/put someone through the wringer', 'to have a difficult experience that upsets you a lot, or to make someone experience this:', 'The girl''s parents have been through the wringer since she disappeared.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4529, 'go through with something', 'to do something unpleasant or difficult that has already been agreed or promised:', 'He''d threatened to divorce her but I never thought he''d go through with it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4530, 'go to bat for someone', 'to support someone when the person needs help:', 'Senators will go to bat for companies that pay lots of taxes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4531, 'go to bed with someone', 'to have sex with someone', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4532, 'go to blazes', 'used to tell someone to go away', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4533, 'go to great lengths', 'to try very hard to achieve something:', 'Some people go to great lengths to make their homes attractive.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4534, 'go to hell', 'used to angrily tell someone to stop talking and go away:', '"Anyway, it''s your own fault." "Oh, go to hell!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4535, 'go to hell and back', 'to live through an extremely unpleasant, difficult, or painful experience:', 'I''ve been to hell and back over this court case.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4536, 'go to pieces', 'to become unable to think clearly and control your emotions because of something unpleasant or difficult that you have experienced:', 'She went to pieces at the funeral.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4537, 'go to pot', 'infml to become worse or be spoiled because of lack of care or effort:', 'Our old neighborhood has gone to pot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4538, 'go to sleep', 'If your arm or leg has gone to sleep, you cannot feel or control it, often because you have been sitting or lying for too long in a strange position.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4539, 'go to someone', 'to be given or sold to someone:', 'Who did the award for Best Actress go to?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4540, 'go to someone''s head', 'If something goes to someone''s head, it makes that person think that they are very important and makes them a less pleasant person:', 'Don''t let fame/success go to your head.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4541, 'go to someone''s head', 'If alcohol goes to your head, it makes you feel slightly drunk:', 'Champagne always goes straight to my head.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4542, 'go to the bad', 'to become a morally bad person:', 'She thought her children would go to the bad unless they were strictly brought up.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4543, 'go to the bathroom', 'to use the toilet:', 'Wait a moment - I just need to go to the bathroom.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4544, 'go to the country', 'to have an election:', 'The prime minister has decided to go to the country.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4545, 'go to the devil', 'something you say to someone annoying or bad to tell them to go away for ever', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4546, 'go to the dogs', 'If a country or organization is going to the dogs, it is becoming very much less successful than it was in the past.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4547, 'go to the stake for something', 'to defend an action, opinion, or belief despite the risks that are involved:', 'She was prepared to go to the stake for her views.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4548, 'go to the trouble to do something', 'to make an effort to do something:', 'If the police had gone to the trouble of looking up his record, they would not have released him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4549, 'go to the wall', 'to be destroyed or fail:', 'After nine months of massive losses the company finally went to the wall.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4550, 'go to the wall', 'to do everything you can to achieve something or help someone:', 'These guys will go to the wall for you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4551, 'go to town', 'to do something in a detailed and enthusiastic way, especially by spending a lot of money:', 'They''ve really gone to town on their wedding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4552, 'go to town (on something)', 'to do something eagerly and as completely as possible:', 'Kayla and Josh really went to town on their wedding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4553, 'go toe to toe', 'to be willing or able to compete or fight with someone in a strong, forceful, determined way:', 'We had a good candidate who stood toe to toe with the President and beat him in three debates.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4554, 'go toe to toe', 'to have equal or similar scores, or to be performing equally well in a competition, so that it is not clear who will win:', 'The pair went toe to toe until the third set, when Azarenka squandered two match points.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4555, 'go together', 'to look good together:', 'Do you think the cream dress and the blue jacket go together?', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4556, 'go together', 'to happen or be found together:', 'Wisdom and maturity don''t necessarily go together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4557, 'go together', 'If two people are going together, they have a romantic or sexual relationship with each other.', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4558, 'go too far', 'to behave in a way that upsets or annoys people:', 'His jokes are funny, but sometimes he goes too far.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4559, 'go under', 'to sink:', 'The ship went under just minutes after the last passenger had been rescued.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4560, 'go under', 'If a company goes under, it fails financially:', 'The charity will go under unless a generous donor can be found within the next few months.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4561, 'go under the knife', 'to have a medical operation:', 'More and more women are choosing to go under the knife to improve their appearance.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4562, 'go up', 'to move higher, rise, or increase:', 'The average cost of a new house has gone up by five percent to £276,500.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4563, 'go up', 'to suddenly explode:', 'There''s a gas leak and the whole building could go up at any moment.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4564, 'go up', 'If a sign goes up, it is fixed into position:', 'The new "No Parking" signs went up yesterday.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4565, 'go up', 'If a building goes up, it is built:', 'A new factory is going up at the site of the old airport.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4566, 'go up', 'If you go up to a college or university, especially Oxford University or Cambridge University, you begin studying there, or continue studying after a holiday.', '', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4567, 'go up in flames', 'to burn or be destroyed by fire:', 'The factory went up in flames.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4568, 'go up in flames', 'to be damaged or destroyed:', 'His career went up in flames when he was jailed for theft.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4569, 'go up in smoke', 'to be wasted:', 'When the business went bankrupt, twenty years of hard work went up in smoke.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4570, 'go up to something', 'to reach as far as something:', 'The path going up to the back door is very muddy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4571, 'go walkabout', 'If you say that an object has gone walkabout you mean that it is missing, often because someone has taken it:', 'My pen was here this morning but it seems to have gone walkabout.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4572, 'go west', 'If something goes west, it is lost, damaged, or spoiled in some way:', 'I couldn''t get a ticket - that''s my last chance to see the show gone west.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4573, 'go whole hog', 'to do something as completely as possible:', 'He decided to go whole hog and wear a tuxedo rather than just a suit.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4574, 'go with a bang', 'If a party or event goes with a bang, it is very exciting and successful.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4575, 'go with something', 'If one thing goes with another, they suit each other or they look or taste good together:', 'This wine goes particularly well with seafood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4576, 'go with something', 'If a problem, activity, or quality goes with another one, they often happen or exist together and the first thing is often caused by the second:', '[ + -ing verb ] What are the main health problems that go with smoking?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4577, 'go with someone', 'to have a romantic or sexual relationship with someone:', 'Did he ever go with anyone else while they were living together?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4578, 'go with someone/something', 'to accept an idea or agree with a person:', 'I think we can go with the advertising agency''s suggestions, don''t you?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4579, 'go with the flow', 'to do what other people are doing or to agree with other people because it is the easiest thing to do:', 'Just relax and go with the flow!', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4580, 'go with the territory', 'to be part of a particular activity:', 'Criticism goes with the territory in politics.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4581, 'go without (something)', 'to not have something or to manage to live despite not having something:', 'They were poor as children, and sometimes had to go without.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4582, 'go wrong', 'to make a mistake or a bad decision:', 'If you just follow the signs to the park, you can’t go wrong.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4583, 'go wrong', 'If a situation goes wrong, there are problems or there is a bad result:', 'I was so worried that something had gone wrong that I called the police.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4584, 'go your (own) separate ways', 'If two or more people go their separate ways, they stop being together:', 'In 1983 the group disbanded and went their separate ways.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4585, 'go your own (sweet) way', 'to do what you want without considering other people:', 'It doesn''t matter how much advice I give Cathy, she always goes her own sweet way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4586, 'go your own/separate way', 'When people or groups of people choose to go their own way, they decide to live or work without continuing their previous personal or business relationship:', 'After a couple of years together, we realized we weren''t really happy and decided to go our separate ways.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4587, 'go/be back to square one', 'to be forced to think of a new course of action because your first course of action failed:', 'The deal with the house fell through so I''m afraid we''re back to square one.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4588, 'go/be run to ground', 'to hide in order to escape someone or something following you:', 'He found the media attention intolerable and went to ground for several months.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4589, 'go/come down in the world', 'to have less money or a worse social position than you had before:', 'They used to live in a big house with lots of servants, but they''ve come down in the world since then.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4590, 'go/come up in the world', 'to have more money or a better social position than you had before:', 'Roger and Ann have gone up in the world - these days they only ever travel first-class.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4591, 'go/come with the territory', 'to be an expected fact or result of a particular situation or position:', 'The public attention that famous people get just goes with the territory.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4592, 'go/do the rounds', 'to go from person to person or place to place:', 'That story has gone the rounds in our office.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4593, 'go/get back to nature', 'to start living a more simple life, often in the country', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4594, 'go/get/head nowhere', 'to not have any success or achieve anything:', 'I''m trying to persuade her to come, but I''m getting nowhere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4595, 'go/jump through hoops', 'to do a lot of difficult things before you are allowed to have or do something you want', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4596, 'go/run around in circles', 'to keep doing or talking about the same thing without achieving anything:', 'The discussion kept going around in circles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4597, 'go/run round in circles', 'to keep doing or talking about the same thing without achieving anything:', 'The discussion kept going round in circles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4598, 'go/sell like hot cakes', 'to be bought quickly and in large numbers:', 'The new game is apparently selling like hot cakes.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4599, 'go/sell like hotcakes', 'to be bought quickly and in large numbers', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4600, 'go/send something/someone flying', 'to fall, or to cause something or someone to fall or move through the air, suddenly and by accident:', 'I tripped going up the stairs and I/my books went flying.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4601, 'go/swim against the tide', 'to not follow what everyone else is doing', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4602, 'go/swim with the tide', 'to follow what everyone else is doing:', 'I thought I''d just swim with the tide and leave when everyone else does.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4603, 'go/turn beetroot (red)', 'to have a red face because you are embarrassed:', 'Whenever I talked about his past life, he would go beetroot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4604, 'go/turn green', 'to look pale and ill as if you are going to vomit', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4605, 'go/walk down the aisle', 'to get married', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4606, 'gobble something up', 'to gobble', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4607, 'gobble something up', 'to use a lot of your supply of something, usually money:', 'The mounting legal costs quickly gobbled up their savings.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4608, 'gobs of something', 'large amounts of something:', 'He''s got gobs of money.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4609, 'going away', 'In sports, if a team or person wins a competition going away, they win it by a lot of points, goals, etc.:', 'They seemed to score at will in the final period and the Knicks won going away.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4610, 'good and ...', 'very:', 'Drink your coffee while it''s good and hot.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4611, 'good and proper', 'completely:', 'The table is broken good and proper.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4612, 'good cop, bad cop', 'used to describe a situation in which two police officers or any two people try to achieve something together, by one of them being friendly and pleasant and the other using threats or force:', 'The good cop - bad cop scenario is given a dizzying, dazzling twist in this movie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4613, 'good heavens/grief/gracious!', 'used to emphasize how surprised, angry, shocked, etc. you are', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4614, 'good idea', 'used for saying that you like or agree with someone''s suggestion:', '"You could grow roses or honeysuckle up that wall." "Good idea!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4615, 'good job!', 'used for praising someone for something they have done well:', 'The house looks great - good job, guys!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4616, 'good riddance', 'I am happy that someone or something is gone:', 'Our neighbors and their nasty dogs have moved out – good riddance!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4617, 'good shout', 'used for saying that you think something is a good idea:', '"Anyone fancy a burger?" "Good shout."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4618, 'good show', 'used as an expression of approval:', 'Good show chaps, you completed the course in the time allowed.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4619, 'good things come in small packages', 'said to emphasize that something does not need to be big in order to be good', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4620, 'good/bad karma', 'the good or bad general character or feeling among a group of people or in a place:', 'In the early 60s hippies arrived, attracted by the island''s "good karma" and physical beauty.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4621, 'good/great/lovely stuff!', 'something you say to encourage or praise someone:', '"The sales figures are up this week." "Great stuff!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4622, 'goodbye to something', 'used when accepting that there is no possibility of getting, keeping, or achieving a particular thing:', 'She only finished sixth - that surely means goodbye to a place in the final.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4623, 'goof around', 'to spend time doing nothing important or behaving in a silly way:', 'The boys spent the whole summer just goofing around.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4624, 'goof off', 'to avoid doing any work:', 'The teacher told them to stop goofing off and get back to work.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4625, 'goof up', 'to do something badly or make a silly mistake that causes something to fail:', 'He''s just waiting for Susan to goof up so he can get her job.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4626, 'got it in one!', 'something that you say when someone has guessed something correctly:', '"Don''t tell me - is Anna pregnant again?" "Got it in one!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4627, 'gouge something out', 'to remove something by digging or cutting it out of a surface:', 'In Shakespeare''s play "King Lear" the Earl of Gloucester''s eyes are gouged out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4628, 'grab at something/someone', 'to try to get hold of someone or something quickly, with your hand', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4629, 'graft sth onto sth', 'to try to combine one idea, method, etc. with another, especially when the two things are very different:', 'The editors attempted to graft new reporting onto previously published articles.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4630, 'grand old age', 'If a person or animal lives to a grand old age, they live until they are very old:', 'He lived to the grand old age of 97.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4631, 'grandfather sb/sth into sth', 'to allow someone to continue to do or to have something that a new law or rule makes illegal:', 'Most existing companies will be grandfathered into the old system for up to five years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4632, 'grapple with someone', 'to hold onto someone and fight with them:', 'Two officers grappled with the gunman.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4633, 'grapple with something', 'to try to deal with or understand a difficult problem or subject:', 'Today, many Americans are still grappling with the issue of race.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4634, 'grasp at something', 'to try to take an opportunity:', 'Certainly if the job were offered me I''d grasp at the chance.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4635, 'grasp at something', 'to try to hold or touch something:', 'She grasped at his shirt as he ran past.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4636, 'grasp the nettle', 'to force yourself to be brave and do something that is difficult or unpleasant:', 'You''ve been putting off making that phone call for days - I think it''s about time you grasped the nettle!', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4637, 'grasping at straws', 'trying to find some way to succeed when nothing you choose is likely to work:', 'We searched all the backup tapes, trying to find the missing files, but we knew we were grasping at straws.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4638, 'grasping at straws', 'trying to find a reason to feel hopeful in a bad situation:', 'I knew my mother was dying, but I was grasping at straws and denying reality.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4639, 'grass on someone', 'If a person grasses on someone else, they tell the police or someone in authority about something bad that that person has done:', 'Dan grassed on them to the local police.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4640, 'grass something over', 'to grow grass on an area of land', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4641, 'grateful/thankful for small mercies', 'If someone should be grateful/thankful for small mercies, they should be grateful for something because it is not as bad as it could have been:', 'She wasn''t badly hurt in the accident, so we''re grateful for small mercies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4642, 'gravitate toward/to something/someone', 'to be attracted by or to move in the direction of something or someone:', 'Susie always gravitates toward the older children in her playgroup.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4643, 'gravitate towards/to something/someone', 'to be attracted by or to move in the direction of something or someone:', 'Susie always gravitates towards the older children in her playgroup.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4644, 'grease someone''s palm', 'to secretly give someone money in order to persuade them to do something for you', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4645, 'great minds think alike', 'said to someone just after you have discovered that they have had the same idea as you', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4646, 'green with envy', 'wishing very much that you had what someone else has:', 'When I heard about his new job I was green with envy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4647, 'greener pastures', 'a new place or activity that offers new opportunities:', 'Many scientists working for the government have left for greener pastures in the private sector.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4648, 'greet/welcome someone with open arms', 'to show someone that you are very pleased to see them', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4649, 'grin and bear it', 'to accept something bad without complaining:', 'I really don''t want to go, but I guess I''ll just have to grin and bear it.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4650, 'grin/smile from ear to ear', 'to look extremely happy:', '"We''ve had a fantastic response!" he said, grinning from ear to ear.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4651, 'grind someone down', 'to treat someone so badly for such a long time that they are no longer able to fight back:', 'Ground down by years of abuse, she did not have the confidence to leave him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4652, 'grind something into something', 'to press something hard into something else using a twisting movement:', 'Sara angrily ground her cigarette into the ashtray.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4653, 'grind something out', 'to produce the same thing, especially a boring thing, again and again:', 'The band ground out the same tunes it had been playing for 20 years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4654, 'grind the faces of the poor', 'Someone who grinds the faces of the poor, treats poor people very badly, often to get money from them.', '', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4655, 'grind to a halt', 'to stop or no longer work well:', 'Traffic ground to a halt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4656, 'grind to a halt/standstill', 'to stop slowly:', 'The car ground to a halt right in the middle of the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4657, 'grit your teeth', 'to press your top and bottom teeth together, often in anger:', 'He gritted his teeth in silent fury.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4658, 'grit your teeth', 'to accept a difficult situation and deal with it in a determined way:', 'We had to grit our teeth and agree with their conditions because we wanted the contract.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4659, 'groan with/under (the weight of) something', 'to carry a very large quantity of something:', 'The tables were positively groaning with food.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4660, 'grope for something', 'to try to think of something, especially the right words, the correct answer, etc.:', 'I''m groping for the right words here.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4661, 'gross someone out', 'If something grosses you out, you think it is very unpleasant or disgusting:', 'He smells and he''s dirty - he really grosses me out.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4662, 'gross something up', 'to increase an amount by adding something that is not normally included, such as tax:', 'All costs were grossed up for tax deductions.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4663, 'grow apart', 'If two people in a close relationship grow apart, or if they grow away from each other, they gradually begin to have a less close relationship, usually because they no longer have the same interests and want the same things:', 'There was nobody else involved - we just grew apart.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4664, 'grow into someone/something', 'to develop into a particular type of person or thing:', 'He''s grown into a fine, responsible young man.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4665, 'grow into something', 'If children grow into clothes, they gradually become big enough to wear them.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4666, 'grow on someone', 'If someone or something grows on you, you like him, her, or it more and more than you did at first:', 'I wasn''t sure about this album when I bought it, but it''s really grown on me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4667, 'grow out of something', 'If children grow out of clothes, they become too big to fit into them.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4668, 'grow out of something', 'If you grow out of an interest or way of behaving, you stop having or doing it as you become older:', 'Lucas says he wants to join the army when he turns 18, but I hope he''ll grow out of the idea.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4669, 'grow out of something', 'If an idea grows out of another one, it develops from it:', 'The idea for the story grew out of a strange experience I had last year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4670, 'grow up', 'to gradually become an adult:', 'I grew up in Scotland (= I lived there when I was young).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4671, 'grow up', 'to behave like an adult; used to criticize someone who you think is being silly or unreasonable:', 'Everyone should just grow up and treat each other with respect.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4672, 'grow up', 'If a town or city grows up in a particular place or way, it develops there or in that way:', 'The city grew up originally as a crossing point on the river.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4673, 'grub something up/out', 'to dig something out of the ground to get rid of it:', 'She spent the morning in the garden, grubbing up weeds.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4674, 'guard against something', 'to take careful action in order to try to prevent something from happening:', 'Regular exercise helps guard against heart disease.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4675, 'guess at something', 'to try to imagine something when you have little knowledge or experience of it:', 'There are no photographs of him, so we can only guess at what he looked like.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4676, 'guilty as charged', 'responsible for doing something illegal that you have been accused of in court:', 'They were guilty as charged and fairly tried, and therefore justice was served.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4677, 'guilty as charged', 'used to admit that what someone has been accused of is true, often when you think this is not really bad:', 'Guilty as charged! I am an Elvis fan!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4678, 'gulp down something', 'to eat or drink something quickly:', 'He hardly has time to gulp down a piece of pizza.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4679, 'gulp something back', 'to try not to show that you are upset, usually by swallowing hard:', 'She gulped back the tears.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4680, 'gum something up', 'to prevent something from working or opening in the usual way because of being blocked or stuck :', 'When I woke up this morning my eyes were all gummed up.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4681, 'gun for something', 'to make a great effort to win or obtain something:', 'Irwin is gunning for his third straight championship.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4682, 'gun for someone', 'to make a great effort to defeat or hurt someone:', 'We know all the other teams are gunning for us.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4683, 'gun for someone', 'If someone is gunning for someone else, that person can also be trying to shoot or attack the other one.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4684, 'gun someone down', 'to shoot someone and kill or seriously injure them, often when that person cannot defend himself or herself:', 'The police officer was gunned down as he took his children to school.', 'phrasal verb', '', 'old-fashioned, informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4685, 'gussy someone/something up', 'to make someone or something look more attractive or impressive:', 'The museum will put finishing touches on new exhibits and gussy up old ones in time for the grand reopening.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4686, 'hack away at sth', 'to slowly reduce the amount of money, staff, or resources that are needed in order to be successful:', 'Profits are in a free fall, and companies are slashing spending on new equipment and hacking away at payrolls.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4687, 'hack someone off', 'to make someone feel annoyed:', 'He leaves all the difficult stuff for me to do, and it really hacks me off.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4688, 'had best', 'used to suggest an action or to show that it is necessary:', 'You had best tell her (= it would be wise if you told her) that you won''t be able to come to her party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4689, 'had better/best do something', 'If you had better/best do something, you should do it or it would be good to do it:', 'I''d better leave a note so they''ll know I''ll be late.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4690, 'had it coming (to you)', 'If someone had it coming, something bad happened to them that was deserved:', 'He''s been fired but, with all that time he took off, he had it coming really.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4691, 'hail from somewhere', 'to come from or to have been born in a particular place:', 'Joe originally hails from Toronto.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4692, 'hail someone/something as something', 'to praise a person or an achievement by comparing them to someone or something very good:', 'She''s been hailed as one of the best young dancers today.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4693, 'half a loaf is better than none', 'said about a situation in which you must accept less than you wanted', '', 'idiom', '', 'old-fashioned, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4694, 'half the battle', 'a large part of the effort or work that is needed:', 'With so many search engines on the Web, deciding which one is best is half the battle.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4695, 'ham it up', 'to perform or behave in a false way, especially in a way that is too obvious or that makes people laugh', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4696, 'hammer away at something', 'to work without stopping and with a lot of effort', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4697, 'hammer something home', 'to make certain that something is understood by expressing it clearly and forcefully:', 'The advertising campaign will try to hammer home the message that excessive drinking is a health risk.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4698, 'hammer something into someone', 'to force someone to understand something by repeating it a lot:', 'I always had it hammered into me that I mustn''t lie.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4699, 'hammer something out', 'to reach an agreement or solution after a lot of argument or discussion:', 'Three years after the accident the lawyers finally managed to hammer out a settlement with the insurance company.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4700, 'hammer sth down', 'to reduce prices or costs by a large amount:', 'Government policies designed to help consumers by hammering down the price of cars also played their part in the company''s plans to axe 2,000 jobs .', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4701, 'hand in glove', 'working together, often to do something dishonest:', 'It was rumoured at the time that some of the gangs were working hand in glove with the police.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4702, 'hand in hand', 'holding each other''s hand:', 'I saw them walking hand in hand through town the other day.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4703, 'hand off', 'in American football, to pass by putting the ball directly into the hands of another player:', 'Favre handed off to Grant.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4704, 'hand something off', 'to pass or give something to someone:', '"Look over there!" he said, handing off his binoculars to the woman standing next to him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4705, 'hand something off', 'in American football, to pass the ball directly into the hands of another player:', 'He was happy to hand off the ball more at the start of this season.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4706, 'hand something off', 'to give another person control of something, or responsibility for dealing with him, her, or it:', 'The work could be handed off to another firm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4707, 'hand over fist', 'If you make or lose money hand over fist, you make or lose a lot of money very quickly:', 'Business was good and we were making money hand over fist.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4708, 'hand something around', 'to pass or offer something to all the people in a group:', 'Adam, could you hand around the cookies?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4709, 'hand something back', 'to return something to the person who gave it to you:', '[ + two objects ] "No, I''ve never seen him before," I said, handing her back the photograph.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4710, 'hand something down', 'to give something to someone younger than you in the family because you want them to have it or because you no longer need it:', 'This necklace was handed down to my mother by my grandmother.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4711, 'hand something down', 'to pass traditions from older people to younger ones:', 'a custom handed down through the generations', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4712, 'hand something down', 'to announce an official decision, especially in a court of law:', 'The court handed down an eight-year sentence.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4713, 'hand something in', 'to give something to someone in a position of authority:', 'Have you handed in your history essay yet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4714, 'hand something out', 'to give something to each person in a group or place:', 'The teacher asked her to hand out the worksheets.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4715, 'hand something out', 'to give something such as a prize or reward, especially generously or in large amounts:', 'He is not known for handing out effusive praise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4716, 'hand something out', 'to announce an official decision, especially in a court of law:', 'She said she was pleased with the judge''s decision to hand out a harsher punishment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4717, 'hand something over', 'to give something to someone else:', 'We were ordered to hand over our passports.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4718, 'hand something/someone over', 'to give another person control of someone or something, or responsibility for dealing with him, her, or it:', 'The hijacker was handed over to the French police.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4719, 'hand something round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4720, 'hand sth on', 'to give something to someone else:', 'hand sth on to sb The business will be handed on to his family or sold.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4721, 'hand sth on', 'to give responsibility for something to someone else:', 'A year ago, she handed on the administrative directorship to become development director.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4722, 'handbags (at dawn)', 'used to talk about a situation in which two football players seem angry and threatening but do not actually fight:', 'It wasn''t a serious confrontation - just handbags.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4723, 'handle/treat someone with kid gloves', 'to be very polite or kind to someone because you do not want to make them angry or upset', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4724, 'hands down', 'definitely:', 'If we had a race, he’d win hands down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4725, 'hang around', 'to move or do things slowly:', 'Go and pack but don''t hang around - we have to go in an hour.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4726, 'hang around (somewhere)', 'to wait or spend time somewhere, usually for no particular reason:', 'I spent most of my youth hanging around the bars of Dublin.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4727, 'hang around with someone', 'to spend time with someone:', 'I got into drugs because I was hanging around with the wrong people.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4728, 'hang back', 'to be slow to do something, often because of fear or having no confidence:', 'There''s no need to hang back - you can sing as well as anyone.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4729, 'hang by a thread', 'If a serious situation hangs by a thread, it means that even a slight change can decide what will happen and that a bad result such as death, failure, etc. is likely:', 'The mayor''s political future has been hanging by a thread since the fraud scandal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4730, 'hang in there', 'said as a way of telling someone to not give up, despite difficulties:', 'Work can get tough in the middle of a term but hang in there and it''ll be OK.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4731, 'hang on', 'to wait for a short time:', 'Sally''s on the other phone - would you like to hang on?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4732, 'hang on', 'to hold or continue holding onto something:', 'Hang on tight - it''s going to be a very bumpy ride.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4733, 'hang something on someone', 'to blame someone for something, especially something they did not do:', 'I wasn''t anywhere near the house when the window was broken, so you can''t hang that on me!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4734, 'hang on/upon something', 'to give careful attention to something, especially something that someone says:', 'He hangs on her every word as if she were some sort of goddess.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4735, 'hang on/upon something', 'to depend on something:', 'The safety of air travel hangs partly on the thoroughness of baggage checking.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4736, 'hang onto something', 'to keep something:', 'You should hang onto that painting - it might be valuable.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4737, 'hang out', 'to spend a lot of time in a place or with someone:', 'You still hang out at the pool hall?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4738, 'hang over something', 'If a threat or doubt hangs over a place or a situation, it exists:', 'Uncertainty again hangs over the project.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4739, 'hang round (somewhere)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4740, 'hang round with someone', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4741, 'hang someone out to dry', 'to allow someone to be punished, criticized, or made to suffer in a way that is unfair, without trying to help them:', 'They felt they had been hung out to dry by their employers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4742, 'hang the cost/expense', 'the cost is not important:', 'Just buy it and hang the expense!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4743, 'hang together', 'If people hang together, they help each other and work together to achieve something:', 'If the opposition party can hang together over the next six months, they might just stand a chance of being elected.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4744, 'hang together', 'If the parts of something hang together, they are well organized or they seem to be true or correct:', 'Somehow her story doesn''t quite hang together.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4745, 'hang tough', 'to not change your actions or opinions although other people try to make you do this:', 'The president is hanging tough on the hostage crisis.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4746, 'hang up', 'to end a phone conversation:', 'He started shouting so I hung up (on him).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4747, 'hang something up', 'to stop using and needing something because you have given up the sport or activity it is used for:', 'So when did you hang up your boxing gloves/golf clubs/ballet shoes?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4748, 'hang your head', 'to be ashamed or unhappy:', 'We played a great game – we have no reason to hang our heads.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4749, 'hang/hold fire', 'to delay making a decision:', 'Ideally we would settle the matter now, but I think we should hang fire until the general situation becomes clearer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4750, 'hang/hold on like grim death', 'to hold on very tightly to something, despite great difficulty:', 'Darren always drives and I sit behind him, hanging on like grim death.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4751, 'hang/stay loose', 'to be calm and relaxed', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4752, 'hanker after/for something', 'to have a strong wish for something, especially if you cannot or should not have it:', 'What did you hanker after most when you were in prison?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4753, 'happen along/by (somewhere)', 'to go to a place by chance or without planning to:', 'I''d have drowned if he hadn''t happened along and pulled me out of the river.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4754, 'happen on/upon something/someone', 'to find or meet something or someone by chance:', 'Eventually they happened on a road leading across the desert.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4755, 'happy ever after', 'happy or happily for the rest of your life, especially in a romantic relationship:', 'They were all going to live in the country and be happy ever after.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4756, 'happy ever after', 'a situation in which someone is happy and satisfied for the rest of their life, especially in a romantic relationship:', 'But some weddings don''t lead to happy ever after.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4757, 'happy place', 'a memory, situation, or activity that makes you feel happy:', 'Print design is my happy place.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4758, 'hard Brexit', 'a Brexit in which the United Kingdom stops being a member of the European single market and gets full control of its own law-making and immigration:', 'Investors worried about a "hard Brexit" sent the pound to a three-decade low.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4759, 'hard at it', 'putting a lot of effort into what you are doing:', 'That''s what I like to see - everybody hard at it!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4760, 'hard feelings', 'anger towards someone that you have argued with:', 'So we''re friends again, are we? No hard feelings?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4761, 'hard luck!', 'used to express sympathy to someone because something slightly bad has happened:', '"We lost again." "Oh, hard luck!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4762, 'hard to swallow', 'difficult to believe:', 'I found her story rather hard to swallow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4763, 'hard/hot/close on someone''s heels', 'following someone very closely:', 'She ran down the steps with a group of journalists hard on her heels.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4764, 'hard/tough as nails', 'not feeling or showing any emotions such as sympathy, fear, or worry', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4765, 'hard/tough cheese!', 'something that you say to indicate that you have no sympathy for someone or cannot do anything to help them:', 'This is the only food we have left, and if you don''t like it, hard cheese.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4766, 'harden your heart', 'to make yourself stop feeling kind or friendly towards someone:', 'You''ve just got to harden your heart and tell him to leave.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4767, 'hardly/barely put one foot in front of the other', 'If you can hardly/barely put one foot in front of the other, you are having difficulty walking:', 'I was so tired that I could hardly put one foot in front of the other.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4768, 'hark at someone!', 'said to someone who has just accused you of something that you think that person is guilty of himself or herself:', 'Hark at him calling me lazy when he never walks anywhere if he can drive!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4769, 'hark back', 'to remember or to cause someone to remember something from the past:', 'The director’s latest film harks back to the era of silent movies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4770, 'hark back to something', 'If someone harks back to something in the past, they talk about it again and again, often in a way that annoys other people:', 'He''s always harking back to his childhood and saying how things were better then.', 'phrasal verb', '', 'old use', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4771, 'hark back to something', 'If something harks back to something in the past, it is similar to it:', 'The director''s latest film harks back to the early years of cinema.', 'phrasal verb', '', 'old use', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4772, 'harm a hair on someone''s head', 'to hurt someone:', 'If he so much as harms a hair on her head, I won''t be responsible for my actions.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4773, 'harp on (about sth)', 'to talk or complain about something many times:', 'He''s always harping on about lack of discipline.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4774, 'harp on sth', 'to talk or complain about something many times:', 'He''s always harping on our lack of discipline.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4775, 'has the cat got your tongue?', 'something you say to someone when you are annoyed because they will not speak:', 'What''s the matter? Has the cat got your tongue?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4776, 'hash something out', 'to talk about something with someone else in order to reach agreement about it:', 'You two hash out the details of the presentation.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4777, 'hash something up', 'to spoil something by doing it badly:', 'The first interview was all right but I think I hashed up the second one.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4778, 'hate on someone', 'to criticize someone or say bad things about them, in an unpleasant and public way:', 'These kids get hated on for no good reason at all.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4779, 'hate someone''s guts', 'to dislike someone very much', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4780, 'hats off to someone', 'said to praise and thank someone for doing something helpful:', 'Hats off to Connie for finding such a splendid venue for a party!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4781, 'haul ass', 'to move very quickly to a different place:', 'When the shooting started we hauled ass out of there.', 'idiom', '', 'very informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4782, 'haul someone up', 'to force someone to go somewhere or see someone in order to be punished or to answer questions about their behaviour:', 'He was hauled up in court/in front of a judge.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4783, 'haul someone/something away', 'to take someone or something somewhere:', 'Most of the buildings are simply flattened and hauled away to local dumps.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4784, 'haul/drag someone over the coals', 'to speak angrily to someone because they have done something you disapprove of:', 'He was hauled over the coals for coming in late for work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4785, 'have (all) the makings of something', 'to seem likely to develop into something:', 'She has the makings of a great violinist.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4786, 'have (got) a hand in something', 'to be involved with something or have influence on something:', 'Who planned the party – I bet you had a hand in it, didn''t you?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4787, 'have (got) it bad', 'to be very much in love', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4788, 'have (got) it made', 'to be certain to be successful and have a good life, often without much effort:', 'With his father at the head of the firm, he''s got it made.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4789, 'have (got) only yourself to blame', 'to be responsible for something bad that has happened:', 'He didn’t study, so he’s got only himself to blame if he fails.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4790, 'have (got) sb sussed', 'to understand what someone is like:', 'I reckon I''ve got him sussed.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4791, 'have (got) sth sussed', 'to realize, understand, or know something about a situation, plan, etc.:', 'All those people who you thought had it sussed are in fact faking it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4792, 'have (got) someone by the short and curlies', 'to have someone in your power', '', 'idiom', '', 'very informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4793, 'have (got) someone''s back', 'to be ready to protect or defend someone:', 'Don''t worry. I''ve got your back.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4794, 'have (got) something licked', 'to have solved a problem', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4795, 'have (got) something on', 'If you have clothes or shoes on, you are wearing them:', 'I loved that dress you had on last night.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4796, 'have (got) something on', 'If you have something on, you have planned to do it:', 'Do you have anything on this week?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4797, 'have (got) the hots for someone', 'to be very sexually attracted to someone:', 'She''s got the hots for this guy in her office.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4798, 'have (got) to hand it to someone', 'If you say you have (got) to hand it to someone you mean that they have been very successful or skilful:', 'I mean you''ve got to hand it to her, she''s brought up those three children all on her own.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4799, 'have (got) your hands full', 'to be very busy or involved with something:', 'I’ve got my hands full right now with a sick baby.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4800, 'have (got) your heart set on something', 'to want something very much, so that you would be very disappointed if you do not get it:', 'She’s got her heart set on ballet lessons.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4801, 'have (just about) had it', 'infml to not be willing or able to continue doing something:', 'We’ve been to three museums today and I’ve just about had it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4802, 'have (just about) had it', 'If something has had it, it is not working any longer:', 'This old vacuum cleaner has had it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4803, 'have (more than) your share of something', 'to have had a lot or too much of something:', 'We’ve had our share of problems with the new computer system.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4804, 'have (sexual) relations (with someone)', 'to have sex or a sexual relationship with someone:', 'The couple had been having sexual relations for a year.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4805, 'have (someone''s) blood on your hands', 'to be responsible for someone''s death:', 'The leaders of this war have the blood of many thousands of people on their hands.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4806, 'have a (good) head for something', 'to have a natural ability to do something well:', 'Kim has a head for numbers.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4807, 'have a (good) nose for something', 'to be good at finding things of the stated type:', 'She has a good nose for a bargain.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4808, 'have a ball', 'to enjoy yourself very much:', '"So how was the party last night?" "Oh, it was great - we had a ball!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4809, 'have a bee in your bonnet', 'to keep talking about something again and again because you think it is very important:', 'She never stops talking about healthy eating - she''s got a real bee in her bonnet about it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4810, 'have a blonde moment', 'to forget something or do something silly, in a way that is sometimes thought to be typical of women with blonde hair', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4811, 'have a bone to pick with someone', 'to want to talk to someone about something annoying they have done:', 'I''ve got a bone to pick with you - you''ve been using my shaver again.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4812, 'have a bumpy ride', 'to have a difficult time:', 'She''s had a bumpy ride at work over the last few months.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4813, 'have a bun in the oven', 'to be pregnant', '', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4814, 'have a butcher''s', 'to look at something:', 'Let''s have a butcher''s at your present, then.', 'idiom', '', 'old-fashioned, slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4815, 'have a card up your sleeve', 'to have an advantage that other people do not know about:', 'England have definitely been the weaker side, but I think they''ve still got one or two cards up their sleeve.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4816, 'have a care', 'used to tell someone to be more careful', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4817, 'have a chip on your shoulder', 'to seem angry all the time because you think you have been treated unfairly or feel you are not as good as other people:', 'He''s got a chip on his shoulder about not having been to university.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4818, 'have a corner on a market', 'If a company has a corner on a particular market, it is more successful than any other company at selling a particular type of product.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4819, 'have a cow', 'to be very worried, upset, or angry about something:', 'My mother had a cow when I said I was going to buy a motorbike.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4820, 'have a face like the back end of a bus', 'to be very ugly', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4821, 'have a face like thunder', 'to look extremely angry:', 'She suddenly came into the room with a face like thunder.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4822, 'have a familiar ring (to it)', 'to seem or sound like something you have heard or seen before:', 'Her name had a familiar ring to it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4823, 'have a few (too many)', 'to drink quite a large number of, or too many, alcoholic drinks:', 'By the look of her, she''d had a few even before she arrived at the party.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4824, 'have a few, several, etc. irons in the fire', 'to be involved with many activities or jobs at the same time or to make certain that there are always several possibilities available:', 'If that job application doesn''t work out I''ve got a couple more irons in the fire.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4825, 'have a field day', 'to take advantage of an opportunity to do something you enjoy:', 'The newspapers had a field day when the wedding was announced (= they wrote a lot about it and printed many photographs of it).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4826, 'have a finger in every pie', 'to be involved in and have influence over many different activities, often in a way that people do not approve of', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4827, 'have a finger in the pie', 'to be involved in something, often when your involvement is not wanted', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4828, 'have a fit', 'to become very angry:', 'My mother threw a fit when she saw the mess we made.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4829, 'have a fling', 'to have a short sexual relationship with someone:', 'She''s been having a fling with her boss.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4830, 'have a foot in both camps', 'to be connected to two groups with opposing interests', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4831, 'have a frog in your throat', 'to have difficulty in speaking because your throat feels dry and you want to cough', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4832, 'have a good innings', 'If you say that someone has had a good innings, you mean that they have had a long and successful life:', 'He was 86 when he died so I suppose he''d had a good innings.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4833, 'have a good run for your money', 'to have a good enough time:', 'I''ve achieved a lot in my life and I feel I''ve had a good run for my money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4834, 'have a good war', 'to behave in a way that is successful and admired during a war, or during a difficult time period that can be seen as similar to a war:', 'Unlike so many of his shell-shocked generation, Spencer had a good war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4835, 'have a good/healthy pair of lungs', 'You say that a baby has a good/healthy pair of lungs when it cries loudly.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4836, 'have a grandstand view', 'to be in a position where you can see something very well:', 'From our hotel room window, we had a grandstand view of the parade.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4837, 'have a heart of gold', 'to be very kind and generous:', 'She has a heart of gold.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4838, 'have a heart of stone', 'to be unkind or cruel', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4839, 'have a heart!', 'used to ask someone to be kinder to you:', 'Don''t make me write it again! Have a heart!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4840, 'have a heavy foot', 'to drive a car too fast:', 'She has a heavy foot - does the trip in half the time it takes me!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4841, 'have a horror of something', 'to hate something very much or be very frightened of something:', 'It may be childish but I have a horror of worms.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4842, 'have a horse in the race', 'to be personally involved in or affected by something:', 'It''s probably going to bring a lot of people out to the election because everyone will have a horse in the race.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4843, 'have a leg up on someone', 'to have an advantage over someone', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4844, 'have a lot of time for someone', 'to like someone and be interested in them:', 'She''s really nice - I have a lot of time for Helen.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4845, 'have a lot to say for yourself', 'to talk too much and seem to have a high opinion of yourself', '', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4846, 'have a memory like an elephant', 'to be able to remember things easily and for a long period of time', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4847, 'have a mind of its own', 'A machine or other object can be said to have a mind of its own if it seems to be controlling the way it behaves or moves, independently of the person using it:', 'This shopping trolley has a mind of its own.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4848, 'have a nice, good, etc. line in something', 'to do something skilfully and successfully:', 'He has a good line in anecdotes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4849, 'have a nodding acquaintance with someone/something', 'to know someone slightly or have a slight knowledge of a subject:', 'She has only a nodding acquaintance with the issues involved.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4850, 'have a passing/slight/nodding acquaintance with something', 'to have very little knowledge or experience of a subject:', 'I''m afraid I have only a nodding acquaintance with his works.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4851, 'have a problem with something/someone', 'to find something or someone annoying or offensive:', 'I have a real problem with people who use their mobile phones on the train.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4852, 'have a rare old time', 'to enjoy yourself very much:', 'We went on a tour of the city''s bars and had a rare old time.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4853, 'have a rare old time', 'to have difficulty:', 'We had a rare old time trying to get tickets.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4854, 'have a ringside seat', 'to be in a position where you can see or observe something very well:', 'He had a ringside seat for the dramas of the Clinton years.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4855, 'have a roving eye', 'If you say that someone has a roving eye, you mean that they are always sexually interested in people other than their partner:', 'By his own admission he had a roving eye and was easily infatuated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4856, 'have a screw loose', 'If you say that someone has a screw loose, you mean that they behave in a strange way and seem slightly mentally ill.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4857, 'have a sharp tongue', 'to be someone who often criticizes and speaks in a severe way:', 'Jane has a sharp tongue, so be warned.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4858, 'have a short fuse', 'to get angry very easily', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4859, 'have a short memory', 'to forget things quickly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4860, 'have a sook', 'to refuse to smile and be pleasant to people because you are angry or unhappy about something:', 'Bullies usually have a sook after they''ve been called out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4861, 'have a stick up your arse', 'a rude phrase meaning to be very serious and easily offended, and always want rules to be obeyed:', 'She has a stick up her arse and likes lecturing people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4862, 'have a stick up your ass', 'a rude phrase meaning to be very serious and easily offended, and always want rules to be obeyed:', 'She has a stick up her ass and likes lecturing people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4863, 'have a sting in the/its tail', 'If something, such as a story or joke, has a sting in the/its tail, it has a surprising or unpleasant part that only becomes clear at the end.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4864, 'have a strong stomach', 'to be able to smell, taste, or see unpleasant things without feeling ill or upset:', 'You need to have a very strong stomach to watch some of the surgery scenes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4865, 'have a strop on', 'to be in a bad mood:', 'Why have you got such a strop on - what''s happened?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4866, 'have a thin time (of it)', 'to have bad or unhappy experiences:', 'He''s been having a thin time (of it) since his accident.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4867, 'have a thing about something/someone', 'to like or dislike something or someone very much:', 'Ben''s got a thing about Harley Davidsons - he''s got three of them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4868, 'have a weak stomach', 'to easily feel ill or upset when you smell, taste, or see something unpleasant', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4869, 'have a whale of a time', 'to enjoy yourself very much:', 'We had a whale of a time on holiday.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4870, 'have a word in someone''s ear', 'to give someone a piece of advice or information secretly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4871, 'have a, some, etc. say in something', 'to be involved in making a decision about something:', 'When he''s 18, he''ll begin to have a/some say in the running of the family business.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4872, 'have a/the feeling', 'to think or believe something, usually based on a guess or on your emotions:', 'I have a feeling we''ll meet again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4873, 'have a/the ring of truth', 'to seem to be true:', 'This story has the ring of truth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4874, 'have all the cares of the world on your shoulders', 'to be very worried by many different problems:', 'You look as if you have all the cares of the world on your shoulders.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4875, 'have an accident', 'to urinate or excrete (= pass solid waste) when you do not intend to:', 'Even a six-year-old can have an accident at night sometimes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4876, 'have an ax to grind', 'to have a selfish reason or strong opinion that influences your actions:', 'The study should be conducted by a firm that has no axe to grind.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4877, 'have an axe to grind', 'to have a strong personal opinion about something that you want people to accept and that is the reason why you do something:', 'Environmentalists have no political axe to grind - they just want to save the planet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4878, 'have an ear for something', 'If someone has an ear for music or languages, they are good at hearing, repeating, and understanding these sounds:', 'She''s never had much of an ear for languages.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4879, 'have an eye for something', 'to be good at noticing a particular type of thing:', 'She has an eye for detail.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4880, 'have an eye to/for the main chance', 'Someone who has an eye to/for the main chance is always ready to use a situation to their own advantage.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4881, 'have another think coming', 'to need to consider something again, because you are wrong:', 'If you think I''m going to pay for everything, you''ve got another think coming.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4882, 'have another/more than one string to your bow', 'to have more than one interest, skill, or resource that you can use if you need to:', 'I enjoy my work, but I''d like to have another string to my bow in case I lose my job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4883, 'have ants in your pants', 'to not be able to keep still because you are very excited or worried about something', '', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4884, 'have bats in the belfry', 'to be silly and slightly crazy and behave in a confused way', '', 'idiom', '', 'old-fashioned, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4885, 'have been around the ridges', 'If you have been around the ridges, you have a lot of experience.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4886, 'have big ideas', 'to have plans that need great effort, skill, and luck to achieve:', 'She''s got big ideas about starting up her own company.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4887, 'have bigger/other fish to fry', 'to have something more important to do', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4888, 'have butterflies (in your stomach)', 'to feel very nervous, usually about something you are going to do:', 'I had terrible butterflies before I gave that talk in Venice.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4889, 'have come a long way', 'to have advanced to an improved or more developed state:', 'Information technology has come a long way in the last 20 years.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4890, 'have deep pockets', 'to have a lot of money or wealth:', 'The politicians with the deepest pockets usually win the election.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4891, 'have dibs on something', 'to have the first right to use something, before anyone else:', 'I’ve got dibs on the sofa.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4892, 'have egg on your face', 'If you have egg on your face, you look stupid because of something that you have done:', 'This latest scandal has left the government with egg on its face.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4893, 'have eyes in the back of your head', 'to know everything that is happening around you:', 'Parents of young children need to have eyes in the back of their heads.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4894, 'have faith!', 'If you tell someone to have faith, you are encouraging them to stay confident:', 'Have faith! Everything will work out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4895, 'have fears for someone/something', 'to be worried about someone or something:', 'The climbers are a day late returning from the mountain and we are beginning to have fears for their safety.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4896, 'have feet of clay', 'to have a bad quality that you keep hidden:', 'Some of the greatest geniuses in history had feet of clay.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4897, 'have friends in high places', 'to know important people who can help you get what you want', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4898, 'have fun and games', 'to have difficulty doing something:', 'We had real fun and games trying to bath the dog.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4899, 'have gimlet eyes', 'to look at things very carefully and not miss anything', '', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4900, 'have got something there', 'If you say that a person has got something there, you mean they have said or discovered an important or interesting thing.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4901, 'have had it (up to here) with', 'to have suffered because of someone or something and to be no longer able to bear him, her, or it:', 'I''ve had it up to here with you - get out!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4902, 'have had it with someone/something', 'to not be willing to continue to deal with someone or something:', 'I’ve had it with this job – I’m quitting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4903, 'have had its/your day', 'to be much less popular than before:', 'She sold a lot of books in the 1990s, but she''s had her day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4904, 'have had your chips', 'to have lost your position, importance, or power', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4905, 'have half a mind/a good mind to do something', 'to think that you might do something, often because something has annoyed you:', 'I have a good mind to go without him if he''s going to be such an idiot!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4906, 'have heard of someone/something', 'If you have heard of someone or something, you know that that person or thing exists:', 'It''s a tiny country that most people have never even heard of.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4907, 'have hysterics', 'to get extremely angry or upset:', 'She''ll have hysterics when she finds out how much money is missing.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4908, 'have inner resources', 'to have the ability to help yourself manage or achieve something:', 'He can''t cope with difficult situations on his own - he has no inner resources.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4909, 'have it all to play for', 'If someone has it all to play for, the result of a competition or situation is still not known, and they still have the chance to win or be successful. :', 'We are looking forward to the challenge and we have it all to play for.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4910, 'have it both ways', 'to get advantages from two opposing things:', 'You can''t have it both ways - you either work longer and get paid more or have more leisure time and get paid less.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4911, 'have it coming (to you)', 'infml to deserve what happens to you, esp. something bad:', 'He got a ticket for speeding, but he had it coming.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4912, 'have it in for someone', 'to be determined to harm or criticize someone:', 'She''s always had it in for me.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4913, 'have it in you', 'to have a particular quality or ability:', 'His speech was really funny - we didn''t know he had it in him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4914, 'have it off', 'to have sex:', 'He was having it off with his friend''s wife.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4915, 'have it on the highest authority', 'to have been told something by someone who knows the truth:', 'I have it on the highest authority that they are getting a divorce.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4916, 'have it out with someone', 'to talk to someone about something they have done that makes you angry, in order to try to solve the problem:', 'She''d been late for work every morning and I thought I''d better have it out with her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4917, 'have kittens', 'to be very worried, upset, or angry about something:', 'My mother nearly had kittens when I said I was going to buy a motorbike .', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4918, 'have legs', 'If a story in the news has legs, it will continue for a long time:', 'This latest scandal has legs - you''ll probably still be reading about it in a year''s time.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4919, 'have legs', 'If something has legs, it can continue to exist and be successful:', 'The business has legs.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4920, 'have money', 'to be rich:', 'I believe her family has money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4921, 'have money to burn', 'to spend a lot of money on things that are not necessary:', 'I don''t know what her job is but she certainly seems to have money to burn.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4922, 'have nerves of steel', 'to be very brave:', 'You need to have nerves of steel to be a fighter pilot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4923, 'have news for someone', 'used to say that someone is going to be unpleasantly surprised because something will not be as they want it to be:', 'I''ve got news for him, if he thinks he can keep living here free of charge.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4924, 'have no business doing something', 'to have no right to do something:', 'You had no business reading my private letters.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4925, 'have no time for someone', 'to disapprove of someone and not want to be involved with them:', 'I have no time for people who are always complaining.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4926, 'have none of something', 'to refuse to accept, agree with, or support something:', 'She tried to persuade him to retire, but he would have none of it.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4927, 'have nothing on someone or something', 'to not be as good as someone or something:', 'He''s a good player, but he''s got nothing on his brother.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4928, 'have nothing to do with someone/something', 'to not involve someone or something:', 'This argument has nothing to do with me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4929, 'have nothing to lose', 'to be in a situation that could improve by doing something and that will not be any worse if you fail at it:', 'Since I had nothing to lose, I accepted the offer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4930, 'have nothing to say for yourself', 'to not be willing to take part in conversations or express your opinions', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4931, 'have occasion to do something', 'to need to do something:', 'Of course, as a teacher I had authority, but rarely did I have occasion to use it.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4932, 'have one foot in the grave', 'to be very old and near death', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4933, 'have seen better days', 'to be old and in bad condition:', 'That jacket has seen better days. Why don''t you get a new one?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4934, 'have shit for brains', 'to be extremely stupid:', 'Don''t ask Jack to do anything - he''s got shit for brains.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4935, 'have shot your bolt', 'to have already achieved all that you have the power, ability, or strength to do and to be unable to do more:', 'He started off the game well but seemed to have shot his bolt by half-time.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4936, 'have skin in the game', 'to be directly involved in or affected by something, especially financially:', 'If people have skin in the game, preventable costs fall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4937, 'have someone by the balls', 'to have someone in a situation where you have complete power over them', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4938, 'have someone eating out of your hand', 'to easily make someone do or think what you want:', 'Within two minutes of walking into the classroom, she had the kids eating out of her hand.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4939, 'have someone in the palm of your hand', 'to have complete control over someone and to be able to make them do anything you want:', 'He had the audience in the palm of his hand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4940, 'have someone on', 'to persuade someone that something is true when it is not, usually as a joke:', 'That''s your new car? You''re having me on!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4941, 'have someone over a barrel', 'to put someone in a very difficult situation in which the person has no choice about what they do:', 'She knows I need the work so she''s got me over a barrel in terms of what she pays me.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4942, 'have someone taped', 'to know about and be able to deal with a person or situation', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4943, 'have someone to thank (for something)', 'If you have someone to thank for something, that person is responsible or to blame for it:', 'You have John to thank for this problem.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4944, 'have someone up', 'to take someone to court for a trial:', 'He was had up for burglary.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4945, 'have someone''s guts for garters', 'If you say you will have someone''s guts for garters, you mean that you will punish them severely:', 'If that boy has taken my bike again, I''ll have his guts for garters!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4946, 'have someone''s number', 'to know a lot about someone and so have an advantage over them:', 'Don''t worry, I''ve got his number, he doesn''t fool me.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4947, 'have someone/something hanging round your neck', 'to be limited in what you can do by someone or something:', 'The last thing I want is a couple of kids hanging round my neck!', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4948, 'have something coming out of your ears', 'to have more of something than you want or need:', 'He''s going to have money coming out of his ears if this deal comes off.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4949, 'have something down to a fine art', 'to be able to do something very well or quickly, often because you have done it so many times', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4950, 'have something going for you', 'If you have something going for you, or if something has something going for it, there are certain advantages that will make the end result successful:', 'They''ve got a happy marriage, great careers, wonderful kids - in fact they''ve got everything going for them.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4951, 'have something going with someone', 'If you have something going with someone, you are involved in a sexual relationship with them:', 'Didn''t he have something going with one of his students?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4952, 'have something in common', 'to share the same interests or have similar characteristics:', 'I didn’t think Larry and Patricia had anything in common, but they talked all evening.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4953, 'have something in hand', 'to have something well organized or under control:', 'The police have the situation in hand.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4954, 'have something in hand', 'If you have something in hand, you have not yet used it and it is still available:', 'I had enough money in hand to buy a new car.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4955, 'have something in mind', 'to have a plan or intention:', 'Did you have anything in mind for Helen''s present?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4956, 'have something in your pocket', 'to be certain to win or succeed at something:', 'Last year''s winners again have the championship firmly in their pocket.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4957, 'have something on good authority', 'to be able to believe a piece of information because you trust the person who told you it:', 'I have it on good authority that she''s getting married.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4958, 'have something on the brain', 'to not be able to stop thinking or talking about one particular thing:', 'You''ve got cars on the brain. Can''t we talk about something else for a change?', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4959, 'have something on your hands', 'If you have a difficult situation on your hands, you have to deal with it:', 'If the police carry on like this they''ll have a riot on their hands.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4960, 'have something on your hands', 'to be to blame for something:', 'We have the blood of these people on our hands (= we are responsible for their death or injury).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4961, 'have something on your mind', 'to be worrying about something:', 'Paul has a lot on his mind at the moment.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4962, 'have something on your plate', 'to have something, usually a large amount of important work, to deal with:', 'She''s got a lot on her plate - especially with two new projects starting this week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4963, 'have something on your side', 'If you have something on your side, it gives you an advantage when you are trying to achieve something:', 'I thought I would get the job, but the other person who was being considered for it had experience on his side.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4964, 'have something out', 'to have something removed from your body:', 'You''ll have to have that tooth out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4965, 'have something to play with', 'If you have a particular amount of time or money to play with, that amount is available for you to use:', 'Having only $800 to play with, they bought a second-hand piano.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4966, 'have something under your belt', 'to have learned or succeeded in something that might be an advantage in the future:', 'Basic computer skills are a good thing to have under your belt.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4967, 'have something up your sleeve', 'to have secret plans or ideas:', 'If I know Mark he''ll have one or two tricks up his sleeve.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4968, 'have something, will travel', 'said if you want to go on a journey and use a particular skill:', 'The ad in the newspaper read "Have English language skills, will travel".', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4969, 'have something/nothing to show for something', 'If you have something/nothing to show for your work or effort, you have/have not won any advantage from it:', 'I worked for two weeks, and $50 was all I had to show for it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4970, 'have sticky fingers', 'to be likely to steal:', 'The last person we hired as a cashier turned out to have sticky fingers.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4971, 'have the blues', 'to feel sad', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4972, 'have the ear of someone', 'If you have the ear of an important person, your ideas are listened to and considered important by that person.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4973, 'have the inside track', 'to have a special position within an organization, or a special relationship with a person that gives you advantages that other people do not have', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4974, 'have the last laugh', 'to finally get an advantage from an argument or disagreement, when it seemed that you would not', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4975, 'have the last word on something', 'to be the person who makes a decision without asking anyone else:', 'Carol has the last word on whether we go.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4976, 'have the measure of someone/something', 'to understand what someone or something is like and to know how to deal with him, her, or it:', 'I don''t think she''s under any illusions about her husband - she has the measure of him.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4977, 'have the odds/cards stacked against you', 'to be very unlikely to succeed because you are not in an good position', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4978, 'have the patience of a saint', 'to always be calm and never allow anything to upset you', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4979, 'have the wind at your back', 'to be in a good situation in which you can succeed:', 'The president has the wind at his back on this issue.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4980, 'have the world at your feet', 'to be extremely successful and admired by a large number of people:', 'Five years after her debut, the diminutive star of the Royal Ballet has the world at her feet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4981, 'have thin/thick skin', 'to be easily/not easily upset by criticism:', 'I don''t worry about what he says - I have a very thick skin.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4982, 'have time on your hands', 'to have nothing to do:', 'Gina has some time on her hands, so she is taking a college course.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4983, 'have time to kill', 'to have nothing to do for a particular period:', 'We''ve got some time to kill before we leave - do you want to have some coffee.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4984, 'have to do with something', 'to be about something:', 'My question has to do with last week’s assignment.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4985, 'have two left feet', 'to move in a very awkward way when dancing:', 'When we danced together, I discovered he had two left feet.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4986, 'have what it takes (to do something)', 'to have the qualities or character needed to be successful:', 'She doesn’t have a college degree, but I think she has what it takes to do the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4987, 'have your (fair) share of something', 'to have a lot or more than enough of something bad:', 'We certainly have our share of problems at the moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4988, 'have your back to/against the wall', 'to have very serious problems that limit the ways in which you can act:', 'He owes money to everyone - he really has his back to the wall now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4989, 'have your business, sensible, etc. head on', 'used for saying that you are considering something from a particular way of thinking:', 'I had my sensible head on that morning and knew we couldn''t afford to buy the car.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4990, 'have your cake and eat it (too)', 'to have or do two good things at the same time that are impossible to have or do at the same time:', 'You can''t have your cake and eat it - if you want more local services, you can''t expect to pay less tax.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4991, 'have your day in court', 'to get an opportunity to give your opinion on something or to explain your actions after they have been criticized:', 'She was determined to get her day in court and the TV interview would give it to her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4992, 'have your differences', 'to disagree with someone on one or more matters:', 'We’ve had our differences, but we''ve learned how to work together very well.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4993, 'have your eye on something', 'to have seen something that you want and intend to get:', 'She''s had her eye on a bike for some time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4994, 'have your feet on the ground', 'to be practical and able to take care of yourself:', 'Don’t worry about Kerry – she’s a smart girl who has her feet on the ground.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4995, 'have your finger on the trigger', 'used to say that someone is ready and prepared to do something, especially something violent:', 'They have their finger on the trigger to start a nuclear war.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4996, 'have your fingers in the till', 'to steal money from the place where you work', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4997, 'have your hands full', 'to be so busy that you do not have time to do anything else:', 'I''d love to help but I''ve got my hands full organizing the school play.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4998, 'have your head (buried/stuck) in a book', 'to be reading:', 'Rose always has her head buried in a book.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (4999, 'have your head (stuck) up your (own) ass', 'an offensive phrase meaning to not pay attention to what is happening; to behave in a silly or stupid way:', 'He admitted that a lot of his co-workers had their heads up their asses.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5000, 'have your head in the clouds', 'to not know the facts of a situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5001, 'have your head screwed on (the right way)', 'to be practical and wise:', 'Ask Lois to help - she''s got her head screwed on the right way.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5002, 'have your head up your arse', 'an offensive phrase meaning to not pay attention to what is happening; to behave in a silly or stupid way:', 'This guy has his head up his arse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5003, 'have your knife into someone', 'to try to upset or harm someone because you dislike them', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5004, 'have your nose in a book', 'to be reading:', 'She always has her nose in a book.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5005, 'have your tubes tied', 'If a woman has her tubes tied, she has a medical operation in which her fallopian tubes are closed to stop her eggs being released so that she cannot become pregnant.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5006, 'have your wits about you', 'to think and react quickly when something dangerous or difficult happens unexpectedly:', 'She managed to keep her wits about her and escaped unharmed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5007, 'have your work cut out (for you)', 'to have something very difficult to do:', 'She''ll really have her work cut out to finish all those reports by the end of the week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5008, 'have your/its moments', 'to be sometimes very good or successful:', 'This album may not be as good as their last one but it has its moments.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5009, 'have/get your shit together', 'to be or become effective, organized, and skilful:', 'One of these days I''ll get my shit together.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5010, 'have/get your snout in the trough', 'to have or get a share of a supply of money or some other advantage that people eagerly and sometimes dishonestly take:', 'The council had been handing out grants indiscriminately, and people were hurrying to get their snouts in the trough.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5011, 'have/hold all the aces', 'to be in a strong position when you are competing with someone else because you have all the advantages:', 'In a situation like this, it''s the big companies who hold all the aces.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5012, 'have/hold the whip hand', 'to be the person or group that has the most power in a situation:', 'During the last decade the right wing of the party has held the whip hand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5013, 'have/keep (all) your wits about you', 'to be ready to think quickly in a situation and react to things that you are not expecting:', 'Cycling is potentially very dangerous in the city - you have to keep your wits about you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5014, 'have/keep your ear to the ground', 'to pay attention to everything that is happening around you and to what people are saying', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5015, 'have/keep your feet on the ground', 'to be very practical and see things as they really are', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5016, 'have/keep your finger on the pulse', 'to be/stay familiar with the most recent changes or improvements:', 'The situation changes daily, so you need to keep your finger on the pulse.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5017, 'have/keep your options open', 'to wait before making a choice:', 'I''m going to keep my options open while I find out about studying abroad.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5018, 'have/know something down pat', 'to know something so well that you can say or do it without having to try or think:', 'I''d given the talk so many times I had it down pat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5019, 'have/know something off pat', 'to know something so well that you can say or do it without having to try or think:', 'I''d given the talk so many times I had it off pat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5020, 'have/lead a sheltered life', 'to have a life in which you are protected too much and experience very little danger, excitement, or change:', 'Until going to college, she had led a very sheltered life.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5021, 'have/make a stab at something', 'to attempt to do something although you are not likely to be very successful:', 'I''d never tried snorkelling before but I had a stab at it while I was in Greece.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5022, 'have/put your head on the block', 'to risk a bad thing happening to you by doing something or helping someone:', 'I''m not going to put my head on the block for you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5023, 'have/take a dump', 'to pass the contents of the bowels out of the body', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5024, 'have/take a notion to do something', 'to suddenly want to do something:', 'I had a notion to write them a letter.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5025, 'have/take pride of place', 'to have the most important position in a group of things:', 'A portrait of his grandfather takes pride of place in the entrance hall.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5026, 'have/throw a fit', 'to become very angry or worried, often shouting a lot:', 'She''ll throw a fit when she sees the mess you''ve made.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5027, 'having said that', 'despite what has just been said:', 'He forgets most things, but having said that, he always remembers my birthday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5028, 'haze over', 'If the sky hazes over, the air becomes less clear, especially because of heat:', 'The sky began to haze over in the afternoon.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5029, 'he who fights and runs away, lives to fight another day', 'used to say that it can be a good and acceptable decision to leave a difficult situation', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5030, 'he who laughs last, laughs longest/best', 'said to emphasize that the person who has control of a situation in the end is most successful, even if other people had seemed originally to have an advantage', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5031, 'he who pays the piper calls the tune.', 'said to emphasize that the person who is paying someone to do something can decide how it should be done', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5032, 'he/she deserves whatever/everything he/she gets', 'said if you think someone should have to suffer because of their bad behaviour:', 'After all the harm she''s done, she deserves whatever she gets.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5033, 'head and shoulders above', 'If someone or something is head and shoulders above other people or things, he, she, or it is a lot better than them:', 'There''s no competition - they''re head and shoulders above the rest.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5034, 'head down', 'if share prices or currencies head down, they lose value:', 'Traders who think a particular company''s shares are headed down make a profit by borrowing stock and selling it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5035, 'head for something', 'If you are heading for a bad situation, you are likely to experience it soon, because of your own actions or behaviour:', 'They''re heading for disaster if they''re not careful.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5036, 'head in the game', 'If someone has their head in the game, they are paying very careful attention to what they are doing:', 'It is important for all the jurors to have their heads in the game.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5037, 'head off', 'to start a journey or leave a place:', 'What time are you heading off?', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5038, 'head someone/something off', 'to force someone or something to change direction:', 'I tried to head the dog off by running towards it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5039, 'head something off', 'to prevent a difficult or unpleasant situation from happening:', 'The company is putting up wages to head off a strike.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5040, 'head over heels (in love)', 'completely in love', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5041, 'head something off', 'to stop something from happening:', 'The team would help developing countries head off such disasters.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5042, 'head something up', 'to lead or control a group, part of a company, etc.:', 'He headed up a Miami-based legal team.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5043, 'head/mind is whirling', 'If your head/mind is whirling, your mind is full of thoughts and images and you are so excited that you cannot relax.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5044, 'heads I win, tails you lose', 'said about a situation in which you will win whatever happens', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5045, 'heads or tails?', 'asked before you throw a coin into the air and want someone else to guess which side it will land on', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5046, 'heads will roll!', 'something that is said to mean that people will be punished for something bad that has happened', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5047, 'heap something on someone', 'to give someone a lot of praise, criticism, etc.:', 'He deals well with all the criticism heaped on him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5048, 'hear (something) through/on the grapevine', 'to hear news from someone who heard the news from someone else:', 'I heard through the grapevine that he was leaving - is it true?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5049, 'hear from someone', 'If you hear from someone, you get a letter, email, or phone call from that person, or that person tells you something:', 'We haven''t heard from her for ages.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5050, 'hear someone out', 'to listen to someone until they have said everything they want to say:', 'At least hear me out before making up your mind.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5051, 'hear something of someone', 'to receive news about someone:', 'We haven''t heard anything of Jan for months.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5052, 'hear tell (of)', 'If you hear tell (of) something, someone tells you about it.', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5053, 'hear warning bells', 'used to describe a situation when people see signs that something bad has started or is going to happen:', 'For me, the warning bells started to ring when she lost all that weight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5054, 'hear wedding bells', 'to think that someone is going to get married:', 'She knew that if she brought her boyfriend home her mother would start hearing wedding bells.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5055, 'hear, hear!', 'said to strongly agree with what someone else has just said', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5056, 'hear/see the last of something', 'If you hear or see the last of something or someone unpleasant or difficult, that person or thing does not cause you trouble again:', 'I paid them $100 for the damage and I hope that''s the last I''ll hear of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5057, 'heart and soul', 'completely:', 'She loves those children heart and soul.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5058, 'heat up something', 'to make something warm or hot:', 'Let''s see what happens when I heat it up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5059, 'heat up something', 'If a situation heats up, it becomes more extreme:', 'With the political climate heating up, we can expect to hear a lot more from both candidates.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5060, 'heave a sigh of relief', 'to suddenly feel very happy because something unpleasant has not happened or has ended:', 'We both heaved a sigh of relief when she left.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5061, 'heavens (above)!', 'used to express surprise or anger', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5062, 'heavy hitter', 'someone who is powerful and has achieved a lot:', 'Have you seen his résumé? He''s a real heavy hitter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5063, 'heavy with sth', 'If something is heavy with something else, it has a lot of it or is full of it:', 'The trees were heavy with fruit.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5064, 'hedge your bets', 'to protect yourself against loss by supporting more than one possible result or both sides in a competition:', 'They''re hedging their bets and keeping up contacts with both companies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5065, 'hell for leather', 'If you go, run, ride, etc. hell for leather, you go as fast as you can.', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5066, 'hell of a', 'extremely, or extremely big:', 'It''s a/one hell of a big decision to take.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5067, 'hell on earth', 'an extremely unpleasant place or situation:', 'Soldiers who survived the war described it as hell on earth.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5068, 'hell yes/no', 'used to emphasize that you strongly agree or disagree, like or dislike something, etc.:', '"Are you gonna go?"—"Hell yes! Try to stop me!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5069, 'hello stranger', 'said to a person that you know but have not seen for a long time:', 'Hello stranger, I haven''t seen you for weeks!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5070, 'help (someone) out', 'If you help out, you do a part of someone''s work or give someone money:', 'Her parents helped (her) out with a £500 loan.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5071, 'hem and haw', 'to be uncertain and take a long time deciding something:', 'We hemmed and hawed for months before actually deciding to buy the house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5072, 'hem someone in', 'to surround someone and prevent them from moving or doing what they want to do:', 'When they reached Trafalgar Square, the demonstrators were hemmed in by the police.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5073, 'her/his heart is in the right place', 'used to say that someone has good intentions:', 'He''s an odd man but his heart is in the right place.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5074, 'here and there', 'in different places:', 'There were a few books here and there, but apart from that the room was quite bare.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5075, 'here goes!', 'said just before you do something brave or something that you have never done before:', 'Well, I''ve never ridden a motorbike before, so here goes!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5076, 'here to stay', 'If something is here to stay, it has stopped being unusual and has become generally used or accepted:', 'Blogging is here to stay.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5077, 'here today, gone tomorrow', 'said about something that lasts only a short time:', 'A lot of new internet companies are here today and gone tomorrow.', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5078, 'here we go', 'a phrase often sung repeatedly by English football crowds when their team is successful', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5079, 'here we go (again)', 'said when something bad starts happening again:', 'Oh, here we go again! Claude''s just asked to borrow some more money from me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5080, 'here you go', 'this is the object you asked me to give you:', '"Would you please pass the sugar?" "Here you go."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5081, 'here''s mud in your eye!', 'sometimes said by people in a friendly way just before drinking an alcoholic drink together', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5082, 'here''s to ...', 'said when asking a group of people to hold up their glasses and then drink as an expression of good wishes to someone or hope for the success of something:', 'Here''s to the happy couple!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5083, 'hero to zero', 'a situation in which someone changes quickly from being very popular or successful to being very unpopular or unsuccessful:', 'In a demonstration of the fickleness of the public, the Prime Minister has gone from hero to zero in just four months.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5084, 'hide out', 'to stay somewhere where you cannot be found:', 'Criminals often hide out in these empty apartments.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5085, 'hide your light under a bushel', 'to keep your good qualities and abilities secret from other people', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5086, 'high and mighty', 'behaving as if you are much more important than other people:', 'He was acting all high and mighty.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5087, 'hike something up', 'to lift or raise something with a quick movement:', 'She hiked up her skirt and climbed onto the bicycle.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5088, 'hinge on/upon something', 'If one thing hinges on another, the first thing depends on the second thing or is very influenced by it:', 'The prosecution''s case hinged on the evidence of a witness who died before the trial.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5089, 'hinge on/upon something', 'If a story or situation hinges on an idea or subject, it develops from that idea or that is the most important subject in it:', 'The film''s plot hinges on a case of mistaken identity.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5090, 'hire something/someone out', 'to allow someone to use something or someone temporarily in exchange for money:', 'UK How much do you charge for hiring out a bicycle for a week?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5091, 'hire yourself out', 'to arrange to be paid to do a job for another person or company:', 'He began hiring himself out as a freelance computer expert.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5092, 'hit back', 'to attack or criticize someone who has attacked or criticized you:', 'In tonight''s speech, the minister is expected to hit back at critics who have attacked her handling of the crisis.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5093, 'hit home', 'to cause you to realize exactly how unpleasant or difficult something is:', 'The full horror of the war only hit home when we started seeing the television pictures of it in our living rooms.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5094, 'hit it off (with someone)', 'to be friendly with each other immediately:', 'We had similar ideas about the show, and the two of us hit it off right away.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5095, 'hit on someone', 'to show someone that you are sexually attracted to them:', 'Some guy hit on me while I was standing at the bar.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5096, 'hit on/upon something', 'to think of an idea when you didn''t expect or intend to, especially one that solves a problem:', 'When we first hit on the idea, everyone told us it would never work.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5097, 'hit out', 'to criticize something or someone strongly:', 'The Medical Association yesterday hit out at government cuts in healthcare services.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5098, 'hit sb up (for sth)/hit sb for sth', 'to ask someone for money:', 'She planned to hit him up for a raise.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5099, 'hit someone between the eyes', 'to shock someone or have a sudden strong effect on someone', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5100, 'hit someone up', 'to ask someone for something:', 'She hit me up for $20.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5101, 'hit someone where it hurts', 'to do or say something to someone that will upset them as much as possible:', 'He''s always worrying about his weight, so if you want to hit him where it hurts, tell him he''s looking a bit fat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5102, 'hit someone where they live', 'to affect someone in a very deep and personal way:', 'The words to that song really hit me where I live.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5103, 'hit the ball out of the park', 'in baseball, to hit the ball so hard that it goes out of the area of play:', 'He''s been hitting them out of the park all season.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5104, 'hit the ball out of the park', 'to do something extremely well:', 'The two chefs hit the ball out of the park with this entrée.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5105, 'hit the books', 'to study:', 'I can''t go out tonight. I need to hit the books.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5106, 'hit the bottle', 'to start to drink too much alcohol', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5107, 'hit the ceiling/roof', 'to become extremely angry:', 'Dad''ll hit the ceiling when he finds out I''ve left school.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5108, 'hit the deck', 'to lie down quickly and suddenly so that you are hidden from view or protected from something dangerous', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5109, 'hit the ground running', 'to immediately work hard and successfully at a new activity', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5110, 'hit the hay/sack', 'to go to bed in order to sleep:', 'I have a busy day tomorrow, so I think I''ll hit the sack.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5111, 'hit the headlines', 'to appear in the news suddenly or receive a lot of attention in news reports:', 'He hit the headlines two years ago when he was arrested for selling drugs to the mayor''s nephew.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5112, 'hit the jackpot', 'to win the largest prize in a competition or game', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5113, 'hit the jackpot', 'to have a big success or make a big profit, usually through luck:', 'He seems to have hit the jackpot with his new invention.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5114, 'hit the nail on the head', 'to describe exactly what is causing a situation or problem:', 'I think Mick hit the nail on the head when he said that what''s lacking in this company is a feeling of confidence.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5115, 'hit the panic button', 'to react to a situation with fear and confusion:', 'The coach isn''t going to hit the panic button just because we lost two games.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5116, 'hit the road', 'to leave a place or begin a journey:', 'I''d love to stay longer but I must be hitting the road.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5117, 'hit the roof', 'to become extremely angry:', 'Dad will hit the roof when he finds out I dented the car.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5118, 'hit the sack', 'infml to go to bed in order to sleep:', 'I’ve got a busy day tomorrow, so I think I’ll hit the sack.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5119, 'hit the skids', 'to fail:', 'His career hit the skids after his illness.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5120, 'hit the spot', 'to be exactly what is needed:', 'That bacon sandwich really hit the spot!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5121, 'hit the wall', 'to reach a point when you are running, exercising, playing sports, etc. where you are so physically tired you feel you cannot continue:', 'Many marathon runners hit the wall at around 20 miles.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5122, 'hit your stride', 'to become familiar with and confident at something you have recently started doing:', 'Let''s wait until she''s hit her stride before we ask her to negotiate that contract.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5123, 'hit/press/push the panic button', 'to do something quickly without thinking about it in order to deal with a difficult or worrying situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5124, 'hit/touch a (raw) nerve', 'to upset someone:', 'She touched a raw nerve when she mentioned that job he didn''t get.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5125, 'hitch something up', 'to pull something, especially trousers or a skirt, upwards to a slightly higher position:', 'She hitched her skirt up before wading across the stream.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5126, 'hitch something up', 'If you hitch up a vehicle, you connect it so that it can be pulled, and if you hitch up an animal to a vehicle, you connect it so that it can pull the vehicle:', 'We watched as the farmer hitched up a team of oxen.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5127, 'hither and thither', 'in many directions:', 'In clearer water, one encounters shoals of tiny fish, which dart hither and thither like flights of arrows.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5128, 'hive something off', 'to separate one part of a company, usually by selling it:', 'The plan is to hive off individual companies as soon as they are profitable.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5129, 'hog the road', 'to drive so that other vehicles cannot go past', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5130, 'hold (down) the fort', 'to have responsibility for something while someone is absent:', 'I''ll be out of the office for a few hours - will you hold the fort until I get back?', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5131, 'hold a clinic', 'to be available at a particular place to provide medical care to members of the public:', 'Dr Clark holds a clinic on Tuesday mornings.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5132, 'hold a clinic', 'to be available at a particular place to provide advice to members of the public:', 'Our MP holds a clinic every Friday evening.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5133, 'hold all the cards', 'to be in a strong position when you are competing with someone else, because you have all the advantages:', 'Management holds all the cards when it comes to the negotiations over job cuts.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5134, 'hold back', 'to not do something, often because of fear or because you do not want to make a bad situation worse:', 'He held back, terrified of going into the dark room.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5135, 'hold someone/something back', 'to stop someone or something developing or doing as well as they should:', 'She felt that having children would hold her back.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5136, 'hold someone/something back', 'If you hold someone or something back, you stop him, her, or it from coming or moving forward:', 'Sandbags will hold the flood waters back for a while.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5137, 'hold something back', 'to keep information secret from someone deliberately', '', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5138, 'hold something back', 'to stop yourself showing an emotion:', 'He spoke slowly, to hold back his growing anger.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5139, 'hold back on sth', 'to wait for a period of time before doing something:', 'We held back on the product release until the third quarter.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5140, 'hold court', 'to receive a lot of attention from other people who stand or sit around you to listen, especially on a social occasion:', 'Patrick is holding court at the end table.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5141, 'hold down a job', 'to manage to keep a job for a period of time', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5142, 'hold everything!', 'used to tell someone to stop what they are doing:', 'Hold everything! He''s changed his mind again.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5143, 'hold forth', 'to talk about a particular subject for a long time, often in a way that other people find boring:', 'She held forth all afternoon about/on government incompetence.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5144, 'hold it!', 'used to tell someone to wait or stop doing something:', 'Hold it! I don''t have my coat on yet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5145, 'hold it/that against someone', 'to like someone less because they have done something wrong or behaved badly in the past:', 'He made a mistake but I don''t hold it against him - we all make mistakes.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5146, 'hold off', 'to not do something immediately:', '[ + -ing verb ] Let''s hold off making a decision until next week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5147, 'hold off', 'If rain or a storm holds off, it does not start immediately.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5148, 'hold someone off', 'to stop someone from attacking or defeating you:', 'How much longer will the resistance fighters be able to hold off the enemy?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5149, 'hold on', 'used to tell someone to wait for a short time:', 'Hold on, I''ll check in my diary.', 'phrasal verb', 'B1', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5150, 'hold on', 'used to say that you are confused or surprised by something that you have just heard or read and want to understand it:', 'Now hold on, Ed, that wasn''t what we agreed at all!', 'phrasal verb', 'C1', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5151, 'hold on', 'to manage to stay alive or to deal with a difficult situation:', 'We just had to hold on until help arrived.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5152, 'hold on', 'to hold something or someone firmly with your hands or arms:', 'She held on tightly to his waist.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5153, 'hold on to/onto sth/sb', 'to keep something or someone that is important or useful:', 'I held onto the tech shares after the stock market fell because I knew they would recover.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5154, 'hold on/tight', 'to continue doing something or staying somewhere although it is difficult or unpleasant to do so:', 'Hold on and I’ll go and get some help.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5155, 'hold onto someone/something', 'to hold something or someone firmly with your hands or your arms:', 'Hold onto the rope and don''t let go.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5156, 'hold onto/on to something', 'to keep something you have:', 'Hold on to your ticket - you''ll need it later.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5157, 'hold out', 'to continue to defend yourself against an enemy or attack without being defeated:', 'They won''t be able to hold out much longer under this sort of bombardment.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5158, 'hold out', 'If a supply of something such as food or money holds out, there is enough of it to last for a particular period of time.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5159, 'hold something out', 'to offer a possibility, solution, hope, etc.:', 'Few people hold out any hope of finding more survivors.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5160, 'hold out for something', 'to wait until you get what you want:', 'The workers are holding out for a ten percent pay rise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5161, 'hold out on someone', 'to refuse to give help or information to someone:', 'Don''t hold out on me - I need to know who did it.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5162, 'hold out on someone', 'to refuse to give money to someone', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5163, 'hold out/offer an olive branch', 'to do or say something in order to show that you want to end a disagreement with someone:', 'He held out an olive branch to the opposition by releasing 42 political prisoners.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5164, 'hold sb to account', 'to make someone accept that they are responsible for something and explain their actions or decisions:', 'Holding those in power to account is the essence of democracy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5165, 'hold someone in high/low repute', 'to respect someone very much/very little:', 'My father was held in high repute by his colleagues.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5166, 'hold someone ransom', 'to force someone to do something by putting that person in a situation where they have no choice:', 'He claimed his country was being held ransom by threats of withdrawing aid.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5167, 'hold someone to ransom', 'to force someone to do something by putting that person in a situation where they have no choice:', 'He claimed his country was being held to ransom by threats of withdrawing aid.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5168, 'hold someone to something', 'to make someone do what they promised or agreed to do:', 'We''ll hold him to the exact terms of the contract.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5169, 'hold someone/something down', 'to keep someone or something in a particular place or position and to stop him, her, or it from moving:', 'He was struggling so much it took three officers to hold him down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5170, 'hold something down', 'to keep something, especially costs, at a low level:', 'to hold down prices/wages', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5171, 'hold someone/something up to ridicule', 'to laugh unkindly and publicly at someone or something, or to make someone or something seem stupid:', 'Her plans were held up to ridicule.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5172, 'hold something against someone/something', 'to consider something as a reason to have a bad opinion about someone or something:', 'He made a mistake, but I don’t hold it against him – we all make mistakes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5173, 'hold something over', 'to delay something:', 'The nomination was held over until the Senate adjourned.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5174, 'hold something over', 'If a film, play, etc. is held over, it is shown or performed more times than was originally planned, usually because it is very popular with the public.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5175, 'hold someone over', 'to delay someone from leaving:', 'The weather held us over in Denver for two days.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5176, 'hold something up as something', 'to use someone or something as an example of something, especially something very good:', 'Sweden is often held up as an example of a successful social democracy.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5177, 'hold still', 'used to tell someone to stop moving:', 'Hold still, this won''t hurt.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5178, 'hold sway', 'to have power or a very strong influence:', 'Fundamentalist beliefs hold sway over whole districts, ensuring the popularity of religious leaders.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5179, 'hold that thought', 'used for telling someone to remember an idea or thought that has just been mentioned, especially because it will be useful later', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5180, 'hold the balance of power', 'to be able to support either opposing side in a competition, etc. and therefore be able to decide who will win:', 'If independents do end up holding the balance of power, then they decide whether Labor or the Liberals govern for the next four years.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5181, 'hold the floor', 'to speak to a group of people, often for a long time, without allowing anyone else to speak', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5182, 'hold the fort', 'to have responsibility for something while someone else is absent:', 'I’m leaving my husband to hold the fort while I’m away.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5183, 'hold the key', 'to have control of something:', 'Because the two main parties have won almost the same number of votes, the minority group holds the key to the result.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5184, 'hold the phone', 'used for telling someone to wait, for example because you are going to say something surprising; sometimes used humorously when something is not surprising at all:', 'It may sound like a great offer, but hold the phone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5185, 'hold the reins', 'be in control:', 'She''s the boss but her secretary often seems to hold the reins.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5186, 'hold the road', 'If a vehicle holds the road, its wheels stay firmly on the road and do not slide while moving.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5187, 'hold together (something)', 'to keep (a group or organization) complete or in its original state or condition:', 'Social relationships held the Crow people together into the 20th century.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5188, 'hold true', 'to continue to be true:', 'Their arguments were valid a hundred years ago and they still hold true today.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5189, 'hold up', 'to remain strong or successful:', 'Will his alibi hold up (= continue to seem true) in court?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5190, 'hold someone/something up', 'to delay someone or something:', 'Traffic was held up for several hours by the accident.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5191, 'hold someone/something up', 'to steal from someone using violence or the threat of violence:', 'They held the same bank up twice in one week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5192, 'hold something up', 'If a centre forward holds up the ball, they keep control of a long pass from a defender on the same team until other members of the team can reach the opponent''s half of the playing field:', 'Lukaku used his strength to hold up the ball, giving Baines time to sprint downfield in support.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5193, 'hold water', 'If a reason, argument, or explanation holds water, it is true:', 'Her alibi just didn''t hold water.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5194, 'hold your head (up) high', 'to be very confident and proud:', 'If you know that you did your best, you can hold your head high.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5195, 'hold your horses', 'used to tell someone to stop and consider carefully their decision or opinion about something:', 'Just hold your horses, Bill! Let''s think about this for a moment.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5196, 'hold your nose', 'to press your nose tightly between thumb and finger in order to close it:', 'I have to hold my nose when I jump into water.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5197, 'hold your nose', 'to do something you find unpleasant or do not want to do because the other choices are worse:', 'He spent days trying to convince congressional colleagues to hold their noses and vote for the bill.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5198, 'hold your own', 'to be as successful as other people or things in a situation:', 'Josie can hold her own in any argument.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5199, 'hold your own', 'to not become more ill or more weak:', 'He''s still ill but holding his own.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5200, 'hold your tongue', 'to not speak:', 'Hold your tongue, young man!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5201, 'hold/keep someone/something at bay', 'to prevent someone or something unpleasant from harming you:', 'Exercise can help keep fat at bay.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5202, 'hold/put your hands up', 'to admit that something bad is true or that you have made a mistake:', 'I know I''m bossy and I hold my hands up to that.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5203, 'hold/stand fast', 'to firmly remain in the same position or keep the same opinion:', 'The rebels are standing fast and refuse to be defeated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5204, 'hold/stand firm', 'to remain in the same place or at the same level:', 'The protesters stood firm as the police tried to disperse them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5205, 'hole up (somewhere)', 'to stay in a safe place, often as a way of avoiding something or hiding from someone:', 'We''d better find some shelter and hole up until the storm passes.', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5206, 'holed below the waterline', 'damaged in a way that is not immediately obvious but that will in the end cause someone or something to fail completely:', 'Rising national debt meant any plans for big projects had been holed below the waterline.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5207, 'hollow something out', 'to make an empty space inside something:', 'Sand carried by the wind has hollowed out the base of the cliff.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5208, 'home away from home', 'a place where you feel as comfortable as you do in your own home:', 'The hotel was a real home away from home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5209, 'home free', 'infml having finished the difficult or dangerous part of an activity and sure of finishing it successfully:', 'Once you get past the essay questions on the test, you’re home free.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5210, 'home from home', 'a place where you feel as comfortable as you do in your own home:', 'The hotel was a real home from home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5211, 'home in on something/someone', 'to aim for:', 'The missile homed in on the ship.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5212, 'home in on something/someone', 'to find and give a lot of attention to something or someone:', 'The report homed in on the weaknesses in the management structure.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5213, 'honest (to God/goodness)', 'used to emphasize that what you are saying is true:', 'I tried to be nice to him, honest to God I did!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5214, 'honesty is the best policy', 'said to advise someone that it is better to tell the truth than to lie', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5215, 'hoof it', 'to walk somewhere, or to walk somewhere quickly:', 'We missed the bus and had to hoof it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5216, 'hook (someone/something) up (to something)', 'to connect a machine to a power supply or to another machine, or to connect a person to a piece of medical equipment:', 'Can we hook up to the electricity supply at the campsite?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5217, 'hook (sth) into sth', 'to become connected or to connect something to a computer or telephone system:', 'After the takeover, one of the company''s first acts was to hook the newly acquired bank into its own computer systems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5218, 'hook up', 'to meet or begin to work with another person or other people:', 'He hooked up with the other members of the band in Amsterdam.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5219, 'hook up', 'to begin a romantic or sexual relationship with someone:', 'When did you two first hook up?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5220, 'hook up (with sb/sth)', 'to meet or begin to work with another person or organization:', 'a conference where startup companies can hook up with investors', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5221, 'hook sb up (with sb/sth)', 'to arrange for someone to meet or work with another person or organization:', 'We videotape applicants in practice interviews and hook them up with employers.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5222, 'hook, line, and sinker', 'completely:', 'I forged the note and the teacher fell for it hook, line, and sinker.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5223, 'hoover something up', 'to remove something from a floor or other surface using a vacuum cleaner (= a machine that sucks up dust and dirt):', 'We''ll hoover up the debris, then we will sit down and open a bottle of wine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5224, 'hoover something up', 'to use something quickly and eagerly:', 'The country is hoovering up ever more commodities because its economy is growing so quickly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5225, 'hop it', 'used to tell someone to go away', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5226, 'hope against hope', 'to hope very strongly that something will happen, although you know it is not likely:', 'They''re just hoping against hope that she''s still alive.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5227, 'hope for the best', 'to hope that something will be successful or happen in the way you want, even if it seems unlikely:', 'I''ve repaired it as well as I can - we''ll just have to hope for the best.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5228, 'hope over experience', 'said in order to express the idea that someone hopes that something will work well in the future, although experience shows that it has not worked well in the past:', 'Hasty company mergers are often a triumph of hope over experience.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5229, 'hope springs eternal', 'said when you continue to hope that something will happen, although it seems unlikely', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5230, 'hope/wish/swear to God', 'used for emphasis:', 'I hope to God (that) he turns up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5231, 'hopping mad', 'very angry', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5232, 'horn in', 'to try to become involved in a discussion or activity when you are not wanted:', 'She''s always horning in on our conversations.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5233, 'horror of horrors', 'said when you are telling someone about a very bad or embarrassing situation:', 'Then, horror of horrors, I discovered that my zip had been undone the whole time I was talking to her.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5234, 'horse around', 'to behave in a silly and noisy way:', 'He was horsing around in the kitchen and broke my favourite bowl.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5235, 'horses for courses', 'used to say that it is important to choose suitable people for particular activities because everyone has different skills', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5236, 'hostage to fortune', 'an action or statement that could create problems for you later:', 'The prime minister was extremely cautious, saying nothing inflammatory and giving no hostages to fortune.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5237, 'hot air', 'If something that someone says is hot air, it is not sincere and will have no practical results:', 'His promises turned out to be a lot of hot air.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5238, 'hot and heavy', 'If something or someone is hot and heavy, they are full of strong emotions or sexual feelings:', 'Guess who I saw getting hot and heavy on the dance floor?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5239, 'hot off the press', 'News that is hot off the press has just been printed and often contains the most recent information about something.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5240, 'hot to trot', 'sexually excited and wanting to find someone to have sex with', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5241, 'hot under the collar', 'embarrassed or angry about something:', 'When I suggested he was mistaken he got rather hot under the collar.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5242, 'hot up', 'If an event or situation hots up, it becomes more exciting and more things start to happen:', 'A few days before the elections, the pace began to hot up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5243, 'hound someone out', 'to force someone to leave a job or a place:', 'He claims he was hounded out of his job by a group of students who disapproved of his views.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5244, 'hour after hour', 'for many hours without stopping:', 'I sat by her bedside for hour after hour.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5245, 'hours (and hours)', 'infml a long time:', 'I spent hours filling out forms.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5246, 'house of cards', 'a complicated organization or plan that is very weak and can easily be destroyed or easily go wrong', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5247, 'how about that?', 'used to emphasize that something is surprising:', 'Sales are up by 36 percent. How about that?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5248, 'how about...?', 'used to make a suggestion:', 'How about the cinema tonight?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5249, 'how about...?', 'used when asking someone about a different thing:', 'You don''t eat meat, do you? How about fish?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5250, 'how are things (with you)?', 'informal for "how are you?"', '', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5251, 'how are you fixed for something?', 'used to ask how much of something someone has, or to ask about someone''s arrangements:', 'How are you fixed for cash?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5252, 'how are you keeping?', 'used to ask if someone is well:', 'How''s your mother keeping?', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5253, 'how are you placed for...?', 'used to ask someone if they have enough money, time, etc.:', 'How are you placed for money?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5254, 'how come?', 'used to ask about the reason for something:', 'So how come you got an invitation and not me?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5255, 'how dare she, you, etc.!', 'used to express anger about something someone has done:', 'How dare you use my car without asking!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5256, 'how dare you do something', 'I am very surprised and shocked by what you are doing:', 'How dare you question my authority?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5257, 'how do you do?', 'a formal greeting for someone that you have not met before:', '"I''m Jack Stewart." "How do you do? I''m Angela Black."', 'idiom', 'A2', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5258, 'how do you do', 'a difficult, worrying, and unpleasant situation:', '"I had a row with my sister and now she''s refusing to talk to me." "Well, that''s a fine how do you do!"', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5259, 'how do you like...?', 'used when asking someone how they like their drinks made:', '"How do you like your tea?" "Milk and one sugar, please."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5260, 'how do you like...?', 'used when asking someone for an opinion:', 'How do you like my new shoes?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5261, 'how does... grab you?', 'used to ask if someone would like to do something or is interested in something:', 'We could have a picnic in the park. How does that grab you?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5262, 'how long is a piece of string?', 'said when you cannot answer a question about the length, size, amount, etc. of something because it could be any length, size, etc.:', 'Asked how long this will take, she replies: "How long is a piece of string?"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5263, 'how sb rolls', 'how someone generally likes to do things:', 'Not a good system you say, but that''s how I roll.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5264, 'how should I know?', 'I cannot be expected to know:', '"Where''s Mikey?" "How should I know? He''s hardly ever in the office these days."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5265, 'how the other half lives', 'something people say when they see or hear about the lives of people who are richer than them', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5266, 'how was I to know?', 'used to say that something you did wrong was not your fault because you did not have enough information:', 'I just wanted to give her a surprise; how was I to know you''d already bought tickets?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5267, 'how would you like...?', 'said to suggest that someone would not like to be in a situation experienced by someone else:', 'I''m not surprised he shouted at you! How would you like to be pushed into a wall?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5268, 'how''s life (treating you)?', 'said as an informal greeting', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5269, 'how''s tricks?', 'how are you?:', '"Hi, how''s tricks?" "Oh, fine, how are you doing?"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5270, 'how''s you?', 'an informal way to greet someone you know and ask how they are:', 'How''s you? How was work today?', 'idiom', '', 'informal, spoken', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5271, 'how, what, why, etc. on earth...', 'used when you are extremely surprised, confused, or angry about something:', 'How on earth did this happen?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5272, 'how/what about...?', 'used when suggesting or offering something to someone:', 'How about a trip to the zoo this afternoon?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5273, 'hue and cry', 'a noisy expression of public anger or disapproval:', 'There has been a great hue and cry about the council''s plans to close the school.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5274, 'huff and puff', 'to breathe loudly, usually after physical exercise:', 'We were huffing and puffing by the time we''d climbed to the top of the hill.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5275, 'huff and puff', 'to complain loudly and express disapproval:', 'They huffed and puffed about the price but eventually they paid up.', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5276, 'hum and haw', 'to be uncertain and take a long time deciding something:', 'We hummed and hawed for months before actually deciding to buy the house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5277, 'hung, drawn, and quartered', 'In the past, if someone was hung, drawn, and quartered, the person was hanged by the neck and their body was cut into pieces.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5278, 'hunger after/for something', 'to want something very much:', 'I hunger for your touch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5279, 'hunker down', 'to sit down on your heels:', 'We hunkered down around the campfire, toasting marshmallows.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5280, 'hunker down', 'to make yourself comfortable in a place or situation, or to prepare to stay in a place or position for a long time, usually in order to achieve something or for protection:', 'The press have hunkered down for the night outside the palace, waiting for news of the royal birth.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5281, 'hunt someone/something down', 'to search everywhere for someone or something until you find him, her, or it:', 'The terrorists must be hunted down and brought to justice.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5282, 'hunt/search high and low', 'to search everywhere for something:', 'I''ve been hunting high and low for that certificate and I still can''t find it!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5283, 'hurl/throw/sling mud at someone', 'to say insulting or unfair things about someone, especially to try to damage their reputation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5284, 'hurry (someone/something) up', 'to move or do things more quickly than normal or to make someone do this:', 'Hurry up or we''ll miss the train.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5285, 'hurry (someone/something) up', 'to do something very soon:', 'All I wanted was for those people to hurry up and leave.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5286, 'hurry up and do something', 'to do something very soon:', 'All I wanted was for these very boring people to hurry up and leave.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5287, 'hurt someone''s feelings', 'to upset someone by criticizing them or by refusing something that they have offered you', '', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5288, 'hush something up', 'to try to prevent people from discovering particular facts:', 'There was some financial scandal involving one of the ministers but it was all hushed up.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5289, 'hype someone up', 'to make someone feel very excited:', 'I always feel hyped up before an exam.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5290, 'ice over', 'If an area of water ices over, it becomes covered with a layer of ice:', 'The lake has iced over.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5291, 'ice up', 'to become covered in ice and often stop working:', 'The plane was delayed because the engine had iced up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5292, 'identify with someone', 'to feel that you are similar to someone in some way and that you can understand that person or their situation because of this:', 'Many women of normal weight feel unable to identify with the super-thin models in fashion magazines.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5293, 'identify someone/something with something', 'to believe that someone or something is closely connected or involved with something:', 'Many football fans are unfairly identified with violent behaviour.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5294, 'idle something away', 'to spend a period of time relaxing and doing very little:', 'We idled away the hours drinking and playing cards.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5295, 'if I may be/make so bold (as to)', 'a polite way of asking for or suggesting something when you do not want to offend someone:', 'If I may be so bold, you still haven''t mentioned why you''re here.', 'idiom', '', 'old-fashioned, formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5296, 'if I were in your shoes', 'used when you want to tell someone what you would do in their situation:', 'If I were in your shoes, I think I''d write to her rather than try to explain over the phone.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5297, 'if I were you', 'used when you give someone advice:', 'If I were you, I''d probably go.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5298, 'if all else fails', 'if what was planned cannot happen:', 'We could go to the beach or to my sister''s house, and if all else fails, we can always find something to do at home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5299, 'if and when', 'at the time that something happens:', 'We don''t own a car - we just rent one if and when we need it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5300, 'if anything', 'used when saying that what people may believe is not true, and the opposite may be true:', 'Her success hasn''t caused tension - if anything, it''s helped our marriage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5301, 'if anything', 'used when saying that there may be nothing:', 'We need to assess what happened and what, if anything, we could have done to prevent it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5302, 'if at first you don''t succeed, try, try again', 'said to encourage someone who has failed at something to try to do it again', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5303, 'if ever there was one', 'used to emphasize that what you are saying is true:', 'It was a brilliant performance if ever there was one.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5304, 'if it ain''t broke, don''t fix it', 'said when you recognize that something is in a satisfactory state, and there is no reason to try to change it', '', 'idiom', '', 'informal, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5305, 'if it''s not one thing, it''s another', 'used when bad things keep happening to you', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5306, 'if it/a thing is worth doing, it''s worth doing well', 'used to emphasize that if you are going to spend time doing a piece of work, you should do it as well as possible', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5307, 'if looks could kill...', 'said when you see someone look very angrily at someone else', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5308, 'if my memory serves me right', 'if I remember correctly:', 'I think he was called Blake, if my memory serves me right.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5309, 'if need be', 'if it is necessary:', 'If need be, we can take two cars.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5310, 'if only', 'used when you want to say how doing something would make it possible to avoid something unpleasant:', 'If only she''d listen to what he''s saying, I''m sure they could solve the problem.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5311, 'if the cap fits (wear it)', 'used to tell someone that they should accept a criticism that another person has made', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5312, 'if the shoe fits (wear it)', 'used to tell someone that they should accept a criticism that another person has made', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5313, 'if the worst comes to the worst', 'if the situation develops in the most serious or unpleasant way:', 'We should be in when you arrive, but if the worst comes to the worst, the neighbours have a spare key and will let you into the house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5314, 'if worse/worst comes to worst', 'if the situation develops in the most serious or unpleasant way:', 'We should be in when you arrive, but if worst comes to worst, the neighbors have a spare key and will let you into the house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5315, 'if you ask me', 'said when giving your opinion on something:', 'If you ask me, people should go on a training course before they become parents.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5316, 'if you can''t beat ''em, join ''em', 'said when you accept that you cannot be as successful as other people without doing what they do, even though you do not approve of or agree with it', '', 'idiom', '', 'informal, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5317, 'if you can''t stand the heat, get out of the kitchen', 'used as a way to tell someone that they should either stop complaining about a difficult or unpleasant activity, or stop doing it', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5318, 'if you don''t mind me saying/asking', 'used in order to be more polite when you say something that could slightly upset, annoy, or embarrass someone:', 'If you don''t mind me saying (so), I think the soup needs a little more salt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5319, 'if you like', 'used for asking if someone agrees with a suggestion:', 'We can leave now if you like.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5320, 'if you take my meaning', 'used to say that you have left out information or your opinion from what you have just said, but that you expect the person listening still to understand it:', 'Let''s just say we had "problems", if you take my meaning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5321, 'if you will', 'used to say that a particular expression is one way of saying something, especially to suggest that some people may not choose to say it that way:', 'I did very well in school , with a "genius IQ" if you will.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5322, 'if you''ll pardon the expression', 'said before or after using language that other people might consider shocking:', 'The man doesn''t know his arse from his elbow, if you''ll pardon the expression.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5323, 'if/when it comes to the crunch', 'if/when a situation becomes extremely serious and a decision must be made:', 'If it comes to the crunch and you and your husband do split up, you can always stay with us.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5324, 'if/when push comes to shove', 'If something can be done if push comes to shove, it can be done if the situation becomes so bad that you have to do it:', 'If push comes to shove, we can always sell the car.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5325, 'ignorance is bliss', 'said to emphasize that sometimes it is better for you if you do not know all the facts about a situation', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5326, 'ill at ease', 'feeling anxious and not relaxed:', 'He looked ill at ease in the room full of reporters.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5327, 'imbue something/someone with something', 'to fill something or someone with a particular feeling, quality, or idea:', 'His poetry is imbued with deep, religious feeling.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5328, 'impinge on/upon someone/something', 'to have an effect on something, often causing problems by limiting it in some way:', 'The government''s spending limits will seriously impinge on the education budget.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5329, 'impress something on/upon someone', 'to make someone understand or be familiar with the importance or value of something:', 'Mr Simmons tried to impress on me how much easier my life would be if I were better organized.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5330, 'improve on/upon something', 'to do something in a better way or with better results than before:', 'Last time she ran the race in 20 minutes, so she''s hoping to improve on that.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5331, 'impute something to someone', 'to say that someone is responsible for something that has happened, or that something is the cause of something else:', 'They imputed the error to the lawyer who was handling her case.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5332, 'impute something to someone', 'to believe that someone or something has a particular characteristic, quality, or meaning:', 'He arrogantly imputed stupidity to anyone who disagreed with him.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5333, 'in God''s/heaven''s name', 'used to add force to something that is said. Some people find the use of "God" offensive:', 'What in God''s name caused that outburst?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5334, 'in a ... place', 'used to talk about someone''s feelings, situation, or mental condition:', 'I feel like I''m in a better place about who I am.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5335, 'in a class by your/itself', 'excellent, or the best of its kind:', 'Her singing is in a class by itself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5336, 'in a dream', 'not conscious of what is happening around you because other thoughts are filling your mind:', 'I didn''t hear what you were saying - I was in a dream.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5337, 'in a flash', 'quickly or suddenly:', 'The ceremony was over in a flash.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5338, 'in a flutter', 'in a confused and excited state:', 'When economic statistics are first published they grab headlines and put markets in a flutter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5339, 'in a heartbeat', 'very quickly, without needing to think about it:', 'I''d do it again in a heartbeat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5340, 'in a huff', 'feeling angry and upset:', 'When Julia criticized his art, Geraldo left in a huff.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5341, 'in a manner of speaking', 'used for saying that something is partly true:', 'She''s his partner, in a manner of speaking.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5342, 'in a nutshell', 'very briefly, giving only the main points:', '"What went wrong?" "In a nutshell, everything."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5343, 'in a pinch', 'Something that you can do in a pinch can be done if it is really necessary, but it will be difficult, not perfect, or not what you would really like:', 'I need $20,000 to set up the business, but I suppose $15,000 would do in a pinch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5344, 'in a spin', 'worried and confused:', 'She''s in a spin over the arrangements for the party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5345, 'in a stew', 'If someone is in a stew, that person is in a difficult situation that causes them to feel worried or upset:', 'William is in a stew about/over his tax return.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5346, 'in a way', 'considered in a particular manner:', 'In a way, I hope he doesn’t win.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5347, 'in a word', 'said when you are going to give your opinion about something quickly and directly:', 'In a word, she''s lying.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5348, 'in a world of your own', 'thinking your own thoughts and ideas and not giving much attention to what is happening around you:', 'When she was young, she lived in a world of her own and had very few friends.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5349, 'in advance', 'before a particular time, or before doing a particular thing:', 'If you''re going to come, please let me know in advance.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5350, 'in advance of something/someone', 'before something or someone:', 'She arrived in advance of everyone else.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5351, 'in all', 'with everything added together to make a total:', 'The bill came to £25 in all.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5352, 'in all but name', 'existing as a fact but not officially described that way:', 'She is vice-president in all but name.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5353, 'in all conscience', 'without feeling guilty:', 'You couldn''t, in all conscience, ask her to pay the whole bill!', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5354, 'in all honesty/seriousness/truthfulness', 'said when expressing your opinion honestly, seriously, or truthfully:', 'In all honesty, I do have some criticisms to make.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5355, 'in all my (born) days', 'in all of my life:', 'I''ve never seen anything so strange in all my born days.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5356, 'in all weathers', 'If something is done in all weathers, it is done in every type of weather:', 'He goes fishing in all weathers.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5357, 'in any case', 'whatever happens or happened:', 'You should be able to catch a bus, but in any case you can always take a taxi home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5358, 'in any event', 'whatever happens:', 'I hope to see her this afternoon, but in any event I’m leaving town tomorrow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5359, 'in arrears', 'owing money that should have been paid already:', 'My account is badly in arrears.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5360, 'in arrears', 'If someone is paid in arrears, they are paid at the end of the period of time during which the money was earned:', 'I''m paid a week in arrears.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5361, 'in back of', 'behind:', 'The garbage cans are in back of the house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5362, 'in balance', 'spending no more money in a budget (= financial plan) than is taken in during a particular period:', 'We want to cut the budget to get it in balance by next year.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5363, 'in ballast', '(of a ship) not carrying any cargo (= goods), but with containers filled with sea water to add weight:', 'vessels arriving at the port laden or in ballast
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5364, 'in bed', 'having sex:', 'She found her boyfriend in bed with another woman.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5365, 'in bed', 'referring to sexual activity:', 'He likes to make people think that he''s good in bed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5366, 'in black and white', 'in writing:', 'I had to believe it, because it was there in black and white.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5367, 'in blissful ignorance', 'not knowing any of the unpleasant facts about something:', 'All the time his business was failing, he kept his wife and family in blissful ignorance.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5368, 'in broad daylight', 'If a crime is committed in broad daylight, it happens during the day, when it could have been seen and prevented:', 'Thieves had broken into the house in broad daylight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5369, 'in buckets', 'in great amounts:', 'The rain came down in buckets.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5370, 'in business', 'able to start doing something that you had planned:', 'Once we get the computer installed we’ll be in business.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5371, 'in charge (of something/someone)', 'responsible for something or someone:', 'Who’s in charge here?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5372, 'in check', 'being controlled within reasonable limits:', 'We’ve got to find ways of keeping our expenses in check.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5373, 'in cold blood', 'If someone kills in cold blood, they kill in a way that seems especially cruel because it seems to show no emotion.', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5374, 'in commission', 'If something, such as a machine or a military ship, is in commission it is working and ready for use.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5375, 'in concert', 'playing or singing with other musicians in a public performance:', 'She was appearing in concert at Carnegie Hall.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5376, 'in concert', 'together:', 'If the member countries would act in concert, the problem might be solved more easily.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5377, 'in conclusion', 'fmlfinally:', 'In conclusion, I''d like to express my thanks to everyone who participated in this project.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5378, 'in deep (trouble)', 'in serious trouble:', 'You will be in deep trouble with Dad if you don''t tell him the truth now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5379, 'in deep doo-doo', 'in a lot of trouble:', 'Would it be safe to say the state budget is in deep doo-doo?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5380, 'in dire straits', 'in a very bad situation that is difficult to fix:', 'These kids are in dire straits, and the schools are doing nothing to help them!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5381, 'in fact', 'actually:', 'He was in fact near death by the time they reached him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5382, 'in fits of laughter', 'laughing a lot:', 'His stories had them in fits of laughter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5383, 'in flower', 'If a plant is in flower, it has open flowers:', 'Our roses are usually in flower from April to November.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5384, 'in foal', '(of a female horse) pregnant:', 'Two of the mares are in foal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5385, 'in for a penny (in for a pound)', 'something you say that means that since you have started something or are involved in it, you should complete the work although it has become more difficult or complicated than you had expected', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5386, 'in for something', 'going to experience something:', 'It looks like we’re in for rain.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5387, 'in force', 'in large numbers:', 'Volunteers turned out in force to plant pines, crab-apple trees, and lilac bushes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5388, 'in force', 'If laws, rules, or systems are in force, they exist and are being used:', 'New regulations limiting fishing on this river are now in force.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5389, 'in front of', 'done or said when the person you are talking about is present:', 'Why did you have to embarrass me in front of all those people?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5390, 'in full cry', 'talking continuously about something in a noisy or eager way:', 'The opposition was in full cry in Parliament last night over the proposed changes to the education bill.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5391, 'in full swing', 'at a stage when the level of activity is at its highest:', 'When we got there, the party was in full swing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5392, 'in glorious technicolor', 'very colourful or too brightly coloured:', 'Her room was painted in glorious technicolor.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5393, 'in good conscience', 'without feeling guilty:', 'You couldn''t, in good conscience, ask her to pay the whole bill!', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5394, 'in good faith', 'If something is done in good faith, it is done sincerely and honestly:', 'She was acting in good faith for her client.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5395, 'in good hands', 'managed or cared for with great attention:', 'You’ll be in good hands with her – she’s a terrific lawyer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5396, 'in good time', 'early:', 'We''ll be at the airport in good time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5397, 'in good, bad, etc. repair', 'in good, bad, etc. condition:', 'The house is in very good repair.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5398, 'in hand', 'being worked on or dealt with now:', 'They''ve had plenty of time to prepare, so the arrangements should be well in hand (= almost ready).', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5399, 'in harness with', 'working together to achieve something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5400, 'in high gear', 'very active and productive:', 'The movie really goes into high gear when Williams appears on screen.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5401, 'in his/her/their wisdom', 'something that you say when you do not understand why someone has done something stupid:', 'The council, in its wisdom, decided to close the library and now the building stands empty.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5402, 'in hot pursuit', 'following someone closely, trying hard to catch them:', 'The gang drove off, with the police in hot pursuit.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5403, 'in hot water', 'in a difficult situation in which you are likely to be punished:', 'Emails that criticize others can land you in hot water, so be careful what you write.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5404, 'in inverted commas', 'used in spoken English after a word or phrase to show that it has not been used accurately or that the opposite meaning is intended:', 'Sick prisoners in the camp were "cared for", in inverted commas, by guards, not nurses.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5405, 'in kind', '(of payment) given in the form of goods or services and not money:', 'She wouldn''t take any money but said I could pay her in kind by lending her the car.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5406, 'in kind', 'If you do something in kind, you do the same thing to someone that they have just done to you.', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5407, 'in knots', 'If your stomach is in knots, it feels tight and uncomfortable because you are nervous or excited.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5408, 'in lieu of', 'instead of:', 'The company is allowing workers to receive cash in lieu of vacation time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5409, 'in light of something', 'because of:', 'In light of recent incidents, we are asking our customers to take particular care of their personal belongings.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5410, 'in limbo', 'in a situation where you do not know what will happen or when something will happen:', 'We were in limbo for weeks while the jury tried to make a decision in the case.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5411, 'in line for something', 'likely to get a job or benefit:', 'I’m in line for a promotion.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5412, 'in line with something', 'similar to, or at the same level as something:', 'The company''s results are in line with stock market expectations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5413, 'in line with something', 'according to or following something such as a rule or principle:', 'A workforce diversity committee will set specific objectives in line with the policy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5414, 'in luck', 'experiencing a surprisingly good situation:', '"Do you have any tickets for tonight’s game?" "You’re in luck – we have two left."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5415, 'in memory of someone', 'as a way of remembering someone who has died:', 'A service was held in memory of those who had died in the fighting.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5416, 'in midstream', 'in the middle of an activity, often one that is interrupted:', 'She interrupted him in midstream to ask a question.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5417, 'in mint condition', 'in excellent condition, as if new:', 'Alex’s old Cadillac is in mint condition.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5418, 'in my book', 'in my opinion:', 'She''s never lied to me, and in my book that counts for a lot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5419, 'in my day', 'when I was young:', 'Kids take so much for granted nowadays - in my day a new bike was really special.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5420, 'in name only', 'If a situation exists in name only, it is officially described that way, although that description is not completely accurate:', 'A large percentage of the population is Catholic, though many are so in name only.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5421, 'in no time (at all)', 'very quickly:', 'Now that we’re on the highway, we’ll be there in no time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5422, 'in no uncertain terms', 'very clearly and often unkindly:', 'She was told in no uncertain terms that the magazine had no interest in her short stories.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5423, 'in no way', 'not at all:', 'She added that she had in no way intended to offend anybody.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5424, 'in on something', 'involved with or knowing about a particular activity or plan:', 'He seems to be in on everything that happens at work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5425, 'in on the ground floor', 'involved in something from its beginning:', 'Can someone tell me how you get in on the ground floor of a deal like that?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5426, 'in on the ground floor', 'involved in something from its beginning:', 'Can someone tell me how you get in on the ground floor of a deal like that?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5427, 'in ones and twos', 'in small numbers:', 'The replies came back in ones and twos.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5428, 'in order', 'right for the occasion:', 'I think congratulations are in order for the new graduates in the room!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5429, 'in order for something to happen', 'if you want a particular result:', 'In order for us to win, we’ll all have to try a little harder.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5430, 'in order to do something', 'with the aim or purpose of doing something:', 'He came home early in order to see the children before they went to bed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5431, 'in other words', 'to explain it more clearly:', 'He was economical with the truth – in other words, he lied.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5432, 'in passing', 'while talking or thinking about something else:', 'Leo mentioned in passing that you are going on vacation next week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5433, 'in person', 'by meeting with someone rather than talking on the phone, e-mailing, or writing to the person:', 'You must apply for the license in person.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5434, 'in phase/out of phase', 'If two things are happening in/out of phase they are reaching the same or related stages at the same time/at different times.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5435, 'in pieces', 'in separate parts rather than as a single thing:', 'The little house was shipped in pieces from France and then reassembled.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5436, 'in pieces', 'broken into small parts:', 'The precious vase lay in pieces on the floor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5437, 'in pieces', 'completely destroyed:', 'My marriage was in pieces - there was nothing left except animosity.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5438, 'in pieces', 'extremely upset:', 'She was in pieces when she heard he''d died.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5439, 'in pieces', 'in small amounts:', 'They''re going to get information in pieces.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5440, 'in plain sight', 'in a place where people can clearly see something:', 'Don''t leave expensive items out in plain sight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5441, 'in pocket', 'having more money than you started with after an activity involving money:', 'Even when we''ve paid all our expenses, we should still be several hundred pounds in pocket.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5442, 'in someone''s pocket', 'in a situation where someone has power or control over you:', 'The head teacher has the school governors completely in her pocket/The school governors are completely in the head teacher''s pocket.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5443, 'in regard to someone/something', 'in relation to someone or something:', 'I am calling in regard to your recent inquiry.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5444, 'in relation to something', 'in connection with something:', 'The drug is being studied for possible beneficial effects in relation to migraine headaches.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5445, 'in relation to something', 'In relation to also means compared with:', 'She checked the map to see where Miami is in relation to Orlando.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5446, 'in respect of something', 'in connection with something:', 'I am writing with respect to your letter of 15 June.', 'idiom', 'B2', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5447, 'in return for something', 'as an exchange for something:', 'The farmer offered us food in return for our work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5448, 'in ribbons', 'torn into narrow strips:', 'Her coat was in ribbons.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5449, 'in rotation', 'one after the other, in a regular order:', 'There are ten employees and they do the various jobs in rotation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5450, 'in safe hands', 'being cared for or dealt with by someone skilled:', 'Dr Bailey is doing the operation, so your wife is in safe hands.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5451, 'in sb''s gift/in the gift of sb', 'If something is in someone''s gift, that person can decide who to give it to:', 'Appointments to these posts were in the gift of the monarch.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5452, 'in secret', 'in a private place with no one else present and without other people knowing:', 'The negotiators were meeting in secret for several months before the peace agreement was made public.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5453, 'in secret', 'only in someone''s thoughts, without telling other people:', 'He says he loathes her, but I think in secret he really likes her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5454, 'in seventh heaven', 'extremely happy:', 'Since they got married, they’re in seventh heaven .', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5455, 'in shirtsleeves', 'dressed informally, wearing a shirt with no jacket over it:', 'Because it was so hot, the men were all in their shirtsleeves.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5456, 'in short', 'used before describing something or someone in as few words and as directly as possible:', 'He''s disorganized, inefficient, never there when you want him - in short, the man''s a pain.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5457, 'in short supply', 'only available in small amounts:', 'Money was in short supply.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5458, 'in small doses', 'for short periods of time:', 'I can only stand opera in small doses.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5459, 'in so many words', 'directly, or in a way that makes it very clear what you mean:', '"Did he say he was unhappy with Anna?" "Well, not in so many words, but that was certainly the impression I got."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5460, 'in someone''s capable hands', 'being dealt with by the person mentioned:', 'I''m going away next week, so I''ll be leaving everything in your capable hands.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5461, 'in someone''s crosshairs', 'If you are in someone''s crosshairs, they intend to catch, arrest, or stop you:', 'He''s in the law''s crosshairs now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5462, 'in someone''s eyes', 'in someone''s opinion:', 'And although she was probably just an ordinary-looking kid, in my eyes she was the most beautiful child on the face of the planet.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5463, 'in someone''s good/bad books', 'If you are in someone''s good/bad books, they are pleased/not pleased with you:', 'He''s in Melanie''s bad books because he arrived two hours late.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5464, 'in someone''s hour of need', 'at a time when someone really needs help:', 'She helped me in my hour of need.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5465, 'in someone''s infinite wisdom', 'used to show that you do not understand why someone has done something and that you think it was a stupid action:', 'The authorities, in their infinite wisdom, decided to close the community centre.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5466, 'in someone''s words', 'used when you repeat what someone said:', 'His wife, Mary, was 25 years his junior and, in his words, "my guiding light".', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5467, 'in someone’s debt', 'grateful for something someone did for you:', 'I’m in the senator’s debt for getting my husband a visa.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5468, 'in someone’s employ', 'working for someone:', 'Mr. Neil is currently in our employ.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5469, 'in spades', 'in large amounts or to a very great degree:', 'My dog has personality in spades.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5470, 'in spite of something', 'even though there is something unpleasant or bad happening:', 'In spite of his injury, Ricardo will play in Saturday’s game.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5471, 'in step with someone/something', 'in agreement with someone or something:', 'She is very much in step with the times.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5472, 'in step with someone/something', 'In step with can also mean at the same speed or level as someone or something:', 'Gasoline prices rose in step with oil prices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5473, 'in stitches', 'If a joke or funny story has you in stitches, it makes you laugh a lot.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5474, 'in store (for someone/something)', 'planned or likely to happen:', 'We have a big surprise in store for you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5475, 'in tandem', 'at the same time:', 'The heart and lungs will be transplanted in tandem.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5476, 'in tandem', 'If two pieces of equipment, people, etc. are working in tandem, they are working together, especially well or closely:', 'I want these two groups to work/operate in tandem on this project.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5477, 'in terms of something', 'in relation to something:', 'We try to do what is best for our customers in terms of the quality of our products.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5478, 'in terror of your life', 'frightened that you will be killed', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5479, 'in the (grand) scheme of things', 'considering everything:', 'In the scheme of things, having lots of money isn''t as important as having friends.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5480, 'in the air', 'If something is in the air, you feel that it is happening or about to happen:', 'With these elections, it feels like change is in the air.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5481, 'in the area of', 'approximately:', 'The repair work will cost in the area of £200.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5482, 'in the back of your mind', 'held as an idea in your mind, but not thought about frequently', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5483, 'in the bag', 'certain to be won, achieved, or obtained:', 'When the score got to 8 to 2 we knew the game was in the bag.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5484, 'in the balance', 'If a situation is in the balance, it has reached a stage where it will soon be decided one way or another:', 'The game hung in the balance until the last minute.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5485, 'in the black', 'earning more money than you spend:', 'This year our business is in the black.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5486, 'in the blink of an eye', 'extremely quickly:', 'In the blink of an eye, he was gone.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5487, 'in the bosom of something', 'If you are in the bosom of a group of people, especially your family, you are with them and protected and loved by them.', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5488, 'in the brain/looks department', 'in intelligence or beauty:', 'He''s somewhat lacking in the brain department.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5489, 'in the buff', 'naked', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5490, 'in the can', 'If a film is in the can, filming has finished and it is ready to be prepared for showing to the public.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5491, 'in the cards', 'likely to happen:', 'Marriage isn''t in the cards for me right now – I''m focused on my career.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5492, 'in the clear', 'not guilty of a crime, or not involved in doing something bad:', 'His lawyers say that Wilson is in the clear.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5493, 'in the club', 'pregnant', '', 'idiom', '', 'old-fashioned, slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5494, 'in the cold light of day', 'If you think about something in the cold light of day, you think about it clearly and calmly, without the emotions you had at the time it happened, and you often feel sorry or ashamed about it:', 'The next morning, in the cold light of day, Sarah realized what a complete idiot she had been.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5495, 'in the country of the blind, the one-eyed man is king', 'said about a difficult situation in which someone with only a few skills is in a better position and more successful than those people who have none', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5496, 'in the dark', 'not informed about things that might be useful to know:', 'Our boss tends to keep us in the dark most of the time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5497, 'in the dead of night/winter', 'in the middle of night/winter:', 'The fire broke out in the dead of night.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5498, 'in the depth(s) of somewhere', 'in the middle of somewhere, and a long distance from its edges:', 'a house in the depths of the forest', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5499, 'in the depth(s) of winter', 'in the middle of winter', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5500, 'in the depths of something', 'in the middle of a difficult or unpleasant time or situation:', 'At the time, America was in the depths of the Depression.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5501, 'in the depths of something', 'If you are in the depths of a negative feeling, you feel it very strongly:', 'He was in the depths of despair about losing his job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5502, 'in the doghouse', 'If you are in the doghouse, someone is annoyed with you and shows their disapproval:', 'I''m in the doghouse - I broke Sara''s favourite vase this morning.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5503, 'in the dumps', 'not successful:', 'The team has been in the dumps all season.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5504, 'in the end', 'after considering everything:', 'In the end, she chose to go to Oberlin College.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5505, 'in the event of something', 'if something should happen:', 'In the event of an actual emergency, you will be told what to do.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5506, 'in the face of something', 'despite having to deal with a difficult situation or problem:', 'She left home in the face of strong opposition from her parents.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5507, 'in the fast lane', 'in a way that is exciting and slightly dangerous:', 'He lived life in the fast lane when he was young.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5508, 'in the firing line', 'likely to be criticized, attacked, or got rid of:', 'He found himself in the firing line for his sexist remarks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5509, 'in the first place', 'in the beginning:', 'We should never have agreed to let him borrow the money in the first place.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5510, 'in the first/second place', 'used to separate and emphasize reasons or opinions:', 'I don''t want to go yet - in the first place I''m not ready, and in the second place it''s raining.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5511, 'in the flesh', 'in real life, and not on TV, in a film, in a picture, etc.:', 'I''ve seen her perform on television, but never in the flesh.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5512, 'in the flower of someone''s youth', 'the time when someone was young and in the best and most active period of life:', 'He died in the very flower of his youth.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5513, 'in the fullness of time', 'If you say something will happen in the fullness of time, you mean that it will happen if you wait long enough:', 'Everything will become clear in the fullness of time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5514, 'in the game', 'with a chance of being successful because you remain involved in something, and especially because you keep trying hard, even when there are problems:', 'They have to put blood, sweat, and tears into the task in order to stay in the game.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5515, 'in the hands of someone', 'controlled or owned by someone:', 'A large percentage of the nation''s wealth is in the hands of a very, very few people.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5516, 'in the heat of the moment', 'If you say or do something in the heat of the moment, you say or do it without thinking because you are very angry or excited:', 'He didn''t mean it - he said it in the heat of the moment.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5517, 'in the hole', 'owing money, rather than having extra money:', 'We’re still in the hole on our credit cards.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5518, 'in the hot seat', 'in a position where you are responsible for important or difficult things', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5519, 'in the lap of luxury', 'living in very comfortable conditions because you have a lot of money', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5520, 'in the lap of the gods', 'used to say that a situation that cannot be controlled and depends only on good luck:', 'The doctors have done everything possible for him, so his recovery now is in the lap of the gods.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5521, 'in the last/final analysis', 'something you say when you are talking about what is most important or true in a situation:', 'In the final analysis, the only people who will benefit are property owners.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5522, 'in the light of something', 'because of:', 'In the light of recent incidents, we are asking our customers to take particular care of their personal belongings.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5523, 'in the line of duty', 'Something that happens to you in the line of duty happens when you are doing your job:', 'This year alone eight police officers have been killed in the line of duty.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5524, 'in the long run', 'at a time that is far away in the future:', 'It seems a lot of effort but I''m sure it''s the best solution in the long run.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5525, 'in the making', 'If something was a period of time in the making, it took that amount of time to make:', 'The film was several years in the making.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5526, 'in the market for something', 'interested in buying something:', 'Thanks for the offer, but I’m not in the market for another car at the moment.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5527, 'in the middle of something', 'busy doing something:', 'When she called, I was in the middle of making dinner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5528, 'in the mold of someone/something', 'sharing some important characteristics with someone or something:', 'Lewis was not an inventor in the mold of Edison.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5529, 'in the name of something', '(said or done) in order to help a particular thing succeed:', 'Much blood has been spilled in the name of religion.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5530, 'in the name of someone/something', 'representing someone or something:', 'In old movies the police shouted "Open up in the name of the law" before they broke the door down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5531, 'in the neighborhood of something', 'approximately:', 'We''re hoping to get somewhere in the neighborhood of $150,000 for our house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5532, 'in the neighbourhood of something', 'approximately:', 'We''re hoping to get somewhere in the neighbourhood of £150,000 for our house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5533, 'in the nick of time', 'at the last possible moment:', 'We got there just in the nick of time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5534, 'in the offing', 'going to happen soon:', 'With an election in the offing, the mayor is getting nervous.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5535, 'in the open', 'no longer secret:', 'Now that her feelings are out in the open, she says she feels relieved.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5536, 'in the palm of your hand', 'under your complete control:', 'The audience was fascinated by his performance – he had them in the palm of his hand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5537, 'in the person of someone', 'in the form of someone:', 'The editorial board has an expert with a world-wide reputation in the person of Professor Jameson.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5538, 'in the pink', 'in very good health', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5539, 'in the pipeline', 'being planned:', 'The theatre company has several new productions in the pipeline for next season.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5540, 'in the process', 'If you are doing something, and you do something else in the process, the second thing happens as a result of doing the first thing:', 'I stood up to say hello and spilled my drink in the process.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5541, 'in the raw', 'naked:', 'They sunbathed in the raw.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5542, 'in the raw', 'in a plain and honest way, with nothing hidden:', 'The film really showed you prison life in the raw.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5543, 'in the red', 'spending more money than you earn:', 'The company has been in the red for the last three quarters.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5544, 'in the right place at the right time', 'in the best position or place to take advantage of an opportunity:', 'The key to success is to be in the right place at the right time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5545, 'in the running', 'having a chance of being successful, esp. in a competition or election:', 'She''s still in the running for Treasurer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5546, 'in the same boat', 'in the same difficult situation as someone else:', 'None of us has any money, so we’re all in the same boat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5547, 'in the same breath', 'If you say two things in the same breath, you say two things that are so different that if one is true, the other must be false:', 'You say he treats you badly but in the same breath you tell me how much you love him!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5548, 'in the same league (as someone/something)', 'having qualities or achievements that are similar to someone or something:', 'The new charity will be giving away $55 million a year, putting it in the same league as other well-known charities.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5549, 'in the shadow of someone', 'receiving little attention because someone else is better known or more skillful:', 'DeMarco plays a lawyer living in the shadow of a famous father.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5550, 'in the shape of something', 'in the form of something, or appearing as something:', 'Luckily, help arrived in the shape of a police officer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5551, 'in the short run', 'at a time that is near in the future:', 'It''s not a long term solution, but it will save money in the short run.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5552, 'in the strictest confidence', 'If you tell someone something in the strictest confidence, you expect them not to tell it to anyone else.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5553, 'in the teeth of something', 'If something happens or is done in the teeth of difficulties, the difficulties cause problems but do not stop it:', 'The road was built in the teeth of fierce opposition from the public.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5554, 'in the thick of something', 'in the most active or dangerous part of a particular situation or activity :', 'He was always right there, in the thick of it when the fighting started.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5555, 'in the tradition of someone/something', 'having characteristics similar to a particular person or thing:', 'His paintings are in the tradition of those of Bacon and Spencer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5556, 'in the twinkling of an eye', 'If something happens in the twinkling of an eye, it happens very quickly:', 'Microprocessors do the calculations in the twinkling of an eye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5557, 'in the vicinity of', 'approximately:', 'The club is believed to have paid in the vicinity of €3 million for Domingo.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5558, 'in the wake of something', 'If something happens in the wake of something else, it happens after and often because of it:', 'Airport security was extra tight in the wake of yesterday''s bomb attacks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5559, 'in the way', 'in a position that prevents something from happening or someone from moving:', 'Work often gets in the way of my social life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5560, 'in the weeds', 'with so many problems or so much work that you are finding it difficult to deal with something:', 'We''re down in the weeds here with customer service.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5561, 'in the weeds', 'concerned with small details, often when this prevents you from understanding what is important:', 'He''s one of those rare people who can get down in the weeds and work on the details, but still see the big picture.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5562, 'in the wilderness', 'If someone, such as a politician, is in the wilderness, they no longer have a position of authority, fame, or success and are not now in the news:', 'After five years in the political wilderness, she was recalled to be foreign minister.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5563, 'in the wind', 'If something is in the wind, people are talking about it and it may happen, but no one is sure:', 'Rumours of a takeover are in the wind.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5564, 'in the wind', 'If someone is in the wind, they are missing, especially after escaping:', 'The suspects are in the wind.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5565, 'in the works', 'in the process of being planned or done:', 'Changes to the system are already in the works.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5566, 'in the world', 'in any conditions; of all possible things:', 'What in the world are you doing in the closet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5567, 'in the wrong', 'responsible for something bad:', 'We had a green light, so she was clearly in the wrong when she hit us.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5568, 'in the wrong place at the wrong time', 'in a situation where something bad happens to you because you are unlucky, not because you do anything wrong:', 'It wasn''t his fault. He was just in the wrong place at the wrong time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5569, 'in the zone', 'If you are in the zone, you are happy or excited because you are doing something very skilfully and easily.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5570, 'in theory', 'possibly:', 'They could, in theory, have been paid twice if someone hadn’t caught the error.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5571, 'in this day and age', 'at the present time:', 'You can''t afford to run businesses inefficiently in this day and age.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5572, 'in too deep', 'too involved in a difficult situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5573, 'in touch (with someone)', 'seeing someone or communicating with someone regularly:', 'We kept in touch for a while after college.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5574, 'in touch (with something)', 'having recent knowledge of a subject:', 'I try to stay in touch with the modern music scene.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5575, 'in tow', 'If you go somewhere with a particular person in tow, they are with you:', 'She arrived at the party, with a tall, silver-haired man in tow.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5576, 'in triplicate', 'When a document is prepared or written in triplicate, two exact copies of it are made also:', 'The application has to be completed in triplicate, with the original being kept by the bank and the copies going to the customer and the tax office.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5577, 'in truth', 'actually:', 'We kept climbing but, in truth, we knew we could not reach the top of the mountain before sunset.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5578, 'in tune with someone/something', 'having a good understanding of someone or something:', 'He is more in tune with his players today, because he has asked them for their opinions.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5579, 'in turn', 'because of that:', 'Stress causes your body to release chemicals, which in turn boost blood pressure.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5580, 'in turn', 'one after the other, in order:', 'She spoke to each of the guests in turn.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5581, 'in two shakes (of a lamb''s tail)', 'very soon:', 'I''ll be with you in two shakes.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5582, 'in unison', 'together and at the same time:', 'The audience rose to its feet in unison, applauding and cheering.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5583, 'in use', 'being used:', 'Is the washing machine in use right now?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5584, 'in view of something', 'because of a particular thing, or considering a particular fact:', 'In view of what you''ve said, I think we should reconsider our proposed course of action.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5585, 'in words of one syllable', 'in simple language avoiding long, difficult, or specialized words:', 'Could you explain to me in words of one syllable how an electron microscope works?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5586, 'in writing', 'in the form of a document, printed or written on paper:', 'We need to have your offer in writing before we can respond to it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5587, 'in years', 'in a long period of time:', 'We haven’t seen Marie in years.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5588, 'in your backyard', 'in the area where you live, or in the area of interest or activity that you are involved in or responsible for:', 'How would you feel about them building a nuclear power station in your backyard?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5589, 'in your birthday suit', 'not wearing any clothes', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5590, 'in your bones', 'in a way that is felt strongly, usually based on feelings or instinct (= natural reactions) rather than information:', 'He knows in his bones that his best days are long gone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5591, 'in your dreams!', 'something you say to someone who has just told you about something they are hoping for, in order to show that you do not believe it will happen:', 'Dave, buy you a car? In your dreams!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5592, 'in your element', 'in a situation you know well and enjoy:', 'Gerard stood up to sing in front of his classmates, and you could see he was in his element.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5593, 'in your face', 'slang rudely annoying someone:', 'One of the managers is always in my face.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5594, 'in your heart of hearts', 'in your most secret and true thoughts:', 'I didn''t want to believe it, but in my heart of hearts I knew that it was true.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5595, 'in your mind''s eye', 'in your imagination or memory:', 'In my mind''s eye, she is still a little girl of six, although she''s actually a grown woman.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5596, 'in your own right', 'If you have a position in your own right, you have earned it or got it by yourself and not because of anyone else:', 'She''s a millionaire in her own right.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5597, 'in your own words', 'If you say something in your own words, you speak without copying what someone else has said:', 'The court has heard accounts of that night''s events from several witnesses - now please tell us in your own words what you saw.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5598, 'in your salad days', 'during the period of time when you were a young person and had little experience:', 'I met her in my salad days.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5599, 'in your stocking(ed) feet', 'wearing only socks or stockings and not shoes:', 'Jerome stands 1 m 75 in his stocking feet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5600, 'in your tracks', 'in the exact place where you are standing:', 'He fell dead in his tracks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5601, 'in your/its prime', 'in the best, most successful, most productive stage:', 'The horse retired from racing while still in his prime.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5602, 'in/by fits and starts', 'If something happens in fits and starts, it often stops and then starts again:', 'Replies to the advertisement are arriving in fits and starts.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5603, 'in/out of keeping (with something)', 'suitable or not suitable for a particular situation:', 'In keeping with tradition, they always have turkey on Christmas Day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5604, 'in/out of the running', 'having/not having a reasonable chance of winning', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5605, 'in/through all the years', 'during the whole of a stated period of time:', 'I''ve never once seen her angry in all the years I''ve known her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5606, 'in/within spitting distance', 'If something is in or within spitting distance, it is very close:', 'The house is within spitting distance of the sea.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5607, 'inch by inch', 'in great detail and in many very small stages:', 'Detectives searched the area around the murder scene inch by inch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5608, 'incline to/towards something', 'to think that a belief or opinion is probably correct:', 'I incline to the view that peace can be achieved.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5609, 'inform against/on someone', 'If you inform on/against someone, you give the police information, usually secretly, about that person, showing that he or she has done something wrong:', 'The terrorists said that anyone caught informing on them would be killed.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5610, 'infringe on/upon something', 'If something infringes on/upon someone''s rights or freedom, it takes away some of their rights or limits their freedom:', 'These restrictions infringe upon basic human rights.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5611, 'inhere in something', 'to exist as a natural or basic part of something:', 'He believes that a power to alter things inheres in the human soul.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5612, 'ink sb/sth in', 'to decide when an action, meeting, etc. will happen, or when someone will do something:', 'The company has a 30 million pound investment inked in for next year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5613, 'inquire after someone', 'to ask for information about someone, especially about their health, in order to be polite:', 'She inquired after his grandfather''s health.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5614, 'inquire into something', 'to try to discover the facts about something:', 'When the authorities inquired into his background, they found he had a criminal record.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5615, 'inquire within', 'written on a notice on a building, meaning that information can be found inside:', 'Saturday staff needed - Inquire within.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5616, 'inside out', 'with the inside part facing out:', 'She put her sweater on inside out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5617, 'inside out', 'If you know something inside out, you know it very well:', 'He''s the best person to tell you how to get there because he knows the city inside out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5618, 'insinuate yourself into something', 'to use clever, secret, and often unpleasant methods to gradually become part of something:', 'Over the years she insinuated herself into the great man''s life.', 'phrasal verb', '', 'formal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5619, 'insist on doing something', 'to keep doing something, even if it annoys other people, or people think it is not good for you:', 'I don''t know why you insist on talking about it.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5620, 'insure against something', 'to do something in order to prevent something unpleasant from happening or from affecting you:', 'We thought we''d insure against rain by putting a tent up where people could take shelter.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5621, 'interest someone in something', 'Someone might ask if they can interest you in something when that person is trying to persuade you to buy something or is offering you something:', 'Can I interest you in our new range of kitchen fittings, madam?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5622, 'interfere with something', 'to prevent something from working effectively or from developing successfully:', 'Even a low level of noise interferes with my concentration.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5623, 'interfere with something', 'If something interferes with radio or television signals, it stops you from getting good sound or pictures.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5624, 'interfere with someone', 'to touch a child in a sexual manner:', 'He was sent to prison for interfering with little boys.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5625, 'into the bargain', 'in addition to other facts previously mentioned:', 'He''s intelligent, funny, a loving husband, and an excellent cook into the bargain.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5626, 'into thin air', 'used to refer to someone or something disappearing suddenly and completely:', 'We couldn''t find the boy. He seemed to have disappeared into thin air.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5627, 'introduce someone to something', 'to help someone experience something for the first time:', 'When were you first introduced to sailing?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5628, 'inure someone to something', 'If you become inured to something unpleasant, you become familiar with it and able to accept and bear it:', 'After spending some time on the island they became inured to the hardships.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5629, 'invalid someone out', 'If you are invalided out of a job, especially a military job, you are forced to leave because of injury or illness:', 'She was invalided out of the service because of injuries she received in a fire.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5630, 'inveigh against someone/something', 'to strongly criticize something or someone:', 'There were politicians who inveighed against immigrants to get votes.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5631, 'invest in something', 'to buy something because you think it will be useful, even if you think it is expensive:', 'We''ve decided it''s time to invest in a new computer.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5632, 'invest someone with something', 'to give authority or power to someone:', 'Our government has invested the representative with all the necessary powers to resolve the dispute.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5633, 'invest someone/something with something', 'to make someone or something seem to have a particular characteristic:', 'In his poems everyday reality is invested with a sense of wonder and delight.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5634, 'invite someone in', 'to ask someone to come into your house:', 'The neighbours invited us in for coffee.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5635, 'invite someone over', 'to invite someone to come to your house:', 'Let''s invite some people over.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5636, 'iron something out', 'to remove problems or find solutions:', 'We''re still trying to iron out some problems with the computer system.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5637, 'is he/she for real?', 'used when you think someone is silly or very surprising', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5638, 'is it me, or...?', 'used to ask if anyone agrees with you about something :', 'Is it me or is it hot in here?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5639, 'is the Pope a Catholic?', 'used to say that the answer to a question you have just been asked is obviously ''yes''', '', 'idiom', '', 'saying, humorous, offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5640, 'is the game worth the candle?', 'said when you are not certain if it is really worth making a great effort to get something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5641, 'isn''t it/aren''t they just?', 'used to strongly agree with what someone has said about someone or something:', '"This is very expensive." "Isn''t it just?"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5642, 'issue from something', 'If something issues from a place, it comes out of that place:', 'A terrible scream issued from the room.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5643, 'it all amounts/comes to the same thing', 'used to mean that any of several different possible actions will produce the same result:', 'It doesn''t matter whether you do it first or last - it all amounts to the same thing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5644, 'it beats me', 'said when you do not understand a situation or someone''s behaviour:', 'It beats me how she got the job.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5645, 'it can''t be helped', 'used to say that an unpleasant or painful situation, or an unwanted duty cannot be avoided and must be accepted:', 'I really didn''t want to go away this weekend but, oh well, it can''t be helped.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5646, 'it doesn''t hurt/never hurts to do something', 'it is useful or helpful to do or have something:', 'It never hurts to check the flight departure time before you leave for the airport.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5647, 'it doesn''t take a rocket scientist', 'used to say that you do not think that something is very difficult to do or to understand:', 'Drugs equals crime. It doesn''t take a rocket scientist to figure that one out.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5648, 'it doesn’t hurt to do something', 'it is an advantage to do or have something:', 'It doesn’t hurt to have money when you want to run for office.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5649, 'it doesn’t take a rocket scientist to do something', 'humorous it is easy to do or understand something:', 'It doesn''t take a rocket scientist to figure out that if you treat her well, she''ll be happier.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5650, 'it figures', 'used to say that you are not surprised by something unpleasant that has happened:', '"Dad, Sadie spilled her milk all over the floor." "It figures."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5651, 'it goes without saying', 'used to mean that something is obvious:', 'Of course, it goes without saying that you''ll be paid for the extra hours you work.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5652, 'it is what it is', 'used to say that a situation cannot be changed and must be accepted:', 'We''re all imperfect human beings in an imperfect world. It is what it is.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5653, 'it is/was nothing', 'used to tell someone not to worry about, or place special value on, what you are doing or have done:', '"You seem very upset." "No, no, it''s nothing - I''m OK."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5654, 'it isn''t over until the fat lady sings', 'used for saying that it is still possible for a situation to change', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5655, 'it makes me (want to) puke', 'used to say that something makes you very upset or angry', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5656, 'it never rains but it pours', 'said when one bad thing happens, followed by a lot of other bad things that make a bad situation worse', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5657, 'it remains to be seen', 'it is not yet certain:', 'It remains to be seen who will win.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5658, 'it says a lot for someone/something', 'used to show how much of a particular quality someone or something has:', 'It says a lot for her determination that she practises her cello so often.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5659, 'it serves someone right', 'infmlsomeone deserves the punishment given:', 'People think this game is so important, and it would serve them right if it was rained out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5660, 'it stands to reason', 'said when something is obvious or clear from the facts:', 'If 20 percent of the earth''s population has 80 percent of its resources, then it stands to reason that 80 percent of the population has only 20 percent of the resources.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5661, 'it stands to reason (that)', 'something seems likely to be true:', 'It stands to reason that with all his experience, he would not make such a simple mistake.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5662, 'it takes a thief to catch a thief', 'used to mean that one dishonest person can guess what another dishonest person might do', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5663, 'it takes all sorts (to make a world)', 'said to emphasize that people have different characters, opinions, and abilities, and that you should accept this', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5664, 'it takes two to tango', 'said when you want to emphasize that both people involved in a difficult situation must accept the blame, or that an activity needs two people who are willing to take part for it to happen:', 'She may want to argue, but it takes two to tango and I won''t stoop to her level.', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5665, 'it will (all) come out in the wash', 'used to tell someone that problems will be solved in the end:', 'We''ve certainly had some problems but I think, in the end, it will all come out in the wash.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5666, 'it wouldn''t hurt you to do something', 'something that you say when you think someone should do something because they do not often do it:', 'It wouldn''t hurt you to do the ironing for once.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5667, 'it''ll (all) end in tears', 'something that you say that means something will end badly and the people involved will be upset:', 'She only met him in May and they were married by July. It''ll end in tears, you''ll see.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5668, 'it''ll cost you', 'it will be very expensive:', 'It''ll cost you to have your roof repaired.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5669, 'it''s a crying shame', 'something that you say when you think a situation is wrong:', 'It''s a crying shame that she''s paid so little for what she does.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5670, 'it''s a date', 'used to say that a particular time is a good time to meet:', '"I can''t make it at seven o''clock. How about 9.30?" "Sure, it''s a date."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5671, 'it''s a fair cop', 'something you say when someone has caught you doing something wrong and you agree that you were wrong', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5672, 'it''s a funny old world', 'said when someone has told you something that is strange or surprising', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5673, 'it''s a long story', 'something that you say when someone has asked you about something that has happened and you do not want to explain it to them because it would take too long:', '"So why was Carlo knocking on your door at midnight?" "It''s a long story."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5674, 'it''s a pleasure', 'a polite way of replying to someone who has thanked you:', '"It was so kind of you to give us a lift." "Don''t mention it - it was a pleasure."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5675, 'it''s a small world', 'said to show your surprise that people or events in different places are connected:', 'You know my old science teacher! Well, it''s a small world, isn''t it?', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5676, 'it''s a wonder', 'it is surprising:', 'It''s a wonder (that) he ever reached Paris, because he set off with only £5 in his pocket.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5677, 'it''s a wrap', 'a phrase used in film making to tell actors and crew that filming of a particular scene, film, etc. has finished', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5678, 'it''s all Greek to me', 'a way of saying that you do not understand something that is said or written', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5679, 'it''s an ill wind (that blows nobody any good)', 'said to show that even a very bad situation must have some good results', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5680, 'it''s early days', 'said when you think it is too soon to make a judgment about the likely result of something because a lot might still happen or change:', 'Our progress has been fairly slow so far, but it''s early days.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5681, 'it''s every man for himself', 'something that you say that means that everyone in a particular situation is trying to do what is best for themselves and no one is trying to help anyone else:', 'It might be a civilized place to shop at other times, but come the January sales, it''s every man for himself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5682, 'it''s just one of those things', 'said about an event or situation that you cannot explain, or do not like but cannot change', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5683, 'it''s more than my job''s worth', 'something that you say in order to tell someone that you cannot do what they want you to do because you would lose your job', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5684, 'it''s no use (doing something)', 'the thing someone tries cannot be or was not successful:', 'People tried to stop her, but it was no use.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5685, 'it''s not brain surgery', 'used to say that you do not think that something is very difficult to do or to understand:', 'Just keep calm and do it. It''s not brain surgery.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5686, 'it''s not rocket science', 'used to say that you do not think that something is very difficult to do or to understand:', 'My coach always said, "Basketball is not rocket science. It''s about putting the ball in the basket."', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5687, 'it''s now or never', 'said when you must do something immediately, especially because you will not get another chance', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5688, 'it''s raining cats and dogs!', 'something that you say when it is raining heavily', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5689, 'it''s safe to say (that)', 'used to say that you are confident about what you are going to say:', 'I think it''s safe to say that the crisis is now over.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5690, 'it''s the least I can do', 'a polite answer to someone who thanks you, usually when you feel you should do more to help:', '"Thanks for cleaning up" "It''s the least I can do, seeing as I''m staying here rent-free."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5691, 'it''s the same old story', 'said when talking about a bad situation that has happened many times before:', 'It''s the same old story - the rich get richer and the poor get poorer.', 'idiom', 'C1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5692, 'it''s the thought that counts', 'used to say that good or kind intentions are the most important thing, even if what you do or give someone is not perfect:', 'Even when people do things for you and give you things that you don''t actually want, you must always remember that it''s the thought that counts.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5693, 'it''s tough at the top', 'used to mean that people in important positions have a lot of advantages and get a lot of good things:', '"The CEO always flies first class." "It''s tough at the top, isn''t it?"', 'idiom', '', 'humorous, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5694, 'it''s your own lookout', 'used to tell someone that they are responsible for their own problems:', 'It''s your own lookout if you''re not properly insured.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5695, 'it''s/that''s the story of my life', 'said when something bad happens to you that has happened to you many times before:', 'Honestly, it''s the story of my life - I meet a totally gorgeous guy and he''s leaving for Australia the next day!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5696, 'itch to do something', 'to want to do something very much and as soon as possible:', 'He was itching to hear the results.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5697, 'itching to do something', 'wanting to do something very much:', 'The kids are itching to go out and play.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5698, 'jack off', 'to masturbate', '', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5699, 'jack something in', 'to stop doing something, often a job or something that you are not enjoying:', 'He''s jacked in his job.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5700, 'jack something up', 'to raise a heavy object such as a car off the ground with a jack', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5701, 'jack something up', 'to increase the price of something suddenly and by a large amount:', 'Once the tourists arrive, the restaurants jack up their prices.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5702, 'jack-of-all-trades, master of none', 'said about someone who is able to do many things, but is not an expert in any', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5703, 'jam on the brakes', 'to use the brakes of a road vehicle suddenly and forcefully:', 'A motorbike appeared from nowhere and I had to jam on the brakes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5704, 'jam tomorrow', 'something good that is promised but never happens:', 'As children we were always being promised jam tomorrow, if only we would be patient.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5705, 'jangle someone''s nerves', 'to make someone feel annoyed or nervous:', 'The constant whine of the machinery jangled his nerves.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5706, 'jar on someone', 'If something, especially a noise, jars on you, it annoys you:', 'His superior manner jars on me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5707, 'jazz something up', 'to make something more attractive or interesting:', 'Jazz the dress up with some bright accessories.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5708, 'jerk off', '(of a man) to 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5709, 'jerk someone around', 'to intentionally cause difficulty for someone:', 'I don’t think she really likes Colten – she’s just jerking him around.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5710, 'jib at something', 'to be unwilling to do or continue with something:', '[ + -ing verb ] Although the tax is unpopular, the government has jibbed at abolishing it completely.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5711, 'jib at something', 'If a horse jibs at something, it stops suddenly in front of it and refuses to move forward.', '', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5712, 'jibe with something', 'If one statement or opinion jibes with another, it is similar to it and matches it:', 'Her account of the accident jibes with mine.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5713, 'job done', 'something you say when someone has achieved something, especially when it seems easier or quicker than you expected:', 'I just changed the fuse in the plug and the lamp worked, job done.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5714, 'job sth out', 'to employ a person or organization to do particular work for you:', 'Several banks are bringing IT work back in house that would normally be jobbed out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5715, 'jobs for the boys', 'work that someone in an important position gives to their friends or relations', '', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5716, 'jockey someone into something', 'to persuade someone to do what you want, often by deceiving them in a clever way:', '[ + -ing verb ] The bosses were eventually jockeyed into signing the union agreement.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5717, 'jog along', 'If something, such as your work, jogs along, it moves on at a slow but regular speed:', '"How''s your research going?" "Oh, it''s jogging along."', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5718, 'jog on', 'used to tell someone forcefully and rather rudely to go away:', 'He asked me for money but I told him to jog on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5719, 'jog someone''s memory', 'to make someone remember something:', 'The police showed him a photo to try to jog his memory about what had happened on the night of the robbery.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5720, 'join battle', 'If armies join battle, they start to fight.', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5721, 'join duty', 'to return to work after a period of time away', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5722, 'join hands', 'If two or more people join hands, they hold each other''s hands, especially in order to do something:', 'The teacher asked us to form a circle and join hands.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5723, 'join in (something)', 'to become involved in an activity with other people:', 'We only need one more player for this game - can you persuade your sister to join in?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5724, 'join the club!', 'said in answer to something that someone has said, meaning that you are in the same bad situation as they are:', '"I''ve got no money till the end of this week." "Join the club!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5725, 'join up', 'If you join up, you become a member of one of the armed forces:', '"Have you been in the army for a long time?" "I joined up as soon as I''d left school."', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5726, 'join up with sb/sth', 'to get together with another company, person, or group in order to do something together or form one company, group, etc.:', 'The design company is planning to join up with a shoe manufacturer and create a new range of footwear.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5727, 'join with sb/sth', 'to get together with another company, person, or group in order to do something together:', 'join with sth/sb in doing sth The department store has joined with other local stores in trying to prevent shoplifting.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5728, 'joker in the pack', 'the person or thing that could change the situation in an unexpected way', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5729, 'joking apart/aside', 'said when you want to start speaking seriously about something after making jokes and laughing about it:', 'Joking apart, will you be able to manage on your own?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5730, 'jolly good', 'used to express approval of something that someone has said or done, or to show that you have heard or understood what someone has said:', '"I''ve left all the papers you need on your desk." "Oh, jolly good."', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5731, 'jolly good show!', 'used to express admiration for what someone has said or done:', '"We won!" "Oh, jolly good show!"', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5732, 'jolly hockey sticks', 'used to describe a woman or girl of a high social class who is enthusiastic in a way that annoys most people', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5733, 'jolly something up', 'to make something brighter and more attractive:', 'I thought I''d jolly the room up with some colourful curtains.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5734, 'jostle for something', 'If people jostle for something, they compete with each other in order to get what they want:', 'Since the fall of the government, the two opposition parties have been jostling for position.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5735, 'jot something down', 'to write something quickly on a piece of paper so that you remember it:', 'I carry a notebook so that I can jot down any ideas.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5736, 'jump all over someone', 'to criticize someone suddenly and severely:', 'When I showed him my report card, Dad jumped all over me.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5737, 'jump at something', 'to accept something eagerly:', 'She jumped at the chance of a trip to Paris.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5738, 'jump down someone''s throat', 'to react angrily to something that someone says or does:', 'I made the mildest of criticisms and he jumped down my throat.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5739, 'jump for joy', 'to be extremely happy:', '"So how did Robert take the news?" "He didn''t exactly jump for joy."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5740, 'jump in', 'to interrupt when someone else is speaking:', 'I wish you''d stop jumping in and finishing my sentences for me all the time.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5741, 'jump in at the deep end', 'If you jump or are thrown in at the deep end, you start doing something new and difficult without help or preparation.', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5742, 'jump in with both feet', 'to become involved in a situation too quickly without thinking about it first:', 'That''s just like Julie - always jumping in with both feet before she knows the facts.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5743, 'jump into sth', 'to suddenly decide to do something, especially without thinking about it carefully:', 'Investors shouldn''t jump into moving their funds without carefully reviewing their financial situation.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5744, 'jump on someone', 'to criticize someone as soon as they have done something wrong or said something that you disagree with:', 'She jumps on her children instantly if they''re disobedient.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5745, 'jump on the bandwagon', 'to join an activity that has become very popular or to change your opinion to one that has become very popular so that you can share in its success:', 'After a couple of politicians won elections by promising to cut taxes, most of the others jumped on the bandwagon.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5746, 'jump out at someone', 'If something jumps out at you, you notice it immediately:', 'That''s a very effective advertisement - it really jumps out at you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5747, 'jump the gun', 'to do something too soon, especially without thinking carefully about it:', 'They''ve only just met - isn''t it jumping the gun to be talking about marriage already?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5748, 'jump the queue', 'to move to the front of a line of people who are waiting for something, so that you are served or dealt with before them:', 'This pre-paid smart card allows you to jump the queue to 60 of the capital''s favourite attractions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5749, 'jump the queue', 'to be dealt with earlier than other people who are also waiting for something and who may have been waiting longer than you:', 'Under this plan the better-off will be able to jump the queue by paying for private health care.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5750, 'jump the shark', '(usually of television shows) to reach a point where something stops becoming more popular or starts to decrease in quality:', 'The show jumped the shark a few years ago.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5751, 'jump through hoops', 'to have to do a lot of things that seem difficult or unnecessary in order to achieve something:', 'We had to jump through hoops to get my Dad admitted to hospital.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5752, 'jump to conclusions', 'to guess the facts about a situation without having enough information:', 'Don''t jump to conclusions! Perhaps it was his daughter he was dancing with.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5753, 'jump to it', 'used to tell someone to do something quickly:', 'I told you to tidy this room - now jump to it!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5754, 'jump to someone''s defence', 'to quickly defend someone:', 'Whenever anyone criticizes her husband, she immediately jumps to his defence.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5755, 'jump/climb/get on the bandwagon', 'to become involved in an activity that is successful so that you can get the advantages of it yourself:', 'The success of the product led many firms to try to jump on the bandwagon.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5756, 'jump/leap out of your skin', 'to be extremely surprised by something:', 'The loud noise made me jump out of my skin.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5757, 'just a minute/moment/second', 'used to ask someone to wait for a short period of time:', 'Just a second - I''ve nearly finished.', 'idiom', 'A2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5758, 'just a minute/moment/second', 'used to interrupt someone in order to ask them to explain something, to calm them, or to express disagreement:', 'Just a minute - can you tell me how to do that again?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5759, 'just a moment', 'wait a short period of time:', 'Just a minute – I''m almost done.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5760, 'just because I''m paranoid doesn''t mean they''re not out to get me', 'said when you recognize that you generally worry too much about people trying to harm you, but believe that in this particular situation people really are trying to harm you', '', 'idiom', '', 'humorous, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5761, 'just gay enough', 'A heterosexual man who is just gay enough has some of the qualities typical of gay men that many women like, such as an interest in clothes or being able to talk about emotions.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5762, 'just in case', 'to protect against something bad that could happen:', 'I’ll take my umbrella too, just in case.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5763, 'just like that', 'suddenly and unexpectedly:', 'Their son went off and got married last week, just like that.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5764, 'just my luck!', 'something that you say when something bad happens to you:', 'They sold the last ticket five minutes before I got there - just my luck!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5765, 'just now', 'a very short time ago:', 'Who was that at the door just now?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5766, 'just the man/woman for the job', 'a man/woman who has all the skills for a particular piece of work:', 'We need someone who has experience in marketing and teaching, and I think Alex is just the woman for the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5767, 'just the thing', 'exactly what is needed:', 'A week''s rest would be just the thing for her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5768, 'just the ticket', 'very suitable and exactly what is needed', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5769, 'just what the doctor ordered', 'exactly what is wanted or needed:', 'Thanks, a strong cup of coffee in the morning is just what the doctor ordered.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5770, 'keel over', 'to fall over suddenly:', 'He finished the bottle, stood up to leave, and keeled over.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5771, 'keel over', 'If a boat keels over, it turns upside down in the water:', 'The storm raged and they struggled to stop the boat from keeling over.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5772, 'keep to somewhere', 'to stay in one particular area:', 'Please keep to the footpaths.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5773, 'keep something to something', 'If you keep something to a particular number or amount, you make certain it does not become larger than that.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5774, 'keep something to yourself', 'to keep something secret:', 'I don''t want everyone to know, so if you could keep it to yourself I''d appreciate it.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5775, 'keep (yourself) to yourself', 'to not talk to other people very much:', 'He''s a very private person - he keeps (himself) to himself.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5776, 'keep to something', 'to do what you have promised or planned to do:', 'I think we should keep to our original plan.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5777, 'keep to something', 'If you keep to a particular subject, you only talk about that subject:', 'For heaven''s sake let''s keep to the point or we''ll never reach any decisions.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5778, 'keep (myself) to myself', 'to spend time alone, not talking to other people very much:', 'I don''t see friends very often. I prefer to keep myself to myself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5779, 'keep (someone/something) away', 'to not go somewhere or near something, or to prevent someone from going somewhere or near something:', 'Keep away from the edge of the cliff.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5780, 'keep (someone/something) off something', 'to not go onto an area, or to stop someone or something going onto an area:', 'There was a notice saying "Keep off the grass".', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5781, 'keep something off (someone/something)', 'to stop something touching or harming someone or something:', 'Put a cloth over the salad to keep the flies off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5782, 'keep (someone) off something', 'to not eat, drink, or use something that can harm you, or to stop someone else from doing this:', 'The doctor told me to keep off fatty foods.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5783, 'keep off something', 'If you keep off a particular subject, you avoid talking about it.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5784, 'keep (someone/something) out', 'to not go in a place, or to stop someone or something from going into a place:', 'Building work in progress. Keep out!', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5785, 'keep (someone/something) out of something', 'to avoid becoming involved in something, or to stop someone or something becoming involved in something:', 'I prefer to keep out of arguments about money.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5786, 'keep (something/someone) back', 'to not go near something, or to prevent someone or something from going past a particular place:', 'Barriers were built to keep back the flood water.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5787, 'keep something back', 'to not use the whole amount of something so that there is a small amount remaining for later', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5788, 'keep something back', 'to not tell someone everything you know about a situation or an event that has happened:', 'I suspect she''s keeping something back.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5789, 'keep a civil tongue in your head', 'used to tell someone to stop being rude', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5790, 'keep a clean sheet', 'in football, to not allow the opposing team to score a goal:', 'Liverpool have kept a clean sheet in five of their last six home games.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5791, 'keep a cool head', 'to stay calm in a difficult situation:', 'I don''t know how you manage to keep such a cool head in such a hectic, stressful office!', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5792, 'keep a firm hand on something', 'to control something or someone carefully:', 'Susan keeps a firm hand on everything that goes on in the office.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5793, 'keep a low profile', 'to avoid attracting attention to yourself:', 'He''s been in a little trouble recently so he''s trying to keep a low profile.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5794, 'keep a straight face', 'to manage to stop yourself from smiling or laughing:', 'She tried to keep a straight face but, unable to contain herself, burst into laughter.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5795, 'keep a tight rein on someone/something', 'to have a lot of control over someone or something:', 'My father always kept us on a tight rein.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5796, 'keep a weather eye on something', 'to watch a particular situation closely to see what happens:', 'They are well accustomed to keeping a weather eye on currency movements.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5797, 'keep a weather eye open', 'to always be paying attention so that you notice if anything happens:', 'His bodyguard kept a weather eye open from across the room.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5798, 'keep a/the lid on something', 'to control the level of something in order to stop it increasing:', 'The administration has intervened to keep a lid on inflation.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5799, 'keep an eye out for something', 'to watch carefully for something:', 'Keep an eye out for spyware programs that install themselves on your computer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5800, 'keep at something', 'to continue to do or work on something:', 'I kept at it and finally finished at three this morning.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5801, 'keep body and soul together', 'to be able to pay for your food, clothing, and somewhere to live:', 'His wages are barely enough to keep body and soul together.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5802, 'keep count (of something)', 'to remember a total:', 'I’ve been keeping count of how many times he’s called this week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5803, 'keep faith with something/someone', 'to continue to support something or someone, or to do what you promised to do in a particular thing:', 'Despite the continuing recession, the government has asked people to keep faith with its reforms.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5804, 'keep from doing something', 'to manage to prevent yourself from doing something:', 'I couldn''t keep from smiling when she told me what she''d done.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5805, 'keep in with someone', 'to continue to try to be friendly with someone, especially because they can help you:', 'I like to keep in with my ex-employer, you never know when you might need a reference.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5806, 'keep it down', 'to be quieter:', 'Hey you guys, keep it down in there – I’m on the phone!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5807, 'keep it up', 'used to encourage someone to continue doing something:', 'You''re doing very well everybody. Keep it up!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5808, 'keep on', 'to continue to talk in an annoying way about something:', 'Don''t keep on, I''ll sort it out in a minute.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5809, 'keep on doing something', 'to continue to do something, or to do something again and again:', 'She kept on asking me questions the whole time.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5810, 'keep on the right side of someone', 'to try to make certain that someone is pleased with you:', 'Paul kept on the right side of his teachers by working really hard.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5811, 'keep on trucking', 'to continue to do something that is ordinary and boring:', '"How''s work going?" "Oh, okay. I just keep on trucking."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5812, 'keep someone at arm''s length', 'to not allow someone to become too friendly with you:', 'I always had the feeling she was keeping me at arm''s length.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5813, 'keep someone at bay', 'to prevent someone from moving closer:', 'He held the police at bay for several hours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5814, 'keep something at bay', 'to control something and prevent it from causing you problems:', 'She fought to keep her unhappiness at bay.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5815, 'keep someone at it', 'to make someone continue to work hard:', 'We need to keep her at it if she''s going to pass the final exam.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5816, 'keep someone company', 'to stay with someone so the person is not alone:', 'I kept him company while he was waiting for the bus.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5817, 'keep someone guessing', 'to not tell someone what you are going to do next', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5818, 'keep someone in', 'to make a child stay inside as a punishment, or to make someone stay in hospital:', 'They kept her in overnight for observation.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5819, 'keep someone in the picture', 'to make sure someone knows all the facts about a changing situation:', 'I use the radio to keep me in the picture about what''s happening abroad.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5820, 'keep someone on the rails', 'to make sure someone continues to behave in a way that is generally acceptable, honest, and legal:', 'It can sometimes be hard trying to keep teenagers on the rails.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5821, 'keep something on the rails', 'to make sure something continues to be successful or effective:', 'It takes a lot out of you keeping a business on the rails.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5822, 'keep someone posted', 'to make sure someone knows what is happening, esp. in a situation that is quickly changing:', 'The doctors kept me posted about her condition.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5823, 'keep someone sweet', 'to try to keep someone satisfied and pleased with you so that you can continue to get what you want:', 'He made a few concessions to keep the shareholders sweet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5824, 'keep someone up', 'to prevent someone from going to bed or sleeping:', 'He keeps yawning - I hope we''re not keeping him up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5825, 'keep something up', 'to make something continue at its present level and not allow it to fall:', 'You must eat to keep your strength up.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5826, 'keep (something) up', 'to continue without stopping or changing, or to continue something without allowing it to stop or change:', 'Keep up the good work!', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5827, 'keep up', 'to be able to understand or deal with something that is happening or changing very fast:', 'I read the papers to keep up with what''s happening in the outside world.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5828, 'keep someone/something from something', 'to prevent someone or something from doing something:', '[ + -ing verb ] Try to keep the children from throwing food all over the floor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5829, 'keep something from someone', 'to not tell someone about something:', 'He says it''s alright but I think he''s keeping something from me.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5830, 'keep something down', 'to be able to eat or drink something without vomiting:', 'On the day after her operation she couldn''t keep anything down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5831, 'keep something down', 'to control the size or number of something and prevent it from increasing:', 'We need to work hard to keep our prices down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5832, 'keep someone down', 'to prevent a person or group of people from having any power or freedom:', 'It''s all part of a conspiracy to keep women down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5833, 'keep something quiet', 'to say nothing about something:', 'She managed to keep the school’s problems quiet for a while.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5834, 'keep tabs on something/someone', 'to watch something or someone carefully:', 'I like to keep tabs on my bank account so that I don''t spend too much.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5835, 'keep the flag flying', 'to act or speak for the country or group that a flag represents', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5836, 'keep the lights on', 'to make sure that a business, system, etc. continues to operate, even if it does not make much progress:', 'Please don''t block those ads - they help keep the lights on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5837, 'keep the wolf from the door', 'to have just enough money to be able to eat and live:', 'As a student, he took an evening job to keep the wolf from the door.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5838, 'keep to yourself', 'to often avoid other people:', 'I was very shy and pretty much kept to myself in school.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5839, 'keep something to yourself', 'do not tell anyone about something:', 'The party’s a surprise, so keep it to yourself!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5840, 'keep track', 'to make certain that you know what is happening or has happened to someone or something:', 'My sister has had so many different jobs, it''s hard for me to keep track (of what she''s doing).', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5841, 'keep track (of someone/something)', 'to continue to be informed or know about someone or something:', 'My sister’s had so many jobs, I can’t keep track anymore.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5842, 'keep up (with someone/something)', 'to do whatever is necessary to stay level or equal with someone or something:', 'He started to walk faster and the children had to run to keep up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5843, 'keep up appearances', 'to pretend to be happier, less poor, etc. than you really are, because you do not want people to know how bad your situation is:', 'They were very unhappily married but kept up appearances for the sake of their children.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5844, 'keep up with the Joneses', 'to always want to own the same expensive objects and do the same things as your friends or neighbours, because you are worried about seeming less important socially than they are', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5845, 'keep your distance', 'to avoid going near someone or something, or to avoid getting too friendly with people:', 'I''ve tried being friendly but she keeps her distance.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5846, 'keep your eye in', 'to continue to be good at a sport or other activity by practising it:', 'I try to play regularly to keep my eye in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5847, 'keep your eye on the ball', 'to give your attention to what you are doing at the time:', 'You have to keep your eye on the ball in business.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5848, 'keep your eyes open for someone/something', 'to watch carefully for someone or something, often while you are doing something else:', 'While you are checking the animals, keep your eyes open for any signs of disease .', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5849, 'keep your eyes peeled/skinned', 'to watch carefully for someone or something:', 'Keep your eyes peeled for Polly and Maisie.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5850, 'keep your fingers crossed', 'to hope strongly that something will happen:', 'We’re keeping our fingers crossed that he’ll be healthy again very soon.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5851, 'keep your hair on', 'said to tell someone to stop being so angry or upset:', 'Keep your hair on! Your car isn''t badly damaged!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5852, 'keep your hand in', 'to practise a skill often enough so that you do not lose the skill:', 'I do a bit of teaching now and then just to keep my hand in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5853, 'keep your head', 'to stay calm despite great difficulties:', 'She kept her head under pressure and went on to win the race.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5854, 'keep your head above water', 'to just be able to manage, especially when you have financial difficulties:', 'The business is in trouble, but we are just about keeping our heads above water.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5855, 'keep your head down', 'to avoid trouble:', 'He''s in a bad mood today - I''m just keeping my head down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5856, 'keep your mouth shut', 'to not talk about something:', 'I don''t know whether to tell him what I know or keep my mouth shut.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5857, 'keep your nose clean', 'to avoid getting into trouble:', 'I''d only been out of prison three months, so I was trying to keep my nose clean.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5858, 'keep your nose out of something', 'to not become involved in other people''s activities or relationships:', 'She can''t keep her nose out of other people''s business.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5859, 'keep your nose to the grindstone', 'to work very hard without resting:', 'After a year of keeping his nose to the grindstone, he finally got a vacation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5860, 'keep your options open', 'to wait before making a choice:', 'I haven’t signed a contract – I’m leaving my options open.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5861, 'keep your own counsel', 'to not say what your opinions are:', 'I''d love to know what Anna thinks, but she always keeps her own counsel.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5862, 'keep your powder dry', 'to wait before taking action, but be ready to take action if it is necessary:', 'I think some potential candidates are going to keep their powder dry and see how it''s playing out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5863, 'keep your shirt on', 'said to tell someone to stop being so angry or upset:', 'Keep your shirt on! Your car isn''t even scratched!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5864, 'keep your temper', 'not become angry:', 'It was hard to keep my temper with so many things going wrong.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5865, 'keep your/an eye on something/someone', 'to watch or take care of something or someone:', 'Will you keep your eye on my suitcase while I go to get the tickets?', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5866, 'keep your/an eye out for someone/something', 'to watch carefully for someone or something to appear:', 'Keep your eye out for signposts to Yosemite.', 'idiom', 'C1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5867, 'keep/hold your cards close to your chest', 'to keep your intended actions secret:', 'You never quite know what Barry''s going to do next - he keeps his cards very close to his chest.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5868, 'keep/hold your end up', 'to continue to deal with difficulties bravely and successfully', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5869, 'keep/put your nose to the grindstone', 'to work very hard for a long time:', 'She kept her nose to the grindstone all year and got the exam results she wanted.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5870, 'key something in', 'to put information into a computer, phone, or other machine using a keyboard or touchscreen:', 'I keyed the number in, but nothing happened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5871, 'kick (some) ass', 'to punish someone or to defeat someone with a lot of force:', 'We''re gonna go in there and kick ass.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5872, 'kick (some) ass', 'to do something extremely well:', 'It was her first attempt and she kicked ass!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5873, 'kick against something', 'to refuse to accept something and react strongly against it:', 'As a boy he always kicked against his father''s authority.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5874, 'kick against the pricks', 'to argue and fight against people in authority', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5875, 'kick around', 'If something is kicking around a place, it is somewhere in that place, not being used:', 'There must be a copy of it kicking around the office somewhere.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5876, 'kick something around', 'If you kick ideas around, you talk about them informally in a group:', 'We need to get everyone together and kick a few ideas around', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5877, 'kick back', 'to stop doing things and relax:', 'What good is life if a guy can’t kick back and watch a good movie?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5878, 'kick in', 'to start to have an effect or to happen:', 'It takes half an hour for the medication to kick in.', 'phrasal verb', 'C1', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5879, 'kick in something', 'to give something, especially money or help:', 'Another plan would require employers to kick in $20 per worker to set up the fund.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5880, 'kick in the teeth', 'If you describe the way someone treats you as a kick in the teeth, you mean that that person treats you badly and unfairly, especially at a time when you need their support:', 'She was dismissed from her job, which was a real kick in the teeth after all the work she''d done.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5881, 'kick it', 'to relax somewhere, usually with other people, not doing anything in particular:', 'Most weekends I''ll just kick it with my friends.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5882, 'kick off', 'If a game of football kicks off, it starts:', 'What time does the game kick off?', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5883, 'kick off', 'to begin:', 'Indonesia''s parliamentary election campaign kicked off at the weekend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5884, 'kick off', 'to become full of action and excitement, sometimes including violence:', 'Chamonix''s bars and clubs - lively any night - really kick off at weekends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5885, 'kick off', 'to start to get angry or complain in a noisy way:', 'The children started to kick off so I couldn''t stay.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5886, 'kick off', 'to die', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5887, 'kick (something) off', 'If you kick off a discussion or an activity, you start it:', 'I''d like to kick off the discussion with a few statistics.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5888, 'kick over the traces', 'to behave badly and show no respect for authority', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5889, 'kick sb''s arse', 'to punish someone or to defeat someone with a lot of force:', 'If you hurt my brother, I''ll kick your arse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5890, 'kick someone out', 'to force someone to leave a place or organization:', 'His wife kicked him out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5891, 'kick someone upstairs', 'to give someone a new job that seems more powerful but is really less powerful, usually in order to stop them causing trouble for you', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5892, 'kick something into the long grass', 'to delay dealing with something, especially because you want people to forget about it:', 'It is disgraceful that the Treasury had kicked the task force''s report into the long grass.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5893, 'kick something into touch', 'to decide not to do what you had planned to do:', 'Our plans to buy a new car have had to be kicked into touch now Kev''s lost his job.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5894, 'kick something off (with something)', 'to begin an event or period of time, esp. with an activity:', 'We like to kick off the summer with a barbecue.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5895, 'kick the bucket', 'to die', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5896, 'kick the can down the road', 'to avoid or delay dealing with a problem:', 'I don''t think we should kick the can down the road and let our grandkids solve that problem.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5897, 'kick the habit', 'to give up something harmful that you have done for a long time:', 'She used to be a heavy smoker but she kicked the habit last year.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5898, 'kick the tires', 'to try something or examine it carefully before you buy it:', 'Come and kick the tires on this latest version of the software.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5899, 'kick up', 'to become more active or noticeable:', 'As the storm moves into the desert, the wind and rain start to kick up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5900, 'kick up a fuss/row/stink', 'to show great anger about something, especially when this does not seem necessary:', 'He kicked up a tremendous fuss about having to wait.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5901, 'kick up your heels', 'to do things that you enjoy:', 'After final exams we kicked up our heels and had a really good party.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5902, 'kick your heels', 'to be forced to wait for a period of time', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5903, 'kick/hit someone when he/she is down', 'to criticize or take unfair advantage of someone when they are in a weak position:', 'It''s typical of the boss to kick someone when they''re down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5904, 'kid around', 'to be silly or not serious:', 'Stop kidding around and listen to me!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5905, 'kill it', 'to do something extremely well:', 'Chris kills it on drums.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5906, 'kill or cure', 'a way of solving a problem that will either fail completely or be very successful:', 'Having a baby can be kill or cure for a troubled marriage.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5907, 'kill someone with kindness', 'to be too kind to someone, harming that person because you are helping or giving them too much', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5908, 'kill something off', 'to destroy something completely, usually over a period of time:', 'The use of pesticides is killing off birds and fish.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5909, 'kill something stone-dead', 'to cause something to be completely unsuccessful or to stop completely:', 'One bad review can kill a film stone-dead.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5910, 'kill the fatted calf', 'to have a special celebration for someone who has been away for a long time', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5911, 'kill the goose that lays the golden egg', 'to destroy something that makes a lot of money for you', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5912, 'kill time, an hour, etc.', 'to do something that keeps you busy while you are waiting for something else to happen:', 'My friend was late, so I killed an hour window-shopping.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5913, 'kill two birds with one stone', 'to succeed in achieving two things in a single action:', 'I killed two birds with one stone and picked the kids up on the way to the supermarket.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5914, 'kind of', 'used when you are trying to explain or describe something, but you cannot be exact:', 'It was kind of strange to see him again.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5915, 'kiss ass', 'to be very nice to people in authority because you want them to help you', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5916, 'kiss my arse!', 'used to tell someone that you will not do what they want you to do', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5917, 'kiss my ass!', 'used to tell someone that you will not do what they want you to do', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5918, 'kiss of death', 'If you describe something as the kiss of death, you mean that it is certain to cause something else to fail:', 'Rain is the kiss of death for a barbecue.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5919, 'kiss someone''s arse', 'to be very nice to someone in order to get an advantage', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5920, 'kiss something goodbye', 'to accept that you have lost something or that you will not be able to have something:', 'If France lose this game, they can kiss their chances of winning the cup goodbye.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5921, 'kiss something off', 'to accept that you have lost something or failed at something:', 'I guess we can kiss off the deal.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5922, 'kiss someone/something off', 'to make it clear that you do not want or need someone or something:', 'You''re not in a position to kiss off any job you''re offered.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5923, 'kit someone/something out', 'to supply someone or something with the clothes or equipment that are needed for a particular purpose:', 'They went shopping to get kitted out for the trip.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5924, 'knit your brow/brows', 'to frown (= move your eyebrows down and together) because you are thinking carefully, or because you are angry or worried:', 'He knitted his brow in concentration.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5925, 'knock ''em dead!', 'used to tell someone to perform or play as well as possible', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5926, 'knock (some) sense into someone', 'to forcefully teach someone not to be silly:', 'A couple of years in the army will knock some sense into him.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5927, 'knock around', 'to spend time relaxing and doing very little:', 'I spent the weekend just knocking around the house.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5928, 'knock around', 'to spend a lot of time with someone:', 'I used to knock around with him at school.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5929, 'knock around (something)', 'to be in a place that is not exactly known or in various places especially over a long period of time:', 'I''m sure I''ve got a copy of "Lolita" knocking around somewhere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5930, 'knock someone around', 'to behave violently towards someone and hit them:', 'Her husband used to knock her around.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5931, 'knock it off', 'used to tell someone to stop doing something that annoys you:', 'Oh, knock it off Alex, I''m really not in the mood for your jokes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5932, 'knock off (something)', 'to stop working, usually at the end of the day:', 'I don''t knock off until six.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5933, 'knock something off (something)', 'to take a particular amount away from a price:', 'The manager knocked $5 off because it was damaged.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5934, 'knock something off', 'to steal something:', 'He has a stack of computer equipment he''s knocked off from various shops.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5935, 'knock something off', 'to produce something quickly and easily:', 'She can knock off (= write) a novel in a couple of weeks.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5936, 'knock someone off', 'to murder someone:', 'He hired a hitman to knock off a business rival.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5937, 'knock someone off', 'to have sex with someone', '', 'phrasal verb', '', 'offensive, old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5938, 'knock on wood', 'said in order to avoid bad luck, either when you mention good luck that you have had in the past or when you mention hopes you have for the future:', 'The deal will be agreed on Wednesday, knock on wood.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5939, 'knock sb/sth out of the park', 'to do something much better than someone else, or to be much better than someone or something else:', 'Hotel Ferrero knocks everyone out of the park with their breakfast.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5940, 'knock sth out of the park', 'to do something extremely well:', 'I feel like I can write anything for this actor, and she''ll knock it out of the park.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5941, 'knock someone back (something)', 'to cost someone a large amount of money:', 'I bet that computer knocked you back several hundred.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5942, 'knock back (something)', 'to quickly drink something, especially a lot of alcohol:', 'She was knocking back the champagne at Maria''s party.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5943, 'knock someone down', 'to hit someone with a vehicle and injure or kill them:', 'She was knocked down by a bus.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5944, 'knock someone/something down', 'to cause someone or something to fall to the ground by hitting him, her, or it', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5945, 'knock someone/something down', 'to reduce a price, or to persuade someone to reduce the price of something they are selling:', 'She wanted $200 but I knocked her down to $175.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5946, 'knock something down', 'to destroy a building or part of a building:', 'There are plans to knock the library down and replace it with a hotel complex.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5947, 'knock something down', 'to show that what someone has said is not true :', 'She easily knocked down every argument he put up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5948, 'knock someone off their pedestal', 'to show people that someone is not as perfect as they seem to be:', 'This recent scandal has really knocked the president off his pedestal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5949, 'knock someone out', 'to hit someone so that they become unconscious:', 'His opponent knocked him out with one punch.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5950, 'knock someone out', 'If a drug or alcohol knocks you out, it makes you go to sleep:', 'The sleeping tablets knocked him out for 18 hours.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5951, 'knock someone out', 'to defeat a person or a team in a competition so that they can no longer take part in it:', 'The champion was unexpectedly knocked out (of the tournament) in the first round.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5952, 'knock someone out', 'to cause enjoyment or admiration in someone:', 'We were all really knocked out by the film.', 'phrasal verb', '', 'old-fashioned, slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5953, 'knock yourself out', 'to make yourself unconscious, usually by hitting your head:', 'She hit her head on the ceiling and knocked herself out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5954, 'knock yourself out', 'to make yourself ill with tiredness:', 'If you carry on working like this, you''ll knock yourself out.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5955, 'knock something out', 'to produce something quickly without spending time thinking about the details:', 'I''ve knocked out a first draft of the report that we can amend at a later date.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5956, 'knock something out', 'If something such as a piece of equipment is knocked out by something else, it stops working or is damaged or destroyed:', 'The surge in the power supply knocked out all the computers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5957, 'knock someone over', 'to hit someone with a vehicle and injure or kill them:', 'She got knocked over by a taxi as she ran for the bus.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5958, 'knock something over', 'to steal something', '', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5959, 'knock someone sideways/for six', 'to shock or upset someone very much, or to make someone very ill:', 'That flu really knocked me sideways.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5960, 'knock someone''s block off', 'If you say that you will knock someone''s block off, you are threatening to hit them very hard, especially on the head:', 'I''ll knock his block off if he tries anything with me!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5961, 'knock something into a cocked hat', 'to be much better than something else:', 'a show that knocks all the others into a cocked hat', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5962, 'knock something on the head', 'to prevent something from happening, or to finally finish something:', 'It''s nearly done - another couple of hours should knock it on the head.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5963, 'knock something out of someone', 'If a quality is knocked out of someone, they lose that quality because the situation they are in does not allow it to exist:', 'Any creativity I had was soon knocked out of me at school.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5964, 'knock something together/up', 'to make something quickly and without much care:', 'I could knock together a quick lunch if you like.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5965, 'knock spots off something', 'to be much better than something or someone else:', 'It knocks spots off that restaurant in Cotswold Street.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5966, 'knock sth from sth', 'to make the value of something go down by a particular amount:', 'A warning of significant losses knocked 10p from the group''s shares.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5967, 'knock the bottom out of something', 'to damage something severely, especially by destroying its support:', 'The rise in mortgage rates really knocked the bottom out of the housing market.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5968, 'knock up', 'Players knock up before beginning a game of tennis or similar sport by hitting the ball to each other:', 'The players have a couple of minutes to knock up before the match starts.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5969, 'knock someone up', 'to wake someone up by knocking on the door of their house or bedroom:', 'I''m sorry to have to knock you up in the middle of the night.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5970, 'knock someone up', 'to make a woman pregnant:', 'You don''t want to get knocked up by some guy you hardly know.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5971, 'knock, knock!', 'a way of describing the sound made when you hit a door. It is sometimes used as the first line of a joke.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5972, 'knock/lick something/someone into shape', 'to take action to get something or someone into the good condition that you would like:', 'to knock the economy into shape
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5973, 'knock/take the stuffing out of someone/something', 'to make someone or something become very weak:', 'Her illness has really knocked the stuffing out of her.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5974, 'knock/throw someone for a loop', 'If something that happens knocks you for a loop, it upsets or confuses you because you do not expect it:', 'He knocked me for a loop when he said he was quitting his job.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5975, 'know a hawk from a handsaw', 'to understand important differences or facts relating to a subject:', 'The referee clearly doesn''t know a hawk from a handsaw.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5976, 'know all the answers', 'If someone knows all the answers, they think they know much more than other people.', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5977, 'know all there is to know about something', 'to know a lot about a subject or activity, or be very good at it', '', 'idiom', '', 'approving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5978, 'know best', 'to be the most suitable person to have responsibility and make important decisions:', 'When it comes to dealing with my own son, I think I know best.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5979, 'know better (than someone)', 'to know more than someone else because you have more experience and more skill:', 'They thought the painting was a fake, but Shackleton knew better.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5980, 'know better (than to do something)', 'to be wise or moral enough not to do something:', 'Sure, she''s only six, but she''s old enough to know better than to run off without us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5981, 'know full well', 'to know something without a doubt:', 'You know full well that you’re not supposed to take the car without asking me!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5982, 'know of someone/something', 'to have heard of someone or something and be able to give a small amount of information about him, her, or it:', 'Do you know of a good doctor?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5983, 'know something back to front', 'to have very good and detailed knowledge of something:', 'She knows her part in the play back to front.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5984, 'know something from something', 'to know the difference between two things and therefore be able to recognize either, used especially to mean that you have a good knowledge and understanding of a particular subject:', 'Computer expert? He doesn''t know a mouse from a modem! (= He knows nothing about computers.)', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5985, 'know something inside out', 'to know everything about a subject:', 'He knows the system inside out.', 'idiom', 'C1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5986, 'know something like the back of your hand', 'to have very good and detailed knowledge of something:', 'I know this area like the back of my hand.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5987, 'know something like the back of your hand', 'to know a place very well:', 'She’ll give you the name of a place to stay – she knows the area like the back of her hand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5988, 'know the score', 'to know all the important facts in a situation, especially the unpleasant ones:', 'You know the score - no payment till after the article is published.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5989, 'know what it is (like) to', 'to be familiar with how it feels to be or do something:', 'She knows what it''s like to go bankrupt - it happened to her 20 years ago.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5990, 'know what you are doing', 'to have the skills and knowledge to do something effectively:', 'You don''t need to tell me - I know what I''m doing!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5991, 'know what you are talking about', 'to understand a subject because of your experience:', 'He doesn''t know what he''s talking about - he''s never even been to Africa.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5992, 'know what''s what', 'If you know what''s what, you have a lot of experience and can judge people and situations well:', 'Linda''s been in the business for 30 years - she knows what''s what.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5993, 'know when you are well off', 'If you do not know when you are well off, you do not understand that your present situation is good compared with other people''s or with what it might be like:', 'She''s always complaining about her car - she doesn''t know when she''s well off (= she''s lucky to have a car even if it''s bad)!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5994, 'know where you stand', 'to know what your opinion or situation is:', 'I know where I stand on this issue - I''m against the war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5995, 'know which side your bread is buttered (on)', 'to know who to be nice to and what to do in order to get an advantage for yourself', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5996, 'know your own mind', 'to be certain about what you believe or want', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5997, 'know your place', 'to accept your position within society, an organization, your family, etc. and to not want to improve it:', 'I just get on with my job and do as I''m told - I know my place.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5998, 'know your stuff', 'to have good practical skills and knowledge in a particular activity or subject', '', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (5999, 'know your way around something', 'to be familiar with a place or organization and able to act effectively within it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6000, 'know/see where someone is coming from', 'If you say to someone you know or see where they are coming from, you mean you understand why that person has a particular opinion, often although you do not have that opinion:', 'I would''ve taken the dog to the vet, but I could see where they were coming from.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6001, 'knuckle down', 'to start working or studying hard:', 'You''re going to have to really knuckle down (to your work) if you want to pass your final exams.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6002, 'knuckle under', 'to accept someone''s power over you and do what they tell you to do', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6003, 'labor of love', 'a piece of hard work that you do because you enjoy it and not because you will receive money or praise for it, or because you need to do it:', 'He''s always working on his car - it''s a labor of love.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6004, 'labor the point', 'to try too hard to express an idea, feeling, or opinion, repeating it when this is not necessary:', 'Look, there''s no need to labor the point - I made a mistake - I admit it!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6005, 'labor under the delusion, illusion, misapprehension, etc.', 'to wrongly believe that something is true:', 'At the time I was still laboring under the delusion that the project might be a success.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6006, 'labour of love', 'a piece of hard work that you do because you enjoy it and not because you will receive money or praise for it, or because you need to do it:', 'He''s always working on his car - it''s a labour of love.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6007, 'labour the point', 'to try too hard to express an idea, feeling, or opinion, repeating it when this is not necessary:', 'Look, there''s no need to labour the point - I made a mistake - I admit it!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6008, 'labour under the delusion, illusion, misapprehension, etc.', 'to wrongly believe that something is true:', 'At the time I was still labouring under the delusion that the project might be a success.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6009, 'lace something up', 'to fasten shoes, boots, or a piece of clothing by tying the laces:', 'She can lace up her shoes and she''s only five!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6010, 'lack direction', 'to not know what you really want to do:', 'She seems to lack direction in her life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6011, 'ladle something out', 'to give money or goods in a (too) generous way to a lot of people:', 'In those days doctors ladled out antibiotics to patients.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6012, 'land of milk and honey', 'a country where living conditions are good and people have the opportunity to make a lot of money:', 'Many Mexicans regard the United States as a land of milk and honey.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6013, 'land on your feet', 'to be successful or lucky, especially after a period of not having success or luck:', 'Don''t worry - she always lands on her feet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6014, 'land someone in something', 'to cause someone to be in a difficult situation:', 'Revealing confidential information to a rival company could land you in serious trouble with your boss.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6015, 'land someone with something', 'If someone or something lands you with something, he, she, or it causes problems for you:', 'I hope you don''t mind me landing you with the kids at such short notice.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6016, 'land up', 'to finally be in a particular place, state, or situation, especially without having planned it:', 'When we accepted that ride in Paris, we never expected to land up in Athens.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6017, 'lap something up', 'to enjoy something very much:', 'We walked around the city, lapping up the atmosphere.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6018, 'lapse into something', 'to start speaking or behaving in a less active or acceptable way:', 'No one could think of anything more to say, and the meeting lapsed into silence.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6019, 'lapse into something', 'to gradually get into a worse state or condition:', 'He lapsed into a coma and died four days later.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6020, 'lard something with something', 'If speech or a piece of writing is larded with a particular type of language, it has a lot of that type of language:', 'Her speech was larded with literary quotations.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6021, 'large/small-scale', 'A large/small-scale event or activity is large/small in size:', 'a large-scale investigation', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6022, 'larger than life', 'If someone is larger than life, that person attracts a lot of attention because they are more exciting or interesting than most people:', 'Most characters in his movies are somewhat larger than life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6023, 'lark around', 'to behave in a silly way because you think it is funny:', 'I was woken up by a couple of drunks larking around in the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6024, 'lash out (something)', 'to spend a large amount of money in a way that is unnecessary or that wastes it:', 'He lashed out £5,000 on his daughter''s wedding.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6025, 'lash out', 'to suddenly attack someone or something physically or criticize him, her, or it in an angry way:', 'I was only teasing him and suddenly he lashed out (at me) and hit me in the face.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6026, 'last but not least', 'importantly, despite being mentioned after everyone else:', 'I would like to thank my publisher, my editor, and, last but not least, my husband.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6027, 'last out', 'to manage to stay alive:', 'How long can they last out without food?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6028, 'last resort', 'the only choice that remains after all others have been tried:', 'As a last resort, we could ask your mother to help.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6029, 'latch on', 'to begin to understand something:', 'It took me ages to latch on to what she was talking about.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6030, 'latch onto something', 'to become connected to something:', 'The antibodies work by latching onto proteins on the surfaces of the viruses and bacteria.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6031, 'latch onto something', 'to become interested in an idea, story, or activity, and to start to use it:', 'Unfortunately the press have already latched onto the story.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6032, 'latch onto someone', 'to stay close to someone or spend a lot of time with someone, usually when they do not want you near:', 'She latched onto me as soon as she arrived, and I had to spend the rest of the evening talking to her.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6033, 'late in the day', 'too late to be useful:', 'It''s too late in the day to start studying - your final exams are next week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6034, 'laugh at someone/something', 'to show that you think someone or something is stupid:', 'I can''t go into work looking like this - everyone will laugh at me.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6035, 'laugh at someone/something', 'to treat someone or something as if he, she, or it is not important or does not deserve serious attention:', 'If you say that, people will just laugh at you.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6036, 'laugh in someone''s face', 'to make it obvious to someone that you do not respect them:', 'They''d laugh in your face if you suggested me for the post.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6037, 'laugh like a drain', 'to laugh a lot, very loudly', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6038, 'laugh out of the other side of your mouth', 'used to tell someone that, despite being pleased now, they will not be pleased later when things do not happen as expected or planned:', 'She''s pleased with her promotion but she''ll laugh out of the other side of her mouth when she sees the extra work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6039, 'laugh something off', 'to make yourself laugh about something unpleasant in order to make it seem less important or serious:', 'She tried to laugh off their remarks, but I could see she was hurt.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6040, 'laugh up your sleeve', 'to secretly find something funny:', 'They''re very polite in your presence, but you get the feeling they''re laughing up their sleeves.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6041, 'laugh your head off', 'to laugh a lot, loudly:', 'You laughed your head off when I fell!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6042, 'laugh, shout, scream, etc. your head off', 'to laugh, shout, scream, etc. very noisily and for a long time:', 'There I was lying face down on the pavement and you two were laughing your heads off!', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6043, 'laughter is the best medicine', 'said to mean that trying to be happy is a good way to stop worrying', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6044, 'launch into something', 'to start saying something or criticizing something with a lot of energy or anger:', 'He launched into a verbal attack on her handling of the finances.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6045, 'lavish something on someone/something', 'to give someone a lot, or too much, of something such as money, presents, or attention:', 'She lavishes money on her grandchildren.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6046, 'lawyer up', 'to employ a lawyer to help you when you are in a situation that may involve you being charged with (= officially accused of) a crime:', 'He hasn''t even lawyered up, and thinks he can represent himself in court and take custody of the kids.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6047, 'lay a finger on someone', 'to harm someone even slightly:', 'Don''t you dare lay a finger on me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6048, 'lay a hand on someone', 'to harm someone:', 'I never laid a hand on her!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6049, 'lay bare something', 'to make something known:', 'It''s been promoted as the biography that lays bare the truth behind the legend.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6050, 'lay down the law', 'to forcefully make known what you think should happen:', 'She can''t just come into this office and start laying down the law.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6051, 'lay down your life', 'to die:', 'I hope you will never be asked to lay down your lives for your principles.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6052, 'lay down your life for something', 'to die for something you believe in strongly:', 'Today we remember those who laid down their lives for their country.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6053, 'lay into someone', 'to attack someone physically, or to criticize someone in an angry way:', 'In the middle of the meeting she suddenly laid into him for no apparent reason.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6054, 'lay it on a bit thick', 'to praise someone too much:', 'She went on and on about how she admired his work - laid it on a bit thick, if you ask me.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6055, 'lay out (sth) for/on sth', 'to spend money, especially a large amount:', 'It''s not every day you lay out so much for a new computer system.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6056, 'lay someone low', 'to cause someone to be unable to do what they usually do:', 'A kidney infection laid her low for a couple of months.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6057, 'lay someone off', 'to stop employing someone, usually because there is no work for them to do:', 'Because of falling orders, the company has been forced to lay off several hundred workers.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6058, 'lay off (something/someone)', 'to stop using or doing something:', 'You''d better lay off alcohol for a while.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6059, 'lay something off', 'in football , to kick the ball gently into a space so that another player from your team can run forward into the space, then move forward with the ball or shoot towards the goal without slowing down or stopping:', 'Quinn laid off the ball for Kinsella to score.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6060, 'lay someone open', 'to put someone in a position where there is risk or danger, esp. of criticism:', 'The Senator''s remarks were unkind and laid him open to criticism.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6061, 'lay someone to rest', 'to bury a dead person:', 'She was laid to rest next to her husband.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6062, 'lay something to rest', 'to end a worry or fear:', 'I hope what he said has laid your fears to rest.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6063, 'lay someone up', 'to force someone to stay in bed:', 'She''s been laid up with the flu for over a week.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6064, 'lay something (to) waste', 'to completely destroy something:', 'The bomb laid the city centre to waste.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6065, 'lay something aside', 'to stop doing or thinking about something, usually for a short period of time:', 'He''s temporarily laid aside some quite interesting projects to write the script.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6066, 'lay something aside', 'to keep something, usually money, for use in the future:', 'She''s trying to lay something aside (= save some money) for her retirement.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6067, 'lay something at someone''s door', 'to blame someone for something:', 'Blame for the accident has been laid at the government''s door.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6068, 'lay something down', 'to store wine for drinking in the future', '', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6069, 'lay something down', 'If you lay down your weapons, you stop fighting:', 'They laid down their weapons and surrendered.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6070, 'lay something down', 'to officially establish a rule, or to officially say how something should be done:', 'This is in line with the policy laid down by the management.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6071, 'lay something in', 'to get a supply of something because you will probably need it in the future:', 'We''d better lay in plenty of food in case we''re cut off when it snows.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6072, 'lay something on', 'to provide something for a group of people:', 'They lay on free entertainment at the club every day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6073, 'lay something on', 'to tell someone something they did not know:', 'I hate to be the one to lay this on you, but your girlfriend has just left with another guy.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6074, 'lay something on the line', 'to risk harm to something:', 'I''d be laying my career/life on the line by giving you that information.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6075, 'lay something on the line', 'to say very clearly that something is the case:', 'You''re just going to have to lay it on the line and tell her that her work''s not good enough.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6076, 'lay something out', 'to arrange something on a flat surface:', 'Most of Manhattan is laid out in/on a grid pattern.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6077, 'lay something out', 'to spend money, especially a large amount:', 'It''s not every day you lay out $500 on a dress.', 'phrasal verb', 'C2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6078, 'lay something out', 'to explain something clearly, usually in writing:', 'The code of practice lays out very clearly what the duties of the registrar are.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6079, 'lay someone out', 'to prepare a dead person''s body to be buried', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6080, 'lay someone out', 'to hit someone so hard that they fall down and become unconscious:', 'Harrison was laid out for several minutes by a blow to the head.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6081, 'lay the basis/foundations for something', 'to prepare for or start an activity or task:', 'The initial negotiations are seen as laying the basis for more detailed talks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6082, 'lay the foundation(s) of/for', 'to produce the basic ideas or structures from which something much larger develops:', 'The two leaders have laid the foundations of a new era in cooperation between their countries.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6083, 'lay the ghost of something (to rest)', 'to finally stop being worried or upset about something that has worried or upset you for a long time:', 'With one stunning performance, he has laid to rest the ghost of all his defeats last season.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6084, 'lay up trouble for yourself', 'to do something that will cause you trouble in the future:', 'You''re laying up trouble for yourself if you ignore health problems now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6085, 'lay your cards on the table', 'to be honest and not hide what you are thinking or doing:', 'I''m going to lay my cards on the table here, and say that I don''t know what to do.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6086, 'lay yourself open to attack, criticism, ridicule, etc.', 'to make it easy for people to attack you, etc.:', 'She lays herself open to criticism with such unashamedly extreme views.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6087, 'lay yourself open to ridicule', 'to make it easy for people to laugh unkindly at you:', 'You lay yourself open to ridicule wearing clothes like that.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6088, 'lead off', 'to begin to speak, usually as the first person to speak:', 'I want to lead off by thanking everyone for coming.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6089, 'lead someone a (merry) dance', 'to cause someone a lot of trouble, especially by getting them to do a lot of things that are not necessary', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6090, 'lead someone by the nose', 'to control someone and make them do exactly what you want', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6091, 'lead someone on', 'to persuade someone to believe something that is untrue:', 'All that time she''d been leading him on (= pretending she liked him), but she was only interested in his money.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6092, 'lead someone up the garden path', 'to deceive someone:', 'It seems as if we''ve been led up the garden path about the position of our hotel - it''s miles from the beach!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6093, 'lead the field/pack/world', 'to be better than all other people or things:', 'Their scientists lead the world in nutrition research.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6094, 'lead the way', 'to be the best:', 'The company leads the way in developing new software.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6095, 'lead the way (somewhere)', 'to go first to show someone how to go somewhere:', 'We all walked down toward the beach with the kids leading the way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6096, 'lead to something', 'If an action or event leads to something, it causes that thing to happen or exist:', 'Reducing speed limits should lead to fewer deaths on the roads.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6097, 'lead up to something', 'If a period of time or series of events leads up to an event or activity, it happens until that event or activity begins:', 'The pilot had no recollection of the events leading up to the crash.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6098, 'lead up to something', 'to prepare to talk about something by gradually mentioning the subject you want to talk about:', 'He started telling me about a wonderful new restaurant he''d been to and I wondered what he was leading up to.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6099, 'lead with something', 'to put a particular story first or in the most important position in a news report or newspaper:', 'The Times leads with the coming mayoral elections.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6100, 'lead/live the life of Riley', 'to live an easy and comfortable life, without any need to work hard', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6101, 'leaf through something', 'to quickly turn the pages of a book or a magazine, reading only a little of it:', 'The waiting room was full of people leafing through magazines.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6102, 'leak like a sieve', 'to leak a lot', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6103, 'lean (something) against/on something', 'to sit or stand with part of your body touching something as a support:', 'He leaned against the wall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6104, 'lean something against/on something', 'to put something against a wall or other surface so that it is supported:', 'She leaned the brush against the wall.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6105, 'lean and hungry', 'showing a very strong and determined wish to get something:', 'He''s got that lean and hungry look.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6106, 'lean on someone/something', 'to use someone or something to help you, especially in a difficult situation:', 'He''s always had his big brother to lean on.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6107, 'lean on someone', 'to try to make someone do what you want by threatening or persuading them:', 'We may have to lean on them a little if we want our money.', 'phrasal verb', 'C2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6108, 'lean toward sth', 'to be interested in something and be likely to do a particular activity:', 'He said he was leaning toward entering the race for governor.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6109, 'lean towards sth', 'to be interested in something and be likely to do a particular activity:', 'She''s not sure what she wants to do, but she''s leaning towards medicine.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6110, 'leap at something', 'to eagerly accept the chance to do or have something:', 'When I offered her the job, she leapt at it.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6111, 'leap out at someone', 'If something leaps out at you, you notice it immediately:', 'As I turned the page his picture leapt out at me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6112, 'learn a/your lesson', 'to suffer a bad experience and know not to do it again:', 'I got horribly drunk once at college and that was enough - I learned my lesson.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6113, 'learn something by rote', 'to learn something in order to be able to repeat it from memory, rather than in order to understand it:', 'She learned the equations by rote.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6114, 'learn something the hard way', 'to discover what you need to know through experience or by making mistakes:', 'He doesn’t want to take my advice, so I guess he''ll have to learn the hard way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6115, 'learn to live with something', 'to accept a new but unpleasant situation that you cannot change:', 'It''s hard not having him around but I''ve learned to live with it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6116, 'learn/know the ropes', 'to learn/know how to do a job or activity', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6117, 'lease sth back (to sb)', 'to sell property or an asset, but continue to use it by paying rent to the new owner:', 'The company may try to raise cash by selling and leasing back its buildings in London and Hong Kong.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6118, 'lease sth back (to sb)', 'to buy property or an asset, and allow the seller to continue to use it by paying you rent:', 'The fund aims to buy the ground''s freehold and lease it back to the club for a pound a year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6119, 'least of all', 'especially not:', 'No one believed her, least of all me .', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6120, 'least said soonest mended', 'used to say that a bad situation can be quickly forgotten if people stop talking about it', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6121, 'leave a bad taste in someone''s mouth', 'If an experience leaves a bad taste in your mouth, you have an unpleasant memory of it:', 'I think we all felt he''d been treated very unfairly and it left a bad taste in our mouths.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6122, 'leave a lot to be desired', 'to be much worse than you would like:', 'Apparently, Meg''s cooking leaves a lot to be desired.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6123, 'leave behind sth; leave sth behind', 'to cause a situation to exist, especially a bad one, after you have gone:', 'The army left a trail of destruction behind them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6124, 'leave behind sth; leave sth behind', 'to be more succesful than someone you are competing with:', 'Three years later, the company had left all its close rivals far behind.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6125, 'leave go/hold of something', 'to stop holding on to something:', 'Leave go of my arm!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6126, 'leave it at that', 'to agree that there has been enough discussion, study, etc. and that it is time to stop:', 'Let''s leave it at that for today and meet again tomorrow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6127, 'leave it out!', 'stop doing or saying that:', 'Hey, leave it out! That hurt!', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6128, 'leave it out!', 'I do not believe you:', '"I tell you, he was driving a sports car." "Leave it out!"', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6129, 'leave no stone unturned', 'to do everything you can to achieve a good result, especially when looking for something:', 'He left no stone unturned in his search for his natural mother.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6130, 'leave someone be', 'to not worry someone, or to allow someone to continue what they are doing:', 'She''s only playing - leave her be.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6131, 'leave someone cold', 'to not make you feel interested or excited:', 'I''m afraid opera leaves me cold.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6132, 'leave someone hanging', 'to keep someone waiting for your decision or answer:', 'I was left hanging, not knowing whether I''d got the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6133, 'leave someone high and dry', 'to do something that is not at all convenient for someone and puts them in a very difficult situation:', 'They pulled out of the deal at the last minute leaving us high and dry.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6134, 'leave someone in the lurch', 'to leave someone at a time when they need you to stay and help', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6135, 'leave someone out in the cold', 'to not allow someone to become part of a group or an activity', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6136, 'leave someone standing', 'to be much better than other people or things of the same type:', 'Her voice is excellent - it leaves the others standing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6137, 'leave someone to their own devices', 'to allow someone to make their own decisions about what to do:', 'He seemed to be a responsible person, so I left him to his own devices.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6138, 'leave someone/something alone', 'to not annoy, change, or touch someone or something:', 'The Federal Reserve is leaving interest rates alone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6139, 'leave someone/something in the dust', 'to easily defeat or be much better than someone or something:', 'She could leave every other runner in the dust.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6140, 'leave someone/something in the dust', 'to leave someone alone without helping or caring for them:', 'He left another woman in the dust and he''ll do the same to you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6141, 'leave someone/something out', 'to not include someone or something:', 'You can leave the butter out of this recipe if you''re on a low-fat diet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6142, 'leave something aside', 'to not discuss one subject so that you can discuss a different subject:', 'Leaving aside the question of cost, how many people do we need on the job?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6143, 'leave something at the door', 'to intentionally not allow something to influence you or to be expressed in a particular situation:', 'His reports were all reviewed by a committee; he had to leave his ego at the door.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6144, 'leave something for/to someone', 'to give someone responsibility for dealing with something:', 'I''ve left the paperwork for you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6145, 'leave something in your wake', 'to go somewhere new, leaving problems, confusion, etc. behind you, that you have caused:', 'Soldiers rampaged through the town, leaving chaos in their wake.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6146, 'leave something/someone behind', 'to leave a place without taking someone or something with you:', 'We left in a hurry and I must have left my keys behind.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6147, 'leave something behind', 'to cause a situation to exist after you have left a place:', 'The army left a trail of destruction behind it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6148, 'leave something/someone off something', 'to not include something or someone on a list:', 'He left three people off the list by mistake.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6149, 'leave off (something/doing something)', 'to stop, or to stop doing something:', 'This novel begins where the other one leaves off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6150, 'leave off!', 'used to tell someone to stop being annoying:', 'Hey, leave off! I hate people touching my hair.', 'phrasal verb', '', 'old-fashioned, informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6151, 'leave the field open for someone', 'to stop competing with someone, making it possible for them to succeed:', 'John decided not to apply for the job, which left the field open for Emma.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6152, 'leave well alone', 'to allow something to stay as it is because doing more might make things worse:', 'It''s going to get in a muddle if you carry on. I should just leave well alone if I were you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6153, 'leave well enough alone', 'to allow something to stay as it is because doing more might make things worse:', 'I could rewrite it, but I decided to leave well enough alone.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6154, 'leave your mark', 'to have an effect that changes someone or something:', 'The heart attack left its mark on him, and he was never quite the same after it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6155, 'leave your/its mark on someone/something', 'to have an effect that changes someone or something, usually in a bad way:', 'The experience had left its mark on her.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6156, 'leave, go off, etc. with your tail between your legs', 'to leave, feeling ashamed and embarrassed because you have failed or made a mistake:', 'The losing team went off with their tails between their legs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6157, 'lech after someone', 'to show too much sexual interest in someone:', 'He''s always leching after younger women.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6158, 'leg before wicket', 'in the game of cricket, the situation in which your time as the person trying to hit the ball is ended because the ball has hit your leg when it should not have', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6159, 'lend an ear', 'to listen to someone with sympathy:', 'Claire''s always one to lend a sympathetic ear if you have problems.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6160, 'lend itself to something', 'fmlto be good for a particular use:', 'The book really lends itself to being turned into a film.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6161, 'lend your name to something', 'to give something your support:', 'Some of the world''s top dancers have lent their names to the project.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6162, 'less and less', 'gradually less or smaller:', 'I seem to see her less and less.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6163, 'let alone do something', 'and to an even greater degree do something:', 'Brian would never even read a newspaper, let alone a book.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6164, 'let someone/something alone', 'to not annoy or interrupt someone:', 'Just let her alone – she’s not bothering you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6165, 'let go', 'to stop holding something:', 'Hold on tight and don''t let go!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6166, 'let go', 'to stop thinking about or being angry about the past or something that happened in the past:', 'She finds it hard to let go of a grudge.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6167, 'let someone go', 'to allow someone to be free:', 'He pleaded with them to let him go.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6168, 'let someone go', 'to make someone leave their job:', 'The firm hired the staff to sell the stocks, then let most of them go only a few months after the crash.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6169, 'let yourself go', 'to allow yourself to become less attractive or healthy:', 'It''s easy to let yourself go when you''ve got small kids.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6170, 'let yourself go', 'to relax completely and enjoy yourself:', 'It''s a party - let yourself go!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6171, 'let something go', 'to stop taking care of something such as a house or garden:', 'The house was beautiful, but the new owners have just let it go.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6172, 'let go (of something/someone)', 'to stop holding something or someone:', 'Brandon let go of her hand and ran across the street.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6173, 'let it all hang out', 'to behave freely without being shy or feeling worried about what other people will think of you', '', 'idiom', '', 'old-fashioned, slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6174, 'let it be known', 'to make certain that people know something:', 'I let it be known that I was not happy about the decision that had been made.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6175, 'let it lie', 'to take no action about something:', 'Instead of going to the police they let things lie for a couple of months.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6176, 'let me see/let''s see', 'used when you want to think for a moment about something:', '"Is there a shop that sells sports clothes?" "Let me see - I think there''s one near here."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6177, 'let nature take its course', 'to allow someone or something to live or die naturally:', 'He could be kept alive artificially, but I think it would be kinder to let nature take its course.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6178, 'let off steam', 'to do or say something that helps you to get rid of strong feelings or energy:', 'She jogs after work to let off steam.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6179, 'let on', 'to tell other people about something that you know, especially when it is a secret:', 'I suspect he knows more than he''s letting on.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6180, 'let rip/fly', 'to behave in an angry and emotional way:', 'She let rip about the state of the kitchen.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6181, 'let sleeping dogs lie', 'said to warn someone that they should not talk about a bad situation that most people have forgotten about', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6182, 'let someone be', 'to stop criticizing or annoying someone:', 'Just let her alone – she’s not bothering you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6183, 'let someone down', 'to disappoint someone by failing to do what you agreed to do or were expected to do:', 'You will be there tomorrow - you won''t let me down, will you?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6184, 'let something down', 'If you let down a piece of clothing, you make it longer:', 'My trousers shrank in the wash so I let them down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6185, 'let something down', 'If you let down something filled with air, you cause the air to go out of it:', 'Someone let my tyres down while I was at the gym.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6186, 'let someone have both barrels', 'to attack, criticize, or punish someone very forcefully:', 'He arrived late to meet his girlfriend at the airport. She gave him both barrels.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6187, 'let someone have it', 'to attack someone with words or physically', '', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6188, 'let someone in on a secret', 'to allow someone to know something that you have not told anyone else:', 'Can I let you in on a little secret?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6189, 'let someone in on something', 'to tell someone about something that is secret, or to allow someone to become involved in something that only very few people are involved in:', 'Debbie agreed to let me in on her plans.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6190, 'let someone know', 'to tell someone something:', 'Let us know when you get there.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6191, 'let someone loose', 'to allow someone to do what they want in a place:', 'You don''t want to let Oliver loose in the kitchen.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6192, 'let loose something', 'If you let loose something such as bullets or bombs, you release a lot of them all together:', 'The allies let loose an intensive artillery bombardment over the border.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6193, 'let loose something', 'to suddenly make a sound or speak in an uncontrolled way:', 'He turned around and let loose a torrent of abuse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6194, 'let someone off', 'to not punish someone who has committed a crime or done something wrong, or to not punish them severely:', 'Instead of a prison sentence they were let off with a fine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6195, 'let something off', 'to fire a gun, or to make something such as a bomb or fireworks explode:', 'Don''t let off fireworks near the house.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6196, 'let someone/something in', 'to allow someone or something to enter:', 'She opened the door and let me in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6197, 'let someone/something out', 'to allow someone or something to leave a place, especially by opening a closed or locked door:', 'I heard a voice from the cupboard shouting "Let me out!"', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6198, 'let something out', 'to cause something to come out:', 'He let the air out of the balloon.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6199, 'let something out', 'to make a piece of clothing wider by removing the sewing from the sides and sewing closer to the edge of the material:', 'These trousers are too tight - I''m going to have to let them out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6200, 'let out', 'When something that people go to, such as school or a show, lets out, it ends and everyone leaves:', 'When does school let out for the summer?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6201, 'let something be known', 'to make certain that people are aware of a fact:', 'She let it be known that she did not want to run again for Congress.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6202, 'let something go/pass', 'to not correct or argue with something that a person says or does that is wrong:', 'I know what he said wasn''t strictly accurate but I let it pass anyway.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6203, 'let something into something', 'to put something into a flat surface so that it does not stick out:', 'A skylight had been let into the roof.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6204, 'let something rest', 'to not talk about or mention a particular subject:', 'After he had told his friends he was writing a novel, they wouldn''t let the subject rest.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6205, 'let something ride', 'to not take any action to stop something wrong or unpleasant, thinking that action may not be necessary or is not yet necessary:', 'Don''t panic about the low sales - let it ride for a while and see if business picks up.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6206, 'let something slip', 'to tell people about something without intending to:', 'He let it slip that he hadn''t actually read the report.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6207, 'let something/someone slide', 'to not do anything about something or someone when you should try to change or correct that thing or person:', 'I knew he wasn’t telling me everything, but I decided to let it slide.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6208, 'let the cat out of the bag', 'to allow a secret to be known, usually without intending to:', 'I was trying to keep the party a secret, but Mel went and let the cat out of the bag.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6209, 'let the genie out of the bottle', 'to allow something to happen that cannot then be stopped:', 'When I told her the secret, I let the genie out of the bottle.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6210, 'let the side down', 'to behave in a way that embarrasses or disappoints a group of people that you are part of', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6211, 'let up', 'If bad weather or an unpleasant situation lets up, it stops or improves:', 'When the rain lets up we''ll go for a walk.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6212, 'let up', 'to stop doing something that you have been doing continuously or in a determined way:', 'Neil spent the entire evening moaning about his job - he just wouldn''t let up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6213, 'let up on someone/something', 'to stop treating someone severely, or to stop doing something so forcefully:', 'He advised her to let up on the relentless criticism.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6214, 'let your hair down', 'to allow yourself to behave much more freely than usual and enjoy yourself:', 'Oh let your hair down for once!', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6215, 'let yourself in for something', 'to become involved in a difficult or unpleasant situation without intending to:', 'Do you realize how much extra work you''re letting yourself in for?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6216, 'let''s face it', 'something that you say before you say something that is unpleasant but true:', 'Let''s face it, we both know why I stopped working there.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6217, 'let''s face it', 'said before stating something that is unpleasant but true:', 'Let''s face it, we''re not going to win.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6218, 'let''s get this bread', 'used to encourage someone to try hard and be successful:', 'Wake up everyone - let''s get this bread!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6219, 'let''s see', 'used when you want to think carefully about something or are trying to remember:', 'Next Saturday, let''s see, that''s when we''re going to the theatre.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6220, 'let/blow off steam', 'to do or say something that helps you to get rid of strong feelings or energy:', 'He lifts weights after work to let off steam.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6221, 'let/set something loose', 'to allow an animal to run around freely after it has been tied up:', 'She let her horse loose in the field.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6222, 'level (sth) down', 'to become worse or less, or to make something worse or less, so that it is the same as something else:', 'Many schools are being levelled down, rather than improved.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6223, 'level off', 'If a rate or amount levels off, it stops rising or falling and stays at the same level:', 'House prices now seem to be levelling off after the steep rises of the last few years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6224, 'level off/out', 'If an aircraft levels off/out, it starts to travel horizontally rather than going up or down:', 'The jet levelled off at 10, 000 feet.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6225, 'level pegging', 'in an equal position in a competition or game:', 'Both teams are level pegging.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6226, 'level something against/at someone', 'to accuse someone in public of doing something wrong:', 'Criticism has been levelled at senior figures in the industry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6227, 'level something at someone', 'to aim something such as a weapon at someone:', 'She picked up the gun and levelled it at me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6228, 'level sth against sb', 'to accuse someone in public of doing something wrong:', 'Criticism has been levelled at senior figures in the industry.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6229, 'level up', 'to gain enough points in a computer game to enable a player or character to go up to a higher level, gaining more skills or strength', '', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6230, 'level up', 'to go to a higher level or standard:', 'Why not level up to our premium version?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6231, 'level something up', 'to increase or improve something so that it is as good as something else:', 'This approach has levelled standards up across the sector.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6232, 'level something up', '(in computer games) to get more skills, etc. for a character in a game by winning points :', 'Here are all the tips and tricks you need to know on how to level up your characters quickly.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6233, 'level with someone', 'to tell someone the truth about something:', 'I''ll level with you - the salary''s not particularly good, and there''s little chance of promotion.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6234, 'leverage (sth) up', 'to increase the amount of money borrowed:', 'He wanted them to leverage up the company and buy back some stock.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6235, 'lick someone''s boots', 'to try very hard to please someone in authority, usually in order to get an advantage:', 'He needn''t expect me to go licking his boots!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6236, 'lick your lips', 'to move your tongue along your lips:', 'She took a bite of doughnut and licked her lips.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6237, 'lick your lips', 'to feel pleasure at the thought of something:', 'He licked his lips at the thought of all that money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6238, 'lick your wounds', 'to spend time getting back your strength or happiness after a defeat or bad experience', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6239, 'lie ahead (of someone)', 'to be in the future:', 'We don''t know what lies ahead.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6240, 'lie around', 'If things are lying around, they are left in places where they should not be:', 'Has anyone seen my keys lying around?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6241, 'lie around', 'to spend time lying down and doing very little:', 'I spent a week in Spain, lying around on the beach.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6242, 'lie back', 'to move the top half of your body from a sitting to a lying position:', 'She lay back in the dentist''s chair and tried to relax.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6243, 'lie behind something', 'If something lies behind something else, it is the hidden cause of it:', 'Do you know what lies behind their decision?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6244, 'lie doggo', 'to keep still and hide so that you cannot be found', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6245, 'lie down', 'to move into a position in which your body is flat, usually in order to sleep or rest:', 'He lay down on the bed and tried to relax.', 'phrasal verb', 'A2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6246, 'lie down on the job', 'to fail to work as hard or as well as you should', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6247, 'lie in', 'to stay in bed later than usual in the morning:', 'It was a Sunday, so she could lie in till almost lunch time.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6248, 'lie in something', 'to exist or be found in something:', 'His skill lies in his ability to communicate quite complex ideas very simply.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6249, 'lie in wait', 'to hide, ready to attack:', 'The gunmen were lying in wait when Mr Predit came out of the hotel.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6250, 'lie low', 'to try not to be noticed:', 'I''d lie low if I were you till the trouble passes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6251, 'lie through your teeth', 'to tell someone something that you know is completely false:', 'He asked me how old I was and, lying through my teeth, I said "29".', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6252, 'lie up', 'to hide from police officers, soldiers, etc. who are looking for you:', 'The escaped prisoners lay up in a barn for a few weeks, until the search had been called off.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6253, 'life in the fast lane', 'a way of living that is full of excitement, activity, and often danger:', 'Parties and women - he was living life in the fast lane.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6254, 'life is just a bowl of cherries', 'something that you say that means that life is very pleasant. This phrase is often used humorously to mean the opposite.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6255, 'life''s a bitch (and then you die)', 'said when you find a situation difficult or have had a bad experience', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6256, 'light (something) up', 'If your face or eyes light up, or if a smile lights up your face, you suddenly look happy:', 'Rosie''s whole face lit up with excitement when she saw the presents.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6257, 'light (something) up', 'to light a cigarette:', 'I was lighting up when I noticed a "no smoking" sign.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6258, 'light a fire under someone', 'to make someone act quickly or forcefully, especially someone who has not been doing enough before:', 'The coach tried to light a fire under the team in his halftime speech.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6259, 'light and shade', 'different parts of the character of a person or the quality of a thing:', 'The orchestra''s playing brought out the light and shade in the music.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6260, 'light at the end of the tunnel', 'signs of improvement in a situation that has been bad for a long time, or signs that a long and difficult piece of work is almost finished:', 'As finals approached, she felt that at last she could see the light at the end of the tunnel.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6261, 'light on/upon something', 'to find or think of something unexpectedly:', 'We lighted upon the solution entirely by accident.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6262, 'light the touchpaper', 'to make a bad or extreme situation start happening or to make someone react in an angry or extreme way:', 'The president was fearful of lighting a touchpaper that could spark greater unrest.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6263, 'light years away', 'an extremely long time from now in the past or future:', 'It all happened when I was at college, which seems light years away now that I''m over 50.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6264, 'lighten something up', 'to make a speech or piece of writing less serious:', 'I thought I''d slip in a few jokes to lighten up the talk.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6265, 'lighten up', 'to become more relaxed and less serious:', 'Oh, lighten up! I was only joking!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6266, 'lightning never strikes twice', 'said to show that it is unlikely that something bad or unusual will happen to the same person twice', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6267, 'like a boss', 'used to say that someone does something very well:', 'I''m going to teach you to draw like a boss.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6268, 'like a bull in a china shop', 'If someone is like a bull in a china shop, they are very careless in the way that they move or behave:', 'We told her it was a delicate situation but she went into the meeting like a bull in a china shop.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6269, 'like a cat on a hot tin roof', 'used to describe someone who is in a state of extreme nervous worry', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6270, 'like a dog with two tails', 'used to say that someone is very happy about something:', 'Lucy will be like a dog with two tails if she gets into the team.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6271, 'like a dose of salts', 'very quickly:', 'The medicine went through me like a dose of salts.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6272, 'like a lamb to the slaughter', 'If someone does something or goes somewhere like a lamb to the slaughter, they do it without knowing that something bad is going to happen and therefore act calmly and without fighting against the situation.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6273, 'like a man/woman possessed', 'in a wild and uncontrolled way:', 'He''s been running around the office this morning like a man possessed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6274, 'like a maniac', 'If someone works like a maniac, they work extremely hard.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6275, 'like a shag on a rock', 'completely alone', '', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6276, 'like a shot', 'When someone does something like a shot, they do it extremely quickly and enthusiastically:', 'The moment I let go of the dog, she''s off like a shot.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6277, 'like a steel trap', '(of someone''s mind or memory) very sharp and quick to understand or remember things:', 'She is an incredible investigative researcher who has a mind like a steel trap.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6278, 'like a streak of lightning', 'extremely quickly:', 'She grabbed the money and ran out of the shop like a streak of lightning.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6279, 'like a thief in the night', 'secretly or unexpectedly and without being seen', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6280, 'like a ton of bricks', 'very strongly or forcefully:', 'If Dad finds out what you''ve been doing, he''ll come down on (= punish) you like a ton of bricks!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6281, 'like blazes', 'very much or very hard:', 'The wind blew and it was raining like blazes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6282, 'like clockwork', 'very regularly, or at exactly the planned times:', 'Since the recent improvements to the service, the buses are running like clockwork.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6283, 'like crazy', 'If you do something like crazy, you do a lot of it or do it very quickly:', 'They were working like crazy to get the job done on time.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6284, 'like dishwater', 'used to describe a drink or liquid that is unpleasant because it contains too much water and has very little flavour:', 'This soup/tea tastes like dishwater.', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6285, 'like fury', 'with great energy and determination:', 'I''ve been working like fury these past few days to catch up.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6286, 'like gold dust', 'said about something that is very difficult to get because a lot of people want it:', 'Tickets for the concert are like gold dust.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6287, 'like greased lightning', 'very fast:', 'As soon as I mentioned work, he was out of the door like greased lightning!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6288, 'like hell', 'very much:', 'We ran like hell.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6289, 'like hell', 'certainly not:', '"Try to be polite to him." "Like hell I will!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6290, 'like herding cats', 'used to describe something that is extremely difficult to do:', 'He says managing lawyers is like herding cats.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6291, 'like it or lump it', 'If you tell someone to like it or lump it, you mean that person must accept a situation they do not like, because it cannot be changed:', 'Like it or lump it, romantic fiction is read regularly by thousands.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6292, 'like lemmings', 'in a silly way, without thinking, and in large numbers:', 'People rushed like lemmings to invest in the company.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6293, 'like lightning', 'extremely quickly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6294, 'like mad', 'If you do something like mad, you do it very enthusiastically, quickly, or a lot:', 'She''s been saving like mad because she wants to buy a car.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6295, 'like nobody''s business', 'very quickly or very much:', 'He was scribbling away like nobody''s business.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6296, 'like nothing (else) on earth', 'very strange, unusual, or unpleasant:', 'With his make-up and strange clothes, he looked like nothing on earth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6297, 'like nothing on earth', 'very strange, unusual, or unpleasant in appearance, sound, or taste:', 'It looked nice, but it tasted like nothing on earth.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6298, 'like pulling teeth', 'If you say that making someone do something was like pulling teeth, you mean it was very difficult and they did not want to do it:', 'Getting her to tell me about her childhood was like pulling teeth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6299, 'like rats leaving a sinking ship', 'used to refer to people leaving a place, organization, activity, etc. very quickly and in large numbers, because it is failing in some way:', 'Former friends have deserted the couple like rats leaving a sinking ship.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6300, 'like ships that pass in the night', 'If two people are like ships that pass in the night, they meet once or twice by chance for a short time then do not see each other again.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6301, 'like stink', 'If someone works like stink, they work extremely hard.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6302, 'like the cat that ate the canary', 'extremely happy or satisfied, or in a very happy or satisfied way:', 'When he asked her on a date she was like the cat that ate the canary.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6303, 'like the cat that got the cream', 'extremely happy or satisfied, or in a very happy or satisfied way:', 'She looks like the cat that got the cream.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6304, 'like the clappers', 'extremely fast:', 'You''ll have to run like the clappers if you want to catch your train.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6305, 'like the sound of something', 'to feel happy or satisfied about a piece of information you have just heard:', '"The radio says there’ll be rain turning into snow." "Ooh, I don’t like the sound of that."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6306, 'like there is/was no tomorrow', 'If someone does something like there is/was no tomorrow, they do it very fast, in large amounts and without thinking carefully:', 'After he won the lottery, he began spending money like there was no tomorrow.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6307, 'like there’s no tomorrow', 'as much or as fast as possible, without planning or thinking first:', 'The minute he got paid, he started spending money like there’s no tomorrow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6308, 'like two peas in a pod', 'very similar, especially in appearance:', 'The twins are like two peas in a pod.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6309, 'like wildfire', 'quickly in a way that cannot be controlled:', 'News of the layoffs spread like wildfire through the company.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6310, 'like you care!/like you''d know!/like he''d ask!', 'used to emphasize that something that has been suggested is not true or would never happen:', '"Are you OK?" "Like you care!" (= I don''t believe you care whether I''m OK.)
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6311, 'like you owned the place', 'in a way that is too confident:', 'He walked into the office like he owned the place.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6312, 'liken someone/something to someone/something', 'to say that someone is similar to or has the same qualities as someone else:', 'She''s been likened to a young Elizabeth Taylor.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6313, 'limber up', 'to do gentle exercises to stretch the muscles in order to prepare the body for more active physical exercise:', 'The substitutes are beginning to limber up on the sidelines.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6314, 'line (someone) up', 'to arrange people or things in a row or to stand in a row:', 'A fight broke out behind me as we lined up to receive our food rations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6315, 'line something up', 'to prepare, organize, or arrange something:', 'Do you have anything exciting lined up for the weekend?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6316, 'line of sight', 'the direction in which a person must look in order to see a particular object:', 'The cannon can be linked to the line of sight of the gunner so that it points in the same direction that he is looking in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6317, 'line your pocket(s)', 'to earn money using dishonest or illegal methods:', 'Staff at the bank have apparently been lining their pockets with money from investors'' accounts.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6318, 'link (something) up', 'to form a connection, especially in order to work or operate together:', 'The organization''s aim is to link up people from all over the country who are suffering from the disease.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6319, 'listen in on something/someone', 'If you listen in on a conversation or on someone talking, you listen, especially secretly, without saying anything:', 'I wish Dad would stop listening in on my phone conversations.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6320, 'listen out for something', 'to make an effort to hear a noise that you are expecting:', 'Would you listen out for the phone while I''m in the garden?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6321, 'listen to reason', 'to listen to good advice and be influenced by it:', 'Friends tried to persuade them to change their minds, but neither man would listen to reason.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6322, 'listen up', 'something you say to make people listen to you:', 'Okay everyone—listen up! I have an announcement to make.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6323, 'little/small wonder', 'it is not really surprising:', 'Her car isn''t working, so it''s little wonder (that) she hasn''t come to visit you recently.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6324, 'live (from) hand to mouth', 'to have just enough money to live on and nothing extra:', 'My father earned very little and there were four kids, so we lived from hand to mouth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6325, 'live (on) in the memory', 'If something lives (on) in the memory, it has such an effect that it is remembered for a long time.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6326, 'live a lie', 'to live in a way that is dishonest because you are pretending to be something that you are not, to yourself or to other people:', 'She doesn''t know you''re married? You have to stop living a lie and tell her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6327, 'live and breathe something', 'When a person lives and breathes something, it is extremely important to them:', 'He lives and breathes music.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6328, 'live and let live', 'said to mean that people should accept the way other people live and behave, especially if they do things in a different way', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6329, 'live by your wits', 'to make money in a clever and usually dishonest way', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6330, 'live down something', 'to make people forget that you made a big mistake or did something very embarrassing in the past:', 'If you show up with green hair, your parents will never let you live it down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6331, 'live for something/someone', 'to have something or someone as the most important thing in your life:', 'She just lives for music.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6332, 'live high on/off the hog', 'to live in great comfort with a lot of money', '', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6333, 'live in', 'to live at the place where you work or study:', 'The university guarantees accommodation in halls of residence for every first year who wants to live in.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6334, 'live in sin', 'to live with someone that you are having a sexual relationship with but are not married to:', 'Last I heard, they''d moved in together and were living in sin.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6335, 'live it up', 'to have an exciting and very enjoyable time with parties, good food and drink, etc.:', 'He''s alive and well and living it up in the Bahamas.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6336, 'live like a king/lord', 'to have a luxurious (= spending a lot of money) way of life', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6337, 'live off someone/something', 'to use someone or something to provide the money or food that you need to live:', 'All his life he had lived off his father.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6338, 'live off the fat of the land', 'to be rich enough to live well without having to do very much', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6339, 'live on borrowed time', 'to continue living after a point at which you might easily have died:', 'Since his cancer was diagnosed, he feels as if he''s living on borrowed time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6340, 'live on borrowed time', 'to continue to exist longer than expected:', 'It is unlikely that serious decisions will be made by a CEO living on borrowed time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6341, 'live on something', 'If you live on an amount of money, that is the money that you use to buy the things that you need:', 'We lived on very little when we first got married.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6342, 'live on something', 'to only eat a particular type of food:', 'I more or less live on pasta.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6343, 'live out', 'to not live at the place where you work or study:', 'We have a nanny, but she lives out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6344, 'live out something', 'to spend your life or the last period of your life in a particular way:', 'She retired and lived out the rest of her days quietly in the country.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6345, 'live out your dreams/fantasies', 'to do something that you really wanted but did not think was possible:', 'They are living out their show-biz dreams.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6346, 'live through something', 'to experience a difficult situation or event:', 'He could never know the pain and fear this child had lived through.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6347, 'live to fight another day', 'to have another chance to fight in a competition; to be able to continue with your life although you have had a bad experience:', 'We didn''t win this time, but we live to fight another day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6348, 'live to tell the tale', 'to successfully deal with or continue to live despite a difficult situation or experience:', 'We had a horrific journey, but we lived to tell the tale.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6349, 'live together', 'If two people live together, they share a house and have a sexual relationship but are not married:', 'Nowadays many young people live together before they get married.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6350, 'live up to something', 'to be as good as something:', 'The concert was brilliant - it lived up to all our expectations.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6351, 'live with someone', 'to share a home with someone and have a sexual relationship with them although you are not married', '', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6352, 'live with something', 'to accept a difficult or unpleasant situation:', 'I can''t change the situation so I''m going to have to learn to live with it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6353, 'live your own life', 'to spend your life doing what you want, usually because something is no longer stopping you from doing so:', 'Now that the children have left home, I can live my own life again.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6354, 'live/be in clover', 'to enjoy a life of money and comfort:', 'With the income from the family estate, she''s in clover.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6355, 'lived in', 'regularly used and comfortable:', 'I like a room to look lived in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6356, 'liven (something) up', 'to become more interesting and exciting, or to make something become like this:', 'A new coat of paint would liven the kitchen up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6357, 'liven (someone) up', 'to become more energetic or in a better mood, or to make someone feel this way:', 'She was subdued to start with, but after a while she livened up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6358, 'lo and behold', 'something that you say when you tell someone about something surprising that happened:', 'I was in Vienna sitting quietly in a café when, lo and behold, my cousin walked in.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6359, 'load (sth) up with sth', 'to get a lot of money, assets, or debt, or to make someone else get them:', 'Private-equity buyouts aim to load companies up with lots of debt.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6360, 'load (sth) up with sth', 'to put a large amount of goods, materials, etc. onto a vehicle to transport them:', 'Fleets of small ships were loading up with oil in the Gulf.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6361, 'load up on something', 'to gather or buy a large amount of something:', 'The tourists started loading up on perfume and cosmetics.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6362, 'load up something', 'to put things in or on a vehicle:', 'Let’s load up the car and then we can go.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6363, 'loaded down with things', 'carrying or trying to carry a lot of things:', 'She had three children and was loaded down with two heavy suitcases.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6364, 'loads of something', 'infml much or many:', 'There were loads of people standing around a TV set in the store.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6365, 'lock (something) up', 'to lock all the doors and windows of a building when you leave it:', 'Sandra, will you lock up tonight when you go?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6366, 'lock someone up', 'to put someone in a prison or a hospital for people who are mentally ill:', 'Murderers should be locked up for life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6367, 'lock horns', 'to begin to argue or fight:', 'The mayor and her deputy locked horns over plans for the new road.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6368, 'lock someone into something', 'to prevent a person or organization from ending or changing an agreement or financial arrangement:', 'The gas company is locked into long-term supply contracts.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6369, 'lock someone out', 'to prevent someone from entering a building or room by locking the door:', 'He had to break into the house because his girlfriend had locked him out.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6370, 'lock someone out', 'to prevent workers from entering their place of work until they agree to particular conditions given by the employer:', 'Management has threatened to lock out the workforce if they do not accept the proposed changes in working methods.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6371, 'lock someone out', 'to make it impossible for someone to use a computer system, electronic device, etc.:', 'When someone is fired they are immediately locked out of the network.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6372, 'lock someone out of something', 'to prevent a person or organization from having or being able to take part in something:', 'The company risks being locked out of China''s booming car market.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6373, 'lock something away', 'to put something in a safe place and lock the door in order that someone else cannot get it:', 'If you keep valuables in your house, lock them away somewhere safe.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6374, 'lock something in', 'to get and keep an advantage such as a low price:', 'People are jumping to purchase homes and lock in affordable mortgage rates before they increase.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6375, 'lock something in', 'to choose or decide something finally and definitely, for example by pressing a key on a computer keyboard:', 'Press SET again to lock in your choice.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6376, 'lock someone in', 'to prevent someone from leaving a room or building by locking the door:', 'She stormed off to her bedroom and locked herself in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6377, 'lock someone in', 'to prevent someone from ending or changing a financial arrangement:', 'Most cell phone contracts lock you in for a fixed period.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6378, 'lock, stock, and barrel', 'including all or every part of something:', 'We had to move our things lock, stock, and barrel to the other side of the country.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6379, 'log in', 'to connect to a computer system by putting in a particular set of letters or numbers:', 'What is the user name and password that you use to log on?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6380, 'log in/on', 'to connect a computer to a computer system by typing your name, so that you can start working:', 'Log on using your name and password.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6381, 'log off', 'to stop using a computer system or program by giving a particular instruction:', 'The program lets you shut down, restart, or log off Windows at specific times and dates.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6382, 'log off/out', 'to stop a computer being connected to a computer system, usually when you want to stop working:', 'Could you all log off for a few minutes, please?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6383, 'log on', 'to start using a computer system or program by giving a password (= a secret word by which the system recognizes an approved user):', 'About 40,000 gamers have been logging on every day since the website appeared last month.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6384, 'log out', 'to end a connection to a computer system by clicking on a spot on the computer screen:', 'To log off, simply turn off the machine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6385, 'lonely hearts', 'a place or part of a magazine, etc. for people who would like to make new friends or meet a sexual partner', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6386, 'long live someone/something!', 'said to show support for the person or thing mentioned:', 'Long live the president!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6387, 'long on something and short on something', 'having too much of one quality and not enough of another:', 'I''ve always found his movies long on style and short on content.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6388, 'long story short', 'used when you do not tell all the details:', 'Long story short, I got fired.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6389, 'long time no see', 'said when you meet someone who you haven''t seen for a long period of time', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6390, 'look a fright', 'to look ugly or untidy:', 'Didn''t she look a fright in that dress?', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6391, 'look after someone/something', 'to take care of or be in charge of someone or something:', 'We look after the neighbours'' cat while they''re away.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6392, 'look ahead', 'to think about what will happen in the future and plan for these events:', 'We are trying to look ahead and see what our options are.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6393, 'look around (somewhere/something)', 'to visit a place and look at the things in it:', 'She spent the afternoon looking around the town.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6394, 'look at something', 'to think about a subject carefully so that you can make a decision about it:', 'Management is looking at ways of cutting costs.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6395, 'look at something', 'to consider something in a particular way:', 'If I''d had children I might have looked at things differently.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6396, 'look at something', 'to read something in order to check it or form an opinion about it:', 'Can you look at my essay sometime?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6397, 'look at something', 'If someone, usually an expert, looks at something, they examine it:', 'Did you get the doctor to look at your knee?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6398, 'look at/see something through rose-colored/rose-tinted glasses', 'to see only the pleasant things about a situation and not notice the things that are unpleasant:', 'She''s always looked at life through rose-tinted glasses.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6399, 'look at/see something through rose-coloured/rose-tinted glasses', 'to see only the pleasant things about a situation and not notice the things that are unpleasant:', 'She''s always looked at life through rose-tinted glasses.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6400, 'look back', 'to think about something that happened in the past:', 'When I look back I can see where we went wrong.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6401, 'look before you leap', 'to check that something is not going to cause problems or have a bad result before you do it:', 'The general advice with a job offer is to do your research and look before you leap.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6402, 'look daggers at someone', 'to look angrily at someone', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6403, 'look down on someone', 'to think that you are better than someone:', 'She thinks they look down on her because she doesn''t have a job.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6404, 'look forward to something', 'to feel pleased and excited about something that is going to happen:', 'I''m really looking forward to my holiday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6405, 'look forward to something', 'used at the end of a formal letter to say you hope to hear from or see someone soon, or that you expect something from them:', 'I look forward to hearing from you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6406, 'look in', 'to visit a person for a short time, usually when you are on your way somewhere else:', 'I thought I might look in on Bob on my way to the shops.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6407, 'look in on someone/something', 'to visit someone or something for a short time:', 'It helps if older people have a nearby relative who will look in on them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6408, 'look into something', 'to examine the facts about a problem or situation:', 'We''re looking into the possibility of merging the two departments.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6409, 'look kindly on someone/something', 'to have a good opinion of someone or something:', 'She had hoped the critics would look kindly on her first novel.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6410, 'look like a drowned rat', 'to be very wet, especially because you have been in heavy rain', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6411, 'look like someone/something', 'to be similar in appearance to someone or something:', 'The twins look like their mother.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6412, 'look like something', 'to appear likely to happen:', 'It sure looks like snow today.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6413, 'look like something the cat brought/dragged in', 'to look very untidy and dirty', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6414, 'look like the back end of a bus', 'to look very unattractive:', 'She may object if she is photographed looking like the back end of a bus.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6415, 'look like/as if you''ve been dragged through a hedge backwards', 'to look very untidy:', 'I looked as if I''d been dragged through a hedge backwards when I woke up this morning.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6416, 'look like/as though you''ve seen a ghost', 'to look very shocked:', 'What''s the matter? You look like you''ve seen a ghost!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6417, 'look lively/sharp!', 'used to tell someone to do something quickly:', 'Look lively - we haven''t got all day!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6418, 'look no further', 'used to say that something is exactly what someone wants or needs:', 'If you want the perfect solution to family transport, look no further, because even children can''t break this thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6419, 'look on', 'to watch something happen but not become involved in it:', 'A large crowd looked on as the band played.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6420, 'look on the bright side', 'to find good things in a bad situation:', 'Look on the bright side - no one was badly hurt.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6421, 'look on/upon someone/something', 'to consider or think of someone or something in a stated way:', 'We looked on her as a daughter.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6422, 'look on/upon someone/something as something', 'to consider or think of someone or something as something:', 'We looked on her as a daughter.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6423, 'look out', 'to watch what is happening and be careful:', 'The police have warned shopkeepers to look out for forged notes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6424, 'look out', 'said or shouted in order to tell someone that they are in danger:', 'Look out! There''s a car coming!', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6425, 'look something out', 'to search for and find something:', 'I''ll look out that recipe I told you about and send it to you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6426, 'look out for number one', 'to do what you think is best for yourself and not care about other people', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6427, 'look out for someone/something', 'to try to notice someone or something:', 'Look out for Anna while you''re there.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6428, 'look over something', 'to quickly examine something:', 'I had a few minutes before the meeting to look over what he''d written.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6429, 'look right through someone', 'to pretend not to see someone even while your eyes are directed toward that person:', 'I smiled at him, but he looked right through me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6430, 'look round (somewhere/something)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6431, 'look someone in the eye', 'to talk to someone in an honest way that shows no doubts:', 'I wanted to look people in the eye and tell them I made a mistake.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6432, 'look someone in the eye/face', 'to talk to someone in a direct and confident way that shows you are honest or not ashamed:', 'I wanted to look people in the eye and tell them I made a mistake.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6433, 'look straight/right through someone', 'to look at someone as if you cannot see them, either intentionally or because you are thinking about something else:', 'I said hello but she looked straight through me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6434, 'look through something', 'to read something quickly:', 'I''ve looked through some catalogues.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6435, 'look to someone for something', 'to hope that someone will provide something for you:', 'They looked to the government for additional support.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6436, 'look to someone to do something', 'to hope that someone will do something for you:', 'We''re looking to you to advise us on how to proceed.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6437, 'look to your laurels', 'to make an extra effort to succeed because there is more competition:', 'Nowadays there are a number of similar products on the market and the older, established companies are having to look to their laurels.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6438, 'look up', 'to become better:', 'I hope things will start to look up in the new year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6439, 'look something up', 'to try to find a piece of information by looking in a book or on a computer:', 'If you don''t know what the word means, look it up in a dictionary.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6440, 'look someone up', 'to visit someone you have not seen for a long time when you are visiting the place where they live:', 'Look me up next time you''re in Los Angeles.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6441, 'look up to someone', 'to admire and respect someone:', 'He''d always looked up to his uncle.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6442, 'look who''s talking!', 'something you say when someone criticizes you for something that that person does himself or herself:', 'I''m lazy? Look who''s talking!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6443, 'look/feel like a million dollars', 'to look or feel extremely good, often because you are wearing something that costs a lot of money:', '"You look like a million dollars in that dress, honey!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6444, 'look/feel like death warmed over', 'to look or feel very sick:', 'He shouldn''t be working when he''s so sick - he looks like death warmed over!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6445, 'look/feel like death warmed up', 'to look or feel very ill:', 'He shouldn''t be working when he''s so ill - he looks like death warmed up!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6446, 'looking for trouble', 'behaving in a way that is likely to cause problems for you:', 'Parking illegally in front of the police station is looking for trouble.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6447, 'loom large', 'If something looms large, it becomes very important and often causes worry:', 'The issue of pay will loom large at this year''s conference.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6448, 'loop the loop', 'to fly in the shape of a loop in the sky', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6449, 'loose your hold/grip', 'to decide to control a person or situation less:', 'Sooner or later Isambard would have to loose his hold of him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6450, 'loosen (something) up', 'to prepare your muscles for a physical activity by stretching and doing simple exercises:', 'I do a few stretches to loosen up before I run.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6451, 'loosen (someone) up', 'to start to feel less embarrassed and to become more relaxed when you are with other people, or to make someone feel like this:', 'He seemed quite nervous at the beginning, but he soon loosened up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6452, 'loosen someone''s tongue', 'to make someone speak more freely:', 'A couple of glasses of champagne had loosened my tongue and I said things that perhaps I shouldn''t have.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6453, 'loosen your grip', 'If you loosen your grip on an object, or your grip loosens, you hold something less tightly:', 'He held my hand very tightly at first but gradually his grip loosened.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6454, 'loosen your grip/hold', 'If you loosen your grip/hold on a situation, or your grip/hold loosens, you decide to control it less:', 'The dictator''s grip on the country has not loosened.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6455, 'lop something off', 'to cut something off in one quick movement:', 'I''ll need to lop off the lower branches of the tree.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6456, 'lop something off', 'to reduce a price or the amount of time taken to do something by a particular amount:', 'He lopped eight seconds off the record.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6457, 'lord it over someone', 'to behave as if you are more important than someone and have a right to tell that person what to do:', 'He likes to lord it over his little sister.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6458, 'lord/master/mistress/king/queen of all you survey', 'If you are lord, master, mistress, king, or queen of all you survey, you own or control the place in which you live or work.', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6459, 'lose count of something', 'to not be able to remember a total:', 'I’ve lost count of how many times she’s been late for work this month.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6460, 'lose face', 'to become less respected by others:', 'She had to accept defeat without losing face.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6461, 'lose ground', 'to become less popular or to be given less support:', 'Do you agree that left-wing politics are losing ground among the working classes?', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6462, 'lose heart', 'to stop believing that you can succeed:', 'Don''t lose heart, there''ll be plenty more chances for promotion.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6463, 'lose it', 'to stop being able to control your emotions and suddenly start to shout, cry, or laugh:', 'I''d been trying so hard to stay calm but in the end I just lost it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6464, 'lose out', 'to not have an advantage that other people have:', 'The new tax means that the vast majority of working people will lose out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6465, 'lose sight of something', 'to forget about an important idea or fact because you are thinking too much about other things:', 'I''m worried that we''re losing sight of our original objectives.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6466, 'lose sleep (over something)', 'to worry about something so much that you cannot sleep:', 'I know you made a mistake, but I wouldn''t lose sleep over it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6467, 'lose sleep over/about something', 'to worry about something:', 'I wouldn''t lose any sleep over what happened.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6468, 'lose the dressing room', 'If a football manager loses the dressing room, the players no longer respect him or follow his instructions:', 'If the owner believes he has lost the dressing room, it could spell the end for the manager.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6469, 'lose the plot', 'to no longer be able to act normally or understand what is happening:', 'I can''t believe Stuart did that - he must be losing the plot.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6470, 'lose touch (with someone)', 'to no longer communicate with someone:', 'I lost touch with Katie after she moved to Canada.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6471, 'lose touch (with something/someone)', 'to no longer have recent knowledge of something or someone, so that you do not understand that thing or person well:', 'Politicians can easily lose touch with the real people if they spend too much time in Washington D.C.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6472, 'lose track', 'to no longer know what is happening, or not to remember something:', 'What he was saying was so complicated that I lost track after the first couple of sentences.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6473, 'lose your head', 'to lose control and not act in a calm way:', 'He usually stays quite calm in meetings but this time he just lost his head.', 'idiom', 'C1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6474, 'lose your heart to someone', 'to fall in love with someone', '', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6475, 'lose your life', 'to die suddenly because of an accident or violent event:', 'Many people lost their lives in the floods.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6476, 'lose your mind', 'to become mentally ill, or to start behaving in a silly or strange way:', 'You just spent all that money on a pair of shoes? Have you completely lost your mind?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6477, 'lose your rag', 'to suddenly become very angry:', 'He said one too many stupid things and I just lost my rag.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6478, 'lose your shirt', 'to lose a lot of money, especially as a result of a bet (= money risked when you guess the result of something)', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6479, 'lose your temper', 'to become very angry:', 'Michelle wanted everybody to like her so much that she just lost it if someone got mad at her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6480, 'lose your touch', 'If you lose your touch, you can no longer do something as well as you could before:', 'It''s good to see their goalkeeper''s not losing his touch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6481, 'lose your way', 'to become lost', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6482, 'lost in the shuffle', 'If something or someone gets lost in the shuffle, that thing or person does not get the attention they deserve:', 'Refugee children in the big camps just get lost in the shuffle and are sometimes left without food.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6483, 'loud and clear', 'very clear and easy to understand:', 'I can hear you loud and clear.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6484, 'lounge around (something)', 'to spend your time in a relaxed way, sitting or lying somewhere and doing very little:', 'We spent our days lounging around the pool.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6485, 'louse (something) up', 'to spoil something or cause it to fail:', 'This is a great opportunity, so don''t louse it up.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6486, 'love me, love my dog', 'said to warn someone that if they want to be in a relationship with you, they must be willing to accept everything about you', '', 'idiom', '', 'humorous, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6487, 'love someone to bits', 'to love someone very much:', 'He''s my old man and I love him to bits but I can''t spend too much time with him.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6488, 'lower your sights', 'to accept that you will only be able to get something less than you hoped for:', 'He had hoped to become a doctor, but he had to lower his sights after his disappointing exam results.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6489, 'luck into something', 'to get something that you want by chance:', 'We lucked into tickets for the World Cup finals.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6490, 'luck out', 'to be very lucky:', 'The Giants really lucked out in last night''s game.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6491, 'lull someone into something', 'to make someone feel safe in order to trick them:', 'Most exercise classes start gently, lulling you into thinking that you''re in good shape.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6492, 'lumber someone with something', 'If you are/get lumbered with something, you have to deal with something or someone that you do not want to:', 'I always seem to get lumbered with the job of clearing up after a party.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6493, 'lump someone/something together', 'to put different groups together and think about them or deal with them in the same way:', 'All the children are lumped together in one class, regardless of their ability.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6494, 'lust after someone', 'to feel sexual desire for someone you are not having a sexual relationship with:', 'She''s been lusting after Dave for months.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6495, 'lust after/for something', 'to want something very much:', 'I''ve been lusting after one of their silk shirts for ages.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6496, 'luxuriate in something', 'to get great pleasure from something, especially because it provides physical comfort:', 'There''s nothing better after a hard day''s work than to luxuriate in a hot bath.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6497, 'made for each other', 'perfectly matched:', 'The long cool drinks and the hot spicy food were made for each other.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6498, 'made of sterner stuff', 'If someone is described as being made of sterner stuff, they are very strong and determined:', 'I was ready to give up the fight, but Nicky was made of sterner stuff and wanted us to finish.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6499, 'mail sth out', 'to send something by mail:', 'In March we mailed out three million catalogues.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6500, 'major in something', 'to study something as your main subject in college or a university:', 'She majored in earth sciences at Arizona State.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6501, 'make (a) nonsense of something', 'to make something appear stupid or wrong, or to spoil something:', 'His repeated lack of promotion makes nonsense of the theory that if you work hard you''ll be successful.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6502, 'make (all) the right, correct, etc. noises', 'to say the things you are expected to say, sometimes when you do not mean them:', 'He made all the right noises about my audition but I couldn''t tell if he was genuinely impressed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6503, 'make (all) the running', 'to do the best and most work:', 'British companies have often made all the running in developing new ideas, but have then failed to market them.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6504, 'make (someone''s) hackles rise', 'to annoy someone:', 'The president''s speech has raised hackles among members of the opposing party.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6505, 'make a (big) difference', 'to improve a situation or condition in an important way:', 'He''s much happier now – his new school seems to have made a big difference.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6506, 'make a beeline for something', 'to move quickly and directly toward something:', 'When he saw me in the kitchen, he made a beeline for the door.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6507, 'make a big thing (out) of something', 'to give something too much importance:', 'I want a party, but I don''t want to make a big thing of it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6508, 'make a bundle', 'to earn a lot of money:', 'They made a bundle selling their business.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6509, 'make a case for something', 'to argue that something is the best thing to do, giving your reasons:', 'We will only publish a new edition if you can make a convincing case for it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6510, 'make a clean breast of it', 'to tell the truth about something:', 'Julia finally made a clean breast of it and admitted that she had stolen the money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6511, 'make a day/night/evening/weekend of it', 'to make an activity longer or combine a series of activities so that they last for the whole of that particular period of time:', 'We wanted to drive up the coast, so we decided to make a weekend of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6512, 'make a dent in something', 'to reduce an amount of something, esp. money or work:', 'Buying a new car put a big dent in our savings.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6513, 'make a difference', 'to improve a situation:', 'Exercise can make a big difference to your state of health.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6514, 'make a difference', 'If a person makes a difference, they make a situation better because of their good actions:', 'What she showed is that one person can make a difference.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6515, 'make a face (at someone/something)', 'to move your mouth, nose, and eyes in strange ways to show emotion or make people laugh:', 'She stepped in something, made a face, and looked down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6516, 'make a fool (out) of someone', 'to do something that makes someone, esp. yourself, seem ridiculous:', 'I almost stood up and sang, but I decided I didn''t want to make a fool out of myself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6517, 'make a habit of something', 'to begin to do something regularly, often without thinking about it:', 'He made a habit of ignoring me whenever his friends were around.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6518, 'make a hole in something', 'to reduce an amount of money by a lot:', 'The trip made a big hole in our savings but I''m glad we went.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6519, 'make a joke of something', 'to laugh at something although it is serious or important:', 'He tried to make a joke of the fact that he hadn''t passed the test.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6520, 'make a killing', 'to earn a lot of money in a short time and with little effort:', 'They made a killing with the sale of their London house.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6521, 'make a man (out) of someone', 'to cause a young man or boy to act like an adult and take responsibility:', 'A couple of years in the army should make a man of him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6522, 'make a meal (out) of something', 'to spend more time or energy doing something than is necessary:', 'I only asked for a summary of the main points but she''s making a real meal out of it.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6523, 'make a mockery of something', 'to make something seem stupid or without value:', 'Behaviour like this makes a mockery of professional sport.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6524, 'make a monkey out of someone', 'to make someone appear stupid', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6525, 'make a mountain out of a molehill', 'to make a slight difficulty seem like a serious problem:', 'You''re making a mountain out of a molehill. You wrote one bad essay - it doesn''t mean you''re going to fail.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6526, 'make a move', 'to leave a place:', 'It''s late - I think it''s time we made a move.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6527, 'make a move', 'to try to start a romantic or sexual relationship with someone:', 'He accused the man of making a move on his girlfriend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6528, 'make a muck of something', 'to spoil something or do something very badly:', 'I''ve made a muck of it - I''ll have to do it again.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6529, 'make a name for yourself', 'to become famous or respected by a lot of people:', 'He''s made a name for himself as a talented journalist.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6530, 'make a noise about something', 'to talk about or complain about something a lot:', 'She''s been making a lot of noise about moving to a new house.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6531, 'make a pig of yourself', 'to eat too much:', 'They made complete pigs of themselves at the dinner.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6532, 'make a pig''s ear of something', 'to do something badly, wrongly, or awkwardly:', 'He''s made a real pig''s ear of that bookcase he was supposed to be making.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6533, 'make a pile', 'to earn a large amount of money:', 'He made a pile selling computers and retired by the time he was 40.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6534, 'make a play for something/someone', 'to try to get something, or start a relationship with someone, sometimes by using a plan:', 'I wouldn''t have made a play for him if I''d known he was married.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6535, 'make a point of doing something', 'to always do something or to take particular care to do something:', 'She makes a point of keeping all her shopping receipts.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6536, 'make a production (out) of something', 'to make something seem more difficult or complicated to do than it is:', 'If you ask Tom to do anything, he always makes such a production of it that you wish you''d just done it yourself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6537, 'make a rod for your own back', 'If you make a rod for your own back, you act in a way that creates more problems for yourself in the future:', 'By giving in to the terrorists'' demands, the government will simply be making a rod for its own back.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6538, 'make a run for it', 'to suddenly start running in order to escape from somewhere:', 'One of the prisoners tried to make a run for it.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6539, 'make a scene', 'to behave in a loud, angry way in public :', 'Please don''t make a scene.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6540, 'make a song and dance about something', 'to make something seem more important than it really is so that everyone notices it:', 'I only asked her to move her car but she made such a song and dance about it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6541, 'make a spectacle of yourself', 'to do something that makes you look stupid and attracts other people''s attention:', 'I wasn''t going to make a spectacle of myself just to give you a laugh!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6542, 'make a splash', 'to become suddenly very successful or very well known:', 'Jodie Foster made quite a splash in the film "Taxi Driver".', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6543, 'make a virtue (out) of something', 'to use something, especially a bad situation, to your advantage:', 'I had a couple of months to spare between jobs so I thought I''d make a virtue of necessity by acquiring a few new skills.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6544, 'make a world of difference', 'If something makes a world of difference, it improves something very much:', 'A little sympathy makes a world of difference to someone who''s been badly treated.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6545, 'make a/your mark (on something)', 'to have an important effect on something:', 'Daniel didn''t work here for very long, but he definitely made his mark on the place.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6546, 'make an ass of yourself', 'a rude phrase meaning to behave stupidly and look silly:', 'Simon always makes a complete ass of himself when he''s had too much to drink.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6547, 'make an exhibition of yourself', 'to do something stupid in public:', 'I hope I didn''t make an exhibition of myself last night.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6548, 'make an honest living', 'to earn money by working hard at a job', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6549, 'make an honest woman (out) of someone', 'to marry a woman you are having a sexual relationship with', '', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6550, 'make an impression on someone', 'to cause someone to notice and admire you:', 'He made quite an impression on the girls at the tennis club.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6551, 'make as if to do something', 'If you make as if to do something, you seem as if that is what you are going to do:', 'He made as if to speak.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6552, 'make capital out of something', 'to use a situation to get an advantage for yourself:', 'The Opposition is making a lot of political capital out of the government''s failure to invest in education.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6553, 'make conversation', 'to say things to someone who you do not know well, in order to be polite:', 'I was just trying to make conversation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6554, 'make do', 'to manage to live without things that you would like to have or with things of a worse quality than you would like:', 'We didn''t have cupboards so we made do with boxes.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6555, 'make do (with something)', 'to use what is available although it is not enough or what you wanted:', 'Can you make do with $5 for now and I’ll give you the rest tomorrow?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6556, 'make ends meet', 'to have just enough money to pay for the things that you need', '', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6557, 'make eyes at someone', 'to look at someone with sexual interest:', 'She was making eyes at him all evening.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6558, 'make for somewhere/something', 'to go in the direction of a place or thing:', 'They made for the centre of town.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6559, 'make for something', 'to result in or make possible:', 'Having faster computers would make for a more efficient system.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6560, 'make fun of someone', 'to be unkind to someone and laugh at or cause others to laugh at the person:', 'You’re always making fun of me!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6561, 'make good', 'to succeed and become rich:', 'a working-class boy made good', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6562, 'make good', 'When someone makes good something, they either pay for it, or make it happen:', 'My uncle owed thousands, but eventually he made good on all of his debts.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6563, 'make good on something', 'to do what you have said you would do:', 'My grandfather said he would pay for me to go to college, and he made good on that promise.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6564, 'make good time', 'to complete a journey quickly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6565, 'make haste', 'hurry up:', 'Make haste!', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6566, 'make hay while the sun shines', 'to make good use of an opportunity while it lasts', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6567, 'make headway', 'to begin to succeed:', 'Has the city made any headway in attracting new businesses?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6568, 'make heavy weather of something', 'to find something hard to do and spend a lot of time on it, although it is not difficult:', 'She''s making such heavy weather of that report she''s writing.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6569, 'make history', 'to do something important that has not been done before and will be recorded publicly and remembered for a long time:', 'Margaret Thatcher made history when she became the first female British prime minister.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6570, 'make it', 'to continue to live or exist, especially after coming close to dying or being destroyed or after being in a difficult or threatening situation:', 'Given his injuries, we didn''t expect him to make it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6571, 'make it', 'to be very successful:', 'She paid tribute to the hit sitcom for helping her make it in Hollywood.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6572, 'make it a rule', 'to act according to a principle:', 'I make it a rule not to eat fatty foods.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6573, 'make it big', 'to become famous or successful', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6574, 'make it quick/fast', 'used to tell someone to do something quickly or to hurry up:', 'Take him to the hospital - and make it quick!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6575, 'make it snappy', 'used to tell someone that you want them to do something immediately and to do it quickly:', 'Get your shoes on, and make it snappy.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6576, 'make it up to someone', 'to do something good for someone you have upset, in order to become friends with them again:', 'I''m sorry we can''t take you with us, but I promise I''ll make it up to you somehow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6577, 'make it with someone', 'to have sex with someone', '', 'idiom', '', 'old-fashioned informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6578, 'make legal history', 'If you make legal history, the case you win in court or take to court is the first of its type and changes the way future cases will be dealt with.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6579, 'make light of something', 'to act as if something is not serious, esp. when it is serious:', 'They''ve both had knee injuries, but the two friends make light of their weaknesses.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6580, 'make like', 'to pretend:', 'She made like she was about to leave, but then stayed for hours.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6581, 'make little of something', 'to not consider something to be very important:', 'He made little of his ordeal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6582, 'make love', 'to have sex:', 'That night they made love for the first time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6583, 'make love to someone', 'to speak romantically and give attention to someone, especially in order to make them love you:', 'Mr Jackson, I do believe you are making love to me.', 'idiom', '', 'old use', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6584, 'make matters worse', 'to make the situation even more unpleasant or difficult:', 'Don''t say anything - you''ll only make matters worse.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6585, 'make mincemeat of someone', 'to defeat someone very easily in an argument, competition, or fight:', 'A decent lawyer would have made mincemeat of them in court.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6586, 'make mischief', 'to intentionally say or do something that causes other people to be upset or annoyed with each other:', 'My children often try to make mischief between me and my new husband.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6587, 'make much of something', 'to give a lot of importance to something:', 'Don''t make too much of the test results.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6588, 'make much/a lot of someone', 'to treat someone very well:', 'His mother used to make much of him when he went back home.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6589, 'make nice', 'to behave in a kind, friendly, or polite way towards someone, especially when you are not being sincere:', 'They need to make nice with each other and get to work.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6590, 'make no apologies', 'to believe that what you have done is right or acceptable:', 'The network makes no apologies for broadcasting the controversial film.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6591, 'make no bones about something', 'not to try to hide your feelings:', 'He made no bones about his dissatisfaction with the service.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6592, 'make no claim to be something', 'to not be trying to make people believe that you are a particular thing:', 'I make no claim to be a brilliant pianist, but I can play a few tunes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6593, 'make no difference', 'to not change or improve a situation:', 'It doesn’t make any difference now what he says – it’s too late for apologies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6594, 'make no mistake (about it)', 'used to show that you are certain about something:', 'Make no mistake, this decision is going to cause you a lot of problems.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6595, 'make no odds', 'to not be important, or to not change a situation or result:', 'I don''t mind whether you come or not - it makes no odds to me.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6596, 'make noises', 'to show what you think or feel by what you say, without stating it directly:', 'He''s been making noises about taking us all to Rio, but we haven''t heard anything definite.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6597, 'make noises', 'to complain or make trouble:', 'If things start going badly again, our members are sure to make noises.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6598, 'make off', 'to leave quickly, usually in order to escape:', 'The burglars made off before the police arrived.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6599, 'make off with something', 'to steal something:', 'Somebody broke into the shop and made off with several TVs.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6600, 'make peace (with someone)', 'to stop fighting or disagreeing with someone and start living and working happily together:', 'Will they make peace, or fight each other?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6601, 'make peace with something', 'to start to accept something that was previously worrying or annoying you:', 'It''s time to make peace with your body image.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6602, 'make representations/a representation to someone/something', 'to complain officially to a person or organization:', 'We made representations to the boss about the long working hours.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6603, 'make sense', 'to be clear and easy to understand:', 'This last paragraph doesn’t make any sense.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6604, 'make sense', 'Someone who makes sense is reasonable or shows good judgment:', 'Everything he said made sense – I''d definitely vote for him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6605, 'make short shrift of something', 'to deal with or get rid of something quickly:', 'Williams made short shrift of her opponent, letting her win only two games in the match.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6606, 'make short work of something', 'to finish or deal with something quickly:', 'Well, you certainly made short work of the chocolate cake! There''s none left for your dad.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6607, 'make someone look small', 'to show that someone is wrong in a way that makes them appear stupid', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6608, 'make someone sweat', 'to make someone wait nervously:', 'It seemed that the authorities had delayed the news just to make us sweat.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6609, 'make someone''s acquaintance', 'fml to meet someone:', 'I’m very pleased to make your acquaintance.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6610, 'make someone''s blood boil', 'to make someone extremely angry:', 'The way they have treated those people makes my blood boil.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6611, 'make someone''s blood curdle', 'to fill someone with fear:', 'The strange sound made his blood curdle.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6612, 'make someone''s blood run cold', 'A sound, sight, or thought that makes your blood run cold frightens you very much:', 'I heard a tapping on the window which made my blood run cold.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6613, 'make someone''s day', 'to make someone happy:', 'Seeing Adrian again after such a long time really made my day.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6614, 'make someone''s hair stand on end', 'to make someone very frightened:', 'The thought of jumping out of a plane makes my hair stand on end.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6615, 'make someone''s heart flutter', 'If someone makes your heart flutter, you find that person very physically attractive and you feel excited when you see or talk to them:', 'James has been making hearts flutter ever since he joined the company.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6616, 'make someone''s mouth water', 'If the smell or sight of food makes your mouth water, it makes you want to eat it:', 'The smell of that bacon cooking is making my mouth water.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6617, 'make someone''s skin crawl', 'If someone or something makes your skin crawl, you think they are very unpleasant or frightening:', 'The filthy house made my skin crawl.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6618, 'make someone/something over', 'to improve something or someone by working on or changing various parts:', 'Ed Carey has been chosen to make over the losing football team.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6619, 'make something (all) your own', 'If you make a piece of music, etc. (all) your own, you make it famous by the way you perform it.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6620, 'make something into something', 'to change something into something else:', 'They''ve made the spare room into an office.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6621, 'make something of something/someone', 'to have an impression or an understanding about something:', 'Can you make anything of this information?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6622, 'make something of something', 'to give a particular level of value or importance to something:', 'You should make more of your computer skills on the application form.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6623, 'make something over to someone', 'to give something, such as money or land, to someone so that they legally own it:', 'Just before her death, she had made over $100,000 to her new husband.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6624, 'make something stick', 'to show something bad that has been said about someone is true:', 'They''ve arrested him for fraud but they''ll never make the charges stick.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6625, 'make something up', 'to invent something, such as an excuse or a story, often in order to deceive:', 'I made up an excuse about having to look after the kids.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6626, 'make something up', 'to prepare or arrange something by putting different things together:', 'Could you make up a list of all the things that need to be done?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6627, 'make something up', 'to produce or prepare something from cloth:', 'We could use the rest of the material to make up some curtains.', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6628, 'make something up', 'If you make up a page, book, or newspaper, you arrange the text and pictures in the form in which they will be printed.', '', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6629, 'make something up', 'If you make up a bed for someone, you put sheets and covers on a bed so that they have a place to sleep in your home.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6630, 'make something up', 'If you make up a fire, you prepare it or put more wood or coal on it when it is burning.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6631, 'make something up', 'to make an amount of something complete or correct:', 'I have £20,000 and I need £25,000 but my parents have promised to make up the difference.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6632, 'make something up', 'to reduce or replace something, usually an amount of time or work, that has been lost:', 'We''re hoping to make up time on the return journey by not stopping at night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6633, 'make someone/something up', 'to put make-up on someone''s face, to improve or change its appearance:', 'For the movie, they made him up as an Indian.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6634, 'make up something', 'to form a particular thing, amount, or number as a whole:', 'Car accident victims make up almost a quarter of the hospital''s patients.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6635, 'make up', 'to forgive someone and be friendly with them again after an argument or disagreement:', 'They kissed and made up, as usual.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6636, 'make something up as you go along', 'to invent a story or a tune without thinking before about how it will end', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6637, 'make something/it worth your while', 'to pay someone money to do something:', 'If you can get me the list of names I want, I''ll make it worth your while.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6638, 'make something/someone out', 'to see, hear, or understand something or someone with difficulty:', 'The numbers are too small - I can''t make them out at all.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6639, 'make something out', 'to write all the necessary information on an official document:', 'I made a cheque out for £20 to "Henry''s Stores".', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6640, 'make out something', 'to say, usually falsely, that something is true:', '[ + to infinitive ] He made himself out to be a millionaire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6641, 'make out', 'to deal with a situation, usually in a successful way:', 'How is Frances making out in her new job?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6642, 'make out', 'to kiss and touch in a sexual way, or to succeed in having sex with someone:', 'Boys at that age are only interested in making out with girls.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6643, 'make sure', 'to take special care to do something:', 'Make sure you’re home by midnight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6644, 'make sure', 'To make sure also means to find out whether something is really true or real:', 'Make sure he''s honest before you lend him any money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6645, 'make that something', 'infml I want to change what I just said to something else:', 'I’ll have a steak – no, make that an omelet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6646, 'make the first move', 'to be the first to take action:', 'Neither side seems prepared to make the first move towards reaching a peace agreement.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6647, 'make the first move', 'to show that you want to start a romantic or sexual relationship with someone:', 'She''s liked him for a long time, but doesn''t want to make the first move.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6648, 'make the fur fly', 'to cause a bad argument:', 'He set the fur flying by demanding to see proof.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6649, 'make the grade', 'to perform well enough to succeed in something:', 'Marvin wanted to be an actor, but he didn''t make the grade.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6650, 'make the grade (as something)', 'to be good enough to be successful at something:', 'Do you think I will make the grade as a chef?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6651, 'make the most of something', 'to use or enjoy something as much as possible:', 'We’re only in Paris for a day, so let’s make the most of it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6652, 'make the ultimate/supreme sacrifice', 'to die while fighting for a principle', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6653, 'make the world go around/round', 'to be extremely important, so that many ordinary events could not happen without it:', 'Love/Money makes the world go round.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6654, 'make time', 'to make certain you have some time when you are not busy in order to do something you think you should do:', 'It''s important to make time to read to your children.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6655, 'make to do something', 'If you make to do something, you are just going to do it when something interrupts you:', 'I made to leave but she called me back.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6656, 'make toward something/someone', 'to go in the direction of something or someone:', 'He made toward the door, but stopped and turned to face me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6657, 'make towards something/someone', 'to go in the direction of something or someone:', 'He made towards the door, but stopped and turned to face me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6658, 'make tracks', 'to leave somewhere to go home:', 'It''s getting late, Jim - I think we should make tracks.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6659, 'make up for lost time', 'to enjoy an experience as much as possible because you did not have the opportunity to do it earlier in life:', 'I didn''t travel much in my twenties but I''m certainly making up for lost time now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6660, 'make up for something', 'to take the place of something lost or damaged or to compensate for something bad with something good:', 'No amount of money can make up for the death of a child.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6661, 'make up to someone', 'to be too friendly to someone or to praise them in order to get advantages for yourself:', 'Have you seen the disgusting way she makes up to the boss?', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6662, 'make up your mind', 'to decide:', 'I haven''t made up my mind where to go yet.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6663, 'make waves', 'to be very active so that other people notice you, often in a way that intentionally causes trouble:', 'It''s probably not a good idea to start making waves in your first week in a new job.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6664, 'make way for something', 'to provide a space or an opportunity for something else:', 'Some beautiful old buildings were torn down to make way for the new parking garage.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6665, 'make whoopee', 'to have sex', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6666, 'make with something', 'to give, bring, or do something:', 'He pointed a gun and said "Make with the money bags, baby!"', 'phrasal verb', '', 'old-fashioned, slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6667, 'make your flesh crawl/creep', 'to make someone very worried or frightened:', 'I don''t mind spiders but worms make my flesh crawl.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6668, 'make your presence felt', 'to have a strong effect on other people or on a situation:', 'The new police chief has really made his presence felt.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6669, 'make your way', 'to be successful and make progress in your life and work:', 'He will teach you how to build a career and make your way in the world.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6670, 'make yourself at home', 'to relax and make yourself comfortable in someone else''s home', '', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6671, 'make yourself known', 'to tell someone who you are:', 'Just go to the hotel reception and make yourself known (to the receptionist).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6672, 'make yourself respectable', 'to put on clothes so that you are in a suitable state to meet someone:', 'Could you wait a minute while I make myself respectable?', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6673, 'make yourself scarce', 'to go away from a difficult situation in order to avoid trouble:', 'Dad''s really angry with you, so you''d better make yourself scarce.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6674, 'make yourself understood', 'to communicate effectively:', 'Since they spoke only Swahili, we used signs and gestures to make ourselves understood.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6675, 'make yourself useful', 'a way of telling someone to start being helpful:', 'Now you''re here, you might as well make yourself useful - there''s a lot of cleaning up to do.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6676, 'make/do the rounds', 'to talk to a lot of people:', 'I''ve made/done the rounds of all the agents, but nobody has any tickets left.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6677, 'make/put a dent in something', 'to reduce an amount of money:', 'The holiday made a big dent in our savings.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6678, 'make/take a note', 'to write something down or remember it carefully:', 'I''ll just take a note of your name and address.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6679, 'make/take soundings', 'to ask questions in order to collect information or opinions:', 'Can you take some discreet soundings to see what her future plans are?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6680, 'man and boy', 'all a man''s life:', 'From 1910 to 1970 he worked in that factory, man and boy.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6681, 'man cannot live by bread alone', 'used to say that people need not just food, but also poetry, art, music, etc. to live happily', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6682, 'man for man', 'used to compare the strength, abilities, etc. of the people in two groups or teams:', 'Man for man, they were one of the most effective military units in the war.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6683, 'man for man', 'in team sports, used to describe a system in which defending players mark a particular player from the opposing team (= stay close to them to try to stop them getting control of the ball):', 'He cannot be marked man for man because their frontline is switching constantly.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6684, 'man of his word', 'people who do what they say they will do:', 'He is obviously a man of his word, a man of integrity.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6685, 'man of the world', 'someone who has a lot of experience of life and can deal with most situations:', 'They would grow up to be true women of the world, educated and experienced in magnificent ways.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6686, 'man on!', 'a warning shouted to a football player who has the ball to make him realize that an opposing player is behind him', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6687, 'man up', 'used to tell someone that they should deal with something more bravely:', 'You need to man up and admit you were wrong.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6688, 'man''s best friend', 'a dog', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6689, 'man''s inhumanity to man', 'the cruel behaviour that people show to each other:', 'Man''s inhumanity to man never fails to shock me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6690, 'man/woman of the people', 'a person, usually involved in politics, who is liked by a lot of ordinary people and seems to understand and like them', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6691, 'manage up', 'to work in a way that makes your manager able to do their work effectively:', 'I''m terrible at managing up. At worst, I''ve seen my bosses as a distraction from getting my job done.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6692, 'manna from heaven', 'help that you get when you need it but are not expecting it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6693, 'many a time', 'many times:', 'I''ve told you many a time not to ride your bike on the pavement.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6694, 'many a true word is spoken in jest', 'said about humorous remarks that contain serious or true statements', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6695, 'many happy returns (of the day)', 'said to mean "Happy birthday"', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6696, 'many moons ago', 'a long time ago', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6697, 'many''s the', 'used to show something has happened many times or for long periods of time:', 'Many''s the hour I''ve spent by the phone just waiting in case he called.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6698, 'map something out', 'to plan something in detail:', 'The department has issued a new document mapping out its policies on education.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6699, 'mark someone down as something', 'to consider someone as a particular type of person:', 'I''d marked her down as a Labour Party supporter, but I was completely wrong.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6700, 'mark something down', 'to reduce the price of something, usually in order to encourage people to buy it:', 'Low consumer demand has forced us to mark down a wide range of goods, sometimes by as much as 30 percent.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6701, 'mark something down', 'to write something on a piece of paper in order to make a record of it:', 'I''ve marked down the number of each item sold.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6702, 'mark something out', 'to show the shape or position of something by drawing a line around it:', 'He''d marked out a volleyball court on the beach with a stick.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6703, 'mark something up', 'to increase the price of something:', 'They buy paintings at auctions, mark them up, and then resell them at a vast profit to collectors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6704, 'mark something up', 'to write notes on something:', 'Someone had marked up the book before I got it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6705, 'mark something/someone off', 'If you mark off things or people that are on a list, you record that you have dealt with them:', 'As I complete each task I mark it off.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6706, 'mark something off', 'to separate an area by putting something around it:', 'Police had marked off the area where the body was found.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6707, 'mark time', 'to march in one place without moving forward', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6708, 'mark time', 'to do little while waiting for something that is going to happen:', 'She''s just marking time until she goes off to university.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6709, 'marry beneath you', 'to marry someone people think is not good enough for you because he or she is from a lower social class', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6710, 'marry in haste, repent at leisure', 'This means that if you marry someone without knowing him or her very well, you will later feel sorry that you got married.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6711, 'marry money', 'to marry a rich person:', 'One way to get rich is to marry money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6712, 'marry someone off', 'to make certain that someone, especially a female member of your family, gets married, or that she marries the person you have chosen:', 'She was married off to the local doctor by the age of 16.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6713, 'marry up (something)', 'If two things marry up or if you marry them up, they match or join together:', 'We need to marry up the names on your list with those on my list and see what the overlap is.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6714, 'mash up something', 'to crush something, especially food:', 'He always mashes up his peas before he eats them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6715, 'mask up', 'to put on a mask:', 'I mask up to protect myself and others at risk.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6716, 'masquerade as someone/something', 'to pretend or appear to be someone or something:', 'Hooligans masquerading as protesters have once again caused disturbances.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6717, 'massage someone''s ego', 'to praise someone in order to make that person think they are better than they are', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6718, 'match someone against someone', 'If one team or player is matched against another team or player, they are made to compete against each other:', 'Williams has been matched against Makarova in the semifinal.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6719, 'match something pound for pound', 'to give one pound for every pound given by someone else:', 'The government has promised to match the money raised by the charity pound for pound.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6720, 'match up', 'If two pieces of information match up, they are the same:', 'Their accounts of what happened that evening don''t match up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6721, 'match up', 'If two things match up, they are similar and are designed to connect or to work together:', 'If the teeth on the cogs don''t match up correctly (= if they are not in the correct place), the mechanism will jam.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6722, 'match up', 'to be as good as another thing, person, or experience:', 'There was so much hype beforehand that it would have been difficult for the film to match up to/with our expectations of it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6723, 'match something up', 'If you match up a design or material, you look for something that would look good with it and be similar to it:', 'I''m trying to match up this wallpaper with some suitable curtain material.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6724, 'match something/someone up', 'to find a similarity or connection between two things or people:', 'Can you match up these songs with the bands who sang them?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6725, 'match up to something', 'to be as good as something else:', 'The sequel didn’t match up to the original movie.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6726, 'mate for life', 'If animals mate for life, they keep the same sexual partner for their whole life.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6727, 'max out', 'to do or have as much as possible of something, or too much of something:', 'The air conditioner was maxed out, but it still felt hot in the car.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6728, 'max something out', 'to reach the limit of something, so that nothing more is possible:', 'We maxed out all our credit cards.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6729, 'may I ask', 'used in questions to show disapproval:', 'What, may I ask, was the point of repeating the tests?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6730, 'may the best man/person win!', 'said before a race or competition, meaning that you want the person who is the fastest, strongest, or most skilled to win or succeed', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6731, 'may well', 'If you say that something may well happen, you mean that it is likely to happen:', 'She may well not want to travel alone.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6732, 'may/might as well', 'used to suggest doing something, often when there is nothing better to do:', 'We might as well walk there.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6733, 'mean business', 'to want very much to achieve something', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6734, 'mean the world to someone', 'to be extremely important to someone:', 'Her children mean the world to her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6735, 'mean well', 'to do what you think will be helpful, although by doing it you might cause problems without intending to:', 'I know he means well, but he just gets in the way.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6736, 'measure someone/something against someone/something', 'to judge someone or something by him, her, or it against someone or something else:', 'She measured the shoe against the footprint, but it was smaller.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6737, 'measure something out', 'to weigh or measure a small amount of something from a larger amount of something:', 'Measure out 250 grams of flour and sift it into a large mixing bowl.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6738, 'measure up', 'to be good enough, or as good as someone or something else:', 'She could never measure up to her mother''s expectations.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6739, 'measure someone/something up', 'to discover what size someone or something is by measuring him, her, or it', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6740, 'meat and two veg', 'a traditional British meal of cooked, hot meat with two types of vegetables', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6741, 'meet someone halfway', 'to do some of the things that someone wants you to do, in order to show that you want to reach an agreement or improve your relationship with them', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6742, 'meet someone''s eye', 'to look at someone directly while they are looking at you:', 'I tried to avoid meeting his eye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6743, 'meet up', 'to meet another person in order to do something together:', 'They suggested we meet up at Mustafa''s.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6744, 'meet up', 'If roads or paths meet up, they join at a particular place.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6745, 'meet up (with someone)', 'to see and talk to someone after making an arrangement to do so:', 'I''m meeting up with some friends after work.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6746, 'meet with something', 'to experience something, usually something unpleasant:', 'I heard she''d met with an accident.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6747, 'meet with something', 'to cause a particular reaction or result:', 'At the time, the decision was met with a barrage of criticism.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6748, 'meet your Waterloo', 'to be defeated by someone who is too strong for you or by a problem that is too difficult for you', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6749, 'meet your maker', 'to die', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6750, 'meet your match', 'to compete unsuccessfully with someone:', 'He was a good player, but he met his match in Peter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6751, 'mellow out', 'to become more relaxed:', 'My dad has definitely mellowed out as he''s gotten older.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6752, 'melt (away) into something', 'to look so similar to something else all around you, or to be so much a part of it, that people do not see or notice you:', 'The security men just melted into the background until they were needed.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6753, 'melt away', 'to disappear slowly:', 'As the police sirens were heard, the crowd started to melt away.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6754, 'melt away', 'If a strong feeling melts away, you feel it less strongly and it disappears:', 'Her anger melted away when she read the letter.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6755, 'melt in your mouth', '(of food) to be prepared well and taste good:', 'The pie crust just melts in your mouth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6756, 'melt something down', 'to heat a metal object until it turns to liquid, because you want to use the metal rather than the object:', 'They melted down the gold rings and bracelets.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6757, 'memory/mind like a sieve', 'If you have a memory or mind like a sieve, you forget things very easily.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6758, 'men in white coats', 'used to refer to people who come to take someone to a psychiatric hospital:', 'He was in and out of psychiatric hospitals for 10 years, escorted by men in white coats.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6759, 'mend your fences', 'to try to be friendly again with someone after an argument', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6760, 'mend your ways', 'to begin to behave well, having until now behaved badly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6761, 'merchant of doom/gloom', 'someone who is always saying that bad things are going to happen:', 'With exports rising and unemployment falling, the merchants of gloom are having to revise their opinions of the economy.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6762, 'merry Christmas!', 'said at Christmas to wish people a pleasant Christmas period:', 'Hello, Phoebe. Merry Christmas!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6763, 'mess around', 'to spend time doing various things that are not important, without any particular purpose or plan:', 'They spend their weekends messing around on their boat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6764, 'mess around', 'to behave in a stupid or annoying way:', 'Stop messing around and listen to me!', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6765, 'mess around with something', 'to use or treat something in a careless or harmful way:', 'I don''t want him coming in here and messing around with our computers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6766, 'mess around (with someone)', 'If a married man or woman messes around with someone, they have a sexual relationship with someone who is not their wife or husband:', 'She found out that her husband was messing around with his secretary.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6767, 'mess someone about/around', 'to treat someone badly:', 'I''m tired of being messed around by my bank.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6768, 'mess something up', 'to make something dirty or untidy:', 'Who''s messed up the bookshelf?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6769, 'mess (something) up', 'to spoil or damage something, or to do something wrong or badly:', 'I messed up my chances of becoming a great singer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6770, 'mess someone up', 'to cause someone to suffer emotional and mental problems:', 'Drugs can really mess you up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6771, 'mess someone up', 'to hit someone repeatedly so that they are badly injured', '', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6772, 'mess with something/someone', 'to use or become involved with something or someone dangerous:', 'You shouldn''t mess with drugs.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6773, 'mess with something', 'to make small changes to something, or to move it to a different place, especially not carefully:', 'He was messing with his bike and then he couldn''t fit the parts back together.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6774, 'mess with someone', 'to treat someone in a bad, rude, or annoying way, or to start an argument with someone:', 'I''ve warned you already, don''t mess with me!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6775, 'mete something out', 'to give or order a punishment or make someone receive cruel or unfair treatment:', 'In the past, schoolteachers regularly meted out physical punishment to their pupils.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6776, 'might I ask/inquire/know', 'used in questions to show disapproval by being more polite than is expected:', 'And what are you doing in there, might I ask?', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6777, 'might just as well', 'If you might just as well do something, there are no reasons not to do it:', 'For the little extra it''ll cost, we might just as well stay for another night.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6778, 'mike someone up', 'to give someone a microphone to use or to attach a microphone to someone''s clothing, for example before they appear on television', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6779, 'miles', 'used to say something is much greater or better than something else:', 'Restaurant food is better by miles/miles better than it used to be 20 years ago.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6780, 'miles from anywhere/nowhere', 'a long distance from other houses or a town:', 'They live miles from nowhere, in the middle of the countryside.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6781, 'miles too big, small, expensive, etc.', 'very much bigger, smaller, more expensive, etc. than you would like:', 'This drink is miles too sweet!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6782, 'militate against something', 'to make something less likely to happen or succeed:', 'The complexity and costliness of the judicial system militate against justice for the individual.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6783, 'mill around', 'If a group of people mill around, they move around with no particular purpose or in no particular direction, sometimes while waiting for someone:', 'In the square, people were milling around in the sunshine.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6784, 'mill around/about', '(of a group of people) to move around with no obvious purpose:', 'There were people milling around the entrance to the stadium.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6785, 'mind (you)', 'used when you want to make what you have just said sound less strong:', 'He''s very untidy about the house; mind you, I''m not much better.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6786, 'mind over matter', 'the power of the mind to control and influence the body and the physical world generally:', 'He announced what he called "the ultimate test of mind over matter" - a woman walking over hot coals.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6787, 'mind the store', 'to be responsible for making sure that nothing bad happens, especially during a time of change or when the person who is normally responsible is absent:', 'In the short term, the agreement is intended to reassure consumers that someone is minding the store.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6788, 'mind your own business', 'used to tell someone in a rude way that you do not want them to ask about something private:', '"Where have you been?" "Mind your own business!"', 'idiom', 'C2', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6789, 'mind your p''s and q''s', 'to make an effort to be especially polite in a particular situation:', 'I have to mind my p''s and q''s when I''m with my grandmother.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6790, 'mind/watch your manners', 'to make a special effort to be polite:', 'His mother taught him to always mind his manners with his elders.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6791, 'mine a rich seam of something', 'to take advantage of a strong feeling or quality in a particular situation:', 'Polidori, the right-wing politician, is mining a rich seam of fear and prejudice.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6792, 'minister to someone', 'to give help to or care for someone, for example someone who is ill:', 'formal The priest ministers to his flock (= the people who go to his church).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6793, 'minor in something', 'to study something as your second most important subject in college or a university:', 'I minored in Spanish in college.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6794, 'misery loves company', 'people who are unhappy like to share their troubles with others:', 'We''d both just broken up with our boyfriends, so we decided to go see a movie together – misery loves company.', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6795, 'miss a chance/opportunity', 'to not use an opportunity to do something:', 'She missed the chance of promotion when she turned down the job of assistant manager.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6796, 'miss someone/something out', 'to fail to include someone or something that should be included:', 'You''ve missed out your address on the form.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6797, 'miss out', 'to fail to use an opportunity to enjoy or get an advantage from something:', 'Don''t miss out on the fantastic bargains in our summer sale.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6798, 'miss the boat', 'to lose an opportunity to do something by being slow to act:', 'There were tickets available last week, but he missed the boat by waiting till today to try to buy some.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6799, 'miss the mark', 'to fail to achieve the result that was intended:', 'Her speech missed the mark and failed to generate the public support she had been hoping for.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6800, 'miss the point', 'to not understand something correctly or what is important about it:', 'What you say is true, but you''ve missed the point of my argument.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6801, 'mist (something) over/up', 'If something that you can see through mists over/up, it becomes covered with a thin layer of liquid so that it is more difficult to see through:', 'Open the window when you have a shower to stop the mirror misting over.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6802, 'mist (something) over/up', 'If your eyes mist over/up, they fill with tears.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6803, 'mistake someone/something for someone/something', 'to confuse someone or something with a different person or thing:', 'I often mistake her for her mother on the phone.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6804, 'mix it', 'to fight or argue with people:', 'Don''t take any notice of Sally - she just likes to mix it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6805, 'mix it up', 'to fight or argue with people:', 'She''s ready to mix it up with the other candidates during the debate.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6806, 'mix someone/something up', 'to fail to recognize two people or things correctly by thinking that one person or thing is the other person or thing:', 'People often mix us up because we look so similar.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6807, 'mix someone up', 'to confuse, worry, or upset someone:', 'The directions he gave me mixed me up and I went the wrong way.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6808, 'mix something up', 'to make a group of things untidy or badly organized, or to move them into the wrong order:', 'Don''t mix up the bottles - you''ll have to repeat the experiment if you do.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6809, 'mix your metaphors', 'to combine two or more metaphors, often producing a silly or humorous effect:', 'Mixing his metaphors, he described the problem by saying "We''ve opened up a can of worms here, and now we have to get the genie back in the bottle".', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6810, 'mock something up', 'to make a model of something in order to show people what it will look like or how it will work', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6811, 'model yourself on someone', 'to try to make yourself very similar to someone else:', 'Lots of young singers modelled themselves on Beyoncé.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6812, 'moderation in all things', 'said to advise someone that it is best not to have or do too much or too little of anything', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6813, 'money doesn''t grow on trees', 'said to warn someone to be careful how much money they spend, because there is only a limited amount:', '"Mum, I''d like a new bike." "I''ll have to think about it - money doesn''t grow on trees, you know!"', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6814, 'money for old rope', 'money you get for doing something very easy:', 'Babysitting is money for old rope if the children don''t wake up.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6815, 'money talks', 'said about people or organizations that are rich, and can therefore get or do what they want', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6816, 'monkey around', 'to behave in a silly and annoying way:', 'The children were bored and started monkeying around.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6817, 'monkey around with sth', 'to touch, change, or treat something in a careless or harmful way:', 'They shouldn''t start monkeying around with the Constitution.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6818, 'moon around', 'to move around or spend time without any clear purpose, especially because you are slightly sad or in love:', 'She was mooning around the house all weekend.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6819, 'moon over someone/something', 'to spend time thinking about someone or something that you love, in a silly way that does not achieve anything:', 'He spends all his time mooning over a girl at school.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6820, 'mop something up', 'to use a piece of cloth or a mop to remove liquid from the surface of something:', 'There''s milk on the floor over there - could you get a cloth and mop it up?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6821, 'mop something up', 'to finish dealing with something:', 'It took a week to mop up the last of the enemy soldiers (= defeat them).', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6822, 'mope around (somewhere)', 'to move from one place to another without any particular purpose or energy, because you are unhappy or disappointed:', 'He was driving me crazy, moping around the house all day.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6823, 'more (...) than you can shake a stick at', 'a lot of:', 'There are more whisky distilleries in this part of Scotland than you can shake a stick at.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6824, 'more and more', 'increasingly, or an increasing number of:', 'It gets more and more difficult to understand what is going on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6825, 'more bang for your buck(s)', 'If you get more bang for your buck(s), you get a better result for the amount of effort or money that you have put into something.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6826, 'more by accident than design', 'because of luck and not because of skill or organization:', 'The play was a success more by accident than design.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6827, 'more by luck than judgment', 'by chance and not because of any special skill:', '"You did amazingly well to get the ball in." "Oh, it was more by luck than judgment."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6828, 'more cowbell', 'an extra quality that will make something or someone better:', 'It was a fairly average show - it needed more cowbell.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6829, 'more haste, less speed', 'said to mean that if you try to do things too quickly, it will take you longer in the end', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6830, 'more like it', 'infmlmore accurate or true:', 'I think he likes her – or maybe he''s madly in love with her is more like it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6831, 'more money than sense', 'used to talk about people spending a lot of money on something that you think is unnecessary:', 'He''s just a man who''s got more money than sense and no idea what to do with his life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6832, 'more often than not', 'usually:', 'More often than not when I make the effort to visit her, I wonder why I even bothered.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6833, 'more or less', 'mostly:', 'The project was more or less a success.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6834, 'more or less', 'approximately:', 'It''s 500 kilos, more or less.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6835, 'more or less', 'almost:', 'He more or less admitted he''d done it.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6836, 'more power to you!', 'an expression of praise or admiration for someone''s success or brave actions:', '"I''ve decided to quit my job and set up my own business." "Well, good for you. More power to you!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6837, 'more power to your elbow!', 'an expression of praise or admiration for someone''s success or brave actions:', '"I''ve decided to quit my job and set up my own business." "Well, good for you. More power to your elbow!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6838, 'more than', 'very:', 'It''s more than likely that there''s oil here under the ground.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6839, 'more trouble than it''s worth', 'If something is more trouble than it''s worth or is not worth the trouble, it is not important or useful enough to make an effort doing it:', 'It''s more trouble than it''s worth to take it back to the shop and ask for a replacement.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6840, 'more/greater/bigger etc. than the sum of its parts', 'used to say that a particular thing, when considered as a whole, is more important, better, etc. than you would expect from looking at the individual parts that make it up:', 'He has built a global operation that is clearly bigger than the sum of its parts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6841, 'morning, noon, and night', 'all the time:', 'Our neighbour''s baby cries morning, noon, and night.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6842, 'mortification of the flesh', 'punishment of yourself, especially by hitting your body with a whip, usually done for religious reasons', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6843, 'motherhood and apple pie', 'used to represent things that most Americans consider to be very good and important:', 'For some Americans, low taxes and small government are as sacred as motherhood and apple pie.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6844, 'mount up', 'to gradually increase in number or amount:', 'It isn''t a good idea to let bills mount up.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6845, 'mouse over something', 'to use a computer mouse to move the cursor over a particular part of the screen:', 'The pictures become bigger when you mouse over them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6846, 'mouth off', 'to express your opinions or complain, esp. loudly and in a way that shows no consideration or respect:', 'Clark was mouthing off in the locker room after we lost, and he started a fight.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6847, 'mouth off (about something)', 'to express your opinions too loudly and publicly:', 'I had to listen to Michael mouthing off about the government all through lunch.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6848, 'mouth off (to/at someone)', 'to speak in a rude or offensive way to someone:', 'She''s a typical teenager, coming home late at night and mouthing off to her parents.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6849, 'move heaven and earth', 'to do everything you can to achieve something:', 'He''ll move heaven and earth to get it done on time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6850, 'move in on something/someone', 'If you move in on a person or place, you come close or closer to them in order to attack or take control of them:', 'Government troops are moving in on the rebel stronghold.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6851, 'move it!', 'used to tell someone to hurry:', 'Come on, Phil, move it!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6852, 'move off something/on (to something)', 'to change from one subject to another when talking or writing:', 'Let''s move off this subject now, all right?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6853, 'move on', 'to leave the place where you are staying and go somewhere else:', 'I''ve lived in this town long enough - it''s time to move on.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6854, 'move on', 'to start a new activity:', 'I''d done the same job for years and felt it was time to move on.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6855, 'move on', 'to accept that a situation has changed and be ready to deal with new experiences:', 'Since he and his girlfriend broke up, he''s been finding it difficult to move on.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6856, 'move on to bigger/better things', 'to get a better job or improve your life in some way:', 'I hear you''re leaving and moving on to better things.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6857, 'move out', 'to stop living in a particular home:', 'Her landlord has given her a week to move out.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6858, 'move someone/something in', 'If the police, army, or any group of people in authority move in, or if someone moves them in, they take control or attack, in order to deal with a difficult or dangerous situation:', 'When a company goes out of business, officials usually move in to take control.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6859, 'move the chains', 'to achieve a first down (= the first of four chances that a team on offence is given to advance the ball toward the opponent''s goal) in American football :', '"He is the kind of running back who can move the chains and pick up a lot of yards when we need them," the coach said.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6860, 'move the chains', 'to advance to the next stage of a project or situation:', 'Once we have approved the design of the new library, we can move the chains and start seeking bids from contractors.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6861, 'move the goalposts', 'to change the rules while someone is trying to do something in order to make it more difficult for them:', 'We''d almost signed the contract when the other guys moved the goalposts and said they wanted more money.', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6862, 'move to/towards sth', 'to change from a particular system, activity, etc. to another:', 'Businesses, consumers, and governments will have to make big changes in order to move to a low-carbon economy.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6863, 'move up', 'to increase in value, number, or amount:', 'Share prices move up and down depending on market conditions.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6864, 'move up', 'to get a more important job in a company or organization:', 'move up to sth He gave his first interview since moving up to the role of chairman.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6865, 'move with the times', 'to change and become more modern, because attitudes or fashions are changing:', 'We have to move with the times and market our products more aggressively.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6866, 'move/go in for the kill', 'to prepare to defeat someone in an argument or competition when that person is already in a weak position:', 'He asked her a couple of difficult questions and then went in for the kill.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6867, 'move/shift your arse!', 'a rude phrase used to tell someone to hurry up or to get out of your way', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6868, 'mow someone down', 'to kill people, usually in large numbers, by shooting them or driving a vehicle into them:', 'Three shoppers were mown down this afternoon when a drunken driver lost control of his car.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6869, 'much as', 'although:', 'Much as I would like to help you, I''m simply too busy at the moment.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6870, 'much less', 'and certainly not:', 'Tony can barely boil an egg, much less cook dinner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6871, 'much to someone''s delight, dismay, disappointment, surprise, etc.', 'used to say that someone is very surprised, happy, unhappy, etc. about something:', 'Much to her surprise, there were two police cars parked down the street.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6872, 'much/still less', 'used to make a negative statement stronger:', 'At the age of 14 I had never even been on a train, much less an aircraft.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6873, 'muck (something) out', 'to clean a place where a large animal lives, especially a stable, by removing the waste products and old straw:', 'She''d spent all morning mucking out the horses.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6874, 'muck in', 'to share the work that needs to be done:', 'She doesn''t mind mucking in with the rest of us when there''s work to be done.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6875, 'muck someone/something about/around', 'to behave in a silly way, or to treat someone or something in a careless way:', 'Stop mucking about with those ornaments, you''ll break something!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6876, 'muck something up', 'to spoil something completely, or do something very badly:', 'I really prepared for the interview because I didn''t want to muck it up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6877, 'mud sticks', 'said to mean that people are likely to believe something bad that is said about someone, even if it is not true', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6878, 'muddle along', 'to continue doing something with no clear purpose or plan:', 'Decide what you want in life - don''t just muddle along.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6879, 'muddle something up', 'to arrange things in the wrong order:', 'I''ve arranged the books alphabetically so don''t muddle them up.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6880, 'muddle someone/something up', 'to think that a person or thing is someone or something else because the two people or things are very similar:', 'I often muddle up Richard with his brother.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6881, 'muddle through', 'to manage to do something although you are not organized and do not know how to do it:', 'Sorry, but I can''t help you - you''ll just have to muddle through on your own.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6882, 'muddy the waters', 'to make a situation more confused and less easy to understand or deal with', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6883, 'mug (something) up', 'to study a subject quickly before taking an exam:', 'I need to mug up (on) my history before tomorrow''s exam.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6884, 'mug someone off', 'to make someone appear stupid, especially by deceiving them or treating them badly in a relationship:', 'Rebecca slammed Luke for mugging her off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6885, 'mull something over', 'to think carefully about something for a long time:', 'I need a few days to mull things over before I decide if I''m taking the job.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6886, 'mum''s the word', 'said when you tell someone, or agree with someone, to keep something a secret:', '"I''m not telling people generally yet." "OK, mum''s the word!"', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6887, 'murky/uncharted waters', 'a situation that is not well known and may be dangerous:', 'In the last two chapters of the book, she enters the murky waters of male sexuality.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6888, 'muscle in', 'to force your way into a situation and make certain you are included, although you are not wanted:', 'I hear Mark is muscling in on our meeting.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6889, 'music to your ears', 'something you are pleased to hear about:', 'When she said they would make a profit, it was music to Richard’s ears.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6890, 'muster something up', 'If you muster up a feeling of courage or energy, you try hard to find that quality in yourself because you need it in order to do something:', '[ + to infinitive ] She finally mustered up the courage to ask him for more money.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6891, 'muster your forces', 'to make great arrangements and efforts, usually to prepare for an attack or event:', 'The Welsh National Opera has mustered its forces to mount its second production of Tristan in only 14 years.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6892, 'mustn''t grumble', 'something you say to mean that your life is not bad and that you should not complain about it:', '"How''s it going then, Mike?" "Oh, not too bad. Mustn''t grumble."', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6893, 'mutton dressed as lamb', 'a way of describing an older woman who is dressed in a style that is more suitable for a younger woman:', 'Do you think this dress is too young-looking for me? - I don''t want to look like mutton dressed as lamb.', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6894, 'my (dear) boy', 'a friendly way of talking to a man:', 'Look here, my boy, this simply won''t do.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6895, 'my arse!', 'a rude phrase used to emphasize that you do not believe what someone has just said:', '"She said she had food poisoning." "Food poisoning, my arse! She just drank too much last night."', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6896, 'my ass!', 'a rude phrase used to emphasize that you do not believe or accept what someone has said:', '"Public holiday" my ass! I still have to work like any other day.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6897, 'my bad', 'used for saying that you accept that you are wrong or that something is your fault:', '"You brought the wrong book." "Okay, my bad. I''ll go get it."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6898, 'my foot', 'used to mean that you do not believe what another person has just told you:', '"He says his car isn''t working." "Not working my foot. He''s just too lazy to come."', 'idiom', '', 'informal, old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6899, 'my heart bleeds for someone', 'used to say that you feel great sadness for someone. This phrase is often used humorously to mean the opposite:', 'humorous John complains he only has two cars - my heart bleeds for him (= I certainly do not feel sadness about that)!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6900, 'my lips are sealed', 'said when you are promising to keep a secret:', '"Oh and please don''t tell him you saw me here." "Don''t worry. My lips are sealed."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6901, 'my point exactly', 'said in answer to something that someone has just said when you believe it yourself, or when you have said it yourself earlier:', '"So even if we got the funding, we still couldn''t get the project started." "My point exactly."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6902, 'my sweet', 'a way of talking to someone you love', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6903, 'my, (oh, my)', 'used to express surprise or pleasure:', 'My, this food is wonderful.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6904, 'naff off', 'used to rudely tell someone to go away because they are annoying you', '', 'phrasal verb', '', 'slang, old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6905, 'nag (away) at someone', 'If doubts or worries nag (away) at you, you think about them all the time:', 'The same thought has been nagging away at me since last week.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6906, 'nail a lie', 'to prove that something really is a lie', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6907, 'nail someone down', 'to make someone give you exact details or a firm decision about something:', 'They nailed him down to a specific time and place.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6908, 'nail something down', 'If you nail down an arrangement or decision, you decide and agree to the details of it:', 'After a five-hour meeting, we finally nailed down a deal.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6909, 'nail something down', 'to understand something completely, or to describe something correctly:', 'We haven''t been able to nail down the cause of the fire yet.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6910, 'nail something on', 'to make something very certain or definite:', 'Australia seem likely to get to the semis, and a win today would nail it on.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6911, 'nail your colours to the mast', 'to make it obvious what your opinions or plans are', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6912, 'nailing Jell-O to the wall', 'trying to give exact details for something that it is not possible to know about exactly:', 'Writing the history of this period is like nailing Jell-O to the wall.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6913, 'nailing jelly to the wall', 'trying to give exact details for something that it is not possible to know about exactly:', 'Writing the history of this period is like nailing jelly to the wall.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6914, 'name and shame', 'to publicly say that a person, group, or business has done something wrong:', 'The report names and shames companies that are not doing enough to fight industrial pollution.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6915, 'name names', 'to tell someone the names of people involved in something, especially an unpleasant, secret, or illegal activity:', 'If people are going to accuse their colleagues of racist acts, they should name names.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6916, 'name someone/something after someone/something', 'to give someone or something the same name as another person or thing:', 'Paul was named after his grandfather.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6917, 'name the day', 'to decide the date on which you are going to get married:', 'When are you going to name the day?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6918, 'name your poison', 'used to ask what type of alcoholic drink someone would like', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6919, 'narrow something down', 'to make a number or list of things smaller, by removing the things that are least important, necessary, or suitable:', 'We narrowed the list of candidates down from ten to three.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6920, 'near at hand', 'If something is near at hand, it is near enough to you for you to reach it:', 'I like to have my books near at hand when I''m working.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6921, 'near the knuckle', 'about sex and therefore likely to offend people:', 'Some of his jokes were a bit near the knuckle.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6922, 'nearly/almost fall off your chair', 'to be extremely surprised:', 'She nearly fell off her chair when she heard the news.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6923, 'nearly/almost have a heart attack', 'to be extremely surprised or shocked:', 'I almost had a heart attack when I found out how much the meal cost.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6924, 'necessity is the mother of invention', 'an expression that means that if you really need to do something, you will think of a way of doing it', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6925, 'neck and neck', 'If two competitors are neck and neck, they are level with each other and have an equal chance of winning.', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6926, 'need I say', 'obviously:', 'Need I say, I''m extremely sorry to hear the news about your father.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6927, 'need I say more?', 'said after a statement when you expect that someone can guess the result of what you have just said:', 'Tom was doing the cooking - need I say more?', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6928, 'need something like you need a hole in the head', 'to not need or want something at all:', 'Extra work? I need that like I need a hole in the head.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6929, 'need you ask!', 'used to say that the person asking you something already knows the answer, because it is expected:', '"Did he upset a lot of people at the meeting?" "Need you ask!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6930, 'need your head examined', 'If you tell someone they need their head examined, you think that that person is crazy because they have done something stupid or strange:', 'You need your head examined if you''re willing to spend that much on a pair of jeans.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6931, 'needless to say', 'as you would expect; added to, or used to introduce, a remark giving information that is expected and not surprising:', 'Needless to say, he''ll be off work for a while.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6932, 'neither here nor there', 'not important, or not connected with the subject being discussed:', 'Her age is neither here nor there – the real question is, can she do the job?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6933, 'net out', 'to be or produce a particular amount of money after tax and other costs have been paid:', 'The facility showed a gross loss of $2.8m, which, when set against investors'' deposits of £1.5m, netted out at $1.36m.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6934, 'net out', 'to be or have a particular amount at the end of a process:', 'We will net out with several hundred additional jobs over two years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6935, 'net sth out', 'to subtract a cost, etc. from an amount of money:', 'The company has suffered pressure from higher raw material costs and changes in a number of its markets. When these are netted out, earnings will stabilise.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6936, 'net sth down', 'to reduce an amount by subtracting tax and other costs:', 'In most cases, the interest rate paid will be the tax-free rate netted down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6937, 'never fear', 'do not worry:', 'Never fear, I''ll take good care of him.', 'idiom', '', 'old use, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6938, 'never hear the end of it', 'to have to listen for a long time to embarrassing or annoying talk:', 'If Mary gets that promotion, we’ll never hear the end of it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6939, 'never live something down', 'to be unable to stop feeling embarrassed about something you have done:', 'I wish I''d never opened my mouth in the meeting - I''m never going to live it down!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6940, 'never look a gift horse in the mouth', 'said to advise someone not to refuse something good that is being offered', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6941, 'never look back', 'to continue to be successful after doing something with a good result:', 'She never looked back after that first exhibition.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6942, 'never mind', 'used to tell someone not to worry about something because it is not important:', '"I''m sorry I lost that wallet you gave me." "Never mind, I can easily buy you another one."', 'idiom', 'A2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6943, 'never mind', 'used as a way of emphasizing that, although a particular thing is true, the one you have just mentioned is more important or interesting:', 'This is one of the best restaurants in the Northeast, never mind Boston.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6944, 'never mind that', 'despite the fact that:', 'He''s going on holiday for the third time this year, never mind that he has hardly any money left.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6945, 'never put off until tomorrow what you can do today', 'said to emphasize that you should not delay doing something if you can do it immediately', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6946, 'never say die', 'said to encourage people to keep trying', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6947, 'never the twain shall meet', 'said when two things or people are completely different, unsuitable for each other, or are unable to agree', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6948, 'new/fresh blood', 'people who join an organization and who can provide new ideas and energy:', 'The company has brought in some new blood in an effort to revive its fortunes.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6949, 'news to someone', 'to be very surprising to someone:', 'She’s expecting a baby? That’s news to me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6950, 'next door but one', 'not in the closest house, building, room, or place but in the one that is next to it:', 'Her sister lives next door but one to a famous singer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6951, 'nibble (away) at something', 'to slowly reduce something:', 'Even when inflation is low, it nibbles away at people''s savings, reducing their value considerably over several years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6952, 'nice one!', 'something that you say when you have just heard that someone has done something you think is good:', '"Graham''s brought some champagne along to mark the occasion." "Oh, nice one, Graham!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6953, 'nice work if you can get it', 'something you say about an easy way of earning money that you would like to do if you could:', 'She got one million dollars for appearing on television for five minutes - (that''s) nice work if you can get it!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6954, 'night after night', 'every night:', 'The howling of wild animals kept him awake night after night.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6955, 'night after night', 'every evening:', 'She stayed in night after night, waiting for him to call.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6956, 'night and day', 'all the time:', 'They''ve worked night and day to publicize their campaign.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6957, 'nine times out of ten', 'almost always:', 'Nine times out of ten, you can fix it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6958, 'nineteen/ten to the dozen', 'If you are talking nineteen/ten to the dozen, you are talking very quickly and without stopping.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6959, 'ninety-nine times out of a hundred', 'almost always:', 'Ninety-nine times out of a hundred everything''s fine, but sometimes we have problems.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6960, 'nip something in the bud', 'to stop something before it has an opportunity to become established:', 'Many serious illnesses can be nipped in the bud if they are detected early enough.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6961, 'no big deal', 'infmlnot important:', 'I’d like to work out today, but if I can’t it’s no big deal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6962, 'no biggie', 'used to say that something is not a serious problem:', 'Because the sunglasses are cheap, losing a pair is no biggie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6963, 'no dice', 'something that people say when you may not or cannot do something:', 'I asked if we could go to the party, but Mom said no dice.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6964, 'no doubt', 'certainly:', 'He will no doubt tell you all about his vacation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6965, 'no end', 'very much:', 'It would please Granny no end if you wrote to her occasionally.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6966, 'no end of something', 'a lot of:', 'If you don''t want the job, there''s no end of people willing to take your place.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6967, 'no expense is spared', 'If no expense is spared in arranging something, a lot of money is spent to make it extremely good:', 'No expense was spared in making the guests feel comfortable.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6968, 'no fear!', 'certainly not:', '"Are you coming to the concert?" "No fear!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6969, 'no fewer than', 'used to show that you consider a number to be surprisingly large:', 'No fewer than five hundred delegates attended the conference.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6970, 'no flies on someone', 'If you say there are no flies on someone, you mean that they cannot easily be deceived.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6971, 'no go', 'not allowed or not acceptable:', 'Shorts are no go here – you have to wear long pants and shoes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6972, 'no great shakes', 'not very good:', 'I''m afraid I am no great shakes as a cook/at cooking!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6973, 'no hard feelings', 'no feeling of being upset:', '"I''m really sorry." "Don''t worry – No hard feelings."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6974, 'no harm no foul', 'used for saying that no damage has been done by someone''s mistake :', 'It was a joke, the joke went wrong, he apologized, so no harm no foul.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6975, 'no ifs or buts', 'something that you say to a child to stop them arguing with you when you want them to do something:', 'I want no ifs or buts - just get on and tidy your room now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6976, 'no ifs, ands, or buts', 'something that you say to a child to stop any argument when you want him or her to do something:', 'I want no ifs, ands, or buts - just finish eating your food now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6977, 'no kidding', 'really or honestly:', 'No kidding, there were about 200 people at the party.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6978, 'no laughing matter', 'very serious:', 'Being late for a job interview is no laughing matter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6979, 'no less', 'used to show the importance of someone or something:', 'Who should arrive at the party but the prime minister, no less!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6980, 'no less than', 'used to show your surprise at a large number:', 'There were no less than a thousand people there buying tickets.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6981, 'no longer', 'in the past but not now:', 'This building is no longer used.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6982, 'no matter', 'it is not a problem:', '"I don''t have that form with me." "No matter - here''s another."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6983, 'no matter what, when, why, etc.', 'used to emphasize that something is always true, or that someone must do something:', 'I never seem to lose any weight, no matter how hard I try.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6984, 'no mean achievement/feat', 'a great achievement:', 'Getting the job finished on time was no mean achievement.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6985, 'no mean something', 'used to say a person is very good at a certain activity:', 'He''s no mean cook.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6986, 'no more Mr Nice Guy', 'something that is said when someone has decided to stop thinking about the wishes and feelings of other people:', 'I''ve had enough of people taking advantage of me. From now on it''s no more Mr Nice Guy.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6987, 'no news is good news', 'said to make someone feel less worried when they have not received information about someone or something, because if something bad had happened, they would have been told about it:', 'We haven''t heard anything from the hospital today, but I suppose no news is good news.', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6988, 'no prizes for guessing something', 'something you say when it is very easy to guess something:', 'No prizes for guessing where Daniel is.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6989, 'no problem', 'said to show that you will or can do what someone has asked you to:', '"Can you get me to the station by 11.30?" "No problem."', 'idiom', 'A2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6990, 'no problem', 'used as a friendly answer when someone thanks you for something you have done:', '"Thanks for the lift." "No problem."', 'idiom', 'A2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6991, 'no room for something', 'If you say there is no room for a feeling or type of behaviour, you mean it is not acceptable:', 'In a small company like this, there is no room for laziness.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6992, 'no shit!', 'an expression of surprise, often used as a joke when someone has told you something that is very obvious:', '"This is hard work!" "No shit!"', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6993, 'no sir', 'certainly not:', 'I''m not going to ride the subway, no sir!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6994, 'no something to speak of', 'not enough of something to make it worth talking about:', 'There was no snow to speak of this winter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6995, 'no sooner ... than', 'used to show that one thing happens immediately after another thing:', 'No sooner had I started mowing the lawn than it started raining.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6996, 'no sooner said than done', 'used to say that you will do something immediately', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6997, 'no such luck', 'used when you are disappointed that something that you hoped for did not happen :', 'I was rather hoping it would rain today and I wouldn''t have to go for a walk, but no such luck.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6998, 'no sweat', 'If you say that something is no sweat, you mean that it will not be difficult or cause problems:', '"Can you fix my car for me?" "No sweat!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (6999, 'no thanks to someone', 'despite:', 'It''s no thanks to you that I got there on time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7000, 'no way', 'used to tell someone that something is impossible:', 'I''m sorry but there''s no way we can help you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7001, 'no way', 'used to say no in a forceful way:', '"Come on, let me borrow your bike." "No way!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7002, 'no way', 'used to express surprise:', 'When someone tells him something interesting, he says, "No way!" as if he is a teen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7003, 'no wonder', 'it is not surprising:', 'No wonder the children are excited - this is the first time they''ve been abroad.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7004, 'no/not enough room to swing a cat', 'said about a place or space that is very small', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7005, 'nod off', 'to begin sleeping, especially not intentionally:', 'After our busy day, we both sat and nodded off in front of the TV.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7006, 'none but', 'only:', 'None but a dedicated scientist would want to read such a detailed report.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7007, 'none other than someone/something', 'said when you want to show that someone or something is a surprising or exciting choice or example:', 'The first speech was given by none other than Clint Eastwood.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7008, 'none the wiser', 'to not understand something:', 'I read the computer manual, but I’m still none the wiser.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7009, 'none the wiser', 'To be none the wiser also means to not be aware of something:', 'The health department gave the restaurant a warning, but the customers were none the wiser.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7010, 'none the worse (for something)', 'not damaged or harmed despite something:', 'It was cold and windy during the parade but we were none the worse for the weather.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7011, 'none the worse, better, richer, etc.', 'not any worse, better, richer, etc. than before:', 'Luckily, the horse seemed none the worse for his fall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7012, 'none to speak of', 'very little of something:', '"Did you get much rain while you were in Singapore?" "None to speak of."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7013, 'none too', 'not very:', 'He seemed none too happy/pleased at the prospect of meeting the family.', 'idiom', 'C2', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7014, 'nooks and crannies', 'small spaces in something or parts of something that are difficult to reach:', 'These fish like to hang out under coral heads, ledges, or in other nooks and crannies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7015, 'nooks and crannies', 'the parts of something that are hidden or difficult to find:', 'There''s lots of great information hidden in the nooks and crannies of our site.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7016, 'north of something', 'used to say that an amount is more than the stated amount:', 'The share price is expected to rise north of $20.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7017, 'nose ahead', 'to get into a position that is slightly in front of someone or something else:', 'The company has nosed ahead of its closest rivals, claiming 33% market share.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7018, 'nose in the air', 'used to describe the way someone behaves when they think they are better than other people and do not want to speak to them:', 'She walked past me with her nose in the air.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7019, 'nose something out', 'to discover something by searching carefully:', 'He soon nosed out the details of the accident by talking to people and making some phone calls.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7020, 'nose up', 'to increase slowly or by a small amount:', 'Savings rates have been nosing up during the past few months.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7021, 'not (do something) for anything (in the world)', 'infml to not do something under any conditions:', 'It was a fantastic party – I wouldn’t have missed it for anything.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7022, 'not (too) bad', 'fairly good or satisfactory:', '"How are things?" "Not too bad, thanks."', 'idiom', 'A2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7023, 'not a bit of it', 'said when a situation or event is very different from what you expected:', 'I thought he would be sorry, but not a bit of it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7024, 'not a chance', 'there is no possibility:', '"Do you think I could pass for a 21-year-old?" "Not a chance!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7025, 'not a dicky bird', 'nothing at all:', 'We haven''t heard a dicky bird from (= spoken to or received a letter from) Riza recently.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7026, 'not a dry eye in the house', 'used to mean that all the people at a particular place felt very emotional about what they had seen or heard and many of them were crying', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7027, 'not a hair out of place', 'If someone does not have a hair out of place, their appearance is very neat:', 'She was as immaculate as ever - not a hair out of place.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7028, 'not a happy camper', 'infmlvery annoyed or upset:', 'The dog is sick, Jessie sprained her ankle, and the car won’t start – I am not a happy camper!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7029, 'not a hundred percent', 'not feeling completely well:', 'I''m better than I was, but I''m still not a hundred percent.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7030, 'not a moment too soon', 'used to say that something happened when it was almost too late:', 'Help arrived - and not a moment too soon.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7031, 'not a red cent', 'no money at all:', 'It turns out his paintings aren''t worth a red cent.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7032, 'not a sausage', 'nothing:', '"Did you find anything out?" "No, not a sausage."', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7033, 'not add up', 'If a situation does not add up, there is no reasonable or likely explanation for it:', 'Why would she disappear the day before her holiday? It just doesn''t add up.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7034, 'not agree with someone', 'If a type of food or drink does not agree with you, it makes you feel slightly ill:', 'Those onions I ate didn''t agree with me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7035, 'not all it''s cracked up to be', 'to not be as good as people have said:', 'This software isn’t all it''s cracked up to be.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7036, 'not all roses', 'If a situation is not all roses, there are unpleasant things to deal with as well as the pleasant ones:', 'Being in a relationship is not all roses, you know.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7037, 'not all that', 'not very:', 'I''m not all that excited about going camping.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7038, 'not amount to much', 'to not become successful or important:', 'He’s lazy, and he’ll never amount to anything.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7039, 'not anywhere near', 'very much less:', 'He isn''t anywhere near as popular as he used to be.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7040, 'not anywhere to be found', 'impossible to see or find:', 'We searched the house, but it wasn''t anywhere to be found.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7041, 'not at all', 'used as a polite reply after someone has thanked you:', '"Thanks for helping." "Not at all."', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7042, 'not at all', 'used to say "no" or "not" strongly:', '"I hope it wasn''t too much hassle for you." "No, not at all."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7043, 'not at any price', 'used to say that you would never do something:', 'I wouldn''t invite her again at any price.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7044, 'not bad', 'very good:', 'He was best in his age group - not bad, eh?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7045, 'not bat an eye/eyelash', 'to show no sign of surprise or worry when something unexpected happens:', 'She told him she''d spent all her savings but he didn''t bat an eye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7046, 'not bat an eyelid', 'to show no sign of surprise or worry when something unexpected happens:', 'She told him she''d spent all her savings but he didn''t bat an eyelid.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7047, 'not be a happy camper', 'to be annoyed about a situation:', 'Her computer crashed an hour ago and she''s lost a morning''s work - she''s not a happy camper at the moment.', 'idiom', '', 'informal humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7048, 'not be a patch on something', 'to be much less good than something:', 'This new washing machine isn''t a patch on our old one.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7049, 'not be a pretty sight', 'to be ugly or unpleasant to look at:', 'I can tell you, first thing in the morning he''s not a pretty sight.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7050, 'not be all fun and games', 'If an activity is not all fun and games, parts of it are difficult or unpleasant:', 'It''s not all fun and games being a tour guide.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7051, 'not be as black as you are painted', 'an old-fashioned phrase used to say that you are not as bad as people say you are, which may be considered offensive because it suggests that it is bad to have dark skin', '', 'idiom', '', 'old-fashioned, offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7052, 'not be beyond the wit of man/someone', 'to be possible to achieve:', 'It shouldn''t be beyond the wit of man to arrange for them both to be there at the same time.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7053, 'not be born yesterday', 'to not be stupid or easy to deceive:', 'You don''t fool me - I wasn''t born yesterday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7054, 'not be carved/etched in stone', 'to not be fixed and able to be changed:', 'These are just a few ideas - nothing is carved in stone yet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7055, 'not be cut out for something', 'to not be the right type of person for something:', 'I''m not cut out for an office job.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7056, 'not be in someone''s vocabulary', 'You say that a particular quality is not in your vocabulary if you never show it or experience it:', 'Did you say "tact"? The word isn''t in his vocabulary!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7057, 'not be in the business of something', 'If a person or organization is not in the business of doing something considered wrong, they do not normally do it:', 'The intelligence agency is not in the business of routinely monitoring the activities of law-abiding citizens.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7058, 'not be in the same league', 'to be not as good as someone or something else:', 'Her latest movie is quite watchable but it''s not in the same league as her first two epics.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7059, 'not be just a pretty face', 'If someone is not just a pretty face, they are not only attractive but also intelligent:', '"How did you know that?" "Well, I''m not just a pretty face, you know."', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7060, 'not be on speaking terms', 'If you are not on speaking terms with someone, you refuse to speak to them because you are angry with them:', 'They had an argument last night and now they''re not on speaking terms (with each other).', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7061, 'not be set/carved in stone', 'to be able to be changed:', 'These are just a few ideas - nothing is set in stone yet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7062, 'not be short of a bob or two', 'to be rich:', 'Did you see his car? He''s not short of a bob or two!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7063, 'not be someone''s cup of tea', 'If something is not your cup of tea, it is not the type of thing that you like:', 'Thanks for inviting me, but ballet isn''t really my cup of tea.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7064, 'not be someone''s day', 'If it is not your day, you are having a difficult or unpleasant day:', 'This really isn''t my day - my wallet was stolen and now I''ve lost my car keys.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7065, 'not be the end of the world', 'If something is not the end of the world, it will not cause very serious problems:', 'I''m really hoping to win, but it won''t be the end of the world if I don''t.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7066, 'not be the marrying kind', 'If a man is not the marrying kind, he does not want to be married. People sometimes use this phrase to mean that the man is gay.', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7067, 'not be thinking straight', 'to not be thinking clearly or using good judgment:', 'I''m sorry, that was a stupid thing to do - I wasn''t thinking straight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7068, 'not be up to much', 'to not be of good quality:', 'The food wasn''t up to much.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7069, 'not believe your eyes', 'to be very surprised:', 'I could not believe my eyes when I saw the garden in full bloom.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7070, 'not believe your eyes/ears', 'to be so surprised by what you see or hear that you think you are imagining it:', 'I couldn''t believe my ears when she said they were getting divorced.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7071, 'not believe your luck', 'to be very surprised and very pleased', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7072, 'not blink', 'to not show any shock or surprise:', 'When he was told I was expecting twins, Harry didn''t even blink.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7073, 'not break your stride', 'to not stop walking or running at the same speed:', 'Without pausing for breath or breaking her stride, she pushed open the door of his private office.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7074, 'not bring yourself to do something', 'to not be able to force yourself to do something that you think is unpleasant:', 'I just couldn''t bring myself to talk to him about it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7075, 'not by a long shot', 'not in any way:', 'It wasn''t as good as his first book - not by a long shot.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7076, 'not by any manner of means', 'not in any way:', 'I''m not satisfied with his excuse - not by any manner of means.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7077, 'not by any stretch of the imagination', 'even if you try, it is still difficult to accept:', 'By no stretch of the imagination could you think of her as a real artist.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7078, 'not care for someone/something', 'to not like something or someone:', 'I have to say I don''t much care for modern music.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7079, 'not care/give a fig', 'to not be at all worried by or interested in something:', 'They can say what they like. I don''t give a fig.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7080, 'not care/give a sod', 'to not be worried about other people''s opinions or actions:', 'I''m leaving and I don''t give a sod (about) what Margaret thinks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7081, 'not care/give tuppence', 'to not care about something or someone in any way', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7082, 'not care/give two hoots', 'to not care about something or someone:', 'I don''t give two hoots what she thinks.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7083, 'not come cheap', 'If you say that something does not come cheap, you mean that it is of good quality and is therefore expensive:', 'If you want a qualified accountant, their services don''t come cheap.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7084, 'not content with something/doing something', 'in addition to something wrong or unpleasant you have done:', 'Not content with having upset my parents, he then insulted my sister!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7085, 'not cricket', 'If behaviour is not cricket, it is not fair, honest or moral:', 'It''s just not cricket to lie to a friend.', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7086, 'not cut it', 'to not be able to deal with problems or difficulties satisfactorily:', 'We were playing against a more experienced team, and we just couldn''t cut it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7087, 'not darken someone''s door', 'used to tell someone to never come back to a place:', 'Never darken my door again!', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7088, 'not do someone any favors', 'to do something that is likely to have a bad effect on you or on another person:', 'You''re not well, and you''re not doing yourself any favors by taking on extra work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7089, 'not do someone any favours', 'to do something that is likely to have a bad effect on you or on another person:', 'You''re not well, and you''re not doing yourself any favours by taking on extra work.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7090, 'not do things by halves', 'If someone does not do things by halves, they put a lot of effort and enthusiasm into doing things, often more than is necessary:', '"I didn''t realize you were decorating the whole house." "Oh, we don''t do things by halves round here."', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7091, 'not for a moment', 'used to say that you do not think or do something at all:', 'I don''t believe that story for a moment.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7092, 'not for one minute', 'certainly not:', 'I''m not suggesting for one minute that she meant to cause any trouble.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7093, 'not for the squeamish', 'used to say that something is unpleasant, and will upset people who are squeamish:', '"The Silence of the Lambs" is an entertaining movie but is not for the squeamish.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7094, 'not for the world', 'never; not in any situation:', 'If I took that job I''d have to leave the kids and I wouldn''t do that for the world.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7095, 'not get a word in edgeways', 'to not be able to say anything because someone else is talking all the time:', 'Rosa was talking so much that nobody else could get a word in edgeways!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7096, 'not get a word in edgewise', 'to not be able to say anything because someone else is talking all the time:', 'Roz was talking so much that nobody else could get a word in edgewise!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7097, 'not get anywhere', 'to not make progress toward a goal:', 'His parents tried to talk him out of joining the army, but they didn’t get anywhere.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7098, 'not get over something', 'When you say that you can''t get over something, you mean that you are very surprised by it:', 'I can''t get over the way he behaved at your party - it was appalling!', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7099, 'not get to first base', 'to not be able to start doing what you intend to do:', 'We need financing for this project, but we can’t get to first base with the banks.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7100, 'not get/go anywhere', 'If you are not getting/going anywhere, you are not improving or advancing a particular situation:', 'I''ve been sorting out my study all day, but it''s such a mess I don''t feel I''m getting anywhere.', 'idiom', 'B2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7101, 'not give a monkey''s', 'If you don''t/couldn''t give a monkey''s about something, you are not at all worried by it:', '"Chrissie won''t like it." "I don''t give a monkey''s."', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7102, 'not give a shit', 'to not be interested in or worried about something or someone:', 'I don''t give a shit what he thinks.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7103, 'not give a tinker''s cuss', 'to not be interested in or worried about something or someone:', 'I couldn''t give a tinker''s cuss about what they think.', 'idiom', '', 'old-fashioned informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7104, 'not give a tinker''s damn', 'to not be interested in or worried about something or someone:', 'I don''t give a tinker''s damn about what they think.', 'idiom', '', 'old-fashioned informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7105, 'not give much for someone''s chances', 'to not believe someone will succeed:', 'I wouldn''t give much for his chances in the next race.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7106, 'not give someone the time of day', 'to not be friendly to someone and not speak to or help that person:', 'He kept pestering me to go out with him, but I wouldn’t give him the time of day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7107, 'not give tuppence for something', 'to think that something will not succeed:', 'I wouldn''t give tuppence for their chances of winning the match.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7108, 'not give/budge/move an inch', 'to not change your opinion:', 'She''s definite that she wants to do it, and she''ll not give an inch, however hard you try to persuade her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7109, 'not give/care a damn', 'used as a way of saying you do not care about something, especially the annoying things that someone else is doing or saying:', 'I don''t give a damn what he thinks of me!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7110, 'not give/care a toss', 'to not be worried at all by something:', 'I don''t give a toss what he thinks.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7111, 'not go much on something', 'to dislike something:', 'I don''t go much on white wine.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7112, 'not go there', 'to not start to think about or discuss a subject:', '"Then there''s the guilt I feel about leaving her for seven hours every day." "Don''t even go there!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7113, 'not half', 'used in spoken English to express a positive statement more strongly:', 'It wasn''t half crowded in the club last night (= it was very crowded).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7114, 'not half as', 'not nearly as:', 'It wasn''t half as good as that other restaurant we went to.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7115, 'not have a bad/dishonest/racist, etc. bone in your body', 'to not be bad, dishonest, racist, etc. in any way:', 'Jimmy did not have a bad bone in his body.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7116, 'not have a bar of something', 'to refuse to accept or have anything to do with something:', 'Karen called her mother and asked her to come and stay, but Mum wouldn''t have a bar of it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7117, 'not have a bean', 'to have no money', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7118, 'not have a cat in hell''s chance', 'to be completely unable to achieve something:', 'They haven''t a cat in hell''s chance of getting over the mountain in weather like this.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7119, 'not have a civil word to say about someone', 'to not be able to think of anything good to say about someone', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7120, 'not have a clue', 'to have no knowledge about something, or to be unable to remember something:', 'I don’t have a clue what I did with my baseball glove.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7121, 'not have a clue/have no clue', 'to be completely unable to guess, understand, or deal with something:', '"Who invented algebra?" "I don''t have a clue."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7122, 'not have a hope in hell', 'to have no possibility of doing or achieving something:', 'We were so outclassed - we didn''t have a hope in hell of winning.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7123, 'not have a leg to stand on', 'to be in a situation in which you cannot prove something:', 'If you have no witnesses, you don''t have a leg to stand on.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7124, 'not have a penny to your name', 'to be very poor', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7125, 'not have a pot to piss in', 'to be very poor:', 'Any help we can offer them will be appreciated. They don''t have a pot to piss in.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7126, 'not have a prayer', 'to have no chance of succeeding:', 'She hasn''t a prayer of winning the competition.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7127, 'not have a snowball''s chance in hell', 'to have no chance of succeeding:', 'If he can''t afford a good lawyer, he doesn''t have a snowball''s chance in hell of winning the case.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7128, 'not have a/the ghost of a chance', 'to have no chance at all:', 'They don''t have a ghost of a chance of winning.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7129, 'not have any of it', 'to be completely unwilling or to refuse:', 'I asked him to help out, but he wasn''t having any of it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7130, 'not have much upstairs', 'to not be very intelligent:', 'People think he hasn''t got much upstairs but in fact he is very intelligent when it comes to computers.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7131, 'not have the foggiest (idea)', 'to not know or understand something at all:', 'I didn''t have the foggiest idea what he was talking about.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7132, 'not have the heart to do something', 'to feel unable to do something because you feel it would be unkind:', 'She asked me to go with her and I didn''t have the heart to refuse.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7133, 'not have the remotest idea', 'to not know at all:', '"Who''s that?" "I haven''t the remotest idea."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7134, 'not have the stomach for something', 'to not feel brave or determined enough to do something unpleasant:', 'I didn''t have the stomach for another fight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7135, 'not hear of something', 'If you say you will not hear of something, you mean you will not allow it, usually when you want to do something good for someone:', 'I wanted to pay but she wouldn''t hear of it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7136, 'not hear the end/last of something', 'to be told repeatedly about something:', 'We''ll never hear the last of it if they win that competition.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7137, 'not hold a candle to someone/something', 'to not be as good as someone or something else:', 'Her latest book can’t hold a candle to her earlier works.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7138, 'not hold with something', 'to not approve of an idea or activity', '', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7139, 'not in a month of Sundays', 'If you say that something will not happen in a month of Sundays, you mean that it is very unlikely to happen:', 'He''s never going to get that finished in a month of Sundays!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7140, 'not in the biblical sense', 'If you say you know someone but not in the biblical sense, you mean you have not had sex with them:', '"Did you know her?" "Yes - not in the biblical sense, of course."', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7141, 'not in the least', 'not in any way:', '"Are you dissatisfied with the results?" "Not in the least."', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7142, 'not in the same league', 'not nearly as good as something or someone else:', 'She''s a brilliant golfer - I''m not in the same league.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7143, 'not know someone from Adam', 'to have never met someone and not know anything about them:', 'Why should she lend me money? She doesn''t know me from Adam.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7144, 'not know the first thing about something', 'to know nothing about a subject:', 'I''m afraid I don''t know the first thing about car engines.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7145, 'not know the half of it', 'If someone does not know the half of it, they know that a situation is bad but do not know how serious it is:', '"I hear things aren''t going too well at work." "You don''t know the half of it!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7146, 'not know the meaning of the word', 'If you are talking about a quality or an activity and you say that someone doesn''t know the meaning of the word, you mean they do not have that quality or have no experience of that activity:', 'Work? He doesn''t know the meaning of the word!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7147, 'not know what has hit you', 'to be shocked and surprised because something unpleasant suddenly and unexpectedly happens to you:', 'You wait till he starts working for Michael - he won''t know what''s hit him!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7148, 'not know what hit you', 'to be suddenly shocked and confused by something:', 'When he said I was fired, I didn’t know what hit me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7149, 'not know what hit you', 'to feel shocked or confused because something bad has happened to you suddenly when you were not expecting it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7150, 'not know what someone sees in someone/something', 'to not understand why someone likes a particular person or thing:', 'He''s so boring - I don''t know what she sees in him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7151, 'not know where to put yourself', 'to feel very embarrassed:', 'And then he started to sing. Well, I didn''t know where to put myself.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7152, 'not know where/which way to turn', 'to not know what to do or who to ask for help:', 'When both her parents died, she didn''t know which way to turn.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7153, 'not know whether to laugh or cry', 'to not know how to react in a particular situation:', 'When she told me they were getting married I didn''t know whether to laugh or cry.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7154, 'not know whether you are coming or going', 'to be in a very confused state:', 'I''m so busy, I don''t know whether I''m coming or going.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7155, 'not know your arse from your elbow', 'an offensive phrase meaning to be stupid and unable to understand very simple things', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7156, 'not know your ass from your elbow', 'a rude phrase meaning to be stupid and unable to understand very simple things:', 'My boss has proven time and again that he doesn''t know his ass from his elbow.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7157, 'not last long', 'to fail or be unsuccessful very soon:', 'You won''t last long in your job if you carry on being so rude to the customers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7158, 'not lift a finger', 'to not make any effort:', 'He just watches TV and never lifts a finger to help with the dishes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7159, 'not lift/raise a finger', 'to not make any effort to help:', 'He never lifts a finger to help with the housework.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7160, 'not long for this world', 'If someone is not long for this world, they will die soon.', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7161, 'not make any difference', 'to not change a situation in any way:', 'You can ask him again if you want, but it won''t make any difference - he''ll still say no.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7162, 'not matter tuppence', 'to not be important:', 'It doesn''t matter tuppence what you think.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7163, 'not mince (your) words', 'to say what you mean clearly and directly, even if you upset people by doing this:', 'The report does not mince words, describing the situation as "ludicrous".', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7164, 'not miss a beat', 'to not pause or show any uncertainty, usually when this is surprising:', '"That''s what I thought," replied Olivia, without missing a beat.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7165, 'not miss a beat', 'to do something without any mistakes or failures:', 'The player hasn''t missed a beat this year, scoring three touchdowns in his first three games.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7166, 'not miss a trick', 'said about someone who never fails to notice and take advantage of a good opportunity:', 'Jonathan doesn''t miss a trick! If there''s a bargain to be had, he''ll find it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7167, 'not miss much', 'said when something you failed to see or experience was not important or special:', '"I didn''t manage to see that programme." "Don''t worry, you didn''t miss much."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7168, 'not miss/skip a beat', 'to not pause or show any uncertainty, usually when this is surprising:', '"That''s what I thought," replied Olivia, without missing a beat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7169, 'not miss/skip a beat', 'to do something without any mistakes or failures:', 'The player hasn''t missed a beat this year, scoring three touchdowns in his first three games.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7170, 'not move a muscle', 'to stay completely still:', 'She sat without moving a muscle as the nurse put the needle in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7171, 'not much cop', 'not very good:', 'His last book wasn''t much cop.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7172, 'not on your life!', 'said as a way of strongly refusing someone''s suggestion or request:', '"So you''re going to bring Kev, are you?" "Not on your life!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7173, 'not pull any/your punches', 'to speak in an honest way without trying to be kind:', 'Her image is that of an investigative reporter who doesn''t pull any punches.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7174, 'not put a foot wrong', 'to not make any mistakes', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7175, 'not put it past someone (to do something)', 'to not be surprised if someone does something bad, because it is a typical thing for that person to do:', 'Perhaps Helena told him - I wouldn''t put it past her.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7176, 'not put something down', 'If you cannot put a book down, you are unable to stop reading it until you reach the end:', 'It was so exciting from the first page I couldn''t put it down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7177, 'not say boo', 'to say nothing:', 'You didn''t say boo to me about going to your mother''s this weekend.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7178, 'not say boo', 'to be very nervous and easily frightened', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7179, 'not see beyond something', 'to have all your attention on something and therefore be unable to consider other things:', 'The government cannot see beyond next year''s election.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7180, 'not see hide nor hair of someone', 'to not see someone at all over a period of time:', 'I haven''t seen hide nor hair of her since last Friday.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7181, 'not see someone for dust', 'used to describe someone leaving quickly in order to avoid something:', 'If you let him know that Margaret''s coming, you won''t see him for dust.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7182, 'not see the forest for the trees', 'to be unable to get a general understanding of a situation because you are too worried about the details', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7183, 'not see the wood for the trees', 'to be unable to get a general understanding of a situation because you are too worried about the details', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7184, 'not see/look, etc. beyond/past the end of your nose', 'to only consider what is very close to you, what is very obvious, or what is happening in the near future:', 'In financial planning you need to look beyond the end of your nose.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7185, 'not set the world on fire', 'to not be very exciting or successful:', 'He has a nice enough voice but he''s not going to set the world on fire.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7186, 'not sit well with someone', 'to be difficult for someone to agree with or accept:', 'The principal''s decision did not sit well with many parents.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7187, 'not sleep a wink', 'to not sleep at all:', 'I didn''t sleep a wink last night with all that noise.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7188, 'not so much', 'used to refer back to something that has been mentioned, saying that it is less true for someone or something else :', 'If you like it, fine, but for me, not so much.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7189, 'not so much something as something', 'If you say that something is not so much one thing as something else, you mean it is more the second thing:', 'They''re not so much lovers as friends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7190, 'not so shabby/not too shabby', 'used for saying that something is good:', 'It was a not so shabby week for the team, who had three wins.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7191, 'not soil your hands', 'to not become involved in something unpleasant or bad:', 'These were top lawyers, the kind who wouldn''t normally soil their hands with police work or criminal law.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7192, 'not stand any nonsense', 'to refuse to accept bad or silly behaviour:', 'The new teacher won''t stand any nonsense.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7193, 'not suffer fools gladly', 'to have very little patience with people who you think are stupid or have stupid ideas', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7194, 'not take a blind bit of notice', 'to pay no attention to something:', 'He didn''t take a blind bit of notice of what I said.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7195, 'not take kindly to something', 'to not like something:', 'After years of being looked after by his mother, he didn''t take kindly to being told to cook for himself.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7196, 'not take something lying down', 'to refuse to be treated badly by someone:', 'He can''t treat you like that! Surely you''re not going to take that lying down!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7197, 'not take your eyes off someone/something', 'to not stop looking at someone or something:', 'He was so handsome - I couldn''t take my eyes off him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7198, 'not that', 'used to say you are not suggesting something:', 'She wouldn''t tell me how much it cost - not that I was really interested.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7199, 'not that', 'used to say you do not think something is important:', 'Not that I mind, but why didn''t you call yesterday?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7200, 'not that I know of', 'used when answering a question to mean that, judging from the information you have, the answer is no:', '"Is she especially unhappy at school?" "Not that I know of."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7201, 'not the done thing', 'not socially acceptable:', 'Smoking during a meal is not the done thing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7202, 'not the end of the world', 'not the worst thing that could happen:', 'We’re hoping to win, but if we finish second it won’t be the end of the world.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7203, 'not the least', 'used for emphasis with nouns:', 'I haven''t the least idea (= I do not know) who he was.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7204, 'not the same', 'not as good:', 'You can make shortbread with margarine instead of butter, but it isn''t the same.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7205, 'not the thing to do', 'not socially acceptable:', 'Smoking during a meal is not the thing to do.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7206, 'not think much of someone/something', 'to have a low opinion of someone or something:', 'I don’t think much of this techno music.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7207, 'not think straight', 'to be unable to use your mind in an effective way:', 'I was so tired, I couldn''t think straight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7208, 'not think twice', 'to do something immediately, without considering if it is a good idea:', 'They didn''t think twice about laying off hundreds of employees.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7209, 'not to be outdone', 'not wanting someone else to do something better than you:', 'Pat was wearing an outrageous purple dress, so, not to be outdone, I put on my new gold suit.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7210, 'not to be sneezed at', 'If you say that something, especially an amount of money, is not to be sneezed at, you mean that it is a large enough amount to be worth having:', 'Well, a five percent pay increase means an extra $700 a year, which is not to be sneezed at!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7211, 'not to be sniffed at', 'valuable or worth having:', 'A £2 million profit is not to be sniffed at.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7212, 'not to mention', 'used when you want to emphasize something that you are adding to a list:', 'He''s one of the kindest and most intelligent, not to mention handsome, men I know.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7213, 'not to put too fine a point on', 'to be completely direct and honest:', 'I think she''s wrong - not to put too fine a point on it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7214, 'not to say', 'and possibly even:', 'It would be unwise, not to say stupid, to leave your first job after only six months.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7215, 'not to worry', 'said to show that you are not worried or upset because something has gone wrong or something unexpected has happened:', 'Not to worry - maybe you''ll be able to come next week instead.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7216, 'not trust someone an/one inch', 'to not trust someone at all:', 'Make sure you tell him as little as possible about what happened. And don''t trust him an inch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7217, 'not turn a hair', 'to not show any emotion when you are told something bad or when something bad happens:', 'I was expecting him to be horrified when he heard the cost but he didn''t turn a hair.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7218, 'not until', 'not before a stated time or event:', 'Don’t move until I tell you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7219, 'not waste words', 'If someone does not waste words, they talk only about what is important using as few words as possible:', 'He explained the whole system in about 30 seconds - he doesn''t waste words, does he?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7220, 'not worth the paper something is printed/written on', 'If a document or agreement is not worth the paper it is written/printed on, it is of very little value.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7221, 'not your day', 'a bad day when things do not happen as you would like them to:', 'I missed my bus and forgot my glasses – I guess it’s just not my day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7222, 'not yourself', 'not feeling well or not acting in your usual way:', 'I''m sorry for crying – I''m not myself today.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7223, 'not/never in your wildest dreams', 'used to say that something is better than anything you could imagine or hope for:', 'Never in my wildest dreams did I imagine that one day I would run a marathon.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7224, 'not/never want for anything', 'to have all the basic things you need to lead a satisfactory life:', 'As children we never wanted for anything.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7225, 'not/no more than', 'used to emphasize how small an amount is:', 'There are beautiful mountains not more than ten minutes'' drive away.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7226, 'not/nothing much', 'very little, or nothing that is important or interesting:', 'I had nothing much to do that day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7227, 'notch something up', 'to achieve something:', 'She has recently notched up her third win at a major ski event.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7228, 'note something down', 'to write something so that you do not forget it:', 'I noted down his phone number.', 'phrasal verb', 'B2', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7229, 'nothing could be further from the truth', 'used to say that what has been suggested is completely untrue:', 'People say we''re splitting up, but nothing could be further from the truth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7230, 'nothing could have been further from my mind/thoughts', 'used to say that you certainly did not intend something:', 'I certainly wasn''t trying to get money from him - nothing could have been further from my mind!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7231, 'nothing daunted', 'still confident and enthusiastic despite a failure or problem:', 'She was rejected the first time she applied to the university, but, nothing daunted, reapplied the following year and was accepted.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7232, 'nothing doing', 'used to mean "no", especially when said in answer to a request:', 'We asked if she''d come over and help us, but she said, "Nothing doing".', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7233, 'nothing less than something', 'only a particular quality in something, and not worse:', 'The chef will accept nothing less than perfection from his kitchen staff.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7234, 'nothing less than something', 'Nothing less than something is also used to show something is very important or serious:', 'The president proposed nothing less than a complete overhaul of the tax system.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7235, 'nothing like someone/something', 'not at all similar to someone or something:', 'Instant coffee is nothing like the real thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7236, 'nothing more than', 'only:', 'He dismissed Bryan as nothing more than an amateur.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7237, 'nothing much', 'very little:', '"What’s up?" "Nothing much."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7238, 'nothing of the kind', 'used to emphasize a negative statement:', 'I told him nothing of the kind (= I did not tell him anything like that).', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7239, 'nothing special', 'neither very good nor very bad:', 'Dinner was nothing special.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7240, 'nothing to sneeze at', 'something that deserves serious attention, esp. an amount of money:', 'An extra two thousand bucks a year is nothing to sneeze at.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7241, 'nothing to write home about', 'not exciting or special:', 'Their performance was nothing to write home about.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7242, 'nothing ventured, nothing gained', 'You have to take a risk in order to get something good.', '', 'idiom', 'C2', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7243, 'now then', 'said to attract attention to what you are going to ask or suggest:', 'Now then, what''s all this noise about?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7244, 'now you''re talking', 'said when someone makes a suggestion or offer that is better than one that they have already made', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7245, 'now, now', 'said when you want to make someone feel better or give someone a gentle warning:', 'Now, now, don''t cry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7246, 'nowhere near', 'not in any way:', 'The operation had already been going on for eight hours, and it was nowhere near finished.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7247, 'nowhere to be found', 'impossible to see or find:', 'We looked for her everywhere, but she was nowhere to be found.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7248, 'nudge nudge (wink wink)', 'something you say when you want to suggest that there is a sexual meaning in something that has just been said', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7249, 'number someone/something among someone/something', 'If you are numbered among a particular group, you belong to that group:', 'At one time, the club numbered an archbishop among its members.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7250, 'oblige someone with something', 'to help someone by giving them something:', 'Could you oblige me with a pen and a piece of paper, please?', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7251, 'occur to someone', 'If a thought or idea occurs to you, it comes into your mind:', 'The thought did occur to me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7252, 'oceans of something', 'a lot of something:', 'We have oceans of time.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7253, 'of a kind', 'used to describe something that exists but is not very good:', 'The school had a swimming pool of a kind, but it was too small for most classes to use.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7254, 'of all people', 'used to show that you are especially surprised at a particular person''s behaviour because it does not seem typical of them:', 'I thought that you, of all people, would believe me!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7255, 'of all people/things/places', 'used to express the idea that a particular person/thing/place is unlikely or surprising:', 'Donna, of all people, is the last one I''d expect to see at the gym.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7256, 'of choice', 'Your thing or person of choice is the one that you usually choose in a particular situation:', 'Botox is now the drug of choice in Hollywood.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7257, 'of course', 'used to say yes or to give someone permission to do something:', '"Can you help me?" "Of course."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7258, 'of course', 'used to show that what you are saying is obvious or already known:', 'The Second World War ended, of course, in 1945.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7259, 'of course', 'used to show that a situation or a piece of information is not surprising:', 'We arrived at the restaurant 30 minutes late so, of course, our reservation had been cancelled.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7260, 'of course not', 'used to emphasize that you disagree or that something is not true:', '"Where did you get the money? Did you steal it?" "Of course not. I borrowed it from Carol."', 'idiom', 'A2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7261, 'of every stripe/of all stripes', 'of all types:', 'Governments of every stripe (= of all political opinions) have a bad habit of interfering in state broadcasting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7262, 'of late', 'recently:', 'We haven''t spoken of late.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7263, 'of old', 'in or from the past:', 'in days of old', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7264, 'of old', 'for a very long time:', 'I know him of old.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7265, 'of sorts', 'used to describe something that is not a typical or good example of something:', 'He managed to make a curtain of sorts out of an old sheet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7266, 'of the kind', 'like or similar to what has been said:', '"You said I was fat." "I didn''t say anything of the kind!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7267, 'of the moment', 'the person or thing that is the most important and successful at a particular time:', 'Jack was man of the moment during the crisis.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7268, 'of the old school', 'traditional and old-fashioned', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7269, 'of the week', 'A thing or person of the week is one that has been chosen as the best in a particular week:', 'Book of the Week: Dog Breeds by Andrew and Helen Barker.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7270, 'of the year', 'A thing or person of the year is one that has been chosen as the best in a particular year, especially in a competition:', 'Young Musician of the Year', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7271, 'of two minds (about something)', 'unable to make a decision:', 'I was of two minds about whether to invite him to the wedding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7272, 'of your own making', 'your own fault:', 'Any problems she has with that child are of her own making.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7273, 'off his line', 'If a goalkeeper is off his or her line, he or she is not standing along the goal line:', 'Neymar caught the keeper off his line with a brilliant 45-yard lob.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7274, 'off someone''s radar', 'If someone or something is off your radar, you are not aware of, or have not thought about, them or it:', 'At that time, boyfriends were completely off my radar.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7275, 'off the bat', 'immediately:', 'You can''t expect to be accepted in a new town right off the bat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7276, 'off the beaten path', 'not known or popular with many people:', 'We wanted to find a camping site that was a little bit off the beaten path.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7277, 'off the beaten track', 'in a place where few people go, far from any main roads and towns:', 'The farmhouse we stayed in was completely off the beaten track.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7278, 'off the books', 'in a way that is not officially written down in a person''s or company''s financial records:', 'These workers are getting paid in cash off the books.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7279, 'off the books', 'removed from an official record, especially as a law:', 'Civil rights groups worry that, once enacted, tough new laws may be difficult to get off the books.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7280, 'off the chain', 'extremely good:', 'I made it with extra cheese and it was off the chain.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7281, 'off the charts', 'at a very high level:', 'His blood pressure was off the charts', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7282, 'off the charts', 'extremely popular or successful:', 'The new restaurant is totally off the charts.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7283, 'off the cuff', 'If you speak off the cuff, you say something without having prepared or thought about your words first:', 'I hadn''t prepared a speech so I just said a few words off the cuff.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7284, 'off the hook', 'If you leave the phone off the hook, you do not put it back correctly and it will not ring.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7285, 'off the hook', 'If you are off the hook, you have escaped from a difficult situation:', 'John''s agreed to go to the meeting in my place so that gets/lets me off the hook.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7286, 'off the hook', 'extremely good:', 'That party was off the hook!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7287, 'off the record', 'If someone says something off the record, they do not want it to be publicly reported:', 'She made it clear that her comments were strictly off the record.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7288, 'off the scale', 'extremely large in amount or degree :', 'Revenues are off the scale and global domination is on the agenda.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7289, 'off the top of your head', 'from the knowledge you have in your memory:', '"What''s the capital of Mauritania?" "I don''t know off the top of my head, but I could go and look it up."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7290, 'off the wall', 'surprising and unusual:', 'an off-the-wall joke
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7291, 'off with something', 'used as a way of ordering someone to remove something:', 'Off with his head!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7292, 'off your rocker', 'If you say that someone is off their rocker, you mean that that person is behaving in a very strange or silly way.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7293, 'off your trolley', 'behaving in an extremely unusual way or doing something very silly:', 'Anyone who saw us doing this would think we were off our trolleys.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7294, 'offend against something', 'to break a rule or principle or not fit well with something that people consider to be correct:', 'Would it be offending against good taste to wear a patterned tie with my striped shirt?', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7295, 'oh yes', 'used when you have just remembered something that you were saying:', 'What was I talking about - oh yes, I was telling you what happened at the party.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7296, 'oil the wheels', 'to make it easier for something to happen:', 'An aid programme was established to oil the wheels of economic reform in the region.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7297, 'old chestnut', 'a subject, idea, or joke that has been discussed or repeated so often that it is not funny any more:', 'I wondered whether there might, after all, be some truth in the old chestnut that one''s school days are the happiest of one''s life.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7298, 'on (a) par with someone/something', 'equal or similar to someone or something:', 'In my opinion, none of the new jazz trumpeters are on a par with Miles Davis.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7299, 'on (your) guard', 'careful and aware because a situation might be dangerous:', 'Passengers on public transportation were warned to be on their guard against pickpockets.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7300, 'on a collision course', 'having very different aims or opinions and therefore likely to strongly disagree or fight:', 'The governor put himself on a collision course with state lawmakers over energy policy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7301, 'on a dime', 'If a vehicle, etc. can turn, stop, etc. on a dime, it can turn, etc. in a very small space:', 'The high-tech steering means that even huge tractors can turn on a dime.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7302, 'on a first-name basis', 'knowing someone well enough that you call each other by your first names:', 'I''ve met her, but I''m not on a first-name basis with her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7303, 'on a full stomach', 'soon after you have eaten:', 'You might get sick if you go jogging on a full stomach.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7304, 'on a need-to-know basis', 'If you tell people something on a need-to-know basis, you only tell them the facts they need to know at the time they need to know them, and nothing more.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7305, 'on a razor edge', 'in a very uncertain and dangerous situation:', 'Allegations of fraud have put the politician''s career on a razor edge.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7306, 'on a roll', 'infml experiencing a period of success or good luck:', 'They’ve won nine games in a row, so they’re obviously on a roll.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7307, 'on a shoestring', 'If you do something on a shoestring, you do it with a very small amount of money:', 'The film was made on a shoestring.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7308, 'on a wing and a prayer', 'If you do something on a wing and a prayer, you do it hoping that you will succeed, although you are not prepared enough for it:', 'With hardly any funding and a staff of six, they were operating on a wing and a prayer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7309, 'on all fours', 'with your hands and knees on the ground:', 'You''ll have to get down on all fours to clean behind the toilet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7310, 'on an empty stomach', 'without eating anything:', 'You should never go to work on an empty stomach.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7311, 'on an even keel', 'regular and well-balanced and not likely to change suddenly:', 'The new manager succeeded in putting the business back on an even keel.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7312, 'on and off', 'If something happens on and off during a period of time, it happens sometimes:', 'I''ve had toothache on and off for a couple of months.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7313, 'on assignment', 'doing a job, especially a job in which you are reporting news for a newspaper, television station, etc.:', 'The two journalists met while on assignment in Colombia.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7314, 'on autopilot', 'doing something without thinking about it or without making an effort:', 'I worked the last hour of my shift on autopilot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7315, 'on average', 'usually:', 'On average, a person’s income is highest when they are in their mid-50s.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7316, 'on balance', 'after considering the power or influence of both sides of a question:', 'The job offer had some advantages, but on balance he thought he was better off where he was.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7317, 'on behalf of someone', 'done for another person’s benefit or support, or because you are representing the interests of that person:', 'I’d like to say on behalf of the whole group that we wish you well in your new job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7318, 'on deposit', 'Money that is on deposit is saved in a bank or something similar:', 'I''ve got £5,000 on deposit in the bank.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7319, 'on earth', 'infml in any conditions; of all possible things:', 'How on earth did this happen?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7320, 'on easy street', 'rich', '', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7321, 'on end', 'continuously:', 'She practices the violin for hours on end.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7322, 'on everyone''s lips', 'being talked about by a lot of people:', 'The question now on everyone''s lips is "Will he resign?"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7323, 'on hand', 'near to someone or something, and ready to help or be used if necessary:', 'A 1,200-strong military force will be on hand to monitor the ceasefire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7324, 'on high', 'in heaven:', 'God looked down from on high.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7325, 'on high', 'If an order comes from on high, it comes from someone in a position of authority:', 'Instructions came from on high to reduce our travel expenses.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7326, 'on ice', '(of drink or food) in a container of ice to get cold:', 'I''ve put a couple of bottles of champagne on ice .
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7327, 'on ice', 'If a plan is on ice, a decision has been made to delay it for a period of time:', 'Both projects are on ice until the question of funding is resolved.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7328, 'on it', 'doing something that needs to be done, or trying to solve a problem:', '"We need help with web design." "Don''t worry, I''m on it."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7329, 'on its (own) merits', 'based only on a person''s or thing''s qualities and not on what other people say about that person or thing:', 'Judge the product on its own merits, and not on what the ads say.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7330, 'on its last legs', 'Something that is on its last legs is in such bad condition that it will soon be unable to work as it should:', 'I''ve had this laptop for five years now, and it''s really on its last legs.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7331, 'on its way', 'happening or arriving soon:', 'They have three kids, and another on the way.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7332, 'on its way', 'If you are on your way you are leaving:', 'Give me a kiss and I''ll be on my way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7333, 'on no account', 'If something must on no account/not on any account be done, it must not be done at any time or for any reason:', 'Employees must on no account make personal phone calls from the office.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7334, 'on occasion', 'sometimes but not often:', 'He has, on occasion, told a small lie.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7335, 'on one level...on another level', 'something that you say when you are speaking about two opposite ways of thinking about or reacting to a situation:', 'On one level I quite like the attention but on another level, I suppose I find it a little disturbing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7336, 'on paper', 'judging something by how it has been planned rather than how it really works in practice:', 'The design certainly looks good on paper.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7337, 'on pins and needles', 'worried or excited about something that is going to happen:', 'Don’t keep Margaret on pins and needles – give her a call.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7338, 'on point', 'as good as it could be; perfect:', 'My hair was on point.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7339, 'on shaky ground', 'likely to fail:', 'At least one factory is on shaky ground, and the town expects more to shut down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7340, 'on short notice', 'only a short time before something happens:', 'I can''t cancel my plans on such short notice.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7341, 'on skid row', 'poor, without a job or a place to live, and often drinking too much alcohol', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7342, 'on someone''s account', 'If something is said to be on someone''s or something''s account, it is because of that person or thing:', 'I''m not very hungry, so please don''t cook on my account (= don''t cook just for me).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7343, 'on someone''s deathbed', 'just before someone''s death:', 'He told her he loved her on his deathbed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7344, 'on someone''s doorstep', 'very close to where someone is or lives:', 'There''s a lovely park right on our doorstep.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7345, 'on someone''s radar', 'If someone or something is on your radar, you are aware of, or have thought about, them or it. :', 'She has been on my radar since her first novel came out, but I haven''t read any of her books yet.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7346, 'on speaking terms', 'friendly enough to talk:', 'We had an argument, but we’re back on speaking terms now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7347, 'on standby', 'ready to work or be used if necessary:', 'Hospitals are on standby to care for casualties of the crash.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7348, 'on standby', 'ready to work or be used if necessary:', 'Hospitals are on standby to care for casualties of the crash.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7349, 'on steroids', 'used for saying that something is an extreme example or version of something:', 'He described the new edifices as "architecture on steroids".
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7350, 'on stream', 'Something in industry or business that is on stream is being produced or is available for use:', 'The company''s increased sales were primarily a result of new stores coming on stream.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7351, 'on tap', 'available:', 'There are several new movies on tap this weekend.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7352, 'on target', 'If you are on target with a piece of work, you are making good progress and likely to achieve what you planned.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7353, 'on the attack', 'to act in a strong, determined way to defeat someone or something, often in a game or competition:', 'In the second half, the Panthers went on the attack and they scored after two minutes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7354, 'on the back burner', 'If something is on the back burner, it is temporarily not being dealt with or considered, especially because it is not urgent or important:', 'We''ve all had to put our plans on the back burner for a while.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7355, 'on the back of an envelope', 'in a hurried way, without much detail:', 'The prices were very roughly calculated - it looked as though he''d done them on the back of an envelope.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7356, 'on the back of something', 'soon after an earlier success, and as a result of it:', 'The advertising agency secured the contract on the back of its previous successful campaigns.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7357, 'on the back of someone/something', 'by using or taking advantage of someone or something else:', 'They have carried on their business operations by riding on the back of established firms.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7358, 'on the ball', 'aware of any changes or developments and quick to react to them:', 'We need someone who’s really on the ball to answer questions from the press.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7359, 'on the blink', 'When a machine is on the blink, it is not working correctly.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7360, 'on the books', 'officially employed by a company, or an official member of an organization, society, sports team, etc.:', 'There are 256 people on the books at the cement works.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7361, 'on the books', 'officially recorded, especially as a law:', 'A ban on texting while driving is on the books in most states.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7362, 'on the booze', 'drinking a lot of alcohol:', 'Every Friday night Rick would go out on the booze.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7363, 'on the bounce', 'one after another with nothing else between:', 'The team has had five wins on the bounce.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7364, 'on the bubble', 'not certain to get a place in a team, keep your job, win an election, etc.:', 'Those who had not gained their paramedic certification were "on the bubble" with regard to keeping their jobs.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7365, 'on the contrary', 'fml actually the opposite is true:', 'The crime problem has not disappeared. On the contrary, it seems to be becoming worse again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7366, 'on the count of something', 'after counting to a particular number:', 'On the count of three, run.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7367, 'on the defensive', 'protecting yourself from criticism instead of attacking or criticizing others:', 'The speech produced a firestorm of protest, putting him on the defensive.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7368, 'on the dot', 'exactly at the stated or expected time:', 'The plane landed at two o''clock on the dot.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7369, 'on the edge of your seat', 'very excited, and giving all your attention to something, because you want to know what is going to happen:', 'He could no longer keep his eyes open to watch any of the videos which, until quite recently, would have kept him on the edge of his seat.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7370, 'on the face of it', 'used when you are describing how a situation seems on the surface:', 'On the face of it, it seems like a bargain, but I bet there are hidden costs.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7371, 'on the factory floor', 'involving ordinary workers rather than managers:', 'That sort of decision should be taken on the factory floor.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7372, 'on the fence', 'not able to decide something:', 'Many consumers are still on the fence, waiting for a less expensive computer to come along.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7373, 'on the firing line', 'in a situation that attracts criticism:', 'The judge found himself in the firing line after his remarks about women staying home with their children.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7374, 'on the fly', 'If you do something on the fly, you do it quickly, often while you are doing something else, without preparing and without thinking too much about how it should be done:', 'This new rule seems to have been created on the fly.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7375, 'on the fly', 'without interrupting a computer program that is already running:', 'He had written a program that could translate from Japanese on the fly.', 'idiom', '', 'specialized', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7376, 'on the front burner', 'getting or needing immediate attention:', 'A few important members of Congress are making an effort to keep human rights on the front burner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7377, 'on the go', 'very busy:', 'I''ve been on the go all day, and I''m really tired.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7378, 'on the go', 'in the process of being produced:', 'Did you know that she''s got a new book on the go (= being written)?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7379, 'on the ground', 'among the general public:', 'Their political ideas have a lot of support on the ground.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7380, 'on the hoof', 'If you do something on the hoof, you do it while you are moving about or doing something else, often without giving it the attention it deserves:', 'I''ve got a meeting downtown in 20 minutes so I''ll have lunch on the hoof.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7381, 'on the horizon', 'likely to happen or exist soon:', 'There is no new drug on the horizon that will make this disease easier to treat.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7382, 'on the house', 'If you have something on the house, it is given to you free by a business:', 'All the drinks were on the house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7383, 'on the inside', 'If someone is on the inside, they have a job or position in which they have special or secret information:', 'Who do we know on the inside who can help us?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7384, 'on the large, small, etc. side', 'too large, small, etc. for a particular purpose:', 'This dress is on the large side for me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7385, 'on the level', 'being honest or speaking truthfully:', 'I know he’s lied to you before, but I really think he’s on the level this time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7386, 'on the line', 'at risk of failing or being harmed:', 'His job is on the line.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7387, 'on the line', 'On the line also means speaking on the telephone:', 'My mom was on the line, but I could hear my dad talking in the background.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7388, 'on the loose', 'If a dangerous person or animal is on the loose, that person or animal is free to move around a place and harm people:', 'Brewer escaped from prison last year and has been on the loose ever since.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7389, 'on the make', 'trying hard to succeed, esp. in a way that is dishonest:', 'The movie is about a businessman on the make, who steals company funds.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7390, 'on the market', 'available for sale:', 'We put our house on the market last spring.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7391, 'on the mend', 'becoming healthy after an illness:', 'She''s still in the hospital, but she''s definitely on the mend.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7392, 'on the nod', 'If a suggestion is approved on the nod, it is accepted without discussion:', 'The new proposal went through on the nod.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7393, 'on the nose', 'exactly right, often an exact amount of money or time:', 'Her description of the play was right on the nose.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7394, 'on the one hand ... on the other hand', 'used when you are comparing two different facts or two opposite ways of thinking about a situation:', 'On the one hand I''d like a job that pays more, but on the other hand I enjoy the work I''m doing at the moment.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7395, 'on the other hand', 'in a way that is different from the first thing you mentioned:', 'My husband likes classical music – I, on the other hand, like all kinds.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7396, 'on the outs', 'in a state of disagreement or unfriendliness:', 'Dick is on the outs with his father.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7397, 'on the part of someone/on someone''s part', 'done or experienced by someone:', 'This was a misjudgment on the part of the government.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7398, 'on the prowl', 'moving around an area and looking for something or someone:', 'On the way home I saw a raccoon on the prowl.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7399, 'on the quiet', 'secretly:', 'His wife found out he''d been seeing someone on the quiet.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7400, 'on the rebound', 'unhappy and confused because a close, romantic relationship of yours has recently finished:', 'Five months after Nick had left her, she married another man on the rebound.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7401, 'on the receiving end of something', 'suffering from something unpleasant when you have done nothing to deserve it:', 'She was on the receiving end of a lawsuit.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7402, 'on the record', 'If you say something on the record, you state it publicly:', 'None of the company directors were prepared to comment on the record yesterday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7403, 'on the right track', 'doing something correctly or well:', 'You haven''t quite got the answer yet, but you''re on the right track.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7404, 'on the right/wrong side of 40, 50, etc.', 'looking younger/older than a particular age:', 'She looks to me as if she''s on the wrong side of 50.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7405, 'on the right/wrong side of the law', 'obeying/not obeying the law:', 'After coming out of prison, he tried to stay on the right side of the law.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7406, 'on the road', 'traveling to different places:', 'The band spends three months a year on the road.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7407, 'on the road to something', 'likely to achieve something:', 'The doctors say she’s on the road to recovery.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7408, 'on the rocks', 'likely to fail soon:', 'I think their marriage is on the rocks.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7409, 'on the rocks', 'If you have an alcoholic drink on the rocks, you have it with pieces of ice:', 'I''ll have a whisky on the rocks, please.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7410, 'on the ropes', 'doing badly and likely to fail:', 'I think the business is finally on the ropes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7411, 'on the run', 'while hurrying to go somewhere:', 'I eat breakfast on the run if I''m late for work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7412, 'on the same wavelength', 'thinking in the same way as someone else:', 'Luckily, my husband and I are on the same wavelength about how to raise our kids.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7413, 'on the scent', 'close to discovering:', '"We''re on the scent of something big," said the police chief.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7414, 'on the shelf', 'not noticed or not used:', 'It''s important to apply research in a practical way and not leave it on the shelf.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7415, 'on the shelf', 'If someone, usually a woman, is on the shelf, she is not married and is considered too old for anyone to want to marry her:', 'In those days, if you hadn''t married by the time you were 30, you were definitely on the shelf.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7416, 'on the side', 'in addition to your main job:', 'He makes a little money on the side by cleaning windows in his spare time.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7417, 'on the side', 'secretly:', 'I think he has another woman on the side (= a relationship with a woman who is not his wife).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7418, 'on the side', '(of food in a restaurant) served on another plate, or on the side of the plate :', 'I''d like a salad with the dressing on the side (= with the dressing served separately from the salad), please.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7419, 'on the sidelines', 'not taking part in an activity:', 'Several countries chose to remain on the sidelines during the war.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7420, 'on the skids', 'failing:', 'Both of the government programs were on the skids.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7421, 'on the slate', '(of the price of food or drink that a regular customer buys) recorded so that they can pay for it at another time:', 'Could you put these drinks on the slate?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7422, 'on the sly', 'secretly:', 'On the sly, Dave was adding chilies to the desserts he made.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7423, 'on the spectrum', 'affected by autism (= a brain condition that affects the development of social and communication skills in ways that can be severe or slight, and that can make someone''s behaviour and interests different from people without the condition ) to some degree:', 'The article describes a mother''s experience of living with a child on the spectrum.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7424, 'on the spot', 'at that moment or place:', 'He was arrested on the spot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7425, 'on the spot', 'Someone who is put on the spot is forced to do or say something the person would rather not do or say:', 'I’m not trying to put you on the spot, but could you explain why you did that?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7426, 'on the spur of the moment', 'used to say that a decision, action, etc. is sudden and done without any planning:', 'We hadn''t planned to go away - it was one of those spur-of-the-moment decisions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7427, 'on the streets', 'without a home:', 'Some of these people have been living on the streets for years.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7428, 'on the strength of something', 'If you do something on the strength of something such as advice, you do it because you have been influenced by it or believe it:', 'I invested in the company on the strength of my brother''s advice.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7429, 'on the stump', '(of a politician) travelling around an area giving speeches and trying to get political support:', 'On the stump, he was a master at turning his simple speaking style into a political virtue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7430, 'on the table', 'If a plan or suggestion has been put/laid on the table, it has been made available for people to hear, read, or discuss.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7431, 'on the take', 'trying to profit in a personal and usually financial way from a situation:', 'He''s obviously on the take - where else did all that money come from?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7432, 'on the threshold of something', 'at the start of a new and important time or development:', 'We are on the threshold of a new era in global relations.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7433, 'on the tip of your tongue', 'about to be said if you can remember it:', 'I know her - her name is on the tip of my tongue, but it won''t come to me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7434, 'on the town', 'enjoying yourself by going to places of entertainment in a town or city:', 'I was out on the town/I had a night on the town last night, and I''m exhausted!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7435, 'on the trot', 'If you do things on the trot, you do them directly after each other without pausing:', 'They won three games on the trot.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7436, 'on the understanding', 'according to someone''s promise or statement:', 'We purchased the computer on the understanding that it could be returned within ten days.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7437, 'on the up (and up)', 'Someone who is on the up (and up) is honest and can be trusted.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7438, 'on the up (and up)', 'improving all the time:', 'Her career has been on the up and up since she moved into sales.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7439, 'on the verge (of)', 'If you are on the verge of something or come to the verge of something, you are very close to experiencing it:', 'on the verge of collapse/success/tears/death/disaster/war
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7440, 'on the wagon', 'If you are on the wagon, you have decided not to drink any alcohol:', 'He was on the wagon for ten years, when he was living in Connecticut.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7441, 'on the warpath', 'angry and ready to argue or fight:', 'I told my friends to watch out because my mother was on the warpath.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7442, 'on the whole', 'generally:', 'We have our bad times but on the whole we''re fairly happy.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7443, 'on the wrong track', 'not correct about something:', 'If you suspect my son was involved, you are on the wrong track.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7444, 'on top', 'in the best or most successful position:', 'She came out on top in every race.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7445, 'on top of something', 'in addition to something, especially something unpleasant:', 'We missed our flight, and on top of that we had to wait seven hours for the next one.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7446, 'on top of the world', 'extremely happy:', 'She was feeling on top of the world.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7447, 'on track', 'making progress and likely to succeed:', 'They''re on track to make record profits.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7448, 'on view', 'placed where the public can see it:', 'Plans for the new design of the park are on view in the library this week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7449, 'on your bike!', 'a rude way of telling someone to go away:', '"Can you lend me some money?" "On your bike, mate!"', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7450, 'on your last legs', 'A person who is on their last legs is very tired or near to death:', 'We''d been out walking all day and I was on my last legs when we reached the hotel.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7451, 'on your marks, get set, go!', 'something called out to competitors at the beginning of a running race', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7452, 'on your mettle', 'ready to do something as well as you can in a difficult situation:', 'Both players were on their mettle in the final round.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7453, 'on your own', 'alone:', 'I don’t mind going to the movies on my own.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7454, 'on your own', 'If you do something on your own, you do it without help from anyone else:', 'Bridget learned to tie her shoes on her own when she was three.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7455, 'on your own head be it', 'used to tell someone that they will have to take full responsibility for what they plan to do', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7456, 'on your rounds', 'to be out on a regular visit:', 'The doctor''s out on his rounds.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7457, 'on your toes', 'Someone or something that keeps you on your toes forces you to continue directing all your attention and energy to what you are doing:', 'I work with people who are half my age so that keeps me on my toes.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7458, 'on/about your person', 'in a pocket, bag, or something else that you are holding:', 'Do you have about your person such a thing as a lighter?', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7459, 'on/at every corner', 'in many places along the streets of a town or city:', 'After the game, police were stationed on every corner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7460, 'on/from the sidelines', 'If you are on the sidelines or do something from the sidelines, you are not actively involved in something:', 'Women have been on the political sidelines for too long - we must now work towards getting into power.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7461, 'on/under pain of death', 'If you have to do something on/under pain of death, you will be killed if you do not do it.', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7462, 'once and for all', 'completely and finally:', 'We have to decide, once and for all, whether we want to ask Dad for money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7463, 'once bitten, twice shy', 'said when you are frightened to do something again because you had an unpleasant experience doing it the first time', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7464, 'once in a blue moon', 'not very often:', 'My sister lives in Alaska, so I only see her once in a blue moon.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7465, 'once more', 'another time:', 'I’ll explain it once more, but listen this time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7466, 'once upon a time', 'used at the beginning of children''s stories to mean "a long time ago":', 'Once upon a time there was an ugly duckling.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7467, 'once upon a time', 'used when referring to something that happened in the past, especially when showing that you feel sorry that it no longer happens:', 'Once upon a time people knew the difference between right and wrong, but nowadays nobody seems to care.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7468, 'one after another', 'many, in a series:', 'I''ll eat chocolates one after the other until the box is finished.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7469, 'one and all', 'everyone:', 'The news of his resignation came as a surprise to one and all.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7470, 'one and done', 'done, or doing something, only once and never again:', 'This is not a one and done process.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7471, 'one and only', 'only:', 'This may be your one and only opportunity to meet her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7472, 'the one and only', 'the only person or thing of this type:', 'And now I''d like to introduce, the one and only Stevie Wonder!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7473, 'one and the same', 'the same thing or person:', 'I was amazed to discover that Mary''s husband and Jane''s son are one and the same (person).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7474, 'one by one', 'separately, one after the other:', 'One by one the old buildings in the city have been demolished and replaced with new high rises.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7475, 'one day', 'at some time in the future:', 'I''d like to go to Berlin again one day.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7476, 'one for the books', 'a surprising or unexpected event:', 'Well, that''s one for the books - I never thought he''d get the job.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7477, 'one for the road', 'an alcoholic drink just before leaving:', 'Before I went home, she persuaded me to have one for the road.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7478, 'one good turn deserves another', 'said when you do a helpful or kind act for someone who has done something good for you', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7479, 'one in a million', 'extremely unlikely:', 'Don''t worry - the chances of anything going wrong are one in a million.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7480, 'one in a million', 'a very special person:', 'Thanks again - you''re one in a million!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7481, 'one man''s loss is another man''s gain', 'said when someone gets an advantage from someone else''s bad luck', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7482, 'one man''s meat is another man''s poison', 'said to emphasize that people like different things', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7483, 'one of a kind', 'the only person or thing of a particular type:', 'In the world of ballet, she was one of a kind.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7484, 'one of these days', 'some time in the near future:', 'You''re going to get into serious trouble one of these days.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7485, 'one of those days', 'a bad day, full of problems:', 'It''s just been one of those days.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7486, 'one or two', 'a few:', 'I''d like to make one or two suggestions.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7487, 'one step at a time', 'slowly and carefully, doing just a little at a time:', 'He wanted to rush through the job, but I encouraged him to take it one step at a time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7488, 'one step forward, two steps back', 'If you take one step forward, two steps back, you make progress but then experience events that cause you to be further behind than you were when you made the progress.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7489, 'one swallow doesn''t make a summer', 'used to say that because one good thing has happened, it is not therefore certain that a situation is going to improve', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7490, 'one thing leads to another', 'If one thing leads to another, there is a series of events in which each event was caused by the previous one:', 'At first, we were just talking a little, but one thing led to another, and he asked me out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7491, 'one too many', 'If you have had one too many, you have drunk too much alcohol.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7492, 'one way or another', 'in some way that is not stated:', 'Everyone at the party was related (in) one way or another.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7493, 'one way or another', 'in any way that is possible:', 'These bills have to be paid one way or another.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7494, 'one way or the other', 'which of two possibilities will be chosen:', 'They''ve had two weeks to think about it, and now they have to decide one way or the other.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7495, 'one way or the other', 'whatever method is used:', 'One way or the other, this project has to be finished by Tuesday.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7496, 'one, two, etc. down, one, two etc. to go.', 'an expression that is used to mean that you have done or dealt with the first, second, etc. of a series of things and have yet to do or deal with the rest:', '"How are your finals going?" "Two down, three to go."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7497, 'one/some day', 'at some time in the future:', 'I''d love to go to China some/one day.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7498, 'only have eyes for someone', 'to be interested in or attracted to only one person:', 'You''ve no need to be jealous. I only have eyes for you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7499, 'only joking!', 'said when you mean that something you said was not intended to be serious:', 'Think I''ll leave you with the kids while I go for a beer - only joking!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7500, 'only so much/many', 'used to say that there are limits to something:', 'There are only so many hours in your working day - you cannot possibly do all the work.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7501, 'only to do something', 'used to show that something is surprising or unexpected:', 'He spent months negotiating for a pay increase, only to resign from his job soon after he''d received it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7502, 'onward and upward', 'becoming more and more successful:', 'Her publishing career started as an editorial assistant on a women''s magazine and it was onward and upward from there.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7503, 'onwards and upwards', 'becoming more and more successful:', 'Her publishing career started as an editorial assistant on a women''s magazine and it was onwards and upwards from there.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7504, 'ooh and aah', 'to express admiration:', 'We watched the fireworks, oohing and aahing with everyone else.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7505, 'open (something) up', 'to open the lock on the door of a building:', 'The caretaker opens up the school every morning at seven.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7506, 'open something up', 'to improve a situation by making it less limited:', 'The government has announced plans to open up access to higher education.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7507, 'open something up', 'to show something that was hidden or not previously known:', 'The debate could open up sharp differences between the countries.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7508, 'open someone up', 'to do a medical operation on someone to see inside their body:', 'When they opened her up, they couldn''t find anything wrong with her.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7509, 'open up', 'to start to talk more about yourself and your feelings:', 'I''ve never opened up to anyone like I do to you.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7510, 'open carry', 'the act of carrying a gun in public in a way that people can see:', 'We live in a state where open carry is still legal.', 'idiom', '', 'specialized', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7511, 'open someone''s eyes', 'to make someone realize something surprising or shocking that they had not known about or understood before:', 'She really opened my eyes to how stupid I''d been.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7512, 'open something out/up', 'to make a space larger or less closed in:', 'We''re going to open up our kitchen by taking out a couple of walls.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7513, 'open the door to something', 'to allow something new to start:', 'The ceasefire has opened the door to talks between the two sides.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7514, 'open the floodgates', 'If an action or a decision opens the floodgates, it allows something to happen a lot or allows many people to do something that was not previously allowed:', 'Officials are worried that allowing these refugees into the country will open the floodgates to thousands more.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7515, 'open your heart to someone', 'to tell someone about your problems and secrets:', 'She''s very understanding - you feel you can really open your heart to her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7516, 'open your mouth', 'to speak or start to speak:', 'I don''t know how she heard about it - I never opened my mouth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7517, 'opt in', 'to choose to be part of an activity, arrangement, etc.:', 'Company policy is to leave new workers out of the pension scheme, unless they choose to opt in.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7518, 'opt out', 'to choose not to be part of an activity or to stop being involved in it:', 'Within any society, there will usually be people who decide to opt out (= choose not to live the way most people do).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7519, 'or die in the attempt', 'said when someone would do anything to achieve what they want to achieve:', 'She''ll finish the race or die in the attempt.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7520, 'or else', 'used to say what will happen if another thing does not happen:', 'We must be there by six, or else we''ll miss the beginning.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7521, 'or else', 'used to compare two different things or situations:', 'She''s either really talkative and you can''t shut her up or else she''s silent.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7522, 'or else', 'used as a threat, sometimes humorously:', 'He''d better find it quickly, or else (= or I will punish him in some way)!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7523, 'or no', 'used to emphasize that the stated thing will not make any difference:', 'Extra pay or no extra pay, I''m not going to work late again tonight.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7524, 'or otherwise', 'used to refer to the opposite of the word that comes before it:', 'Hand in your test papers, finished or otherwise (= or not finished).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7525, 'or so', 'approximately:', 'They raised two hundred dollars or so for charity.', 'idiom', 'B1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7526, 'or something (like that)', 'used to show that what you have just said is only an example or you are not certain about it:', 'She works for a bank or something.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7527, 'or two', 'approximately or a little more than:', 'I''ll be with you in a minute or two.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7528, 'or what?', 'used at the end of a phrase for emphasis:', 'Are you stupid or what?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7529, 'order out (for something)', 'to order food that is ready to eat to be brought to your home or to the place where you work:', 'We stayed home, ordered out for pizza, and watched a movie on demand.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7530, 'order someone around', 'to tell someone what they should do in an unpleasant or forceful way, especially repeatedly:', 'You can''t just come in here and start ordering people around.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7531, 'order something in', 'to order food that is ready to eat to be brought to your home or to the place where you work:', 'I think I''ll stay home tonight, order in a pizza, and watch my new box set.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7532, 'order sth up', 'to ask a company, store, manufacturer, etc. to supply goods or services:', 'Universities have ordered up thousands of copies of the new software.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7533, 'order your thoughts', 'to plan what you want to say or do:', 'Just give me a moment to order my thoughts, and then I''ll explain the system to you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7534, 'orders are orders', 'said when you have to do something because someone in authority has told you to, and usually when you do not really approve of it:', 'Nobody wants to do it, but orders are orders, so let''s start.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7535, 'other than', 'except:', 'The form cannot be signed by anyone other than you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7536, 'out and about', 'active; doing the things you usually do:', 'The doctor says she''s making a good recovery, and she should be out and about in a few days'' time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7537, 'out and away', 'used with superlatives to mean by a great amount:', 'She is out and away the best student I have ever taught.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7538, 'out front', 'In a theatre, if you say that someone is out front, you mean they are one of the people watching the performance:', 'Don''t worry about your parents being out front tonight.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7539, 'out loud', 'If you say or read something out loud, you say or read it so that other people can hear you:', 'I had to read the essay out loud in front of the whole school.', 'idiom', 'B1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7540, 'out of action', 'If a machine or vehicle is out of action, it is not working or cannot be used:', 'I''m afraid the TV''s out of action.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7541, 'out of action', 'If a person is out of action, they are injured or ill and cannot do things they usually do:', 'Jackson''s torn ligaments will keep him out of action for the rest of the season.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7542, 'out of bounds', 'If an area is out of bounds, people are not allowed to go there.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7543, 'out of bounds', 'If the ball is out of bounds, it is not within the playing area.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7544, 'out of commission', 'If something, such as a machine or a military ship, is out of commission it is broken or not available to be used.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7545, 'out of hand', 'out of control:', 'Things got a little out of hand at the party and three windows were broken.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7546, 'out of hand', 'If you refuse something out of hand, you refuse it completely without thinking about or discussing it:', 'Moving to London is certainly a possibility - I wouldn''t dismiss it out of hand.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7547, 'out of harm''s way', 'in a position that is safe from harm or from which harm cannot be done:', 'The children will be here soon - you''d better put that plate out of harm''s way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7548, 'out of hours', 'If you drink in a bar out of hours, you drink alcohol at a time when it is not allowed by law:', 'The police are trying to stop out-of-hours drinking.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7549, 'out of it', 'not conscious of where you are or what condition you are in as a result of taking alcohol or drugs:', 'She was lying on the sofa, totally out of it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7550, 'out of it', 'unhappy because you are not included in what is happening:', 'I didn''t know anyone at the party, and I felt really out of it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7551, 'out of line', 'beyond what is considered acceptable behavior:', 'You can disagree with her, but calling her dishonest was out of line.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7552, 'out of luck', 'not having the success or good opportunities you wanted:', 'The bike only comes in large sizes, so if you''re a short person you''re out of luck.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7553, 'out of order', 'If something someone says or does is out of order, it is unpleasant or not suitable and it is likely to upset or offend people:', 'His behaviour in the meeting was out of order.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7554, 'out of place', 'not comfortable in or not suitable for a situation:', 'The picture looks out of place here.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7555, 'out of shape', 'not physically healthy enough for difficult exercise because you have not been involved in physical activities:', 'I''m so out of shape that I get out of breath climbing the stairs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7556, 'out of sight', 'extremely expensive and more than you are able to spend:', 'The price of the house we like is out of sight.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7557, 'out of sight', 'excellent:', 'The group''s new record is out of sight!', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7558, 'out of sight, out of mind', 'said to emphasize that when something or someone cannot be seen, it is easy to forget it, him, or her', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7559, 'out of sorts', 'in an unhappy mood:', 'Peter overslept this morning and has been out of sorts all day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7560, 'out of station', 'away; not present in a place:', 'I am at present out of station and will reply on my return.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7561, 'out of step with someone/something', 'not having the same ideas or beliefs as other people, or not being aware of other people''s beliefs:', 'The governor''s remarks show that she is seriously out of step with the voters.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7562, 'out of the blue', 'If something happens out of the blue, it is completely unexpected:', 'One day, out of the blue, she announced that she was leaving.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7563, 'out of the corner of your eye', 'without looking at something directly:', 'I was watching TV when I saw something move out of the corner of my eye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7564, 'out of the frying pan into the fire', 'said when you move from a bad or difficult situation to one that is worse', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7565, 'out of the mouths of babes (and sucklings)', 'said when a child says something that surprises you because it seems very wise', '', 'idiom', '', 'literary, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7566, 'out of the picture', 'not important to or not involved in a situation:', 'He used to be an important member of the team, but he''s gradually drifted out of the picture.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7567, 'out of the picture', 'unnecessary in a particular situation:', 'The new systems cut humans out of the picture altogether.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7568, 'out of the question', 'not possible or not allowed:', 'The class ends at 2, and leaving before then is out of the question.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7569, 'out of the running', 'having no chance of being successful in a competition or election:', 'He wasn''t able to raise enough money for his campaign and declared himself out of the running.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7570, 'out of the woods', 'not having a problem or difficulty any longer:', 'It''s too soon to say if either airline is out of the woods yet.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7571, 'out of thin air', 'from nothing:', 'I can''t come up with €10,000 out of thin air.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7572, 'out of this world', 'extremely good:', 'What a restaurant - the food was out of this world!', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7573, 'out of touch', 'not informed or not having the same ideas as most people about something, so that you make mistakes:', 'A few of the older teachers are completely out of touch with their students.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7574, 'out of your depth', 'not having the knowledge, experience, or skills to deal with a particular subject or situation:', 'I was out of my depth in the advanced class, so I moved to the intermediate class.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7575, 'out of your depth', 'in water that is so deep that it goes over your head when you are standing:', 'I''m not a strong swimmer, so I prefer not to go out of my depth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7576, 'out of your league', 'doing something that you are not skilled enough to do, esp. compared to other people doing the same thing:', 'She has been working very hard on the project, but I think she''s a little out of her league.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7577, 'out of your mind', 'unable to behave or deal with things normally because something has made you very worried, unhappy, or angry:', 'She was out of her mind with grief.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7578, 'out of your mind', 'extremely stupid or mentally ill:', 'You must be out of your mind paying £500 for one night in a hotel!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7579, 'out of your mind/head', 'extremely silly:', 'He must be out of his mind to have spent that much money on an old car!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7580, 'out of/from the corner of your eye', 'If you see something out of/from the corner of your eye, you see it but not clearly because it happens to the side of you:', 'I saw something move out of the corner of my eye.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7581, 'out on a limb', 'having an opinion that is different from most people''s and is unpopular:', 'She''s going out on a limb in criticizing her own party leadership.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7582, 'out on your arse', 'a rude phrase meaning having been forced to leave a job or place, especially because you have done something wrong:', 'He''s doing well in the company now, but there was a time he was almost out on his arse.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7583, 'out on your ass', 'a rude phrase meaning having been forced to leave a job or place, especially because you have done something wrong:', 'You have one month to improve, or you''ll be out on your ass.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7584, 'out to lunch', 'infmlslightly crazy or not thinking clearly:', 'You must have thought I was completely out to lunch when I forgot about meeting you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7585, 'out with it!', 'said to someone when you want that person to tell you something that they do not want you to know:', 'What did he do then? Come on, out with it!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7586, 'out/up the wazoo', 'in large quantities:', 'We have tourists here out the wazoo.', 'idiom', '', 'very informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7587, 'outlive your usefulness', 'to no longer be useful:', 'This old system has outlived its usefulness.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7588, 'over and over (again)', 'happening or done many times:', 'I read the article over and over till it made sense.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7589, 'over my dead body', 'If you say something will happen over your dead body, you mean that you will do everything you can to prevent it:', '"Joe says he''s going to buy a motorbike." "Over my dead body!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7590, 'over the hill', 'used for describing someone who is old and no longer useful or attractive', '', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7591, 'over the odds', 'more than something is really worth:', 'It''s a nice enough car but I''m sure she paid over the odds for it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7592, 'over the top', 'too extreme and not suitable, or demanding too much attention or effort, especially in an uncontrolled way:', 'I thought the decorations were way (= very) over the top.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7593, 'over your head', 'too difficult or strange for you to understand:', 'I tried to take in what he was saying about nuclear fusion, but most of it went over my head.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7594, 'over-egg the pudding', 'to make something seem larger, more important, better, or worse than it really is:', 'We all know insurance claimants who have over-egged the pudding to increase their payouts.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7595, 'over-egg the pudding', 'to spoil something by trying too hard to improve it:', 'There are some great moments, but the writer tends to over-egg the pudding with metaphors and similes when all she''s describing is a group of women getting through the day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7596, 'overfocus on someone/something', 'to give too much attention to one particular person, subject, or thing:', 'We don''t believe you can over-focus on this problem.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7597, 'overplay your hand', 'to spoil your chance of success by saying or doing too much', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7598, 'overstep the mark', 'to behave in a completely unacceptable way:', 'You''ve overstepped the mark this time, Simpson - you''re fired!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7599, 'owe a debt of gratitude/thanks', 'to have a reason to thank or feel grateful to another person for something good that they have done:', 'There are no words that can express the debt of gratitude that future generations will owe them for their sacrifices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7600, 'owe it to someone to do something', 'to have a duty to do something for someone:', 'We owe it to our students to prepare them well for college.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7601, 'you owe it to yourself to do something', 'you deserve to do something:', 'You owe it to yourself to take a long vacation.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7602, 'owe it to yourself', 'to deserve and need to do something that will be good for you:', 'Take a few days off work - you owe it to yourself.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7603, 'owe someone a living', 'If you say that someone thinks that people owe him or her a living, you mean that that person thinks that he or she deserves to be paid without having to work hard for it:', 'He seems to think the world owes him a living.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7604, 'own up', 'to admit that you have done something wrong:', 'No one has owned up to stealing the money.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7605, 'pace something off/out', 'to measure a distance by taking steps of equal size across it and counting them:', 'You can get a rough idea of the size of the room by pacing it out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7606, 'pack a punch', 'to have a lot of force or a great effect:', 'His speech packed quite a punch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7607, 'pack it in', 'infml to stop doing something:', 'When it started to rain again, we decided to pack it in and go home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7608, 'pack someone off', 'to send someone to another place:', 'We''ve packed the kids off for the weekend.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7609, 'pack something away', 'to put something into a bag or container, or to put something in the place where it is usually kept:', 'Come on, children, it''s time to pack away your toys.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7610, 'pack something away', 'to eat a lot of food:', 'She''s tiny but she can really pack away the biscuits.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7611, 'pack something in', 'to stop doing something:', 'This course is really tough - sometimes I feeling like packing it all in.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7612, 'pack something in', 'said to rudely tell someone to stop doing something that is annoying you:', 'Pack it in, Julie - I''m trying to read.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7613, 'pack someone in', 'to end your relationship with someone, or to stop meeting or spending time with them:', '"Is Emma still seeing Joe?" "No, she''s packed him in."', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7614, 'pack someone in', 'If an entertainment or exhibition packs people in, a large number of people come to see it:', 'Spielberg''s new film is packing in the crowds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7615, 'pack something/someone in', 'to manage to include a large number of things, activities, or people:', 'We were only there four days but we packed a lot in.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7616, 'pack something into something', 'to manage to do a lot of activities in a limited period of time:', 'We packed a lot of sightseeing into our weekend in New York.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7617, 'pack something/somewhere out', 'to make a place very full:', 'Around 100,000 football fans packed out the stadium to see the game.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7618, 'pack sth with sth/sb', 'to fill something with things or people of a particular type:', 'We have packed the conference with an exciting line-up of interesting speakers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7619, 'pack up', 'If a machine packs up, it stops operating:', 'My camera has packed up.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7620, 'pack up (something)', 'to stop working or doing another regular activity:', 'She packed up her job, and went off to Australia.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7621, 'pack (something) up', 'to collect all your things together when you have finished doing something:', 'I''m about to pack up my things and go home.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7622, 'packed/squashed like sardines', 'If people are packed or squashed like sardines, they are positioned very close together so that they cannot move:', 'We were squashed like sardines in the rush-hour train.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7623, 'pad something out', 'If you pad out a speech or piece of writing, you add unnecessary words or information to make it longer or to hide the fact that you are not saying anything very important.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7624, 'paddle your own canoe', 'If you describe a person as paddling their own canoe, you mean that they are independent and do not need help from anyone else.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7625, 'page through sth', 'to go from one page to the next in a book or newspaper, or on a computer screen:', 'The presenter paged through her slides with a remote control.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7626, 'paint a black picture of something/someone', 'to describe a situation or person as extremely bad', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7627, 'paint a picture (of something)', 'to describe something in a particular way:', 'The statistics do not paint an optimistic picture.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7628, 'paint a picture (of something)', 'to describe or show something in a particular way:', 'The statistics do not paint an optimistic picture.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7629, 'paint the town red', 'to go out and enjoy yourself by drinking alcohol, dancing, laughing with friends, etc.:', 'I''m ready to paint the town red with a few of my closest friends.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7630, 'painting by numbers', 'a simple way of painting a picture by filling in a printed drawing that has numbered sections for the different colours of paint:', 'The grid evokes childhood memories of painting by numbers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7631, 'painting by numbers', 'something that is very easy to do and does not need skill:', 'Business is not that simple; it is not a matter of painting by numbers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7632, 'pair off', 'to begin a romantic or sexual relationship with someone:', 'All my friends seem to be pairing off and getting married.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7633, 'pair someone off', 'to introduce two people to each other so that they will start a romantic relationship:', 'I managed to pair my best friend Sue off with Mike.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7634, 'pair (someone) off', 'If a group of people pair off, they divide into pairs in order to do something, and if you pair them off, you divide them into pairs:', 'The students paired off to practise their conversational skills.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7635, 'pair up', 'to join together temporarily with another person in order to do something:', 'Everyone should pair up for the next dance.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7636, 'pal around', 'to spend time with someone that you are very friendly with:', 'He used to pal around with one of the president''s sons.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7637, 'pal up', 'to become friends with someone:', 'I''ve palled up with some people from work and we''re going on holiday together.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7638, 'pale in comparison', 'to seem much less serious or important when compared with someone or something else:', 'I thought I was badly treated but my experiences pale in comparison with yours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7639, 'pale in comparison (with something/someone)', 'to be not nearly as good as something or someone else:', 'The paintings he made later pale in comparison with his earlier work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7640, 'pale into insignificance', 'to seem not important when compared with something else:', 'Everything else that happened in my life pales into insignificance beside that one event.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7641, 'palm someone off with something', 'to give someone an untrue or unsatisfactory answer, or to give someone something that has no value in order to try to satisfy them and make them go away:', 'You''re not going to palm me off with that feeble excuse.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7642, 'palm something off', 'to give away something, or persuade someone to accept something, because you do not want it and you know it has no value:', 'She tried to palm her old car off on me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7643, 'pan out', 'to develop in a particular way or in a successful way:', 'We''ll have to see how things pan out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7644, 'pander to someone/something', 'to do or provide exactly what a person or group wants, especially when it is not acceptable, reasonable, or approved of, usually in order to get some personal advantage:', 'It''s not good the way she panders to his every whim.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7645, 'pant for/after someone/something', 'to want someone or something very much:', 'The newspapers are panting for details of the scandal.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7646, 'paper over something', 'to hide an unpleasant situation, especially a problem or disagreement, in order to make people believe that it does not exist or is not serious:', 'He tried to paper over the country''s deep-seated problems.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7647, 'paper over the cracks', 'to hide problems, especially arguments between people, in order to make a situation seem better than it really is:', 'She tried to paper over the cracks, but I could see that the relationship was failing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7648, 'par for the course', 'what should be expected because of past experience:', 'The school budget is going to be cut again this year, but then that’s par for the course.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7649, 'parcel something out', 'to divide something and give the separate parts to different people:', 'The bigger farms were parcelled out after the revolution in 1973.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7650, 'parcel something up', 'to wrap something and make it into a parcel:', 'Parcel up the books and we''ll send them off tomorrow.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7651, 'parcel sth off', 'to get rid of something:', 'parcel sth off to sb Human Resources administrators were considering plans to parcel health services off to a private provider.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7652, 'pardon (me)', 'used to say that you are sorry for doing something wrong or for being rude', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7653, 'pardon me for breathing/existing/living!', 'used to tell someone that you think they have just answered or spoken to you in an unreasonably critical or rude way:', '"If you''re going to get in my way, James, could you just leave the kitchen?" "Oh, pardon me for breathing!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7654, 'pare something (down) to the bone', 'to reduce something to a level at which only what is absolutely necessary is left', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7655, 'park the bus', 'If a football team parks the bus, it defends without trying to attack, with almost all of the players on the team staying deep inside their own half of the pitch.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7656, 'park up', 'to put a vehicle in a place where it can stay for some time:', 'We decided to park up for the night and sleep in the car.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7657, 'parlay sth into sth', 'to achieve success by using a small advantage or opportunity in an effective way:', 'They parlayed some modest investments into massive profits for the company.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7658, 'part company', 'If two people part company, they end their relationship:', 'The world''s number one tennis player and his coach parted company earlier this month.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7659, 'part of the furniture', 'something or someone so familiar that you no longer notice it, him, or her', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7660, 'part with something', 'to give something to someone else, especially when you do not want to:', 'I was going to give away her old baby clothes, but I couldn''t bring myself to part with them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7661, 'partner up', 'to marry or form a long and serious relationship with another person:', 'All his friends were partnering up and settling down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7662, 'partner up', 'to act as someone''s partner in a sport, game, dance, or activity:', 'They partner up and throw weighted medicine balls at each other.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7663, 'partner up', 'to join with another person or organization in a business activity:', 'Businesses partner up with local schools to offer work experience to students.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7664, 'pass (all) belief', 'to be (extremely) difficult to believe:', 'It passes all belief that he could have been so selfish.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7665, 'pass as someone/something', 'to be accepted as something:', 'She had to go out in the world and try to pass as a boy.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7666, 'pass as/for sth/sb', 'to appear to be something or someone else, or try to make others believe that they are:', 'These watches are good-quality fakes, and would pass for the genuine article in a store.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7667, 'pass away', 'polite expression for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7668, 'pass for sb/sth', 'to be accepted as something:', 'I really want to go and see the film, but I don''t think I''d pass for 18.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7669, 'pass judgment on someone/something', 'to express a strong opinion about someone or something:', 'Don’t pass judgment on Lori until you hear what happened.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7670, 'pass muster', 'to reach an acceptable standard:', 'New teams won''t be admitted to the league if their stadiums don''t pass muster.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7671, 'pass off', 'to happen:', 'The pop festival passed off peacefully, despite the fears of local residents.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7672, 'pass on', 'polite expression for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7673, 'pass on something', 'to refuse an opportunity or decide not to take part in something:', 'He passed on the chance to be head coach and took a job in Florida.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7674, 'pass something on', 'to tell someone something that another person has told you:', 'If he provided us with any information, no one passed it on to me.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7675, 'pass something on', 'to give someone something that another person has given you:', 'Could you pass it on to Laura when you''ve finished reading it?', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7676, 'pass something on', 'to give a disease to another person:', 'It''s possible to pass on the virus to others through physical contact.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7677, 'pass out', 'to become unconscious for a short time, for example when ill, badly hurt, or drunk:', 'I was hit on the head and passed out.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7678, 'pass out', 'to leave a military college after successfully finishing the course:', 'The new officers passed out from Britannia Royal Naval College on Thursday 1 August .', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7679, 'pass something out', 'to give something to each person in a group of people:', 'The teacher passed out the test booklets.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7680, 'pass someone by', 'If an event or opportunity passes you by, you do not notice it, or get any pleasure or advantage from it:', 'Do you ever feel that life is passing you by?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7681, 'pass someone/something over', 'to ignore or not give attention to someone or something:', 'The woman alleges that her employers passed her over for promotion because she was pregnant.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7682, 'pass something around', 'to offer something to each person in a group of people:', 'Could you do me a favour and pass these sandwiches around?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7683, 'pass something down', 'to teach or give something to someone who will be alive after you have died:', 'His is a family trade, passed down from generation to generation.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7684, 'pass something off as something', 'to pretend that something is a particular thing when it is not:', 'The dealer was trying to pass off fakes as valuable antiques.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7685, 'pass something round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7686, 'pass something up', 'to fail to take advantage of an opportunity:', 'I can''t believe she passed up the chance to go to South America.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7687, 'pass sth around/round', 'to offer something to each person in a group of people:', 'The managing editor passed the copy around to get feedback.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7688, 'pass sth on/along to sb', 'to tell someone something that another person has told you:', 'That''s good news – I''ll pass it on to the rest of the team.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7689, 'pass sth on/along to sb', 'if a company passes higher or lower costs on to its customers, it raises or reduces prices :', 'The car industry is too competitive to pass higher costs along to customers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7690, 'pass the buck', 'to blame someone or make them responsible for a problem that you should deal with:', 'She''s always trying to pass the buck and I''m sick of it!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7691, 'pass the hat', 'to ask a number of people to give money for something, esp. to help pay for something or reward someone:', 'They''re passing the hat around the company to get money for charity.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7692, 'pass the hat (around)', 'to try to collect money by asking people or organizations', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7693, 'pass the hat around/round', 'to try to collect money by asking people or organizations', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7694, 'pass the time', 'to do something to keep busy while waiting:', '[ T ] We passed the time in the airport playing cards.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7695, 'pass the time of day', 'to have a short informal conversation:', 'I was just passing the time of day with her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7696, 'pass water', 'polite expression for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7697, 'pass wind', 'to release gas from the bowels through the anus:', 'He had the look of someone who is trying to pass wind quietly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7698, 'passions run high', 'a way of describing a time when people feel strong emotions about a particular subject:', 'Passions run very high at election time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7699, 'past your/its prime', 'after the best, most successful, most productive stage:', 'He can still play, but he''s past his prime.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7700, 'pat someone down', 'to search someone for weapons, drugs, etc. by touching their clothes:', 'The police handcuffed him and patted him down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7701, 'pat someone on the back', 'to praise someone for doing something good', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7702, 'a pat on the back', 'praise:', 'I got a pat on the back from (= was praised by) my boss.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7703, 'patch into something', 'to connect to a device or network:', 'The team has the ability to patch into the Cleveland Clinic health care system for instant access to X-rays, MRIs, and other test results.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7704, 'patch something into something', 'to connect one device to another or to a network:', 'The cameras are patched into a computer that sees the video in real time and analyzes it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7705, 'patch someone through', 'to connect someone to a phone number or network:', 'I patched her through to customer service.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7706, 'patch something together', 'to arrange something very quickly but not very carefully:', 'There is much disagreement, but the group of countries is trying to patch together a treaty on defence.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7707, 'patch something up', 'to try to improve a relationship after there have been problems:', 'Jackie and Bill are still trying to patch up their marriage.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7708, 'patch something up', 'to repair something, especially in a simple and temporary way', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7709, 'patch someone/something up', 'to give basic medical care to someone that helps them temporarily:', 'If you''ve cut your hand, the first-aider will patch you up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7710, 'paths cross', 'If two people''s paths cross, the people meet:', 'It was a pleasure meeting you - I hope our paths cross again.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7711, 'pattern yourself on someone/something', 'to copy something or someone:', 'She patterns herself on her big sister.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7712, 'pave the way', 'If something paves the way for/to something else, it makes the other thing possible:', 'Scientists hope that data from the probe will pave the way for a more detailed exploration of Mars.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7713, 'pave the way (for something/someone)', 'to make it possible or easier for something or someone to follow:', 'Data from the space flight should pave the way for a more detailed exploration of Mars.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7714, 'paved with gold', 'used about a city to mean that it is easy to make money there:', 'Unemployed youngsters still come to London thinking that the streets are paved with gold.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7715, 'pay (something) out', 'to spend a lot of money on something, or to pay a lot of money to someone:', 'I''ve just paid out $500 on getting the car fixed.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7716, 'pay something out', 'to release a piece of rope or cable in a controlled way', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7717, 'pay dividends', 'If something you do pays dividends, it causes good results at a time in the future:', 'All that extra training is paying dividends.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7718, 'pay down something', 'to pay part of an amount that you owe, so that the debt is reduced:', 'She plans to live at home with her mother while she pays down her student loan.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7719, 'pay for something', 'to be punished for doing something bad to someone else, or to suffer because of a mistake that you made:', 'We all pay for our mistakes in some way at some time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7720, 'pay into sth', 'to pay money regularly towards a pension:', 'He has been paying into a private pension scheme for 30 years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7721, 'pay it forward', 'to do something kind or useful for someone because someone else has done something kind or useful for you :', 'We are so thankful for their kindness and generosity and we promise to pay it forward.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7722, 'pay off', 'If something you have done pays off, it is successful:', 'All her hard work paid off in the end, and she finally passed the exam.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7723, 'pay something off', 'to pay back money that you owe:', 'We should be able to pay off the debt within two years.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7724, 'pay someone off', 'If your employer pays you off, they pay you for the last time and then end your job, because you are not needed or there is not enough money to pay you in the future.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7725, 'pay someone off', 'to give someone money so that they will not do or say something, or so that they will go away:', 'There were rumours that key witnesses had been paid off to keep quiet.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7726, 'pay someone a visit', 'to visit someone:', 'Why don’t you pay us a visit next time you’re in town?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7727, 'pay someone/something back', 'to pay someone the money that you owe them:', 'Can you lend me a fiver? I''ll pay you/it back tomorrow.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7728, 'pay someone back', 'to do something unpleasant to someone because they have done something unpleasant to you:', 'He swore he''d pay her back for all she''d done to him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7729, 'pay something in', 'to put money into a bank account:', 'If you go to the bank, will you pay these cheques in for me?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7730, 'pay sth in/pay sth into sth', 'to put money into a bank account:', 'They offer 3% interest if you pay a minimum of £1,000 a month into the account.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7731, 'pay the price', 'to experience the bad result of something you have done:', 'If you abuse your body now, you''ll pay the price when you''re older.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7732, 'pay the ultimate price', 'to die because of something you have done, especially something you do for moral reasons:', 'These soldiers have paid the ultimate price for their country''s freedom.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7733, 'pay through the nose', 'to pay too much money for something:', 'We paid through the nose to get the car fixed.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7734, 'pay through the nose (for something)', 'to pay too much money for something:', 'If you drive into the city, you have to pay through the nose for parking.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7735, 'pay top dollar', 'to pay a lot of money for something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7736, 'pay up', 'to give someone the money that you owe them, especially when you do not want to:', 'Eventually they paid up, but only after receiving several reminders.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7737, 'pay your dues', 'to do something that you do not enjoy in order to have something that you want, or because you feel it is your duty', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7738, 'pay your respects', 'to visit someone in order to welcome or talk to them:', 'We went to pay our respects to our new neighbours.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7739, 'pay your respects', 'to honour someone after their death, usually by going to the person''s funeral:', 'Friends and relatives came to pay their last respects to Mr Clarke.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7740, 'pay your way', 'to pay for yourself rather than allowing someone else to pay', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7741, 'payback''s a bitch', 'If a person says payback''s a bitch, they mean that something bad has happened as a result of something else.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7742, 'peace of mind', 'a feeling of calm or not being worried:', 'For my peace of mind, please check that the door is locked.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7743, 'peck at something', 'to eat small quantities of something without any enthusiasm', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7744, 'peel away/off', 'When vehicles, people, or animals peel away/off, they separate from the group or structure they were part of and move away in a different direction:', 'One motorbike peeled away from the formation and circled round behind the rest.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7745, 'peg down', 'to fix something in place:', 'The tent’s ropes were pegged down by two-foot stakes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7746, 'peg out', 'to die', '', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7747, 'peg out', 'to stop working:', 'The car finally pegged out about 20 miles from home.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7748, 'peg something out', 'If you peg out an area, you mark the edges of it by putting short sticks into the ground.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7749, 'pelt (down)', 'to rain heavily:', 'It''s pelting down (with rain).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7750, 'pen someone in/up', 'to keep people or animals in a small area:', 'The sheep were penned in behind the barn.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7751, 'pencil something/someone in', 'to arrange for something to happen or for someone to do something on a particular date or occasion, knowing that the arrangement might be changed later:', 'We''ll pencil in the dates for the next two meetings and confirm them later.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7752, 'pension someone off', 'to make someone leave a job and give them a pension:', 'Workers in the company are being pensioned off at 50.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7753, 'pension something off', 'to stop using something, usually a machine, because it is old and has been used too much:', 'After flying for 38 years, their Wessex helicopter is about to be pensioned off.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7754, 'people something/somewhere by/with someone', 'If something or somewhere is peopled by/with a particular type of person, it is filled with them:', 'Her novels are peopled with the rich and beautiful.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7755, 'people who live in glass houses shouldn''t throw stones', 'This means that you should not criticize other people for bad qualities in their character that you have yourself.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7756, 'pep someone/something up', 'to make someone or something more energetic or interesting:', 'A good night''s sleep will pep you up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7757, 'pepper something with something', 'to hit something repeatedly with small objects:', 'The city''s walls were peppered with bullets.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7758, 'pepper something with something', 'If you pepper a speech or piece of writing with something, you include a lot of that particular thing:', 'The letter was peppered with exclamation marks.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7759, 'perform/work miracles/a miracle', 'to be extremely effective in improving a situation:', 'You''ve performed a miracle in this kitchen - I''ve never seen it so clean!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7760, 'perish the thought', 'said to show that you hope that something that has been suggested will never happen:', 'Me, get married? Perish the thought!', 'idiom', '', 'humorous, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7761, 'perk (someone) up', 'to become or cause someone to become happier, more energetic, or more active:', 'She perked up as soon as I mentioned that Charles was coming to dinner.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7762, 'perk up', 'to improve or become more exciting:', 'Prices perked up slightly before the close of trading.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7763, 'pertain to something', 'to be connected with a particular subject, event, or situation:', 'We are only interested in the parts of the proposals that pertain to local issues.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7764, 'peter out', 'to gradually stop or disappear:', 'The fighting which started in the night had petered out by morning.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7765, 'phase something in', 'to introduce something gradually or in stages:', 'They will phase the new healthcare system in over a period of five years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7766, 'phase something out', 'to remove or stop using something gradually or in stages', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7767, 'phase sth down', 'to remove or stop using something gradually or in stages:', 'We are working to phase down the use of this dangerous gas.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7768, 'phone in', 'to phone the place where you work in order to tell your employer something:', 'She phoned in sick (= saying that she was ill) this morning.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7769, 'phone in', 'to phone a television or radio programme in order to express your opinion on a matter:', 'Over 300 people phoned in to complain.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7770, 'phone something in', 'If someone phones in a performance, they do it without any effort:', 'The actor phoned in his performance without a hint of personality.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7771, 'phone up', 'to call someone on the phone:', 'I''ll phone up and see if they have any tickets left.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7772, 'pick ''n'' mix', 'a system in a shop where you can choose a few of several different small things, especially sweets', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7773, 'pick a fight', 'to intentionally start a fight:', 'Some kids were teasing him, trying to pick a fight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7774, 'pick a fight/quarrel/argument', 'to start a fight/quarrel/argument with someone:', 'He''d had too much to drink and tried to pick a fight with the bartender.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7775, 'pick and choose', 'to take only the things you want from a group:', 'You can''t pick and choose which rules you want to follow and which ones you don''t.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7776, 'pick at something', 'to eat only a small amount of your food, showing no interest or enjoyment while you eat it:', 'Charles picked at his food in a bored fashion.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7777, 'pick holes in something', 'to find mistakes in something someone has done or said, to show that it is not good or not correct', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7778, 'pick on someone', 'to criticize, punish, or be unkind to the same person often and unfairly:', 'He gets picked on by the other boys because he''s so small.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7779, 'pick on someone your own size', 'said to someone who wants to fight a person who is smaller than they are:', 'Just leave me alone, will you? Why don''t you go and pick on someone your own size?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7780, 'pick over something', 'to look carefully at a group of things, choosing the ones you want or getting rid of the ones you do not want:', 'All the clothes at the sale had been thoroughly picked over and there was nothing nice left.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7781, 'pick someone up on something', 'to criticize someone about something they have said:', '"I want to pick you up on the point you made a few minutes ago about personal morality, Archbishop."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7782, 'pick up on something', 'to start talking again about something that someone said previously:', 'Can I just pick up on your first point again, please?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7783, 'pick up on something', 'to notice something that other people have not noticed:', 'Only one newspaper picked up on the contradictions in the statement.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7784, 'pick someone''s brain', 'to ask someone who knows a lot about a subject for information or their opinion:', 'Can I pick your brain about how you got rid of those weeds?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7785, 'pick someone''s brains', 'to ask someone who knows a lot about a subject for information or their opinion:', 'I was picking Simon''s brains about which computer to buy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7786, 'pick someone''s pocket', 'to steal small objects, especially money, from someone''s pockets or bag', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7787, 'pick someone/something off', 'to shoot at one particular person, animal, or vehicle that you have chosen from a group:', 'The snipers picked the soldiers off one by one as they ran for cover.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7788, 'pick someone/something off', 'to take the best person or thing from a group:', 'It is relatively easy for newcomers to pick off the most lucrative business and ignore the rest.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7789, 'pick someone/something out', 'to recognize, find, or make a choice among different people or things in a group:', 'Can you pick out the three deliberate mistakes in this paragraph?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7790, 'pick someone/something out', 'to choose and emphasize, make clearer, or highlight someone or something:', 'The ship''s name was picked out in bright gold letters along her stern.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7791, 'pick something out', 'If you pick out a tune, you play it slowly or with difficulty, note by note:', 'I can pick out a simple tune on the piano, but that''s about it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7792, 'pick someone/something up', 'to lift someone or something using your hands:', 'If she starts to cry, pick her up and give her a cuddle.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7793, 'pick someone/something up', 'to collect, or to go and get, someone or something:', 'When you''re in town could you pick up the books I ordered?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7794, 'pick something up', 'to learn a new skill or language by practising it rather than being taught it:', 'Don''t bother with the computer manual - you''ll pick it up as you go along.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7795, 'pick something up', 'to learn interesting or useful information from someone or something:', 'The nurse had picked up the information from a conversation she overheard.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7796, 'pick something up', 'to buy something cheaply:', 'She picked up some real bargains in the sale.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7797, 'pick something up', 'to win or get a prize or something that gives you an advantage, such as votes or support:', 'The People''s Front expect to pick up a lot more votes in this year''s elections.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7798, 'pick something up', '(of a piece of electrical equipment) to receive a signal:', 'Can you pick up (= receive broadcasts from) Moscow on your radio?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7799, 'pick something up', 'to notice and react to something:', 'Police dogs picked up the scent of the two men from clothes they had left behind.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7800, 'pick something up', 'to catch an illness from someone or something, caused by bacteria or a virus:', 'He picked up malaria when he was visiting the country on business.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7801, 'pick (something) up', 'to start something again after an interruption:', 'The author picks the same theme up again on page ten.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7802, 'pick someone up', '(of the police) to stop someone and take them to a police station in order to be questioned or arrested:', 'He was picked up by the police for drug dealing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7803, 'pick someone up', 'to start a sexual or romantic relationship with someone you do not know, by talking to that person and giving them a lot of attention:', 'He said he''d picked the woman up in a bar.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7804, 'pick up', 'to increase or improve:', 'The truck picked up speed slowly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7805, 'pick up', 'to answer the phone:', 'I tried his home number but he didn''t pick up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7806, 'pick through something', 'to look at the things in a group and take only what you want:', 'I had to pick through the rubbish to find my electricity bill.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7807, 'pick up steam', 'to start working or producing at a faster rate or more effectively:', 'After a slow start, the project began to pick up steam.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7808, 'pick up the bill/tab', 'to pay for what has been bought, especially a meal in a restaurant', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7809, 'pick up the phone', 'to make a phone call to someone:', 'If you need me, you just have to pick up the phone.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7810, 'pick up the pieces', 'to try to return to a satisfactory situation:', 'The fire was a blow, but we were determined to pick up the pieces and get the business back on its feet.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7811, 'pick up the slack', 'to improve a situation by doing something that someone else has not done or not completed:', 'With our best player injured, other players have to pick up the slack.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7812, 'pick up the tab (for something)', 'to pay for something, esp. for what someone else has bought or used:', 'The company will pick up the tab for this trip.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7813, 'pick up the thread(s)', 'to start again after an interruption:', 'Picking up the threads of our discussion, let''s return to the topic of factory farming.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7814, 'pick up/take the ball and run with it', 'to continue an activity or process that someone else has started, often when that person could not finish it or make it work:', 'We had a very vague idea of what we wanted, but the marketing team just took the ball and ran with it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7815, 'pick up/take up the slack', 'to do the work that someone else has stopped doing but still needs to be done:', 'If Sue gets a job, Mike will have to take up the slack at home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7816, 'pick your way somewhere', 'to walk carefully and slowly:', 'Charlie picked his way through the muddy field.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7817, 'pick yourself up off the floor', 'to make improvements to your life after a bad period', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7818, 'pick/pull someone/something to pieces', 'to criticize someone or something severely:', 'The moment she left, the rest of the family started to pull her to pieces.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7819, 'pie in the sky', 'something that you hope will happen but is very unlikely to happen:', 'Their plans to set up their own business are just pie in the sky.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7820, 'piece something together', 'to create something by joining the separate parts of it together or by joining different things together:', 'The ancient skull has been pieced together from fragments.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7821, 'pig out', 'to eat a lot or too much:', 'We pigged out on all the delicious cakes and pastries.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7822, 'pigs can fly', 'said when you think that there is no chance at all of something happening:', '"I''ll have finished it by tomorrow." "And pigs can fly!"', 'idiom', '', 'humorous, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7823, 'pigs might fly', 'said when you think that there is no chance at all of something happening:', '"I''ll have finished it by tomorrow." "And pigs might fly!"', 'idiom', '', 'humorous, saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7824, 'pile (something) up', 'to form a pile, or to put a lot of things into a pile', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7825, 'pile (something) up', '(of something bad) to increase:', 'Unpaid bills began to pile up alarmingly.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7826, 'pile it high and sell it cheap', 'to sell large amounts of a product at cheap prices', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7827, 'pile it on', 'to say too much, especially giving too much emphasis:', 'You''re really piling it on with the compliments tonight, Gareth, aren''t you!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7828, 'pile on', 'to increase quickly:', 'After she had the heart attack, the pounds piled on, and her weight rose to 15 stone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7829, 'pile something on', 'to make something increase quickly:', 'I''d given up smoking, but I piled on weight as a result, which was a bad thing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7830, 'pile on the agony', 'to enjoy emphasizing how bad a situation is:', 'Okay, I''ll give you some money - just stop piling on the agony.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7831, 'pile on the pounds', '(of a person) to gradually get heavier and fatter:', 'She did slim down a couple of years ago but has piled on the pounds again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7832, 'pile something onto someone', 'to give someone a lot, or too much, of something:', 'Management was strict but fair and the hardest part of the job was probably keeping up with everything they piled onto me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7833, 'pin back your ears', 'to listen carefully', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7834, 'pin someone down', 'to stop someone from escaping by surrounding and shooting at them if they try to escape:', '[ often passive ] Government forces were pinned down by resistance fighters 30 miles north of the capital.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7835, 'pin someone down', 'to make someone provide details about something or make a decision about something:', 'I''ve tried asking Stephanie, but she''s proving difficult to pin down to a particular date.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7836, 'pin something down', 'to discover exact details about something:', 'We can''t pin down where the leak came from.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7837, 'pin something on someone', 'to blame someone for something, especially for something they did not do:', 'You can''t pin the blame on her - she wasn''t even there when the accident happened.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7838, 'pin your hopes on something/someone', 'to hope very much that something or someone will help you to achieve what you want', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7839, 'pinch pennies', 'to spend as little money as possible:', 'When we were first married we had to pinch pennies just to get by.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7840, 'pine for something/someone', 'to want or miss something or someone very much:', 'He''s still pining for his ex-girlfriend.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7841, 'pipe down', 'to stop talking or making unnecessary noise:', 'Will you please pipe down, you two? I''m trying to read!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7842, 'pipe up', 'to suddenly start to speak or make a noise:', 'In the silence that followed, a lone voice piped up from the back of the room.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7843, 'pique someone''s curiosity, interest, etc.', 'to make someone interested in something and want to know more about it:', 'The noise continued, piquing her curiosity.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7844, 'piss (someone) about/around', 'to behave in a stupid way or to treat someone badly:', 'Look, we don''t have much time, so stop pissing about.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7845, 'piss down', 'to rain heavily:', 'It''s really pissing (it) down here at the moment.', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7846, 'piss off', 'to leave or go away; used especially as a rude way of telling someone to go away:', 'Everyone just pissed off and left me to clean up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7847, 'piss someone off', 'to annoy someone:', 'He never helps with the housework and it''s starting to piss me off.', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7848, 'piss something away', 'to waste an opportunity:', 'This is your last chance to win the league so don''t piss it away.', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7849, 'piss yourself (laughing)', 'to laugh very much:', 'There I was writhing in agony on the floor and you were all pissing yourselves laughing!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7850, 'piss/shit your pants', 'to suddenly feel very frightened:', 'I shit my pants when all the lights went out.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7851, 'pissed as a newt/fart', 'very drunk', '', 'idiom', '', 'UK', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7852, 'pit of your stomach', 'the part of the body in which people say they feel fear or nervousness:', 'I got a sick feeling/a knot in the pit of my stomach when the news of the attack was announced.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7853, 'pit someone/something against someone/something', 'to cause one person, group, or thing to fight against or be in competition with another:', 'It was a bitter civil war, that pitted neighbour against neighbour.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7854, 'pit your wits against someone/something', 'to see if you can be cleverer than someone or something:', 'Would you like to pit your wits against our quiz champion?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7855, 'pitch in', 'to start to do something as part of a group, especially something helpful:', 'If we all pitch in together, it shouldn''t take too long.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7856, 'pitch into someone/something', 'to criticize or attack someone or something forcefully:', 'He pitched into me as soon as I arrived, asking where the work was.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7857, 'pitch up', 'to arrive in a place:', 'Gerald finally pitched up two hours late.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7858, 'pitchfork someone into something', 'to cause someone suddenly to be in a particular situation, usually a difficult one, especially when they are not ready:', 'Her father died when she was 22, and she was pitchforked into the running of the estate.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7859, 'plan on doing something', 'to intend to do something:', 'We were planning on just having a snack and catching the early train.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7860, 'plan on someone/something doing something', 'to realize that someone might do something or that something might happen and to make arrangements to deal with the situation:', 'They hadn''t planned on the whole family coming.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7861, 'plan something out', 'to think about and decide what you are going to do or how you are going to do something:', 'I''ve planned out the day - some shopping, then a meal and a show.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7862, 'plant something out', 'to put a plant into the ground outside to continue growing:', 'Plant out the geraniums in early June.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7863, 'plate something up', 'to put food onto plates, so that one plate of food can be served to each person in a group:', 'Will you collect the soup bowls while I plate up the main course?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7864, 'play (it) safe', 'to be careful and not take risks:', 'To play safe, I''d allow an extra ten minutes, just in case.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7865, 'play (merry) hell with something', 'to seriously damage or confuse something:', 'The power cuts played hell with our computers.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7866, 'play (something) by ear', 'to play a piece of music by remembering the notes:', 'He did not need sheet music. He could play the piece by ear.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7867, 'play God', 'to act as if you are in total control of something:', 'Genetic engineers should not be allowed to play God, interfering with the basic patterns of Nature.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7868, 'play a joke/trick on someone', 'to confuse someone or cause problem for them:', 'I thought I heard something - my ears must have been playing tricks on me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7869, 'play along', 'to do what someone asks you to do, for a limited period of time:', 'I know you don''t like Jack''s idea, but just play along with him for a while.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7870, 'play around', 'to behave in a silly way:', 'Stop playing around and get on with your homework!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7871, 'play around', 'If someone who is married or has a serious relationship plays around, they have sex with another person or people:', 'If she finds out he''s been playing around with his secretary, there''ll be trouble.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7872, 'play around with something', 'to try out different methods or different things, before deciding which one to choose:', 'We''ve been playing around with ideas for a new TV show.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7873, 'play at something', 'to pretend to be a particular person or to do a particular thing, usually as a game:', 'The children were playing at Batman and Robin.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7874, 'play at something', 'to do something for enjoyment or interest, or without much care and effort, rather than in a serious way or as a job:', 'She''s only playing at being an actress - she''s going off to law school next year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7875, 'play ball', 'to agree to work with or help someone in the way they have suggested:', 'The family wanted him to be taken care of at home, but the insurance company refused to play ball.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7876, 'play big', 'to take risks and not allow problems and unpleasant feelings to stop you from achieving what you want to achieve :', 'I have always played big in my career.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7877, 'play big', '(in sport) to play very well:', 'Zidane always played big when it counted.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7878, 'play big', 'to be given a lot of attention or importance:', 'The two reports played big on television.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7879, 'play both ends against the middle', 'to try to get opposing people or groups to fight or disagree so that you will get an advantage from the situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7880, 'play cat and mouse', 'to try to defeat someone by tricking that person into making a mistake so that you have an advantage over them:', 'The 32-year-old singer spent a large proportion of the week playing cat and mouse with the press.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7881, 'play chicken', 'to play dangerous games in order to discover who is the bravest', '', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7882, 'play dirty', 'to behave dishonestly, especially by cheating in a game:', 'Don likes hockey, but he plays dirty.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7883, 'play fair', 'to act in a fair and honest way:', 'It wasn''t really playing fair not to tell her the job was already filled.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7884, 'play fast and loose with something/someone', 'to treat something or someone without enough care:', 'Like many movie-makers, he plays fast and loose with the facts to tell his own version of the story.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7885, 'play footsie', 'to touch someone''s feet with your own under the table, usually in order to show sexual interest in the person:', 'She kicked off her shoes and started playing footsie with him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7886, 'play for time', 'to delay until you are ready:', 'We can''t sign the agreement yet - we''ll have to play for time.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7887, 'play games', 'to try to deceive someone:', 'Don''t play games with me!', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7888, 'play gooseberry', 'to be an unwanted third person who is present when two other people, especially two people having a romantic relationship, want to be alone', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7889, 'play hard to get', 'to pretend that you are less interested in someone than you really are as a way of making them more interested in you, especially at the start of a romantic relationship:', 'Why won''t you call him back? Are you playing hard to get?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7890, 'play hardball', 'to be firm and determined in order to get what you want:', 'He''s a nice guy, but he can play hardball when he needs to.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7891, 'play havoc with', 'to make a situation much more difficult or confusing:', 'The snowstorm is really playing havoc with rush-hour traffic.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7892, 'play havoc with', 'to damage something:', 'The acid rain plays havoc with marine life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7893, 'play hooky', 'to stay away from school without permission:', 'They played hooky and went fishing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7894, 'play in the hole', 'in football, to play in the central area of the playing field, immediately in front of the defenders and behind the other midfielders and forwards:', 'Although Mulumbu plays most of the game in the hole, he pushes into the box to support the strikers whenever possible.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7895, 'play it by ear', 'to decide how to deal with a situation as it develops, rather than acting according to plans made earlier:', 'We can''t make a decision yet. Let''s just play it by ear.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7896, 'play it cool', 'to behave in a calm, controlled way, often intentionally appearing not to be interested in the thing that you very much want to get:', 'Play it cool - don''t let them know how much you need the money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7897, 'play it straight', 'to do something seriously, without making jokes or demanding too much attention :', 'It would be easy enough to make fun of much of this, but Barber wisely plays it straight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7898, 'play it straight', 'to do something honestly:', 'I hope for your sake you''re playing it straight.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7899, 'play off', 'to play a game, in a team sport, to decide which side will win:', 'United and Rangers are playing off for the championship.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7900, 'play on words', 'a humorous use of a word with more than one meaning or that sounds like another word:', 'The name of the shop - "Strata Various" - is a play on words, because it sounds like Stradivarius, the famous violin maker.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7901, 'play on/upon something', 'If you play on/upon someone''s feelings, you encourage and make unfair use of these feelings in order to give yourself an advantage:', 'I hate marketing strategies that play on people''s fears and prejudices.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7902, 'play politics', 'to use a situation or the relationships between people for your own advantage:', 'He accused councillors of playing politics with children''s education.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7903, 'play possum', 'to pretend to be dead or sleeping so that someone will not annoy or attack you:', 'I don''t think he''s really asleep. He''s playing possum.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7904, 'play second fiddle', 'to be less important or in a weaker position than someone else:', 'I''m not prepared to play second fiddle to Christina any more - I''m looking for another job!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7905, 'play silly buggers', 'to behave in a silly, stupid, or annoying way:', 'There''ll be a serious accident sooner or later if people don''t stop playing silly buggers.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7906, 'play small', 'to avoid risks and actions that might cause problems or make you feel uncomfortable, with the result that you might not achieve what you want to achieve :', 'Playing small means our actions are motivated by our fears, insecurities, and low self-worth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7907, 'play someone at their own game', 'to try to get an advantage over someone by using the same methods as they use:', 'If women want to succeed in business, they have to play men at their own game.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7908, 'play someone/something off against someone/something', 'to encourage one person or group to compete or argue with another, hoping to gain some advantage from this situation:', 'Management policy seemed to be to play one department off against another.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7909, 'play something back', 'If you play back something that has been recorded, you put it through a machine so that you can listen to it or watch it:', 'The message I recorded for the answering machine sounded terrible when I played it back.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7910, 'play something down', 'to make something seem less important or less bad than it really is:', 'Military spokespeople tried to play down the seriousness of the disaster.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7911, 'play something out', 'to pretend that an imaginary situation or event is really happening:', 'In the psychotherapy group, patients were free to play out their fantasies.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7912, 'play itself out', 'If a situation plays itself out, it develops until nothing more can happen, and it is no longer very important:', 'We were forced to stand back and let the crisis play itself out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7913, 'play out', 'When a situation plays out, it happens and develops:', 'The debate will play out in the media over the next week or two.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7914, 'play something up', 'to emphasize a particular quality or part of something, or make it seem more important than it really is, usually for your own advantage:', 'The official report plays up the likely benefits of the plan, but glosses over the costs.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7915, 'play (someone) up', 'to cause someone pain:', 'His knee''s been playing him up again.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7916, 'play up', 'When children play up, they behave badly:', 'The boys have been playing up at school again.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7917, 'play up', 'If a machine plays up, it does not work as it should:', 'The starter motor was playing up again.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7918, 'play the field', 'to hold an interest in a number of people or things, especially to become romantically or sexually involved with a number of partners:', 'Becky''s not ready to settle down with one man - she enjoys playing the field too much.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7919, 'play the game', 'to behave fairly:', 'You should have told them - it wasn''t playing the game to keep it secret.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7920, 'play the race card', 'If someone accuses someone else of playing the race card, they think that person is trying to gain special treatment because of their race.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7921, 'play the race, gender, etc. card', 'to claim that you have been treated unfairly because of your race, sex, etc., in order to get an advantage:', 'His critics say he played the race card by accusing his opponents of conspiring to bring down an uppity black man.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7922, 'play the system', 'to use the rules of a system to get an advantage for yourself, in a way that is wrong or dishonest:', 'There are some really powerful people who are in it for self-interest, who kind of play the system for personal and institutional gain.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7923, 'play to the gallery', 'to behave in a way intended to make people admire or support you:', 'Politicians these days are more interested in playing to the gallery than exercising real influence on world events.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7924, 'play to the whistle', 'used to say that a football player should continue playing until the referee blows the whistle, rather than stop playing because he or she thinks the referee will award a foul, throw-in, etc.:', 'You always have to play to the whistle.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7925, 'play up to someone', 'to try to make someone like you and treat you well by behaving in a way you think will please them:', 'Julia knows how to play up to the supervisors - she can always get time off work when she wants it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7926, 'play with fire', 'to act in a way that is very dangerous and to take risks', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7927, 'play with something', 'to consider an idea or plan:', 'Patricia and I were playing (around) with the idea/possibility of moving to Glasgow.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7928, 'play with something', 'to keep touching and moving something around with no purpose or interest:', 'Stop playing with your hair!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7929, 'play with yourself', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7930, 'play your cards right', 'to behave in a way that gives you an advantage or allows you to succeed at something:', 'If you play your cards right, you could make quite a lot of money out of this.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7931, 'please God', 'used to express a strong hope:', 'It''ll be finished by Christmas, please God.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7932, 'please yourself', 'to do whatever you choose to do, often used in a slightly rude way by someone who does not agree with or care about what you do:', '"I can''t stand this place - I''m going home." "Please yourself."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7933, 'pleased with yourself', 'happy and satisfied about something good that you have done or that has happened to you:', 'Simon''s looking very pleased with himself today.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7934, 'plough into something/someone', 'If a vehicle ploughs into something or someone, it hits the object or person with great force:', 'Many people were injured when the train came off the rails and ploughed into the bank.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7935, 'plough something into something', 'to invest money (= give money hoping to get more back) in a business, especially to help make it successful or to make more money:', 'They ploughed all their savings into their daughter''s business.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7936, 'plough on', 'to continue doing something although it is difficult or boring:', 'He could see that she didn''t like what he was saying, but he ploughed on (= continued talking) regardless.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7937, 'plough something back', 'to spend the money that a business has earned on improving that business:', 'All the profits are being ploughed back into the company.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7938, 'plough something back/in', 'to dig the roots and other remaining parts of a crop into the soil to make the soil more healthy', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7939, 'plough sth back in/plough sth back into sth', 'to spend the money that a business has earned on improving that business:', 'Profits are being ploughed back into the company to allow expansion.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7940, 'plough through something', 'to go through a substance or an area of something with difficulty:', 'We ploughed through the mud.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7941, 'plough through something', 'to finish reading, eating, or dealing with something with difficulty:', 'I''ve got an enormous pile of papers to plough through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7942, 'plow into something/someone', 'If a vehicle plows into something or someone, it hits the object or person with great force:', 'Many people were injured when the train came off the rails and plowed into the bank.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7943, 'plow on', 'to continue doing something although it is difficult or boring:', 'He could see that she didn''t like what he was saying, but he plowed on (= continued talking) regardless.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7944, 'plow something back', 'to spend the money that a business has earned on improving that business:', 'All the profits are being plowed back into the company.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7945, 'plow something back/in', 'to dig the roots and other remaining parts of a crop into the soil to make the soil more healthy', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7946, 'plow through something', 'to go through a substance or an area of something with difficulty:', 'We plowed through the mud.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7947, 'plow through something', 'to finish reading, eating, or dealing with something with difficulty:', 'I have an enormous pile of papers to plow through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7948, 'pluck at something', 'to pull something with your fingers again and again, using quick, small movements:', 'I felt a small hand plucking at my jacket.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7949, 'pluck something out of the air', 'to say something quickly, usually because a reply is expected, without having thought about it or made certain it is correct:', '"Where did you get those figures from?" "Oh, I just plucked them out of the air."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7950, 'pluck up your courage', 'to force yourself to be brave enough to do something, although you are frightened or worried about it:', 'He finally plucked up courage to ask her to marry him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7951, 'plug (something) in/plug (something) into something', 'to connect an electrical device to an electrical system or device so that it can be used, by pushing its plug into a socket:', 'Of course the radio isn''t working - you haven''t plugged it in!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7952, 'plug (something/someone) into something', 'to make something or someone fit well or have good connections with something:', 'This new product line should be able to plug into our existing distribution network.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7953, 'plug into something', 'to get to know and receive information about something, or to start using or being involved in it:', 'Andy is really plugged into the popular music scene.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7954, 'plug away', 'to work hard and in a determined way, especially at something that you find difficult:', 'Katie has been plugging away at her homework for hours.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7955, 'plumb the depths', 'to reach the lowest point:', 'Roy plumbed the depths of despair when his wife left him.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7956, 'plump (someone/something) down', 'to sit down suddenly and heavily, or to put an object or child down suddenly and without taking care:', 'She plumped down next to me on the sofa.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7957, 'plump for something/someone', 'to choose something or someone, especially after taking time for careful thought:', 'I''m going to plump for the vegetable curry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7958, 'plump something up', 'to make something fuller or fatter:', 'She went round plumping up the cushions.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7959, 'plunge (someone/something) into something', 'to suddenly experience a bad situation or unhappiness, or to make someone or something suddenly experience a bad situation or unhappiness:', 'The country was plunged into recession.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7960, 'plunge in/plunge into something', 'to suddenly start doing something actively or enthusiastically:', 'Two months before his exams, he suddenly plunged into his studies.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7961, 'ply someone with something', 'to keep giving a person something, usually food or drink:', 'John''s been plying me with drinks all evening.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7962, 'ply someone with something', 'to keep giving someone work or forms to complete, or asking them questions:', 'We plied Charlie with questions about his trip round the world.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7963, 'poacher turned gamekeeper', 'someone whose behaviour is now the same as that he or she previously opposed:', 'He is the epitome of a poacher turned gamekeeper. Once commander of the whaling station, he now devotes his energy to saving the whale and other marine life of the area.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7964, 'point (something/someone) out', 'to make a person notice someone or something, sometimes by holding up one of your fingers towards him, her, or it:', 'If you see her, please point her out to me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7965, 'point something out', 'to tell someone about some information, often because you believe they do not know it or have forgotten it:', '[ + that ] He was planning to book a rock-climbing holiday, till I pointed out that Denis is afraid of heights.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7966, 'point someone towards/in the direction of something', 'to suggest that someone should do or buy a particular thing:', 'The salesman was trying to point us in the direction of the most expensive furniture in the showroom.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7967, 'point something up', 'to emphasize a problem or fact, so that people notice it more:', 'It was a badly researched documentary that glossed over important questions while pointing up trivial ones.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7968, 'point taken', 'used to say you accept what someone has said', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7969, 'point the finger at someone', 'to accuse someone of being responsible for something bad that has happened:', 'Unhappy tourists have pointed the finger at unhelpful travel agents.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7970, 'point the way', 'to show how something can be done better in the future:', 'Recent medical discoveries are already pointing the way to more efficient vaccines.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7971, 'point the way (to something)', 'to be among the first to show how something can be done:', 'The new research points the way to the development of better vaccines.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7972, 'point to/towards something', 'to make it seem likely that a particular fact is true or that a particular event will happen:', 'All the evidence points to suicide.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7973, 'poison someone''s mind', 'to make someone believe unpleasant things about another person that are not true:', 'Don''t listen to her lies - she''s just trying to poison your mind against me.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7974, 'poke around', 'to search for something by moving things around, usually not in a very careful or organized way:', 'I was poking around in the drawer, looking for the key, when I found this!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7975, 'poke around/about', 'to search through something, esp. without permission or without any particular idea of what you might find:', 'He loves going to auctions and poking around antique shops.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7976, 'poke fun at someone', 'to make someone seem stupid by making jokes about them or laughing unkindly', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7977, 'poke the bear', 'to intentionally make or try to make someone angry or offended, especially someone more powerful than you:', 'He attacked his colleagues for not wanting to poke the bear, referring to them not wanting to confront the president.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7978, 'poke/dig someone in the ribs', 'to push your finger quickly into someone''s chest, usually to make them notice something or to stop them from doing or saying something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7979, 'poles apart', 'completely opposite:', 'My sister and I are poles apart in personality.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7980, 'polish something off', 'to finish som ething quickly and easily, especially a lot of food or work:', 'He polished off the whole pie.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7981, 'polish something/someone off', 'to defeat a competitor easily:', 'Arsenal polished off Chelsea 5–0 in Saturday''s match.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7982, 'polish someone off', 'to kill someone:', 'He was accused of polishing off his former partner.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7983, 'polish something up', 'to rub or brush an object to make it shine, especially a metal or wooden object:', 'Robert was polishing up some old silver candlesticks.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7984, 'polish something up', 'to improve a skill, especially when you have allowed it to become less good over a period of time:', 'I really must polish up my Japanese before we visit Japan next year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7985, 'ponce about/around', 'If a man ponces about/around, he behaves or dresses more like a woman than like a man:', 'He was poncing around in a pair of fluffy slippers.', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7986, 'ponce about/around', 'to waste time doing silly things that do not achieve anything or help anyone:', 'There''s no time for poncing around - we need to get these boxes packed by this evening.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7987, 'pony up (something)', 'to pay (a particular amount of money) for something :', 'As well as putting up his own cash, he persuaded others to pony up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7988, 'poodle around (something)', 'to spend time doing things without any particular purpose or plan:', 'We spent the day poodling around town.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7989, 'poop out', 'to become too tired to continue what you are doing:', 'I just poop out if I stay up too late.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7990, 'poop out', 'to stop working or operating:', 'The engine pooped out before we reached our destination.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7991, 'poop someone out', 'to make someone very tired:', 'All that dancing has really pooped me out.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7992, 'poor man''s...', 'used to refer to something that is a worse or cheaper version of something else that is mentioned:', 'Rugby union was turned into a poor man''s rugby league.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7993, 'poor relation', 'something or someone similar to but less important than another thing or person, and that people do not consider equally valuable:', 'The air force and navy were modernized but the army, very much the poor relation, was not.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7994, 'pop (something) in/into something', 'to put something quickly into something else:', 'Pop the CD-ROM into a personal computer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7995, 'pop (something) in/into something', 'Something that pops into your head/mind is an idea that you suddenly have:', 'He jotted down story ideas that popped into his head.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7996, 'pop in/into (somewhere)', 'to visit briefly:', 'Why don’t you pop in and see us this afternoon?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7997, 'pop in/into (somewhere)', 'If you pop into a place, you visit there briefly, usually for some purpose:', 'All I have to do on the way home is pop into the drugstore.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7998, 'pop off', 'to die:', 'You''re all just waiting till I pop off so you can get your hands on my money.', 'phrasal verb', '', 'humorous', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (7999, 'pop someone off', 'to kill someone', '', 'phrasal verb', '', 'humorous', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8000, 'pop the question', 'to ask someone to marry you:', 'So did he pop the question, then?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8001, 'pop up', 'to move quickly and suddenly from a closed or flat position to a vertical one:', 'This tent pops up fully formed in a couple of seconds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8002, 'pop up', 'to appear or happen, especially suddenly or unexpectedly:', 'She''s one of those movie stars who pops up everywhere, on TV, in magazines, on Broadway.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8003, 'pop your clogs', 'to die:', 'I think I''ll leave all my money to charity when I pop my clogs.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8004, 'pore over something', 'to look at and study something, usually a book or document, carefully:', 'She spends her evenings poring over textbooks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8005, 'portion something out', 'to share something:', 'We''ll have to portion the money out among/between the six of us.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8006, 'pose as someone', 'If you pose as a particular person, you pretend to be that person in order to deceive people:', 'He''s posing as her date, but he''s really her bodyguard.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8007, 'pot something off', 'to move a very young plant from a tray (= a container for several young plants), etc. and plant it in a pot:', 'As soon as it is possible to handle the seedlings, pot them off into small individual pots.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8008, 'pot something on', 'to plant a plant in a larger pot than the one it is in already:', 'Once two leaves appear, pot them on into 3.5-inch pots.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8009, 'pot something up', 'to put a plant into a container to grow:', 'The shoots from the shrub can be potted up and put in a warm place until they develop a good root system.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8010, 'pot something up', 'to plant a plant in a larger pot than the one it is in already:', 'The plants will probably need to be potted up after a few years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8011, 'pot something up', 'to move a very young plant from a tray (= a container for several young plants), etc. and plant it in a pot:', 'Pot up the seedlings into 3 inch pots and keep them in a warm place.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8012, 'pounce on something', 'to immediately criticize a mistake:', 'He knows that his critics are waiting to pounce on any slip that he makes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8013, 'pounce on something', 'to accept something quickly and with enthusiasm:', 'I think if she were given the opportunity to work here, she''d pounce on it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8014, 'pound away at something/someone', 'to criticize something or try to get someone to do something:', 'The campaigners have promised to keep pounding away at the council until the decision to build the road is reversed.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8015, 'pound of flesh', 'something that you have the right to receive but is unreasonable to demand from someone', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8016, 'pour oil on troubled waters', 'to do or say something in order to make people stop arguing and become calmer:', 'My husband''s always arguing with my father, and I''m the one who has to pour oil on troubled waters.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8017, 'pour scorn on someone/something', 'to say a person or thing is stupid and not worth anything:', 'Critics of the president have been pouring scorn on the plan ever since it was first proposed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8018, 'pour something into something', 'to give a lot of money or effort to something with the idea of making it successful:', 'Most of the money raised by the new taxes will be poured into the arena project.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8019, 'pour something out', 'to tell all your problems or feelings to someone, especially privately or secretly:', 'He spends every lunchtime pouring out his emotional problems to me and expects me to find a solution.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8020, 'pour your heart out', 'to tell someone your secret feelings and things that worry you, usually because you feel a strong need to talk about them:', 'I poured my heart out to him and then he told all his friends what I''d said.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8021, 'pour/throw cold water on something', 'to criticize someone''s opinions or ideas and stop people believing them or being excited about them', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8022, 'powder your nose', 'a polite or humorous way of saying that you are going to go to the toilet:', 'Would you get me another drink while I go and powder my nose?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8023, 'power (something) down', 'If something that needs power or energy powers down, or if someone powers it down, it is turned off:', 'Power down your phone and remove the SIM.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8024, 'power (something) up', 'If something that needs power or energy powers up, or if someone powers it up, it is turned on or prepared so that it is ready for use or action:', 'The computer takes a few seconds to power up after it''s been switched on.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8025, 'power through (something)', 'to continue in a strong and determined way until the end of something, even when this is difficult:', 'resilient companies that have powered through the economic downturn
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8026, 'practice makes perfect', 'said to encourage someone to continue to do something many times, so that they will learn to do it very well', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8027, 'practice what you preach', 'to do the things that you advise other people to do:', 'He''s such a hypocrite! He never practices what he preaches.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8028, 'practise what you preach', 'to do the things that you advise other people to do:', 'He''s such a hypocrite! He never practises what he preaches.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8029, 'prat about/around', 'to behave stupidly, especially when you should be behaving in a responsible way:', 'Stop pratting around and get on with your work!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8030, 'preach to the choir', 'to try to persuade people who already agree with you:', 'The men who really need to hear the message don''t come to the meetings, so I''m just preaching to the choir.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8031, 'preach to the converted', 'to try to persuade people to believe things that they already believe:', 'You needn''t bother telling us how recycling helps the environment, because you''re preaching to the converted.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8032, 'predispose someone to/towards something', 'to make someone more likely to behave in a particular way or to suffer from a particular illness or condition:', 'Smoking predisposes you to lung cancer.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8033, 'prepare the ground', 'If you prepare the ground for an activity or a situation, you do something that will help it to happen:', 'The leaders of both countries are preparing the ground for negotiations which may lead to peace.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8034, 'present company excepted', 'used to show that a criticism or a rude remark does not refer to the people you are talking to:', 'People here just don''t know how to dress, present company excepted.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8035, 'preside over something', 'to be in charge of a situation or place :', 'This government has presided over some of the most significant changes in education this century.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8036, 'press ahead (with something)', 'to continue to do something although there is opposition to it:', 'The company pressed ahead with plans to build the skyscraper.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8037, 'press ahead/on', 'to start or continue doing something in a determined way, although it is difficult:', 'press ahead/on with sth Most of the delegates said they wanted to press ahead with the talks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8038, 'press for something', 'to work hard to win support for a plan so that it will succeed:', 'He will press for stricter pollution controls.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8039, 'press home your advantage', 'to use an advantage that you already have in order to succeed', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8040, 'press on/ahead', 'to start or continue doing something in a determined way, often despite problems:', 'It was pouring with rain, but we pressed on regardless.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8041, 'press sb about/on sth', 'to try hard to persuade someone to tell you something:', 'Although he was pressed on the matter by journalists, the minister refused to disclose any further details.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8042, 'press something on someone', 'to give something to someone and not allow them to refuse to accept it:', 'All the children had sweets and presents pressed on them by the visitors.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8043, 'press something/someone into service', 'to use something or someone that is not completely suitable because nothing or no one more suitable is available:', 'The car''s broken down so I''ve had to press my old bike back into service.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8044, 'press the flesh', 'to shake hands with a lot of people:', 'Politicians have to get out and about and press the flesh.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8045, 'press/push someone''s buttons', 'to cause a strong reaction or emotion in someone:', 'My brother knows exactly how to push my buttons (= annoy me).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8046, 'press/push the right button(s)', 'to do exactly what is necessary to get the result that you want:', 'You have to know how to push all the right buttons if you want to be a successful diplomat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8047, 'press/push/hit (all) the right buttons', 'to successfully cause a reaction or emotion in someone, especially when this makes them do what you want :', 'The coach has pushed the right buttons with his players this season.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8048, 'pretty much', 'almost completely:', 'I’ve pretty much finished packing now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8049, 'pretty please', 'used for asking someone for something or persuading them to do something by trying to make yourself sound friendly:', 'Can we have one, too? Please! Pretty please!', 'idiom', '', 'spoken, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8050, 'prevail on/upon someone', 'to persuade someone to do something that they do not want to do:', 'He was eventually prevailed upon to accept the appointment.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8051, 'prevail on/upon someone to do something', 'to persuade someone to do something:', 'My father prevailed on some friends to let us stay with them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8052, 'prevail upon/on sb', 'to persuade someone to do something that they do not want to do:', 'They finally prevailed on him to hand in his resignation.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8053, 'prevention is better than cure', 'It is better to stop something bad from happening than it is to deal with it after it has happened.', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8054, 'prey on sb''s mind', 'If a problem preys on your mind, you think about it and worry about it a lot:', 'I lost my temper with her the other day and it''s been preying on my mind ever since.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8055, 'prey on something', 'If an animal preys on another animal, it catches and eats it:', 'The spider preys on small flies and other insects.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8056, 'prey on someone', 'to hurt or deceive a group of people, especially people who are weak or can easily be hurt or deceived:', 'He would attack at night, preying on lone women in their twenties or thirties.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8057, 'prey on/upon sb/sth', 'to harm somebody who is weaker than you are:', 'It is regrettable that such companies prey upon homeowners who are already experiencing financial difficulties.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8058, 'price someone out', 'to make someone unable to buy or pay for something because the price is too high:', 'Individuals earning the median hourly wage of $15.20 would qualify for a mortgage of $104,532 - effectively pricing them out of most homes in the area.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8059, 'price sth in', 'to include something in the total price of a product, etc.:', 'I''ve priced in the arrangement fees in the total cost of the mortgage.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8060, 'price yourself out of the market', 'If a company prices itself out of the market, it charges so much for a product or service that no one wants to buy it.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8061, 'prick (something) up', 'When an animal pricks its ears up, or when its ears prick up, it puts its ears up straight because it is listening carefully to a small sound or one that is far away.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8062, 'prick (something) up', 'If you prick up your ears, or if your ears prick up, you suddenly begin to listen very carefully because you have heard something interesting:', 'I overheard them mentioning my name and pricked up my ears.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8063, 'prick someone''s conscience', 'to make someone do something because they feel guilty:', 'Dan''s mentioning Julia pricked my conscience and I gave her a call.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8064, 'prick the bubble (of something)', 'to make someone suddenly understand the unpleasant truth of a situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8065, 'prick up your ears', 'to listen carefully:', 'The children pricked up their ears when they heard the word “candy.”', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8066, 'pride comes/goes before a fall', 'said to emphasize that if you are too confident about your abilities, something bad will happen that shows that you are not as good as you think', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8067, 'pride yourself on something', 'to value a skill or good quality that you have:', 'He prides himself on his loyalty to his friends.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8068, 'print something out', 'to produce a printed copy of a document that has been written on a computer:', 'Could you print out a copy of that letter for me?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8069, 'print sth out/off', 'to produce a printed copy of a document that has been written on a computer:', 'Could you print out a copy of that letter for me?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8070, 'prize something out of someone', 'to get something from someone with difficulty, especially information or money:', 'He''s so secretive - you''ll have a hard time prizing any information out of him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8071, 'proceed against someone', 'to start to take legal action against someone:', 'Lack of evidence meant that the Council could not proceed against Mr Naylor.', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8072, 'proceed to sth', 'to move forward to the next stage:', 'If the evidence stands, the case will proceed to trial.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8073, 'profit from something', 'to earn money from something:', 'Many companies will profit from the fall in interest rates.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8074, 'profit from something', 'to achieve an advantage from something:', 'I profited enormously from working with her.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8075, 'project an image', 'to represent yourself in a particular way through your speech, behavior, and appearance:', 'He’s trying to project a more confident image by dressing better.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8076, 'project an image', 'to represent yourself in a particular way through your speech, behavior, and appearance:', 'He’s trying to project a more confident image by dressing better.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8077, 'promise someone the earth/moon', 'to say that you will do much greater things than you will ever be able to achieve:', 'Like most governments in their first term of office, they promised the earth.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8078, 'promises, promises!', 'something that you say when someone says they will do something and you do not believe it:', '"When I''ve got some time I''ll show you everything." "Promises, promises!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8079, 'pronounce on/upon something', 'to give a judgment or opinion about something:', 'I''d rather not go pronouncing on a subject that I know so little about.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8080, 'prop something up', 'to lift and give support to something by putting something under it:', 'He was sitting upright in his hospital bed, propped up by pillows.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8081, 'prop something up', 'to give support to something, especially a country or organization, so that it can continue to exist in a difficult situation:', 'How long is the government likely to survive without the US military force there to prop it up?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8082, 'properly speaking', 'really:', 'It''s not, properly speaking, champagne but it is very similar.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8083, 'prophet of doom', 'someone who always expects bad things to happen:', 'The prophets of doom have been predicting the end of European cinema for the last ten years.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8084, 'protest too much', 'to express an opinion or fact so strongly or so often that people start to doubt that you are telling the truth:', 'She keeps trying to impress on me how she doesn''t like him but does she protest too much?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8085, 'provide against something', 'to make plans in order to prevent or deal with a bad situation:', 'Beach operators do not have a legal obligation to provide against injury or drowning.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8086, 'provide for someone', 'to give someone the things they need, such as money, food, or clothes:', 'He has a wife and two young children to provide for.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8087, 'provide for something', 'to make plans in order to deal with a possible event in the future:', 'We must provide for depreciation when calculating the costs.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8088, 'provide for something', 'If a law or agreement provides for something, it allows it to happen or exist:', 'Current legislation provides for the detention of those suspected of terrorism.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8089, 'psych someone out', 'to behave in a very confident or forceful way in order to make a competitor, especially in a sports event, feel less confident:', 'Both athletes were trying to psych each other out before the race.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8090, 'psych yourself up', 'to try to make yourself feel confident and ready to do something difficult:', 'I have to spend a little time on my own before I give a speech, psyching myself up.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8091, 'public enemy number one/no. 1', 'someone or something that many people do not like or approve of', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8092, 'puff something out', 'to make your chest or your face become bigger by filling it with air:', 'He puffed out his cheeks and sat back in his chair.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8093, 'puff up', 'If part of your body puffs up, it becomes bigger because it is infected or injured:', 'My leg puffed up all around the insect bite.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8094, 'puff someone/something up', 'to talk a lot about how excellent or important someone or something is, sometimes praising them or it more than is deserved:', 'The report puffs him up until he sounds like the chairman.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8095, 'puff something up', 'to become larger or full of air, or to make something become larger in this way:', 'When the crust is golden and puffed up, take the pie out of the oven.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8096, 'pull a fast one', 'to successfully deceive someone:', 'You paid too much - I think he pulled a fast one on you.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8097, 'pull a gun, knife, etc. on someone', 'to suddenly take out a weapon and threaten someone with it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8098, 'pull a stunt', 'to do something silly and dangerous:', 'What did you want to pull a stupid stunt like that for?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8099, 'pull ahead', 'to start to do well or to do better than someone else:', 'It was slow at first, but we''re starting to pull ahead.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8100, 'pull at something', 'to pull something quickly and usually repeatedly:', 'The child pulled at his sleeve to get his attention.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8101, 'pull away', 'If a vehicle pulls away, it starts moving:', 'There was a roar and a cloud of smoke as the car pulled away from the traffic lights.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8102, 'pull away', 'If you pull away from someone who is holding you, you suddenly move your body backwards, away from them:', 'She pulled away just as he was about to kiss her.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8103, 'pull back', 'to move backwards or away from someone:', 'He leaned forward to kiss her but she pulled back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8104, 'pull back', 'to decide not to do or involve yourself with something when you were previously going to:', 'The news is that the company intends to pull back from petrochemicals.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8105, 'pull back', '(of a military force) to move back from an attacking position:', 'After pulling back, the tanks waited for fighter planes and helicopter gunships to attack the building.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8106, 'pull back', '(of prices, rates, etc.) to become lower or less :', 'Stock prices pulled back within minutes of the Fed''s announcement, before resuming their rise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8107, 'pull back', 'If a person or team that is losing pulls back, they score a goal or win a point or some points. :', 'The Vikings pulled back to within 10 points at the break.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8108, 'pull someone back', 'to move soldiers, etc. back from an attacking position:', 'The regime has been pulling back its forces.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8109, 'pull something back', 'If a person or team that is losing pulls a goal back or pulls a point or points back, they score a goal or win a point or some points:', 'Martin Butler pulled back a goal on the stroke of halftime.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8110, 'pull in/pull into somewhere', 'If a vehicle pulls in or pulls into somewhere, it moves in that direction and stops there:', 'He pulled in at the side of the road.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8111, 'pull out', 'If a vehicle pulls out, it starts moving onto a road or onto a different part of the road:', 'A car pulled right out in front of me.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8112, 'pull (someone/something) out', 'If soldiers or military forces pull out or are pulled out, they move out of an area because they have been ordered to.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8113, 'pull (someone/something) out', 'to stop being involved in an activity or agreement:', 'He pulled out of the deal at the last moment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8114, 'pull out all the stops', 'to do everything you can to make something successful:', 'They pulled out all the stops for their daughter''s wedding.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8115, 'pull over', 'If a vehicle pulls over, it moves to the side of the road and stops:', 'Just pull over here, and I''ll get out and walk the rest of the way.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8116, 'pull rank', 'to use the power that your position gives you over someone in order to make them do what you want:', 'He doesn''t have the authority to pull rank on me.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8117, 'pull someone in', 'If the police pull you in, they arrest you:', 'The police pulled in dozens of protesters during the demonstration.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8118, 'pull someone up', 'to tell someone that they have done something wrong:', 'She''s always pulling me up for/on/over my bad spelling.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8119, 'pull something up', 'to get information to show on a computer screen:', 'Click on a square to pull up an overview of the site with name, description, location, and domain.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8120, 'pull up', 'When a car or someone driving a car pulls up, the driver stops the car, often for a short time:', 'A car pulled up outside my house.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8121, 'pull someone up short', 'to surprise someone, often so that that person stops what they are doing:', 'Seeing her picture in the paper pulled me up short.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8122, 'pull up short', 'to stop suddenly in a vehicle:', 'A dog suddenly ran across the road and I had to pull up short.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8123, 'pull someone''s leg', 'to try to persuade someone to believe something that is not true, as a joke:', 'Is it really your car or are you pulling my leg?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8124, 'pull something down', 'to destroy a building:', 'They pulled down the warehouse to build a new supermarket.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8125, 'pull someone down', 'If an illness or a difficult situation or experience pulls you down, it makes you feel unhappy or physically weak:', 'That virus she had two months ago really pulled her down - she still hasn''t fully recovered.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8126, 'pull down something', 'to earn a stated amount of money:', 'Between them they must be pulling down over $100,000 a year.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8127, 'pull something off', 'to succeed in doing something difficult or unexpected:', 'The central bank has pulled off one of the biggest financial rescues of recent years.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8128, 'pull off', 'If a vehicle pulls off, it starts moving:', 'The car pulled off and sped up the road.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8129, 'pull something on', 'to put on clothes quickly:', 'I pulled on my jeans and ran downstairs.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8130, 'pull on', 'to manage or deal with a situation:', 'Few of us can ever pull on with such meagre salaries.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8131, 'pull on', 'to have a friendly relationship with someone:', 'Radha and Rema come from different backgrounds but they pull on very well in office.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8132, 'pull something out of a/your hat', 'to do something unexpected that suddenly improves a bad situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8133, 'pull something out of the bag/hat', 'to do something unexpected that suddenly improves a bad situation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8134, 'pull something/someone apart', 'to separate two things or people:', 'They went for each other with their fists and had to be pulled apart.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8135, 'pull something apart', 'to destroy something by tearing it into pieces', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8136, 'pull something apart', 'to say that something, usually a piece of work, is very bad:', 'The last essay I gave him he completely pulled apart.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8137, 'pull strings', 'to secretly use the influence you have over important people in order to get something or to help someone:', 'I may be able to pull a few strings if you need the document urgently.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8138, 'pull the other leg/one (it''s got bells on)!', 'used when you do not believe what someone has just said:', 'Helen, mountain climbing? Pull the other one - she can''t even climb a ladder without feeling sick!', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8139, 'pull the plug', 'to do something that prevents an activity from continuing, especially by no longer giving money to support it:', 'If the viewing figures drop much more, the TV network will probably pull the plug on the whole series.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8140, 'pull the rug out (from under someone)', 'to suddenly take away important support from someone:', 'The school pulled the rug out from under the city soccer league when they asked them to pay for using their field.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8141, 'pull the rug/carpet from under someone''s feet', 'to suddenly take away help or support from someone, or to suddenly do something that causes many problems for them:', 'Do you sometimes just have the feeling that someone is trying to pull the rug from under your feet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8142, 'pull the strings', 'to be in control of an organization, often secretly:', 'I want to know who''s pulling the strings around here.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8143, 'pull the wool over someone''s eyes', 'to deceive someone in order to prevent them from discovering something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8144, 'pull through (something)', 'to become well again after a serious illness, especially when you might have died:', 'They said the operation had been successful and they expected his wife to pull through.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8145, 'pull (someone) through (something)', 'to succeed in dealing with a difficult period, or to help someone do this:', 'He''d never have managed on his own, but his colleagues have pulled him through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8146, 'pull together', 'to work hard as a group in order to achieve something:', 'We don''t have much time but if we all pull together we should get the job done.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8147, 'pull something together', 'to manage with difficulty to collect enough money, information, etc. to produce a result:', 'If you can pull together sufficient funding, we are prepared to approve the project.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8148, 'pull yourself together', 'to become calm and behave normally again after being angry or upset:', 'Just pull yourself together. There''s no point crying about it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8149, 'pull up stakes', 'to take all the things that you own and go and live in a different place:', 'This is the fourth time in five years that we''ve had to pull up stakes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8150, 'pull your socks up', 'to make an effort to improve your work or behaviour because it is not good enough:', 'He''s going to have to pull his socks up if he wants to stay in the team.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8151, 'pull your weight', 'to work as hard as other people in a group:', 'The others had complained that Sarah wasn''t pulling her weight.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8152, 'pull/get your finger out', 'to start working hard, especially after a period of low activity:', 'She''s really going to have to pull her finger out if she wants to finish before Friday.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8153, 'pull/haul yourself up by the/your (own) bootstraps', 'to improve your situation without any help from other people:', 'He left school at 15 and pulled himself up by his bootstraps to ultimately head up a company.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8154, 'pump iron', 'to lift heavy weights for exercise:', 'These days both men and women pump iron for fitness.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8155, 'pump someone up', 'to make someone feel more confident or excited:', 'He was offering them advice and trying to pump them up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8156, 'pump something up', 'to fill something with air using a pump:', 'Have you pumped up the balloons yet?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8157, 'pump something up', 'to increase something by a large amount:', 'The US was able to pump up exports.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8158, 'pump someone''s hand', 'to shake someone''s hand (= hold it and move it up and down, especially in order to greet that person)', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8159, 'pump something into something', 'to spend a lot of money trying to make something operate successfully:', 'They had been pumping money into the business for some years without seeing any results.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8160, 'pump something out', 'to remove water or other liquid from something using a pump:', 'We took turns pumping out the boat.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8161, 'pump something out', 'to produce words or loud music in a way that is repeated, forceful, and continuous:', 'The government keeps pumping out the same old propaganda.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8162, 'pump out something', 'If someone''s stomach is pumped out, a poisonous substance is removed from it by being sucked through a tube:', 'She had to go to hospital to have her stomach pumped out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8163, 'pump sth in', 'to invest a lot of money in something:', 'We are not prepared to pump in extra funds without some form of guarantee.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8164, 'punch above your weight', 'If a country or business punches above its weight, it becomes involved in, or succeeds in, an activity that needs more power, money, etc. than it seems to have:', 'Singapore punches above its weight in the world economy.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8165, 'punch in', 'to use a special clock to record the time you start working:', 'I punched in at 8:00 a.m.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8166, 'punch something in', 'to enter information into a computer or other device, using keys or buttons:', 'Think before you punch in your credit card number.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8167, 'punch out', 'to use a special clock to record the time you leave work', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8168, 'punch someone''s lights out', 'to hit someone repeatedly very hard', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8169, 'punch the clock', 'to put a card into a special machine to record the times you arrive at and leave work', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8170, 'punch the clock', 'to go to work every day:', 'After 17 years of punching the clock, he just disappeared one morning and was never heard from again.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8171, 'punt on something', 'to risk money by buying or supporting something, in the hope of making or winning more money:', 'Investors are punting on a big move in the stock market next week.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8172, 'punt on something', 'If you punt on something, you decide not to do or include it:', 'We punted on a motion that makes no sense.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8173, 'push (someone) toward(s) something', 'to try to do or achieve something, or to make someone more likely to do or achieve something:', 'It is hoped that these measures will push the nation towards recovery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8174, 'push (something) forward', 'to continue doing something or making progress in something, with effort or enthusiasm:', 'Their research has pushed forward the frontiers of knowledge.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8175, 'push yourself forward', 'to try to make other people notice and pay attention to you:', 'She always seemed to be pushing herself forward and not giving anyone else a chance.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8176, 'push ahead', 'to continue with an activity in a determined or enthusiastic way, especially when it is difficult or makes you feel tired:', 'They have decided to push ahead with the legal action.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8177, 'push along', 'to leave:', 'Anyway, I''d better be pushing along now.', 'phrasal verb', '', 'old-fashioned, informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8178, 'push for something', 'to demand something repeatedly, or to take strong action to try to make it happen:', 'Local residents are pushing for the road to be made safer.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8179, 'push in', 'to rudely join a line of people who are waiting for something, by moving in front of some of the people who are already there:', 'I was about to get on the bus when two men pushed in in front of me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8180, 'push off', 'used to rudely tell someone to go away:', 'He told me to push off.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8181, 'push off', 'to push against the side of a pool, lake, or river in order to move your body or a boat away from the side:', 'He pushed off from the side of the pool and swam slowly to the other side.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8182, 'push on', 'to continue doing something, especially when this is difficult:', 'They are pushing on with their campaign for improved childcare facilities.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8183, 'push on', 'to continue travelling somewhere:', '"You''ve been driving for a long time - do you want to stop for a rest?" "No, we''re nearly there - let''s push on."', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8184, 'push someone around', 'to tell someone what to do in a rude or threatening way:', 'If you think you can push me around like that, you''re mistaken.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8185, 'push someone out', 'to make someone leave a job or stop being involved in an activity by being unpleasant or unfair to them:', 'I felt I was being pushed out of the job.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8186, 'push someone/something aside', 'to decide to forget about or ignore someone or something:', 'He claimed that he had been pushed aside (= not given a job) in favour of a younger person.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8187, 'push someone/something over', 'to push someone or something so that they fall to the ground:', 'Daddy, Matthew pushed me over.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8188, 'push something back', 'to delay something so that it happens later than planned:', 'The target date for construction has been pushed back.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8189, 'push something through', 'to cause a plan or suggestion to be officially accepted or put into use:', 'We are trying to push this deal through as quickly as possible.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8190, 'push something up/down', 'to cause the amount, number, or value of something to increase or be reduced:', 'Rising demand tends to push prices up, and falling demand pushes them down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8191, 'push sth down', 'to make something lower in level or amount:', 'Increased competition will push down prices.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8192, 'push the boat out', 'to spend a lot of money on celebrating something:', 'They really pushed the boat out for Annie''s wedding.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8193, 'push the envelope', 'to behave in more extreme ways, or to try new things that have not been acceptable or tried before:', 'Just like every other kid, I pushed the envelope. If I got away with being ten minutes late one night, I might be twenty minutes late the next night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8194, 'push your luck', 'to try too hard to get a particular result and risk losing what you have achieved:', 'She''s agreed to help on Saturday, but I think I''d be pushing my luck if I asked her to be here the whole weekend.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8195, 'put (your) money on someone/something', 'to risk money on someone or something winning a race or competition:', 'He put some money on a horse in the five o''clock race.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8196, 'put (your) money on someone/something', 'to strongly believe that someone will do something or that something will happen:', 'Chris will be promoted - I''d put money on it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8197, 'put a bow on something', 'to make something complete or perfect:', 'This final victory puts a bow on his success story.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8198, 'put a damper on something', 'to make something less enjoyable:', 'The bad weather put a damper on this year''s New Year celebrations.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8199, 'put a figure on it', 'to say exactly how much something is or costs:', 'I''m sure we''ll make a good profit, but I couldn''t put a figure on it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8200, 'put a gloss on something', 'to emphasize the good parts of something that has been done, especially those that are to your advantage, and to avoid the bad parts:', 'Politics is all about putting a good gloss on unpleasant or difficult situations.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8201, 'put a lid on something', 'to keep something under control and stop it from increasing:', 'We’ve got to keep a lid on our credit-card purchases.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8202, 'put a sock in it!', 'used to tell someone to be quiet or stop making so much noise:', 'Hey, put a sock in it, will you? I''m trying to work here.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8203, 'put a spoke in someone''s wheel', 'to make it difficult for someone to achieve something they had planned to do:', 'His letter really put a spoke in our wheel.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8204, 'put all your eggs in one basket', 'to depend for your success on a single person or plan of action:', 'I''m applying for several jobs because I don''t really want to put all my eggs in one basket.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8205, 'put an end to something', 'to make something stop happening or existing:', 'How can we put an end to the fighting?', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8206, 'put down roots', 'If you put down roots in a place where you have moved to live, you make new friends and join in new activities there so that you feel it is your home.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8207, 'put flesh on (the bones of) something', 'to add more details to a plan, idea, argument, etc. to make it better or more complete', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8208, 'put forward/forth something', 'to suggest an idea for consideration:', 'None of the ideas that I put forward have been accepted.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8209, 'put ideas into someone''s head', 'to make someone want to do something they had not thought about before, especially something stupid:', 'Don''t go putting ideas into his head. We can''t afford a new car.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8210, 'put in a good word for someone', 'to say positive things about someone:', 'I really need a job and I was hoping you might put in a good word for me with your boss.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8211, 'put in for something', 'to make an official request to have or do something:', 'I''m putting in for a job at the hospital.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8212, 'put in/make an appearance', 'to go to an event, but only for a short time because you do not really want to be there:', 'I felt like I had to put in an appearance at the staff party, but I only stayed for an hour.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8213, 'put it about', 'to have sex with a lot of different people:', 'Have you been putting it about recently, then?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8214, 'put it down to experience', 'to decide that instead of being upset about something bad that has happened or that you have done, you will learn from it:', 'Okay, so you made a mistake - you just have to put it down to experience and carry on with your life.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8215, 'put it there!', 'something that you say when you want someone to shake your hand to show that you have just made an agreement:', '"So, do we have a deal?" "Sure, put it there."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8216, 'put on a brave face', 'to behave as if a problem is not important or does not worry you:', 'She seems all right but I think she''s just putting on a brave face.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8217, 'put on an act', 'to behave or speak in a false or artificial way:', 'He''s just putting on an act for the boss''s benefit.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8218, 'put on the dog', 'to act as if you are more important than you are', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8219, 'put one over on someone', 'to trick someone:', 'He''d tried to put one over on the tax office and got found out.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8220, 'put out feelers', 'to make informal suggestions as a way of testing other people''s opinions on something before any decisions are made', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8221, 'put out fires', 'to spend time on problems that need to be dealt with quickly, instead of working in a calm, planned way:', 'She spends much of her time putting out fires and navigating red tape.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8222, 'put paid to something', 'to finish or destroy something:', 'A knee injury has put paid to her chances of getting into the final.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8223, 'put someone down as something', 'to think that someone is a particular type of person, especially when you do not know them very well:', 'I''d hate them to put me down as a snob.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8224, 'put someone down for something', 'to make a record that someone has promised to pay a particular amount of money as part of a collection to help people in need:', 'Put me down for a £10 donation.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8225, 'put someone in mind of something', 'to cause someone to remember something:', 'The mention of skiing holidays put me in mind of a documentary that I saw last week.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8226, 'put someone in the picture', 'to tell someone the facts about a situation:', 'His lawyer put him in the picture about what had happened since his arrest.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8227, 'put someone in their place', 'to tell or show someone that they are less important than they thought:', 'When he tried to take charge, she soon put him in his place.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8228, 'put someone off their stride', 'to take someone''s attention away from what they are doing, so that they stop doing it or do it wrong:', 'He interrupted mid-speech and it put me off my stride.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8229, 'put someone off their stride/stroke', 'to take someone''s attention away from something they are doing for a short time, making it more difficult to do:', 'The slightest noise puts him off his stride when he''s performing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8230, 'put someone on a pedestal', 'to believe that someone is perfect', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8231, 'put someone on the spot', 'If you put someone on the spot, you cause them embarrassment or difficulty by forcing them at that moment to answer a difficult question or make an important decision:', 'Mira rather put the boss on the spot by asking him when he was going to give us a pay rise.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8232, 'put someone onto something', 'to introduce a person to something or someone that could bring them an advantage:', 'David put me onto a wonderful vegetarian cookery book.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8233, 'put someone out to grass', 'to make someone stop work permanently because they are too old', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8234, 'put someone out to pasture', 'to stop someone working in a job because they are too old to be useful', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8235, 'put someone through something', 'to make someone experience something unpleasant or difficult:', 'I''m sorry to put you through this ordeal.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8236, 'put someone through something', 'to pay for someone to study at school, college, or university:', 'It''s costing them a lot of money to put their children through school.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8237, 'put someone through', 'to connect a person using a phone to the person they want to speak to:', 'Could you put me through to customer services, please?', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8238, 'put someone through the mill', 'to cause someone to have a difficult and unpleasant experience, especially by asking them a lot of difficult questions:', 'I had the interview this morning - they really put me through the mill.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8239, 'put someone through the wringer', 'to ask someone difficult or unpleasant questions, often to find out if they are doing their job in a satisfactory way:', 'Outside investigators will put the company''s accounting practices through the wringer.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8240, 'put something to someone', 'to suggest an idea or plan to someone so that they can consider it or discuss it:', '"Shall we all go out for a pizza tonight?" "I don''t know. I''ll put it to Jim and see what he says."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8241, 'put something to someone', 'to ask someone a question:', 'I have a question I want to put to you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8242, 'put someone to the sword', 'to kill someone:', 'Thousands of innocents were put to the sword.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8243, 'put someone up to something', 'to encourage someone to do something, usually something wrong:', 'I think he was put up to it by his friends.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8244, 'put someone''s nose out of joint', 'to offend or upset someone, especially by getting something that that person wanted for himself or herself:', 'John''s nose was really put out of joint when Jane was promoted and he wasn''t.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8245, 'put someone/something first', 'to treat someone or something as being more important than anyone or anything else:', 'She all too often puts others first and never stops to think of herself.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8246, 'put someone/something through their/its paces', 'to make someone show their skills or knowledge, or to make something show its good qualities:', 'All the candidates were put through their paces during the television debate.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8247, 'put something about/around', 'to tell a lot of people something that is not true:', '[ + that ] I''d like to know who put the rumour around that I''m pregnant.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8248, 'put something across', 'to express your ideas and opinions clearly so that people understand them easily:', 'It''s an interesting idea and I thought he put it across well.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8249, 'put yourself across', 'to express your ideas and opinions clearly so that people understand them and realize what you are like as a person:', 'I don''t think I managed to put myself across very well in my interview.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8250, 'put something across/over someone', 'to cause a piece of false information to be believed by one or more people:', 'You didn''t manage to put that story over on the tax people, did you?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8251, 'put something aside', 'to save something, usually time or money, for a special purpose:', 'I put aside a little every month for a deposit on a house.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8252, 'put something aside', 'If you put a disagreement or problem aside, you ignore it temporarily so that it does not prevent you doing what you want to do:', 'Let''s put our differences aside and make a fresh start.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8253, 'put something at something', 'to guess or roughly calculate that something will cost a particular amount, or that something is a particular size, number, or amount:', 'The value of the painting has been put at £1 million.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8254, 'put something away', 'to put something in the place or container where it is usually kept:', 'Put your toys away now.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8255, 'put something away', 'to eat a large amount of food:', 'He put away a whole box of chocolates in one evening.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8256, 'put someone away', 'to move someone into a place where people live and are cared for together, such as a mental hospital or old people''s home:', 'In the past, people who suffered from schizophrenia were often put away.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8257, 'put someone away', 'to send someone to prison:', 'After what he did, he deserves to be put away for life.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8258, 'put something back', 'to return an object to where it was before it was moved:', 'Will you put the books back when you''ve finished with them?', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8259, 'put something back', 'to delay a planned event:', 'We had to put the meeting back a week.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8260, 'put something back', 'to drink something quickly, especially a large amount of alcohol:', 'He regularly puts back six pints a night - I don''t know how he does it.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8261, 'put something back', 'to change a clock or watch to make it show an earlier time, for example because you are now in a part of the world where the time is different', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8262, 'put something before someone', 'to give more attention to one thing than another because you think it is more important:', 'I''d never put my work before my family.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8263, 'put something before someone', 'to formally tell or explain facts or ideas to a group of people in authority:', 'We have to put our proposal before the committee.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8264, 'put something behind you', 'If you put an unpleasant experience behind you, you stop thinking about it, so that it does not affect your life:', 'Like any divorce, it was a painful business but I''ve put it all behind me now.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8265, 'put something by', 'to save an amount of money to use later:', 'I try to put by a few pounds every week.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8266, 'put something down to something', 'to think that a problem or situation is caused by a particular thing:', 'I put the children''s bad behaviour down to the fact that they were tired.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8267, 'put something in', 'to fix a large piece of equipment or system into a room or building, ready to be used:', 'I''ve just had central heating/a new kitchen put in.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8268, 'put something in', 'to formally offer a particular thing to be considered:', 'I''ve put in an application to the college.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8269, 'put (something) in', 'to say something that adds to or interrupts what is already being said:', '[ + speech ] "But she''s too inexperienced for the job," put in Jane.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8270, 'put something in/put something into something', 'to spend a lot of time or effort doing something:', 'You''ve obviously put a lot of work in on your garden.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8271, 'put something into something', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8272, 'put something off', 'to decide or arrange to delay an event or activity until a later time or date:', 'The meeting has been put off for a week.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8273, 'put someone off', 'to tell someone that you cannot see them or do something for them, or to stop someone from doing something, until a later time:', 'I really don''t want to go out with Helen and Greg tonight - can''t we put them off ?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8274, 'put someone off (something)', 'to take someone''s attention away from what they want to be doing or should be doing:', 'Once she''s made up her mind to do something, nothing will put her off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8275, 'put someone off (something/someone)', 'to make someone dislike something or someone, or to discourage someone from doing something:', 'The smell of hospitals always puts me off.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8276, 'put something on', 'to make a device operate, or to cause a device to play something, such as a CD or DVD, by pressing a switch:', 'Could you put the light on?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8277, 'put something on', 'to cover part of the body with clothes, shoes, make-up, or something similar:', 'Put your shoes on - we''re going out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8278, 'put something on', 'to pretend to have a particular feeling or way of behaving that is not real or natural to you:', 'Why are you putting on that silly voice?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8279, 'put something on', 'to produce or provide something, especially for the good of other people or for a special purpose:', 'She put on a wonderful meal for us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8280, 'put something on', 'If people or animals put weight on, they become heavier:', 'I''d expected to put weight on when I gave up smoking, but I didn''t.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8281, 'put someone on', 'to try to persuade someone that something is true when it is not, usually as a joke:', 'She said she was planning to give her house to a charity for the homeless but I thought she was putting me on.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8282, 'put someone on something', 'to tell someone to start taking a particular medicine or eating particular foods:', 'Doctors put her on antibiotics after discovering an infection.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8283, 'put something out', 'to make a light stop shining by pressing or moving a switch:', 'Did you put the lights out downstairs?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8284, 'put something out', 'to make something such as a fire or cigarette stop burning:', 'Firefighters have been called to put out the fire in the city centre.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8285, 'put someone out', 'to cause trouble or extra work for someone:', 'Would it put you out if we came tomorrow instead of today?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8286, 'put someone out', 'to annoy or upset someone, often by what you do or say to them:', 'She was very put out when they turned up two hours late for dinner.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8287, 'put yourself out', 'to make an effort to do something to help someone, even if it is not convenient:', 'Ethan is always willing to put himself out for other people.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8288, 'put something out', 'to move forward part of your body, such as your hand or your tongue, from your body:', 'She put out her hand to shake mine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8289, 'put something out', 'to injure part of your body by causing it to be moved out of its correct position:', 'He put his knee out playing tennis.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8290, 'put something out', 'to produce something in large quantities, so that it can be sold:', 'They put out millions of pairs of shoes a year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8291, 'put something out', 'to produce information and make it available for everyone to read or hear:', 'Police have put out a warning to people living in the area.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8292, 'put something out', 'If a mistake puts out a set of mathematical calculations, it causes them to be wrong:', 'That one error put the figures out by several thousand pounds.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8293, 'put something out', 'If you put work out, you employ someone outside your organization to do it:', 'The council has put the job of street-cleaning out to a private firm.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8294, 'put out', '(especially of a woman) to agree to have sex:', 'I wasn''t going to put out just because he''d paid for dinner.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8295, 'put something out of its misery', 'to kill an animal because it is in great pain, so that it does not have to suffer any more', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8296, 'put someone out of their misery', 'to stop someone worrying, usually by giving that person information that they have been waiting for:', 'We try to put our students out of their misery and give them their exam results as early as possible.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8297, 'put something out of joint', 'to prevent a plan from working correctly:', 'Our whole schedule was put out of joint by the designs arriving a week late.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8298, 'put something out of your mind', 'to force yourself not to think about something:', 'It''s over, put it out of your mind.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8299, 'put something over on someone', 'to persuade someone to believe something that is not true:', 'My dad’s really smart – you can never put anything over on him.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8300, 'put something over/across', 'to express an idea clearly so that people understand it:', 'Did you feel that you managed to put over your point of view?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8301, 'put something to bed', 'to successfully deal with something or solve a problem:', 'We thought we''d put the issue to bed, but it was brought up again at the next meeting.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8302, 'put something to bed', 'to start printing something', '', 'idiom', '', 'specialized', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8303, 'put something to sleep', 'to kill an animal that is very ill or very old so that it does not suffer any more', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8304, 'put something to the test', 'to find out how good something is:', 'Her constant questions put the teacher''s patience to the test.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8305, 'put something together', 'to put the parts of something in the correct places and join them to each other:', 'It took several hours to put the puzzle together.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8306, 'put something together', 'to prepare a piece of work by collecting several ideas and suggestions and organizing them:', 'The management are putting together a plan/proposal/package to rescue the company.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8307, 'put something together', 'said after a phrase that refers to a group of people or things to show that you are thinking of them as a group rather than separately:', 'She earns more than all the rest of us put together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8308, 'put something toward something', 'to use an amount of money to pay part of the cost of something:', 'My grandma gave me some money to put toward a new coat.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8309, 'put something towards something', 'to use an amount of money to pay part of the cost of something:', 'My grandma gave me some money to put towards a new coat.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8310, 'put something under the microscope', 'to examine or think about a situation very carefully:', 'The investigation put the company''s financial accounts under the microscope.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8311, 'put something up', 'to raise something, or to fix something in a raised position:', 'Why don''t you put up your hood/umbrella?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8312, 'put something up', 'to build something:', 'They''re planning to put a hotel up where the museum used to be.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8313, 'put something up', 'to fix an object to a vertical surface:', 'We''ve put up some new curtains in the living room.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8314, 'put something up', 'to increase the price or value of something:', 'I see they''ve put up the price of fuel again.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8315, 'put something up', 'to provide or lend an amount of money for a particular purpose:', 'The money for the new hospital was put up by an anonymous donor.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8316, 'put something up', 'to preserve food in glass or metal containers :', 'There is a period of young motherhood when you wash and iron, garden, and put up preserves.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8317, 'put up something', 'to show or express a particular type of opposition to something:', 'The villagers were unable to put up any resistance to the invading troops.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8318, 'put something/someone up', 'to suggest an idea, or to make a person available, to be considered:', 'It was Bob who originally put up the idea of the exhibition.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8319, 'put someone up', 'to provide someone with a place to stay temporarily:', 'Sally is putting me up for the weekend.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8320, 'put up', 'to stay somewhere for the night:', 'We put up at a small hotel for the night.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8321, 'put something/someone down', 'to put an object that you are holding onto the floor or onto another surface, or to stop carrying someone:', 'I put my bags down while we spoke.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8322, 'put something/someone down', 'to write someone''s name on a list or document, usually in order to include that person in an event or activity:', 'Do you want me to put you down for the trip to London?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8323, 'put something down', 'If you put the phone down, you place it or the receiver back in the position you keep it in when it is not being used.', '', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8324, 'put something down', 'to pay part of the cost and promise to pay the rest later:', 'I''ve put a deposit down on a new car.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8325, 'put someone down', 'to make someone feel silly or not important by criticizing them:', 'Why did you have to put me down in front of everybody like that?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8326, 'put someone down', 'to place and make a baby comfortable in the place where it sleeps:', 'I''d just put Jack down for his nap.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8327, 'put something down', 'to kill an animal that is old, sick, or injured, to prevent it from suffering:', 'If a horse breaks its leg, it usually has to be put down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8328, 'put something down', 'to stop or limit an opposing political event or group:', 'Police used tear gas to put the riot down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8329, 'put something down', 'to reduce a price or a charge:', 'Shops are being forced to put their prices down in order to attract customers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8330, 'put (something) down (somewhere)', 'When an aircraft puts down, it lands, and when pilots put down their aircraft, they land:', 'She put down safely in the corner of the airfield.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8331, 'put someone down somewhere', 'to stop a vehicle and allow someone to get out of it or off it:', 'Ask the taxi driver to put you down outside the church.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8332, 'put something/someone forward', 'to state an idea or opinion, or to suggest a plan or person, for other people to consider:', 'The proposals that you have put forward deserve serious consideration.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8333, 'put something forward', 'to change a clock or watch to make it show a later time, especially an hour later:', 'Most European countries put the clocks forward in the spring.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8334, 'put something/someone in a pigeonhole', 'to form a very fixed, often wrong, opinion about what type of person or thing someone or something is', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8335, 'put something/someone on the map', 'to make a thing, person, or place famous:', 'The governor has managed to put this sleepy state on the map.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8336, 'put sth in/into sth', 'to spend a lot of time or effort doing something:', 'If I put in some extra hours today, I can have some time off tomorrow.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8337, 'put sth in/into sth', 'to invest money in something', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8338, 'put sth over', 'to express an idea clearly so that people understand it:', 'Did you feel that you managed to put over your point of view?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8339, 'put stock in something', 'If you put stock in something that someone says or does, you have a high opinion of it:', 'He''s been wrong before, so I don''t put much stock in what he says any more.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8340, 'put the boot in', 'to kick someone when they are already on the ground', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8341, 'put the boot in', 'to make a bad situation worse, by criticizing or being unkind:', 'After he lost his job, his wife put the boot in by announcing she was leaving him.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8342, 'put the brakes on', 'to slow down or stop an activity:', 'The city has put the brakes on further spending.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8343, 'put the cart before the horse', 'to do things in the wrong order:', 'Aren''t you putting the cart before the horse by deciding what to wear for the wedding before you''ve even been invited to it?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8344, 'put the fear of God into you', 'to frighten you a lot', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8345, 'put the finishing touches on', 'to add the final improvements to something so that you are satisfied with it or certain that it is complete', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8346, 'put the finishing touches to', 'to add the final improvements to something so that you are satisfied with it or certain that it is complete', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8347, 'put the flags out!', 'something that you say when you are pleased and surprised that something has happened:', 'Josh has cleaned the bathroom - put the flags out!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8348, 'put the heat on someone', 'to try to persuade or force someone to do something', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8349, 'put the lid on something', 'If something that happens puts the lid on a plan, it causes the plan to fail:', 'Well, James'' resignation just about puts the lid on it/the project.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8350, 'put the roses (back) into someone''s cheeks', 'If something puts the roses back into your cheeks, it makes you look healthy, especially after an illness:', 'A brisk walk will put the roses back into your cheeks.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8351, 'put the shot', 'to throw a heavy metal ball as far as possible in a sports competition:', 'He won the gold medal for putting the shot.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8352, 'put the skids under something', 'to cause something such as a plan to fail:', 'Local residents have put the skids under plans to build a new shopping centre.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8353, 'put the squeeze on someone', 'to ask someone to give you money:', 'She put the squeeze on her mother for a hundred bucks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8354, 'put the word out', 'to tell people a new piece of news:', 'So, the new manager has been appointed - should we put the word out?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8355, 'put the world to rights', 'to have a conversation in which you talk about many different things, for example how to solve society''s problems :', 'When we were students we used to stay up late putting the world to rights.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8356, 'put their heads together', 'If two or more people put their heads together, they plan something together:', 'If we put our heads together, we can think of a solution.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8357, 'put two and two together', 'to guess the truth about a situation from what you have seen or heard:', '"How did you know they were having an affair?" "I''d seen them out together a couple of times, so I just put two and two together."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8358, 'put two and two together and make five', 'to understand a particular situation wrongly, often in a way that is more shocking or exciting than the truth:', '"Why in the world did she think you were pregnant?" "I was sick a couple of times, and I guess she just put two and two together and made five."', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8359, 'put up or shut up', 'If you say someone should put up or shut up, you mean that they should either take action in order to do what they have been talking about, or stop talking about it:', 'You keep saying you''re going to ask her out. Well, put up or shut up.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8360, 'put up with something/someone', 'to accept or continue to accept an unpleasant situation or experience, or someone who behaves unpleasantly:', 'I can put up with the house being messy, but I hate it if it''s not clean.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8361, 'put words in someone’s mouth', 'to say that someone means one thing when the person really meant something else:', 'I never said you should leave – don''t put words in my mouth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8362, 'put words in/into someone''s mouth', 'to suggest that someone meant one thing when really they meant another:', 'Stop putting words in my mouth - I didn''t say you looked fat in the red dress - I merely said you looked very slim in the black!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8363, 'put years on someone', 'If something puts years on a person, it makes them appear much older:', 'Being tired and unhappy puts years on you.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8364, 'put your back into something', 'to use a lot of physical effort to try to do something:', 'You could dig this plot in an afternoon if you really put your back into it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8365, 'put your best foot forward', 'to try as hard as you can', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8366, 'put your feet up', 'to relax and do very little:', 'After working all week, you deserve to put your feet up.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8367, 'put your feet up', 'to relax, especially by sitting with your feet supported above the ground:', 'You go home and put your feet up.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8368, 'put your finger on something', 'to discover the exact reason why a situation is the way it is, especially when something is wrong:', 'There''s something odd about him, but I can''t quite put my finger on it.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8369, 'put your foot down', 'to use your authority to stop something happening:', 'When she started borrowing my clothes without asking, I had to put my foot down.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8370, 'put your foot down', 'to increase your speed when you are driving:', 'The road ahead was clear, so I put my foot down.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8371, 'put your foot in it', 'to say something by accident that embarrasses or upsets someone:', 'I really put my foot in my mouth – I asked her if Jane was her mother, but she said Jane is her sister.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8372, 'put your foot in your mouth', 'to say or do something that you should not have, esp. something that embarrasses someone else:', 'I really put my foot in my mouth – I asked her if Jane was her mother, but she said Jane is her sister.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8373, 'put your foot in your mouth', 'to say something by accident that embarrasses or upsets someone:', 'I really put my foot in my mouth with Eva. I had no idea she was divorced.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8374, 'put your hand in your pocket', 'to give money to someone or to charity (= organizations that collect money to give to poor people, ill people, etc.):', 'People are more inclined to put their hands in their pockets to help children.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8375, 'put your head over/above the parapet', 'to be brave enough to state an opinion that might upset someone', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8376, 'put your heart and soul into something', 'to make a lot of effort to do something:', 'She puts her heart and soul into her work.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8377, 'put your money where your mouth is', 'to show by your actions and not just your words that you support or believe in something', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8378, 'put your neck on the line', 'to do something that you know might fail and spoil other people''s opinion of you or cause you to lose money:', 'There''s a lot of money at stake here and none of the partners wants to put his neck on the line.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8379, 'put your shirt on something', 'to feel very certain that something will happen:', 'I''d put my shirt on the president being re-elected.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8380, 'put your thinking cap on', 'to think seriously about something:', 'I need some interesting suggestions so if you can put your thinking cap on I''d be grateful.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8381, 'put yourself across', 'to express ideas and opinions in a way that people can understand them and know what type of person you are:', 'I don''t think I managed to put myself across very well in my interview.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8382, 'put yourself in someone''s place/position/shoes', 'to imagine how someone else feels in a difficult situation:', 'Put yourself in my place - what else could I have done?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8383, 'put/get someone''s back up', 'to annoy someone:', 'Just ignore him - he''s only trying to put your back up.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8384, 'put/get the wind up someone', 'to make someone feel worried about their situation:', 'Tell them your father''s a policeman - that''ll put the wind up them!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8385, 'put/lay something on the line', 'to risk something:', 'Firefighters put their lives on the line every working day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8386, 'put/lay something on/to one side', 'to not use something, especially an amount of money, in order to keep it for later use:', 'We have put some money on one side for next year''s summer holiday.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8387, 'put/lay your cards on the table', 'to be honest about your feelings and intentions:', 'I thought it was time I laid my cards on the table, so I told him that I had no intention of marrying him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8388, 'put/leave someone in the shade', 'to be so good that another person or thing does not seem important or worth very much:', 'Although I thought I''d done well, my sister''s exam results put mine in the shade.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8389, 'put/leave something on/to one side', 'to stop talking about a particular subject:', 'Can we leave the issue of pay on one side for the moment?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8390, 'put/place your faith in something/someone', 'to make a decision to trust something or someone:', 'Some people put their faith in strong leaders rather than sound policies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8391, 'put/set pen to paper', 'to start to write:', 'It''s time you put pen to paper and replied to that letter from your mother.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8392, 'put/set pencil to paper', 'to write:', 'Everyone should put pencil to paper and complain about the proposal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8393, 'put/set someone right', 'to stop someone believing something that is not true, or to correct someone by telling them the truth:', 'She thought she wouldn''t have to work hard, but we soon put her right on that.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8394, 'put/set someone right', 'to make someone feel better:', 'A good night''s sleep will soon put you right.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8395, 'put/set someone straight', 'to make certain that someone knows the real facts about a situation:', 'Don''t worry, I set him straight (on this matter).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8396, 'put/set something in motion', 'to start a machine or process:', 'Once the printing processes have been put in motion, they''re not so easy to stop.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8397, 'put/set something in train', 'to start a process:', 'The reform process was put in train in 1985.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8398, 'put/set the cat among the pigeons', 'to say or do something that causes trouble or makes a lot of people very angry', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8399, 'put/stick that in your pipe and smoke it!', 'a rude way of telling someone that they must accept what you have just said, even if they do not like it', '', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8400, 'put/stick the knife into someone', 'to be unpleasant about someone, or try to harm someone:', 'The reviewer in the magazine that I read really put the knife in.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8401, 'put/stick your oar in', 'to say or do something that annoys other people because they have not asked you to join their conversation or activity:', 'No one asked him to help - he''s always sticking his oar in.', 'idiom', '', 'informal, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8402, 'put/throw a spanner in the works', 'to do something that prevents a plan or activity from succeeding:', 'The funding for the project was withdrawn so that really threw a spanner in the works.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8403, 'put/tighten the screws on someone', 'to use force or threats to make someone do what you want:', 'They put the screws on him until he paid up.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8404, 'put/turn the clock back', 'to make things the same as they were at an earlier time:', 'The court''s decision on this case will turn the clock back 50 years.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8405, 'puzzle something out', 'to discover or understand something by thinking hard about it:', '[ + question word ] I still can''t puzzle out how I managed to spend so much money last month.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8406, 'quarrel with something', 'to think that something is wrong:', 'No one can quarrel with the improvements that have been made.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8407, 'quick march!', 'an order given to soldiers to make them start marching', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8408, 'quit on someone', 'to stop supporting or being friends with someone, especially when they need your support:', 'I will never quit on my teammates and they will never quit on me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8409, 'quote... unquote', 'said to show that you are repeating someone else''s words, especially if you do not agree:', 'She says they''re quote "just good friends" unquote.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8410, 'rabbit on', 'to continue talking about something that is not interesting to the person you are talking to:', 'He''s always rabbiting on about his stamp collection.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8411, 'rack off', 'to leave or go away, used especially as a rude way of telling someone to go away:', 'If you don''t like Sydney, rack off. All you are doing is whinging.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8412, 'rack something up', 'to gradually get more points, profits, etc.:', 'He has racked up 450 points in three months.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8413, 'rack something up', 'to increase something such as a rent or price, especially by an amount that is considered to be too much:', 'Our landlord racked up the rent by 15 percent this year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8414, 'rack your brain', 'to think very hard:', 'I''ve been racking my brain all day but I can''t remember her name.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8415, 'rack your brains', 'to think very hard:', 'I''ve been racking my brains all day but I can''t remember her name.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8416, 'raffle off something', 'to sell chances to win something:', 'Players signed footballs, which were raffled off along with a mink coat.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8417, 'rag on someone', 'to continually laugh at someone or say unkind things about them, either because you are joking or because you want to upset that person:', 'They''ve been ragging on me, but it''s just in fun.', 'phrasal verb', '', 'old-fashioned, informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8418, 'ragtag and bobtail', 'all types of person or thing, including those that are ordinary and not special in any way:', 'a ragtag and bobtail bunch of amateurs', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8419, 'rail something off', 'to close something, especially using railings:', 'Part of the playing field had been railed off for use as a car park.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8420, 'rain (something) down', 'to fall in large amounts, or to direct something in large amounts, usually forcefully or violently:', 'Bombs rained down on the besieged city.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8421, 'rain cats and dogs', 'to rain very heavily:', 'Don''t forget to take your umbrella - it''s raining cats and dogs out there.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8422, 'rain on someone''s parade', 'to do something that spoils someone''s plans:', 'I''m sorry to rain on your parade but you''re not allowed to have alcohol on the premises.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8423, 'rain something off', 'If an event is rained off, it cannot start or continue because it is raining:', 'His hockey match was rained off.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8424, 'rain something out', 'If an event is rained out, it cannot start or continue because it is raining:', 'His hockey game was rained out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8425, 'raise (a few) eyebrows', 'to cause surprise or shock:', 'Jemma''s miniskirt raised a few eyebrows at the board meeting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8426, 'raise a rumpus', 'to make a forceful complaint:', 'You should raise a rumpus about the lack of safety routines here.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8427, 'raise hell', 'to behave in a way that is not controlled and that causes trouble', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8428, 'raise hell', 'to protest about something in a loud and angry way', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8429, 'raise someone from the dead', 'to make a dead person start living again:', 'Christians believe that, at Easter, Christ was raised from the dead.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8430, 'raise the alarm', 'to make people understand the danger of something:', 'A local doctor was the first to raise the alarm about this latest virus.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8431, 'raise the roof', 'to play/sing very loudly and enthusiastically:', 'With their last, triumphant piece, the musicians raised the roof.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8432, 'raise your eyebrows', 'to show surprise by moving your eyebrows upwards', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8433, 'raise your game', 'to make an effort to improve the way that you do something:', 'They''re going to have to raise their game if they want to stay in the Premiership this season.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8434, 'raise your hand to/against someone', 'to hit someone:', 'Never raise your hand to a child.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8435, 'rake over something', 'to keep talking or thinking about an unpleasant event or experience:', 'He keeps on raking over his divorce, when really he should be getting on with his life.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8436, 'rake something in', 'to earn or get a large amount of money:', 'He rakes in over $200,000 a year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8437, 'rake something out', 'to look for something and find it, usually among various things you have stored:', 'I raked this old blanket out for camping.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8438, 'rake something up', 'to talk again about a past event or experience that should be forgotten, because it upsets or annoys someone else:', 'She''s always raking up the past/that old quarrel.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8439, 'rake something/someone up', 'to get the things or people you need, with difficulty or by looking in various places:', 'I''m trying to rake up some people to play football on Saturday - do you want to come along?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8440, 'rally around (someone)', 'to help or support someone:', 'When I''m ill, my friends always rally around.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8441, 'rally round (someone)', 'to help or support someone:', 'When I''m ill, my friends always rally round.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8442, 'ram something down someone''s throat', 'to force someone who disagrees with you to listen to your opinions:', 'For years I''ve had his political views rammed down my throat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8443, 'ram something home', 'to emphasize the importance of what you are saying in order to make certain people understand it:', 'He thumped the desk as he rammed his point home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8444, 'ram something into someone', 'to force someone to accept an idea, opinion, or principle:', 'It''s time someone rammed a bit of sense into you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8445, 'ramp something up', 'If a business ramps up its activity, it increases it:', 'The company announced plans to ramp up production to 10,000 units per month.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8446, 'ramp something up', 'to increase the speed, power, or cost of something:', 'Announcement of the merger is expected to ramp up share prices over the next few days.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8447, 'rank as', 'to fit or be given a particular description:', 'rank as sth The storms rank as one of the worst insurance disasters ever to hit Europe.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8448, 'rap someone over the knuckles', 'to speak officially to someone in a severe or angry way because you disapprove of their actions:', 'He was rapped over the knuckles by the management.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8449, 'rat on someone/something', 'to not be loyal to someone, especially by giving away secret information about them, or to fail to do something that you said you would do:', 'He ratted on us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8450, 'ratchet something up/down', 'to increase/reduce something over a period of time:', 'The debate should ratchet up awareness of the problem among members of the general public.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8451, 'ratchet sth down', 'to reduce something in controlled stages over a period of time:', 'The state plans to ratchet down greenhouse gas emissions by 25% within the next 10 years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8452, 'ratchet sth up', 'to increase something in controlled stages over a period of time:', 'The constant ratcheting up of rewards for executives means they are expanding out of all proportion to those of other staff.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8453, 'rather you than me', 'said by someone who does not want to do the thing that someone else is doing:', '"I''m having two teeth out next week." "Rather you than me."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8454, 'ration something out', 'to divide something between a group of people so that each person gets a small amount:', 'Ann rationed out the cake between the children.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8455, 'rattle on/away', 'to talk for a long time, especially about things that are not important:', 'She was on the phone for hours last night, just rattling on to her friends.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8456, 'rattle something off', 'to say or read aloud very quickly a list of names or things, or something you have learned:', 'She rattled off the names of the people who were coming to the party.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8457, 'rattle through something', 'to do or say something very quickly:', 'I''m going to rattle through my work today so that I can go home early.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8458, 'ray of sunshine', 'a happy person who makes others feel happy, especially in a difficult situation:', 'We love looking after our grandchild. He''s a ray of sunshine!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8459, 'reach for the stars', 'to want or try to get something that is difficult or impossible to get', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8460, 'reach out (to someone)', 'to try to communicate with a person or a group of people, usually in order to help or involve them:', 'The new mayor is reaching out to inner city communities to involve them in his plans for the city.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8461, 'reach out (to someone)', 'to communicate with someone, especially by using a phone, sending them an email, etc.:', 'The Washington Post reached out to Turner for comment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8462, 'reach out (to someone)', 'to offer help and support to someone:', 'She set up her charity to reach out to the thousands of homeless on the streets.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8463, 'react against something', 'to intentionally do the opposite of what someone wants you to do because you do not like their rules or ideas:', 'He reacted against everything he had been taught.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8464, 'read (someone) the riot act', 'to speak angrily to someone about something they have done and warn that person that they will be punished if it happens again :', 'He''d put up with a lot of bad behaviour from his son and thought it was time to read him the riot act.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8465, 'read between the lines', 'to try to understand someone''s real feelings or intentions from what they say or write:', 'Reading between the lines, I''d say he isn''t happy with the situation.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8466, 'read my lips', 'a slightly rude way of telling someone to listen carefully to what you are saying:', 'Read my lips. No new taxes.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8467, 'read someone''s lips', 'to follow the movements of someone''s lips in order to understand what is being said, especially if you are unable to hear them speak:', 'She read his lips across the busy conference hall - "Time to go."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8468, 'read someone''s mind', 'to know what someone is thinking without them telling you:', 'humorous "How about a drink, then?" "Ah, you read my mind!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8469, 'read someone''s palm', 'to look at the lines on a person''s hand as a way of trying to find out what will happen to that person in the future:', 'In a tent an old gypsy woman was reading palms.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8470, 'read something into something', 'to believe that an action, remark, or situation has a particular importance or meaning, often when this is not true:', 'Don''t read too much into her leaving so suddenly - she probably just had a train to catch.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8471, 'read something out', 'to read something and say the words aloud so that other people can hear:', 'He read out the names of all the winners.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8472, 'read something over/through', 'to read something quickly from the beginning to the end, especially to find mistakes:', 'I read your proposal through last night and I think we''ll agree to it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8473, 'read the room', 'to be or become aware of the opinions and attitudes of a group of people that you are talking to :', 'You have to read the room when you''re performing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8474, 'read the runes', 'to understand what will happen in the future, by looking at what is happening now:', 'He was the first of the Eastern leaders to read the runes and make political changes to stay in power.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8475, 'read up (on/about) something', 'to spend time reading in order to find out information about something:', 'It''s a good idea to read up on a company before going for an interview.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8476, 'read up on something', 'to learn about something by reading:', 'I don''t know much about Malawi – I''ll go home and read up on it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8477, 'ready to hand', 'close to you and therefore available for use when necessary:', 'The sheriff slept with his gun ready to hand under his pillow.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8478, 'ready, steady, go!', 'said at the start of a race, especially one for children', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8479, 'ream someone (out)', 'to tell someone off severely because you strongly disapprove of their behaviour:', 'The boss reamed them out for sleeping on the job.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8480, 'reap the benefit, reward, etc.', 'to get something good as a result of your own actions:', 'She studied every evening and reaped the benefit at exam time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8481, 'reap what you have sown', 'to win or lose as a result of something you did in the past', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8482, 'rear above/over something/someone', 'to appear very tall and big in comparison with another thing or person:', 'The mountain reared above the village.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8483, 'rear its (ugly) head', '(of something unpleasant) to appear:', 'The familiar spectre of drought and famine has reared its ugly head again.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8484, 'reason with someone', 'to try to persuade someone to act in a wise way or to change their behaviour or a decision, by explaining why it is a good idea:', '[ + to infinitive ] The police reasoned with the hijackers to at least let the children go free.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8485, 'recharge your batteries', 'to rest and relax for a period of time so that you feel energetic again:', 'She took a trip to the South of France to recharge her batteries.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8486, 'reckon on something', 'to feel that something is likely to happen and to make plans that depend upon it happening:', '[ + -ing verb ] We''re reckoning on selling 2,000 cars a month.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8487, 'reckon something in', 'to include an amount in your calculations:', 'When you reckon in all my overtime, my total pay is quite good.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8488, 'reckon something up', 'to calculate the total amount of something:', 'She can reckon up a bill faster than any calculator.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8489, 'reckon with someone/something', 'to deal with a difficult or powerful person or thing:', 'If you harm her, you''re going to have the police to reckon with.', 'phrasal verb', 'C2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8490, 'reckon without something', 'to fail to think about something when you are making plans and therefore not be prepared to deal with it:', 'We''d expected a two-hour drive but had reckoned without the rain.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8491, 'reconcile yourself to something', 'to accept a situation or fact although you do not like it:', 'She must reconcile herself to the fact that she must do some work if she wants to pass her exams.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8492, 'reduce someone to something', 'to make someone unhappy or cause someone to be in a bad state or situation:', 'His comments reduced her to tears (= made her cry).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8493, 'reduce someone to something', 'If you are reduced to doing something, you are forced to do it because you have no other choice:', 'He was out of cigarettes and was reduced to smoking the butts left in the ashtrays.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8494, 'reduce something to something', 'to cause something, especially a large structure, to be destroyed and broken into pieces:', 'Allied bombing reduced the city to ruins/rubble.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8495, 'reduce, reuse, recycle', 'said to encourage people to waste less, by using less and using things again, in order to protect the environment', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8496, 'reek of something', 'If an event or situation reeks of an unpleasant quality, it seems to be caused by or connected to that quality:', 'His promotion reeks of favouritism.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8497, 'reel someone/something in', 'to get control of something or someone, sometimes by offering something in exchange:', 'The article offers tips on how computer users can avoid being reeled in by internet scams.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8498, 'reel something in/out', 'to pull in a rope or an object on the end of a rope by turning a wheel round and round, or to release something in the same way:', 'Slowly the fisherman reeled in his line, bringing the fish ashore.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8499, 'reel something off', 'to say a long list of things quickly and without stopping:', 'The old man reeled off the names of his 22 grandchildren.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8500, 'reel something off', 'to win several games or points one after the other in a sports competition', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8501, 'refer to someone/something', 'to talk or write about someone or something, especially in only a few words:', 'In her autobiography she occasionally refers to her unhappy schooldays.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8502, 'refer to someone/something', 'If writing or information refers to someone or something, it relates to that person or thing:', 'The new salary scale only refers to company managers and directors.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8503, 'refer someone to something/someone', 'to direct someone or something to a different place or person for information, help, or action, often to a person or group with more knowledge or power:', 'My doctor referred me to a hospital specialist.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8504, 'refer (someone) to something', 'to look at, or tell someone else to look at, a book or similar record in order to find information and help:', 'She spoke for an hour without once referring to her notes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8505, 'reflect on someone/something', 'to affect other people''s opinion of someone or something, especially in a bad way:', 'When one player behaves disgracefully, it reflects (badly) on the whole team.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8506, 'refresh someone''s memory', 'to help someone remember something:', 'I looked the word up in the dictionary to refresh my memory of its exact meaning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8507, 'regale someone with something', 'to entertain someone with stories, jokes, etc.:', 'The sailor regaled us all night with stories of his adventures.', 'phrasal verb', '', 'humorous', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8508, 'regardless of something', 'without being influenced by any other events or conditions:', 'I tell them the truth, regardless of what they want to hear.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8509, 'rein something in', 'to make a horse go more slowly or stop by pulling on its reins', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8510, 'rein something in', 'to control an emotion, activity, or situation to prevent it from becoming too powerful:', 'We tried to rein in our excitement and curiosity.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8511, 'rein sth in/back', 'to control something and stop it increasing:', 'Consumers tend to rein in their spending in a recession.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8512, 'reinvent the wheel', 'to waste time trying to create something that someone else has already created', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8513, 'relate to someone/something', 'to be connected to, or to be about someone or something:', 'Chapter 9 relates to the effects of inflation on consumers.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8514, 'relate to someone/something', 'connected with something:', 'Anything relating to maths is a complete mystery to me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8515, 'relate to someone', 'to understand someone and be able to have a friendly relationship with them:', 'Many parents find it hard to relate to their children when they are teenagers.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8516, 'relate to something', 'to understand a situation or someone''s feelings because you have experienced a similar situation or similar feelings:', 'The culture that he describes is so different from mine that I sometimes find it hard to relate to.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8517, 'relax your grip/hold', 'to start to hold something less tightly:', 'She relaxed her grip on my arm.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8518, 'relax your grip/hold', 'to start to control something less:', 'The Mafia has relaxed its grip on local businesses.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8519, 'relieve someone of something', 'to take from a person something that they are carrying, in a helpful or polite way:', 'May I relieve you of that heavy bag?', 'phrasal verb', 'C2', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8520, 'relieve someone of something', 'to steal something from someone:', 'The pickpocket delicately relieved him of his wallet.', 'phrasal verb', '', 'humorous', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8521, 'relieve someone of something', 'to remove someone from their job or position because they have done something wrong:', 'Following the scandal, he was relieved of his post as deputy finance minister.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8522, 'rely on/upon someone/something', 'to need a particular thing or the help and support of someone or something in order to continue, to work correctly, or to succeed:', '[ + -ing verb ] The success of this project relies on everyone making an effort.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8523, 'rely on/upon someone/something', 'to trust someone or something or to expect him, her, or it to behave in a particular way:', 'British weather can never be relied on - it''s always changing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8524, 'remark on something', 'to notice something and make a remark about it:', 'All his friends remarked on the change in him since his marriage.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8525, 'remember someone to someone', 'to ask someone to say hello to another person for you:', 'Please remember me to your parents.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8526, 'remind someone of something/someone', 'to be similar to, and make someone think of, something or someone else:', 'Your hair and eyes remind me of your mother.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8527, 'render something down', 'to melt fat in order to make it purer', '', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8528, 'render something down', 'to prepare or treat the bodies of dead animals in order to take out the fat and other substances that can be used in other products:', 'to render down animal carcasses', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8529, 'repair to somewhere', 'to go to another place, usually in a group of people:', 'After dinner, we repaired to the lounge for coffee.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8530, 'repay someone''s effort, time, attention, etc.', 'If an activity, book, etc. repays your effort, time, attention, etc., it is worth the effort or time, etc. that you spend on it:', 'You should read this article - it would repay your time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8531, 'repeat on someone', 'When food repeats on you, the taste of it comes up again into your mouth:', 'Cucumber always repeats on me.', 'phrasal verb', '', 'UK', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8532, 'report back', 'to bring information to someone in authority:', 'Find out their names and report back to me tomorrow.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8533, 'report to someone', 'Someone you report to at work is the person in authority over you who gives you tasks and checks that you do them:', 'You will report directly to the boss.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8534, 'repose trust/confidence/hope in someone/something', 'to place your trust or hopes in someone or something:', 'We repose a lot of hope in this project.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8535, 'reside in something/someone', 'If a power or quality resides in someone or something, the person or thing has that power or quality:', 'The power to sack employees resides in the Board of Directors.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8536, 'resign yourself to something', 'to make yourself accept something that you do not like because you cannot change it:', '[ + -ing verb ] He resigned himself to living alone.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8537, 'resolve something into something', 'to separate something into different parts:', 'There was a blur of sound, which slowly resolved itself into different words.', 'phrasal verb', '', 'formal, specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8538, 'resort to something', 'to do something that you do not want to do because you cannot find any other way of achieving something:', 'I had to resort to violence/threats to get my money.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8539, 'rest assured', 'to be certain that something will happen:', 'You can rest assured that you’re going to get a good deal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8540, 'rest easy', 'used to tell someone not to worry and that you are in control of the situation:', '"Rest assured, Mrs Cooper," said the police officer. "We will find your son for you."', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8541, 'rest in peace', 'said to express the hope that someone''s spirit has found peace after death:', 'She was a decent and compassionate woman: may she rest in peace.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8542, 'rest in peace', 'often written on a gravestone', '', 'idiom', '', 'abbreviation', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8543, 'rest on someone/something', 'If your eyes rest on something or someone when you are looking around an area, you start looking only at that particular object or person:', 'Her eyes rested on a small wooden box at the back of the shop.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8544, 'rest on your laurels', 'to be satisfied with your achievements and not to make an effort to do anything else:', 'Just because you''ve got your degree doesn''t mean you can rest on your laurels.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8545, 'rest on/upon something', 'If something rests on a particular idea, belief, or fact, it is based on it or needs it in order for it to be true:', 'Christianity rests on the belief that Jesus was the son of God.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8546, 'rest on/upon someone/something', 'to depend on someone or something:', 'Our success rests on an increase in sales.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8547, 'rest up', 'to relax in order to have strength for something:', 'Why don''t you take a nap to rest up for the party?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8548, 'rest with someone', 'If a responsibility or decision rests with someone, they are responsible for it:', 'The authority to call an emergency meeting rests with the president.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8549, 'rest with someone/something', 'to depend on someone or something:', 'Our hopes rest with you.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8550, 'restrict yourself to something', 'to limit yourself to one particular thing or activity:', 'If I''m driving, I restrict myself to one glass of wine.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8551, 'restrict yourself to sth', 'to limit yourself to one particular thing or activity:', 'The company is restricting itself to non-living cargoes at first.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8552, 'result from something', 'If a situation or problem results from a particular event or activity, it is caused by it:', 'His difficulty in walking results from a childhood illness.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8553, 'result in something', 'to cause a particular situation to happen:', 'The fire resulted in damage to their property.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8554, 'retire a number', 'If a sports team retires a number, it stops using the shirt number worn by a particular player when they stop playing, as a way of honouring them.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8555, 'retrace your steps', 'to go back to a place in the same way that you came:', 'She walked straight past her office and then had to retrace her steps.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8556, 'rev up (someone/something)', 'to become more active, or to make someone or something become more active:', 'The hotel is revving up for the busy summer season.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8557, 'revel in something', 'to get great pleasure from a situation or an activity:', 'She''s revelling in her newly found freedom.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8558, 'revenge is sweet', 'said when you feel satisfaction from harming someone who has harmed you', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8559, 'revert to something', 'to return to doing, using, being, or referring to something, usually something bad or less satisfactory:', 'Why does the conversation have to revert to money every five minutes?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8560, 'revert to someone', 'to become the property of a particular person again:', 'When I die, the house will revert to my sister.', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8561, 'revolve around someone/something', 'to have someone or something as the main or most important interest or subject:', 'The conversation revolved around childcare problems.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8562, 'rewind the clock', 'to go back to an earlier time:', 'I''m sure she wishes she could rewind the clock now.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8563, 'rice and peas', 'a Jamaican dish consisting of rice and kidney beans (= small, dark red beans with a curved shape), cooked in coconut milk :', 'We ate curried goat and rice and peas.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8564, 'rid someone/something of something/someone', 'to cause someone or something to be free of an unpleasant or harmful thing or person:', 'Our aim is to rid this government of corruption.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8565, 'ride (on) a wave of something', 'If you ride (on) a wave of a feeling, you get an advantage from it:', 'The new president is riding (on) a wave of popularity.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8566, 'ride (out) the storm', 'to manage not to be destroyed, harmed, or permanently affected by the difficult situation you experience:', 'The government seems confident that it will ride out the storm.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8567, 'ride a wave of something', 'to be helped by being connected to something attractive or interesting:', 'The president was riding a wave of good feeling about the economy, but it didn''t last long.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8568, 'ride herd on someone/something', 'to be responsible for controlling a group of people and their actions:', 'The new editor will ride herd on the staff, checking on the overall policy and tone of the paper.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8569, 'ride on something/someone', 'When something important, such as your reputation or money, rides on a particular person or thing, it will be won or achieved if that person or thing is successful:', 'The future of the company now rides on the new managing director.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8570, 'ride something out', 'to continue to exist during a difficult situation and until it ends, without serious harm:', 'Many companies did not manage to ride out the recession.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8571, 'ride something out', 'If a ship rides out a period of bad weather, it continues to float during it, without serious damage:', 'The ship managed to ride out the storm.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8572, 'ride tandem', 'If two people ride tandem, they ride together on a tandem (= a bicycle made for two people):', 'When she rode tandem with me, our pedalling rate was 80–90 RPM.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8573, 'ride up', 'If a piece of clothing rides up, it moves up out of position:', 'Your skirt has ridden up at the back.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8574, 'ride, drive, walk, etc. (off) into the sunset', 'to begin a new, happy life at the end of a story:', 'At the end of the film, the two of them ride off into the sunset.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8575, 'riding high', 'doing very well:', 'The soccer team was riding high after winning four straight games.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8576, 'rig someone out', 'to put a particular type of clothing on someone:', 'We rigged ourselves out in tracksuits and running shoes for the race.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8577, 'rig something up', 'to quickly make a piece of equipment from any materials you can find:', 'I rigged up a temporary radio aerial from a coat hanger.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8578, 'rig the market', 'to make the price of shares go up or down in order to make a profit', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8579, 'right away', 'immediately:', 'I need someone to help me right away.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8580, 'right behind someone', 'If you are right behind someone, you give them your complete support:', 'My whole family are right behind me in this crisis.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8581, 'right on the button', 'exactly correct:', 'She was right on the button when she said I''d regret moving out.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8582, 'right you are!', 'said to show that you understand and agree:', '"Give me a shout when you''re ready." "Right you are."', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8583, 'right, left, and center', 'all the time or everywhere:', 'He spends money right, left, and center.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8584, 'right, left, and centre', 'all the time or everywhere:', 'He spends money right, left, and centre.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8585, 'right/wrong way round', 'facing the right/wrong way:', 'He put the wheel on the right/wrong way round.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8586, 'ring (someone) back', 'to call someone who called you earlier, or to call someone for a second time:', 'I''m a bit busy - can I ring you back in a few minutes?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8587, 'ring a bell', 'to sound familiar:', 'The name rang a bell but I couldn''t remember where I had heard it before.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8588, 'ring around (sb/sth)', 'to call several people on the phone in order to find out information or organize something:', 'The first thing they did was to ring around all their competitors'' stores undercover to find out their prices.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8589, 'ring off', 'to end a phone conversation intentionally:', 'She said "No, thank you" and rang off hurriedly.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8590, 'ring out', 'When a sound rings out, it is loud and clear:', 'A cry of warning rang out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8591, 'ring someone/something up', 'to make a phone call to someone:', 'She rang me up to say she couldn''t come.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8592, 'ring something up', 'to record the money that has been paid by a customer by pressing buttons on a cash register:', 'I''m sorry, I rang up the wrong amount.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8593, 'ring the changes (on)', 'to do something in a different way in order to make it more interesting:', 'Ring the changes on packed lunches using different types of bread and spicy fillings.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8594, 'ring true', 'If something someone says or writes rings true, it seems to be true:', 'Something about his explanation didn''t quite ring true.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8595, 'ring true/false', 'to seem true/false:', 'Her explanations didn''t ring true.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8596, 'ring with something', 'If a place rings with a sound, it is full of it:', 'The room rang with his screams.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8597, 'ring/sound hollow', 'If something someone says rings hollow, it does not sound true or sincere.', '', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8598, 'rinse something out', 'to quickly wash the inside of something with clean water:', 'I''ll just rinse these glasses out and leave them to dry.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8599, 'rip into sb/sth', 'to attack or criticize someone or something with great force:', 'She ripped into her opponent''s proposals, calling them "completely unworkable".', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8600, 'rip someone off', 'to cheat someone by making them pay too much money for something:', 'Bob''s tickets cost much less than ours - I think we''ve been ripped off.', 'phrasal verb', 'C2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8601, 'rip something off', 'to remove something very quickly and carelessly:', 'They ripped off their clothes and ran into the sea.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8602, 'rip something off', 'to steal something:', 'He rips stuff off from supermarkets to pay for his heroin.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8603, 'rip something up', 'to tear something into small pieces:', 'She ripped up his letters and burned the pieces.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8604, 'rip through something', 'to move very powerfully through a place or building, destroying it quickly:', 'The explosion ripped through the hotel.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8605, 'rip/tear up the rulebook', 'to do something in a way that is very different to the way in which it is usually done or has been done in the past:', 'The book reveals the story of how the couple tore up the rulebook and created completely new methods of brewing beer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8606, 'ripe for something', 'developed to a suitable condition for something to happen:', 'The company is ripe for takeover.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8607, 'rise above something', 'to not allow something bad to affect your behaviour or upset you:', 'He rose above his pain/bad luck/difficulties.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8608, 'rise and shine!', 'said to tell someone to wake up and get out of bed:', 'Wakey wakey, rise and shine!', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8609, 'rise from the dead/grave', 'to become alive again after having died', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8610, 'rise to fame', 'to become famous:', 'He rose to fame in the 90s as a TV presenter.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8611, 'rise to something', 'to react to a difficult situation by working hard to succeed:', 'There were some other very good competitors, but Megan rose to the challenge and sang beautifully.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8612, 'rise to the bait', 'to accept an offer or suggestion that seems good but is really a trick:', 'They offered a good salary, but I didn''t rise to the bait.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8613, 'rise to the occasion/challenge', 'to show that you can deal with a difficult situation successfully:', 'In the exam she rose to the occasion and wrote a brilliant essay.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8614, 'rivers of something', 'a large amount of a liquid:', 'Rivers of sweat ran down his back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8615, 'road to Damascus', 'Your road to Damascus is an experience you have that you consider to be very important and that changes your life.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8616, 'roar ahead', 'to increase or move quickly or suddenly:', 'Property prices continue to roar ahead.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8617, 'roar with something', 'to express an emotion, such as laughter or anger, noisily:', 'She roared with laughter when she saw what he was wearing.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8618, 'roaring drunk', 'very drunk and noisy:', 'They came back from the bars roaring drunk.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8619, 'rob Peter to pay Paul', 'to borrow money from one person to pay back money you borrowed from someone else', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8620, 'rock out', 'to perform rock music loudly and enthusiastically:', 'The singer and his E Street Band played their longest ever concert in Helsinki, Finland, in 2012, when they rocked out for four hours and six minutes.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8621, 'rock out', 'to listen to and enjoy rock music, for example by dancing:', 'Audience members were transported back to the days of roller skates, disco lights, and smoke machines as they rocked out to the music of the Bee Gees.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8622, 'rock the boat', 'If you rock the boat, you do or say something that will upset people or cause problems:', 'Don''t rock the boat until the negotiations are finished.', 'idiom', 'C2', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8623, 'rock up', 'to arrive somewhere:', 'They rocked up two hours late, dressed in ball gowns.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8624, 'rocky road', 'If you are on a rocky road, you are experiencing a difficult period and have a lot of problems:', 'Analysts predict a rocky road ahead for the economy.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8625, 'roll (something) out', 'to make a new product, service, or system available for the first time:', 'The government plans to roll out a series of tax cuts over the next few years.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8626, 'roll around', '(of a time or event) to happen:', 'She wondered if he would still be there when spring rolled around.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8627, 'roll back something', 'to limit or reduce the effects of a particular arrangement:', 'He wants to roll back laws designed to clean up the air, water, and land.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8628, 'roll something back', 'to reduce the cost or price of something:', 'The furniture dealer is rolling back the prices on all beds for this week only.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8629, 'roll by', 'If an amount of time rolls by, it passes:', 'The years rolled by, and I didn''t see her again until she was married with two children.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8630, 'roll in', 'to arrive in great numbers or amounts:', 'Once our business gets started, the money will be rolling in.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8631, 'roll on the weekend, five o''clock, etc.', 'said when you want time to go quickly because you are looking forward to something:', 'I can''t wait to be finished with this project - roll on October!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8632, 'roll out the red carpet', 'to welcome someone as a very important person or guest:', 'We''ll roll out the red carpet for the senator.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8633, 'roll out the red carpet', 'to be very pleased about something, and encourage and support it:', 'All three cities rolled out the red carpet for the aerospace giant.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8634, 'roll out the red carpet (for someone)', 'to give a guest special treatment:', 'New York rolled out the red carpet for the astronauts.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8635, 'roll over', 'to agree to what someone wants, especially because you are under pressure or under someone''s control:', '"If the bill passes, we''re certainly not going to roll over and say that''s fine," he said.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8636, 'roll (something) over something', 'If you roll over something on a computer screen, you move the mouse over an active place so that you can see information that is hidden under it:', 'If you roll your mouse over a word, its definition will appear.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8637, 'roll up your sleeves', 'to prepare for hard work:', 'There''s a lot of work to do, so roll up your sleeves and get busy.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8638, 'roll something up', 'to fold something around itself to make the shape of a ball, or to fold cloth around itself to make a piece of clothing shorter:', 'Could you roll up that string for me?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8639, 'roll up', 'to arrive at a particular place or event, usually late:', 'They rolled up at the party two hours late and rather drunk.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8640, 'roll with the punches', 'to be able to deal with a series of difficult situations', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8641, 'roll your eyes', 'to move your eyes around in a circle because someone has said or done something stupid or strange:', '"Don''t pay any attention to what he says," Carrie said rolling her eyes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8642, 'roll your eyes', 'to move your eyes upwards as a way of showing that you are annoyed or bored after someone has done or said something', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8643, 'rolled into one', 'If someone or something has several qualities rolled into one, the person or thing has all of those qualities:', 'He is a father, sales manager, and athlete all rolled into one.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8644, 'rolling in the aisles', 'infml laughing very hard:', 'The comedian had the audience rolling in the aisles.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8645, 'romp home/in', 'to win easily:', 'She is riding the fastest horse and is certain to romp home.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8646, 'romp through something', 'to successfully do something, quickly and easily:', 'Rory expected to romp through the test and interviews.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8647, 'roof something in/over', 'to put a roof over a place or area:', 'The council has decided to roof over the open-air swimming pool.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8648, 'room for doubt', 'a possibility of something being true:', 'There is little room for doubt about what happened.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8649, 'room for improvement', 'a possibility or hope that someone or something will improve:', 'Her writing is better but there is still room for improvement.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8650, 'room for maneuver', 'the opportunity to change your plans or choose between different ways of doing something:', 'The law in this area is very strict and doesn''t allow us much room for maneuver.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8651, 'room for manoeuvre', 'the opportunity to change your plans or choose between different ways of doing something:', 'The law in this area is very strict and doesn''t allow us much room for manoeuvre.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8652, 'root and branch', 'completely:', 'Racism must be eliminated, root and branch.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8653, 'root around (somewhere)', 'to search for something, especially by looking through other things:', 'She was rooting around in her drawer for a pencil.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8654, 'root for someone', 'to show support for someone who is doing something difficult:', 'Good luck! We''re all rooting for you.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8655, 'root for someone', 'to support a sports team or a sports player and want them to win:', 'Who do you root for in the Super Bowl?', 'phrasal verb', 'B1', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8656, 'root something out/up', 'to remove a whole plant, including the roots, from the ground:', 'I suggest you root out those weeds before they take hold.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8657, 'root something/someone out', 'to search and find something or someone that is difficult to find:', 'I''ve rooted out an old pair of shoes that might fit you.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8658, 'root something/someone out', 'to find and remove a person or thing that is causing a problem:', 'Ms Campbell has been appointed to root out inefficiency in this company.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8659, 'rooted to the spot', 'unable to move:', 'She was rooted to the spot with fear/amazement.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8660, 'roots and all', 'completely:', 'Racism must be eliminated, roots and all.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8661, 'rope someone in', 'to persuade someone to do something for you:', 'At the last minute, we roped in a couple of spectators to complete the team.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8662, 'rope someone in', 'to force or persuade someone to join a group or become involved in something:', 'The National Guard roped him in for another two years of service.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8663, 'rope someone into something', 'to persuade a person or group to do something:', 'I was roped into playing softball last night.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8664, 'rope something/somewhere off', 'to surround an area or place with ropes in order to keep people out:', 'The police roped off the scene of the crime.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8665, 'rot in jail, prison, etc.', 'to stay in prison for a very long time:', 'Ruben Carter was left to rot in jail for most of his life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8666, 'rough and ready', 'produced quickly, with little preparation', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8667, 'rough and ready', 'simple but good enough:', 'rough and ready accommodation', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8668, 'rough and tumble', 'fighting between children that is not serious:', 'It was just a bit of rough and tumble.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8669, 'rough and tumble', 'a busy activity that people do in a very forceful way:', 'She enjoys the rough and tumble of politics.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8670, 'rough edges', 'If something such as a product, a piece of work or a performance has rough edges, some parts of it could be improved:', 'He''s a great player, but his game still has a few rough edges.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8671, 'rough edges', 'If a person has rough edges, they do not always behave well and politely:', 'Age and experience have softened his rough edges (= have made him a more polite or gentle person).', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8672, 'rough it', 'to live without comforts, esp. running water, heat, etc.:', 'We roughed it until our house was repaired.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8673, 'rough justice/luck', 'something that happens to you that is severe or unfair:', 'It seems like rough justice that he should lose his house as well as his wife.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8674, 'rough someone up', 'to hit and kick someone, usually to frighten or threaten them', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8675, 'rough something in', 'If you rough a drawing in, you draw the basic lines, without the detail.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8676, 'rough something out', 'If you rough out a drawing, idea, or plan, you draw or write the main parts of it without giving its details.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8677, 'round about', 'approximately:', 'We''ll be at your house at round about nine o''clock, okay?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8678, 'round and round', 'moving in circles:', 'The skater twirled round and round.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8679, 'round of applause', 'a period of time during which people are clapping:', 'The singer got a big round of applause.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8680, 'round on someone/something', 'to suddenly turn and attack someone or something:', 'The fox rounded on its pursuers.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8681, 'round on someone/something', 'to criticize someone who has criticized you:', 'The mayor rounded on his critics with a very forceful speech.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8682, 'round something down', 'to reduce a number to the nearest whole or simple number', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8683, 'round something off', 'to make something that is pointed or sharp into a smooth, curved shape by rubbing it:', 'He used a special machine to round off the corners of the old table.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8684, 'round something off', 'to complete an event or activity in a pleasant or satisfactory way:', 'To round off her education, her father sent her to a Swiss finishing school.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8685, 'round something out', 'to complete something:', 'More research is needed to round out the article.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8686, 'round something/someone up', 'to find and bring together a group of animals or people:', 'The cowboys rounded the cattle up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8687, 'round something up', 'to increase a number to the nearest whole or simple number', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8688, 'round sth down/up', 'to reduce or increase a number to the nearest 1, 10, 100, etc.:', 'The figures were rounded down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8689, 'round the corner', 'very near here:', 'There''s a great restaurant just round the corner.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8690, 'round/around the clock', 'all day and all night:', 'Doctors and nurses worked round the clock to help those injured in the train crash.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8691, 'rout someone out', 'to make someone come out of the place where they are:', 'His wife had to rout him out of the crowd.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8692, 'row back', 'to change a previous decision, opinion, or statement:', 'The management rowed back on the decision the very next day.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8693, 'rub along', 'If two people rub along, they work or live together in a satisfactory way:', 'My flatmate and I rub along okay together.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8694, 'rub it in', 'to make someone feel worse about something the person already feels embarrassed about:', 'I know I shouldn’t have paid that much for the poster – don’t rub it in, OK?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8695, 'rub off', 'If a quality or characteristic that someone has rubs off, other people begin to have it because they have been with that person and learned it from them:', 'His enthusiasm is starting to rub off on the rest of us.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8696, 'rub off on someone', 'to become part of someone because that person has been in a place where it was present:', 'I like to think that our love of reading will rub off on our children.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8697, 'rub salt in/into the wound', 'to make a difficult situation even worse for someone:', 'Losing was bad enough. Watching them receiving the trophy just rubbed salt into the wound.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8698, 'rub shoulders (with)', 'to meet and spend time with someone:', 'She claims that she rubs shoulders with royalty all the time.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8699, 'rub someone the wrong way', 'to annoy someone without intending to:', 'As soon as they met they started to rub each other the wrong way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8700, 'rub someone up the wrong way', 'to annoy someone without intending to:', 'As soon as they met they started to rub each other up the wrong way.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8701, 'rub someone''s nose in it', 'to say or do things that make someone remember that they failed or got something wrong:', 'Sue failed her exam, so just to rub her nose in it, I put my certificate up on the wall.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8702, 'rub something down', 'to rub something with a rough cloth, brush, or paper until its surface is smooth, or clean and shiny:', 'Rub the wood down with fine sandpaper until it is smooth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8703, 'rub something/someone down', 'to use a cloth to dry an animal or person:', 'I used a towel to rub the dog down after his bath.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8704, 'rub something in', 'to talk to someone about something that you know they want to forget because they feel bad about it:', 'OK, I made a mistake - you don''t have to rub it in.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8705, 'rub something out', 'to remove writing or a mark from something by rubbing it with a piece of rubber or a cloth:', 'It''s in pencil, so you can rub it out if you need to.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8706, 'rub someone out', 'to murder someone:', 'He was rubbed out by the Mafia.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8707, 'ruck (something) up', 'If material rucks up, it forms a lump (= mass) or folds, and if something rucks it up, it pushes the material into a lump or folds:', 'The blankets had rucked up around his feet.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8708, 'rue the day', 'to feel very sorry about an event:', 'She''ll rue the day (that) she bought that house.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8709, 'ruffle someone''s feathers', 'to upset or annoy someone:', 'She knows how to ruffle his feathers.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8710, 'rule OK', 'is the best:', 'The graffiti on the wall said "Liverpool rules OK".', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8711, 'rule of thumb', 'a practical and approximate way of doing or measuring something:', 'A good rule of thumb is that a portion of rice is two handfuls.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8712, 'rule something or someone in', 'to decide or say officially that something is possible or will definitely happen, or that something or someone is suitable:', 'Are we prepared to negotiate? We haven''t ruled it in or out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8713, 'rule something or someone out', 'to decide or say officially that something is impossible or will not happen, or that something or someone is not suitable:', 'The police haven''t yet ruled out murder.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8714, 'rule something out', 'to prevent something from happening:', 'This recent wave of terrorism has ruled out any chance of peace talks.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8715, 'rule something with an iron hand/fist', 'to control a group of people very firmly, having complete power over everything they do', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8716, 'rule the roost', 'to be the person who makes all the decisions in a group:', 'In that family it is the grandma who rules the roost.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8717, 'rules are made to be broken', 'used to say that it is good and acceptable to not obey a rule', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8718, 'rumble on', 'If something such as a disagreement rumbles on, it continues for a long time without being resolved:', 'The dispute rumbled on for months.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8719, 'run (something) into something/someone', 'to drive a vehicle into an object or a person in another vehicle by accident:', 'I had to brake suddenly, and the car behind ran into me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8720, 'run into someone', 'to meet someone you know when you are not expecting to:', 'Graham ran into someone he used to know at school the other day.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8721, 'run into something', 'If you run into problems, you begin to experience them:', 'We ran into bad weather/debt/trouble.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8722, 'run into something', 'to reach a particular cost or amount, as a total:', 'The repairs will probably run into thousands of dollars.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8723, 'run a mile', 'to be extremely unwilling to be involved:', 'He''d run a mile if I asked him to marry me.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8724, 'run across someone', 'to meet someone you know when you are not expecting to:', 'I ran across several old friends when I went back to my hometown.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8725, 'run across something', 'to experience a problem when you are not expecting to:', 'We''ve run across a slight problem with the instruction manual.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8726, 'run afoul of something', 'to do something you are not allowed to do, esp. breaking a rule or law:', 'Foreigners who run afoul of the law are punished severely.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8727, 'run after someone/something', 'to chase someone or something that is moving away from you:', 'Why do dogs run after cats?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8728, 'run after something', 'to try very hard to get or achieve something:', 'She has spent her life running after fame and fortune.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8729, 'run after someone', 'to try to start a sexual relationship with someone:', 'He''s always running after women.', 'phrasal verb', '', 'informal, disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8730, 'run against someone/something', 'to oppose or have an effect that is not helpful towards someone or something:', 'Luck is really running against you tonight!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8731, 'run aground/ashore', 'If a ship or boat runs aground/ashore, it hits the coast, sometimes becoming stuck there.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8732, 'run along!', 'said to children to tell them to go away:', 'Run along now, children!', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8733, 'run amok', 'to behave without control in a wild or dangerous manner:', 'There were 50 little kids running amok at the snack bar.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8734, 'run and run', 'to be performed successfully for a long period of time:', 'This show will run and run.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8735, 'run around', 'to be very busy doing a lot of different things:', 'I''m exhausted - I''ve been running around all morning.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8736, 'run around after someone', 'to do a lot of things for someone else, especially when that person should be able to do more for himself or herself:', 'I seem to spend most of my time running around after those kids.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8737, 'run around in circles', 'to be very active but with few results:', 'We''ve been running around in circles trying to get the information we need, but no-one will tell us anything.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8738, 'run around with someone', 'to spend a lot of time with someone:', 'She''s running around with Micky and his friends these days.', 'phrasal verb', '', 'old-fashioned, informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8739, 'run away', 'to leave a place or person secretly and suddenly:', 'He ran away from home when he was only twelve.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8740, 'run away', 'to avoid dealing with a problem or difficult situation:', 'She accused him of running away from his responsibilities.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8741, 'run away to sea', '(especially of a boy or young man) to leave your family and become a sailor:', 'My grandfather ran away to sea when he was twelve.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8742, 'run away with someone', 'If an animal or machine that you are riding runs away with you, you lose control of it and it carries you away:', 'Her horse ran away with her.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8743, 'run away with someone', 'If a feeling or idea runs away with you, you cannot control it and it makes you behave stupidly:', 'Sometimes my imagination runs away with me and I convince myself that they are having an affair.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8744, 'run away with something', 'to win a competition or prize very easily:', 'She ran away with four first prizes.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8745, 'run errands', 'to go out to buy or do something:', 'After school he runs errands for his father.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8746, 'run high', 'If feelings are running high, people are angry or excited.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8747, 'run in the family', 'If a quality, ability, disease, etc. runs in the family, many members of the family have it:', 'Intelligence seems to run in that family.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8748, 'run interference', 'to deal with problems for someone as they happen:', 'His no-nonsense assistant runs interference for him on just about everything, from work to social life.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8749, 'run interference', 'in American football, to protect the player who has the ball by physically preventing the opposing team from coming near him', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8750, 'run its course', 'to develop and finish naturally:', 'The doctor''s advice is to let the fever run its course.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8751, 'run off', 'to leave somewhere or someone suddenly:', 'You can''t run off (home) now, just when I need you!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8752, 'run something off', 'If you run off copies of something, you print them:', '[ + two objects ] Could you run me off five copies of this, please?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8753, 'run something off', 'to quickly and easily write something that is usually slow or difficult to write, such as a piece of poetry or music:', 'Kate can run off a sonnet in half an hour on any subject you like.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8754, 'run something off', 'to win points easily in a competition:', 'Iowa ran off 12 straight points to take the lead.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8755, 'run off with something', 'to leave a place or person suddenly after having stolen something:', 'He ran off with $10,000 of the company''s money.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8756, 'run on', 'If an event runs on, it continues for longer than expected:', 'The game/speech/discussion ran on for hours.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8757, 'run on', 'If time runs on, it seems to pass quickly:', 'Time''s running on - let''s get this job finished soon!', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8758, 'run on something', 'If a machine runs on a particular type or supply of power, it uses that power to work:', 'Some calculators run on solar power.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8759, 'run out', 'to finish, use, or sell all of something, so that there is none left:', 'I''ve run out of milk/money/ideas/patience.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8760, 'run out', 'If a supply of something runs out, all of it has been used or it is completely finished:', 'The milk has run out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8761, 'run out', 'If a document or official agreement runs out, the period of time for which it lasts finishes:', 'My passport runs out next month - I must get it renewed.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8762, 'run out', 'used to say that there is not much time left in which to achieve something:', 'Time is running out for the men trapped under the rubble.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8763, 'run someone out', 'If you are run out in cricket, a player on the opposing team throws the ball at the wicket you are running towards and hits it before you can reach it, and your turn as batsman ends:', 'Their best batsman was run out for (= having scored) 99.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8764, 'run out of steam', 'to suddenly lose the energy or interest to continue doing what you are doing:', 'The peace talks seem to have run out of steam.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8765, 'run out on someone/something', 'to leave someone you are having a relationship with or something you are responsible for, without warning and usually causing problems:', 'She ran out on him two months ago, leaving him to take care of their two children.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8766, 'run out the clock', 'to use all the time that is still available:', 'He was supposed to fall on the ball, allowing San Jose to run out the clock.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8767, 'run over/through something', 'to quickly say or practise something:', 'I''ll just run over what''s been said so far, for latecomers who missed the first speakers.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8768, 'run over/through something', 'to examine a document or subject with someone in order to explain it or to get their help or opinion on it:', 'I''d like to run over the main points of the article with you.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8769, 'run rings around someone', 'If someone runs rings around you, they are very much better, faster, or more successful at something than you are:', 'Our girls'' hockey team have run rings around all their opponents this year.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8770, 'run rings round someone', 'If someone runs rings round you, they are very much better, faster, or more successful at something than you are:', 'Our girls'' hockey team have run rings round all their opponents this year.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8771, 'run riot', 'If people run riot, they behave in a way that is not controlled, running in all directions or being noisy or violent:', 'I dread them coming here because they let their kids run riot.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8772, 'run riot', 'If your imagination runs riot, you have a lot of strange, exciting, or surprising thoughts:', 'My imagination was running riot, thinking of all the ways that I could spend the money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8773, 'run roughshod over someone', 'to act without caring how you will affect someone or something:', 'He ran roughshod over his employees when he thought they weren''t working hard enough.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8774, 'run round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8775, 'run round in circles', 'to be very active but with few results:', 'We''ve been running round in circles trying to get the information we need, but no-one will tell us anything.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8776, 'run round like a headless chicken', 'to be very busy doing a lot of things, but in a way that is not very effective', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8777, 'run someone close', 'to be nearly as good, fast, etc. as someone else:', 'She got 90 percent, but Fred ran her close with 87 percent.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8778, 'run someone out of town (on a rail)', 'to force someone to leave a town:', 'The sheriff and his men ran the horse thieves out of town.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8779, 'run someone ragged', 'If you run someone ragged, you make them very tired, usually by giving them too much work or work that is too demanding:', 'The kids have run me ragged this week - I''m glad they''re going back to school tomorrow.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8780, 'run someone/something down', 'to criticize someone or something, often unfairly:', 'He''s always running himself down.', 'phrasal verb', 'C1', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8781, 'run someone/something down', 'to hit and injure a person or animal with a vehicle, especially intentionally:', 'Two masked men on motorbikes tried to run me down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8782, 'run someone/something down', 'to find someone or something after following or searching for him, her, or it for a long time:', 'I finally ran Mr Green down in/to a house in the country.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8783, 'run (something) down', 'to reduce a business or organization in size or importance, or to become reduced in this way:', 'The government is secretly running down the troop levels.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8784, 'run (something) down', 'If a machine or device such as a clock or battery runs down, it loses power, or if you run it down, you cause this to happen:', 'These batteries can be recharged when they run down.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8785, 'run something down', 'If a large ship runs down a smaller one, it hits it.', '', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8786, 'run yourself down', 'to make yourself tired and ill:', 'Since he took that extra job, he''s really run himself down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8787, 'run someone/something over', 'If a vehicle or its driver runs over someone or something, the vehicle hits and drives over him, her, or it:', 'I think we''ve just run a rabbit over.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8788, 'run over', 'If liquid runs over, it flows over the edges of something, because there is too much of it:', 'The water/The bath is running over - quick, turn the taps off.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8789, 'run over (something)', 'to continue after the expected finishing time:', 'We''re starting to run over time, so could you keep your speeches short, please.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8790, 'run someone/something to ground', 'to find someone or something after a lot of searching and problems:', 'Detectives finally ran the terrorists to ground in an apartment building in Chicago.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8791, 'run something by someone', 'to tell someone about something so that that person can give their opinion about it:', 'Would you run your idea by me one more time?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8792, 'run something in', 'If you run in a vehicle, you use it carefully and slowly for a short time when it is new, so that you do not damage its engine.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8793, 'run someone in', 'If the police run someone in, they find that person and take them to a police station.', '', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8794, 'run something up', 'If you run up a debt, you do things that cause you to owe a large amount of money:', 'She stayed two weeks at the hotel and ran up a bill that she couldn''t pay.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8795, 'run something up', 'to quickly make something such as a piece of clothing from material:', '[ + two objects ] I can run you up some curtains in a few hours, if you want.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8796, 'run something up', 'to make the price or value of something increase:', 'Heavy buying ran the price of stocks up higher than expected.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8797, 'run something up', 'to raise a flag into the air on a pole or mast:', 'They''ve run up a British flag on the roof.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8798, 'run sth by/past sb', 'to tell someone about something, to make sure they understand or approve:', 'I would like to run some ideas by you before we agree to the deal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8799, 'run the gamut', 'to include the whole range of possible things within a group or type:', 'Their projects run the gamut from mobile homes to luxury condos.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8800, 'run the gauntlet', 'to have to deal with a lot of people who are criticizing or attacking you:', 'Every day they had to run the gauntlet of hostile journalists on their way to school.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8801, 'run the risk of doing something', 'to make a particular result possible:', 'When doctors do not follow government guidelines, they run the risk of being sued.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8802, 'run the risk of doing something', 'to do something although something bad might happen because of it:', 'If you tell him the truth, you run the risk of hurting his feelings.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8803, 'run the show', 'to be the leader, who is in control of a group of people doing something:', 'If you need help, ask Mark - he''s running the show.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8804, 'run through someone''s head/mind', 'If something is running through your head/mind, you cannot stop thinking about it or singing it silently:', 'I''ve had that tune running through my head all day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8805, 'run through someone''s mind/head', 'to suddenly think of something:', 'It ran through my mind that I was being tricked by Charlie.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8806, 'run through something', 'to look at, examine, or deal with a set of things, especially quickly:', 'We ran through the list, but none of the machines seemed any good.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8807, 'run through something', 'If a quality runs through something, it is in all parts of it:', 'Melancholy runs through all her stories.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8808, 'run through something', 'to use up an amount of something quickly:', 'It took him just a few months to run through all the money his father left him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8809, 'run someone/something through', 'to push a sword or similar pointed weapon right into a person or animal:', 'He drew his sword and ran the villain through.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8810, 'run to something', 'to reach a particular amount, level, or size:', 'The new encyclopedia runs to several thousand pages.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8811, 'run to something', 'to have enough money to buy something or (of an income, etc.) to be enough to buy something:', 'I can lend you €1,000, but I can''t run to more than that.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8812, 'run to something', 'If your taste or skill runs to something, that is the type of thing that you enjoy or can manage to do:', 'I doubt if his musical taste runs to opera.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8813, 'run up against something', 'to experience an unexpected difficulty:', 'The plans for the new bridge ran up against strong local opposition.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8814, 'run wild', 'If someone, often a child, runs wild, that person behaves as they want to without being controlled by anyone.', '', 'idiom', 'C2', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8815, 'run with it', 'infml to work independently to achieve something:', 'The Japanese took that technology and ran with it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8816, 'run with something', 'to accept something, start to use it, and develop it further:', 'The Japanese took that technology and ran with it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8817, 'run your eye over something', 'to look quickly at the whole of something:', 'Can I have a copy of the article to run my eye over, before it''s printed?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8818, 'run yourself into the ground', 'to make yourself very tired by working too much:', 'We ran ourselves into the ground to meet the July deadline.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8819, 'run/go deep', 'If a feeling or problem runs deep, it is strong or serious and has existed for a long time:', 'The anger runs deep on both sides.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8820, 'run/go like clockwork', 'to happen exactly as planned, without any trouble:', 'The party went like clockwork.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8821, 'runners and riders', 'all the horses and jockeys (= riders) that are competing against each other in a race:', 'Here are the main runners and riders in the race.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8822, 'runners and riders', 'the people who are competing to get a job or be elected:', 'The speculation about the runners and riders to succeed her was unmatched.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8823, 'running battle', 'an argument that lasts over several different occasions:', 'I''ve had a running battle with the neighbours over whose responsibility that fence is.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8824, 'running on empty', '(of an engine or vehicle) having almost no fuel left:', 'His diesel engine was running on empty.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8825, 'running on empty', 'having almost reached a point where you are unable to continue, because you have almost no energy, money, etc. left:', 'His campaign treasury is running on empty.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8826, 'running with blood', 'If a place is running with blood, a lot of fighting is happening and many people are being hurt or killed there:', 'During the revolution the streets were running with blood.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8827, 'rush into something', 'If you rush into something such as a job, you start doing it without having really decided if it is the right thing to do or having considered the best way to do it.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8828, 'rush someone into (doing) something', 'to forcefully persuade someone to do something without giving them time to decide if they really want to do it', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8829, 'rush something out', 'to very quickly produce something and make it available to sell:', 'When the war started, several publishers rushed out books on the conflict.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8830, 'rush sth through', 'to cause something to happen or be produced too quickly:', 'The bill was rushed through parliament.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8831, 'rush/run someone off their feet', 'to cause someone to be very busy:', 'I''ve been rushed off my feet all morning.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8832, 'rustle something up', 'to make something quickly, usually a meal from the food that is available:', 'Give me a minute and I''ll rustle something up for supper.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8833, 'sack out', 'to go to bed:', 'It''s late - I''m going to sack out.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8834, 'sad to say', 'it is sad, regrettable, or embarrassing that this fact is true:', 'Sad to say, the violin was never found.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8835, 'sadder but wiser', 'If someone is sadder but wiser after a bad experience, they have suffered but they have also learned something from it.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8836, 'saddle someone with something', 'to give someone a responsibility or problem that they do not want and that will cause them a lot of work or difficulty:', 'The company is saddled with debt.', 'phrasal verb', 'C2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8837, 'saddle up something', 'to fasten a seat on the back of a horse, or to ride a horse:', 'Fred saddled up a horse and set out for Kingston to pick up the mail.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8838, 'safe and sound', 'not hurt or damaged:', 'Three days later, the hikers were found safe and sound.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8839, 'safeguard against something', 'to do things that you hope will stop something unpleasant from happening:', 'A good diet will safeguard against disease.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8840, 'safety first', 'said to mean that it is best to avoid any unnecessary risks and to act so that you stay safe', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8841, 'sail against the wind', 'to be trying to achieve something that is unlikely to succeed because most people would oppose it:', 'He''s sailing against the wind in his attempt to stop women joining the club.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8842, 'sail close to the wind', 'to do something that is dangerous or only just legal or acceptable:', 'You were sailing a little close to the wind there when you made those remarks about his wife.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8843, 'sail in', 'to start an activity enthusiastically:', 'The children sailed into the pile of cakes and in minutes the cakes were gone.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8844, 'sail in', 'to attack someone using words:', 'The president sailed into her opponents with an angry speech.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8845, 'sail through (something)', 'to succeed very easily in something, especially a test:', 'Rachel sailed through her finals and got A''s in everything.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8846, 'sally forth', 'to leave a safe place in a brave or confident way in order to do something difficult:', 'The minister opened the door and sallied forth to face the angry crowd.', 'idiom', '', 'old-fashioned, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8847, 'salt of the earth', 'very good, honest, and reasonable, and not thinking you are special in any way:', 'They were such a lovely couple. They really were the salt of the earth.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8848, 'salt something away', 'to save something, often money, secretly:', 'He salted away a fortune over the years and no one ever knew!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8849, 'same again', 'said when you want another drink of the same type as you have just had:', '"What are you having, David?" "Same again, please."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8850, 'same difference', 'said when you agree that what you said was not exactly correct, but you think the difference is not important:', '"He was driving a red car." "Actually, it was maroon." "Same difference."', 'idiom', '', 'not standard', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8851, 'same here', 'used when you agree with what someone has said or you have experienced the same thing as they have:', '"I thought that film was awful!" "Same here!"
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8852, 'same old same old', 'used to say that a situation or someone''s behaviour remains the same, especially when it is boring or annoying:', 'Most people just keep on doing the same old same old every day.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8853, 'same to you', 'used as an answer to someone who has greeted or insulted you in order to wish the same thing to them:', '"Have a good holiday!" "Same to you!" (= I hope you have a good holiday too.)', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8854, 'sandwich someone/something between someone/something', 'If you are sandwiched between two people or things, you are in a small space between them:', 'On the train I was sandwiched between two very large men.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8855, 'sandwich something together', 'to put a layer of something between two things that sticks them together:', 'I sandwiched the cakes together with chocolate butter cream.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8856, 'sarcasm is the lowest form of wit', 'said to mean that sarcasm is unkind and not very funny', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8857, 'save (something) up', 'to keep money so that you can buy something with it in the future:', 'It took me months to save up enough money to go travelling.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8858, 'save face', 'to keep your reputation and avoid others losing respect for you:', 'We said he left "to pursue other interests" to let him save face, but actually we fired him.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8859, 'save on something', 'to avoid using something so that you do not have to pay for it:', 'It was a warm winter, so we saved on electricity.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8860, 'save someone''s bacon/neck', 'to help someone avoid getting into trouble', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8861, 'save the day', 'to do something that prevents a likely defeat or failure:', 'The team seemed to be heading for disaster until a late goal saved the day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8862, 'save your breath', 'used to say that it is not worth talking to someone because they will not listen to you:', 'I don''t know why I even try to talk to him - I might as well save my breath.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8863, 'save your own skin/hide', 'to protect yourself from danger or difficulty, without trying to help other people', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8864, 'save/keep money for a rainy day', 'to save money for a time when it might be needed unexpectedly:', 'Luckily she had saved some money for a rainy day.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8865, 'saved by the bell', 'something that you say when a difficult situation ends suddenly before you have to do or say something that you do not want to:', 'Luckily my bus arrived before I had time to reply. Saved by the bell.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8866, 'savour of something', 'to have particular characteristics or qualities that make people think of something, especially something unpleasant:', 'His behaviour does rather savour of hypocrisy.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8867, 'saw something down', 'to make something fall to the ground by cutting it with a saw', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8868, 'saw something off', 'to remove something by cutting it with a saw:', 'She sawed off the dead branches of the tree.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8869, 'saw something up', 'to cut something into smaller pieces using a saw:', 'I''ll saw the logs up into smaller pieces.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8870, 'say a lot about something/someone', 'to clearly show or express something about someone or something:', 'It says a lot about her that she''s willing to help people she doesn''t even know.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8871, 'say cheese', 'something that someone who is taking a photograph of you tells you to say so that your mouth makes the shape of a smile', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8872, 'say goodbye to something', 'to accept that you will not have something any more or that you will not get it:', 'Once you have kids, you can say goodbye to going out every weekend.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8873, 'say no more', 'said to show that you understand exactly what the other person is suggesting:', '"I saw him coming out of her flat." "Say no more!"', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8874, 'say something to yourself', 'to think something:', 'I said to myself, I’d better take care of that now.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8875, 'say the word', 'used to tell someone that you will do what they want at the time they ask you:', 'You only have to/Just say the word, and I''ll come and help.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8876, 'say this/that much for someone/something', 'to say something good about someone or something considered to be bad:', 'I''ll say this much for Kay, she always agrees to help whenever we ask her.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8877, 'say uncle', 'to admit failure', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8878, 'say when', 'said when you are pouring a drink for someone and you want them to tell you when to stop pouring', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8879, 'say your piece', 'to say what you are obviously wanting to say:', 'Just say your piece and then go.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8880, 'says something about someone/something', 'to show what a particular person or thing is like:', 'The way he drives says a lot about his character.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8881, 'says who?', 'used when you are arguing with someone, to show that you do not accept or agree with what they say:', 'You''re the best? Says who?', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8882, 'sb wouldn''t touch something/someone with a bargepole/barge pole', 'someone does not want a particular thing or person at all, or does not want to have anything at all to do with it or them:', 'Don''t tell granny we made the cake or she''s not going to touch it with a bargepole.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8883, 'sb wouldn''t touch something/someone with a ten-foot pole', 'someone does not want a particular thing or person at all, or does not want to have anything at all to do with it or them:', 'If you''re not successful, they won''t touch you with a ten-foot pole.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8884, 'sb''s way or the highway', 'used for saying that someone will only accept their own way of doing something:', 'Some coaches say, "it''s my way or the highway".
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8885, 'scale back/down (something)', 'to reduce something in size, amount, or production:', 'Sid will have to scale back his plans.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8886, 'scale something down', 'to make something smaller than it was or smaller than it was planned to be:', 'A shortage of money has forced them to scale down the project.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8887, 'scale something up', 'to increase the size, amount, or importance of something, usually an organization or process:', 'My company is scaling up its operations in Western Asia.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8888, 'scale the heights', 'If you scale the heights of a type of work, you are very successful in it:', 'At the age of 35, she had already scaled the heights of the acting profession.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8889, 'scare someone into doing something', 'to persuade someone to do something by frightening them:', 'The two boys scared the old man into handing over his wallet.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8890, 'scare someone shitless', 'to make someone extremely frightened', '', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8891, 'scare someone to death', 'to frighten someone very much:', 'Thunderstorms scare her to death.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8892, 'scare someone/something away/off', 'to make a person or an animal so frightened that he, she, or it goes away:', 'Don''t make too much noise or you''ll scare away the birds.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8893, 'scare someone away/off', 'to make someone so worried about doing something that they decide not to do it:', 'If you charge as much as that, you''ll scare customers off.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8894, 'scare something up', 'to find or get something despite difficulties or limited supplies:', 'There''s hardly any food in the house, but I''ll scare something up from these leftovers.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8895, 'scare the (living) daylights out of someone', 'to frighten someone very much:', 'You scared the daylights out of me, yelling like that.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8896, 'scare the bejabbers out of someone', 'to frighten, annoy, bore, etc. someone very much:', 'It''s the fact that this is happening to good kids from good families that scares the bejabbers out of us.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8897, 'scare the bejesus out of someone', 'to frighten, annoy, bore, etc. someone very much:', 'I was in the middle of a typhoon in 2012 and it scared the bejesus out of me.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8898, 'scare, frighten, etc. the (living) daylights out of someone', 'to frighten someone very much:', 'Don''t jump out on me like that! You scared the living daylights out of me!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8899, 'scare/frighten the life out of someone', 'to frighten someone very much', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8900, 'scent blood', 'to believe that someone you are competing against is having difficulties and to use this to get an advantage for yourself:', 'The manager has already made some serious errors of judgment and it is clear that other employees scent blood.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8901, 'school of hard knocks', 'If you learn something in the school of hard knocks, you learn it as a result of difficult or unpleasant experiences.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8902, 'scissors and paste', 'If something such as a piece of writing is a scissors and paste job, it is not original, but is made up from parts of other people''s work.', '', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8903, 'scoop something out', 'to remove something that is inside something else with a spoon:', 'Cut the tomato in half and scoop out the seeds.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8904, 'scoop something/someone up', 'to lift something or someone with your hands or arms in a quick movement:', 'She scooped the children up and ran with them to safety.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8905, 'scoop the pool', 'to win all the prizes that are available:', 'Cuba scooped the pool in the boxing at this year''s Olympics.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8906, 'scope something/someone out', 'to look carefully to see if something or someone is interesting or attractive:', 'We scoped out the local area to see if it would be a good place to rent a flat.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8907, 'score points (with sb)', 'to do something that will make someone like you:', 'He tried really hard to be funny and cool to try to score points with Amanda.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8908, 'score points off someone', 'to say things that make someone else seem silly or wrong:', 'He''s always trying to score points off people and it''s really irritating.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8909, 'score something out/through', 'to draw a line through a piece of writing:', 'He scored out two names on the list.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8910, 'scour something out', 'to make a hole by a movement that is repeated continuously over a long period of time:', 'The fast-moving water had scoured out a channel in the rock.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8911, 'scrape a living', 'to only just earn enough money to provide yourself with food, clothing, and a place to live:', 'He settled in Paris, where he scraped a living writing short stories and magazine articles.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8912, 'scrape by', 'to have only enough money to pay for the basic things you need:', 'Even with both of us working, we earn just enough to scrape by.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8913, 'scrape by/along', 'to manage to live when you do not have enough money and other necessary things:', 'He lost his job, so the family had to scrape by on one small salary.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8914, 'scrape by/along', 'to manage with difficulty to get a successful result or to reach an acceptable standard:', 'I only studied Spanish for a year but I can scrape by in most situations.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8915, 'scrape home', 'to win by a very small amount in a competition:', 'The reigning champion scraped home just 2.9 seconds ahead of his nearest rival.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8916, 'scrape something/someone together/up', 'to manage with great difficulty to collect enough of something, especially money, or to find the things or people that you need:', 'I finally scraped together enough money for a flight home.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8917, 'scrape the bottom of the barrel', 'to use the worst people or things because that is all that is available:', 'Richard''s in the team? You really are scraping the bottom of the barrel!', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8918, 'scrape through (something)', 'to succeed in something but with a lot of difficulty:', 'He managed to scrape through his final exams.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8919, 'scratch around for something', 'to look for something that is very difficult to find because it is rare:', 'The editor of the local paper says he''s really scratching around for stories this week.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8920, 'scratch beneath the surface', 'to look further than what is obvious:', 'If you scratch beneath the surface you''ll find she''s really a very nice person.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8921, 'scratch the surface', 'to deal with only a small part of a subject or a problem:', 'All the payments we’ve made have hardly scratched the surface of the amount we borrowed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8922, 'scratch your head', 'to think hard about something:', 'A lot of people must be scratching their heads about which way to vote.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8923, 'scratch/scrape the surface', 'to deal with only a very small part of a subject or a problem:', 'There''s far more to be said - I''ve only had time to scratch the surface in this talk.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8924, 'scream (out) for something', 'to need something very much:', 'This matter is screaming out for attention.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8925, 'scream your head off', 'to scream very loudly:', 'I screamed my head off on the roller coaster.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8926, 'scream/shout blue murder', 'to show your anger about something, especially by shouting or complaining very loudly:', 'He''ll scream blue murder if he doesn''t get his way.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8927, 'screen out something/someone', 'to prevent something or someone undesirable from coming in:', 'Home water filtration systems are supposed to screen out toxins and other contaminants.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8928, 'screen something off', 'to separate one area from another using a wall or other vertical structure:', 'We can screen off part of the room and use it as a temporary office.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8929, 'screw (something) up', 'to make a mistake, or to spoil something:', 'I totally screwed up the chemistry exam.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8930, 'screw someone up', 'When bad experiences or people screw you up, they make you worried and unhappy or damage your personality:', 'It really screwed him up when he saw his friend get killed.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8931, 'screw around', 'to have sex with a lot of people or with people other than your husband or wife', '', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8932, 'screw it', 'slang I do not care what happens:', 'It takes a lot of work to be successful, but most people are lazy and say screw it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8933, 'screw it/you/them!', 'used when expressing extreme anger:', '"Screw it!" he said. "If they won''t give us the money, we''ll just take it."', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8934, 'screw something out of someone', 'to get something from someone by using force or threats:', 'We''ll screw every last penny out of him.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8935, 'screw up your courage', 'to force yourself to be brave:', 'I screwed up my courage and went in to see the director.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8936, 'scrounge around', 'to look in different places or in a particular place where you might find something that you need:', 'She scrounged around in the tool box for a tack or nail to hang the sign up with.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8937, 'scrub up', 'When a doctor scrubs up or scrubs in, he or she washes his or her hands and arms very carefully before performing a medical operation.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8938, 'scrub up well', 'said about someone when they have made an effort to look nice:', 'Mary scrubs up well.', 'idiom', '', 'informal, approving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8939, 'sea of something', 'a lot of something:', 'She looked out at the sea of faces in the audience.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8940, 'seal of approval', 'a statement or sign that someone in an important position approves of something:', 'The mayor has given the proposal her seal of approval.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8941, 'seal someone''s fate', 'If an action, event, or situation seals your fate, nothing can stop some unpleasant thing happening to you:', 'From the moment she stepped into the busy road her fate was sealed.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8942, 'seal something in', 'to prevent a substance or quality from being lost from something during a process such as cooking:', 'Fry the meat quickly in hot oil to seal in the flavour/juices.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8943, 'seal something off', 'to prevent people from entering an area or building, often because it is dangerous:', 'Two more bombs have been discovered since the police sealed off the area.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8944, 'search me!', 'something that you say when you do not know the answer to a question:', '"Where''s Jack?" "Search me!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8945, 'search something/someone out', 'to find something or someone after searching:', 'Despite the warm weather, we searched out some snow and went skiing.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8946, 'seat of learning', 'a place where people are educated:', 'The Sorbonne is a world-famous seat of learning.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8947, 'second best', 'not as good as the best and therefore not wanted as much:', 'She refuses to settle for second best - she strives for perfection.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8948, 'second to none', 'as good as or better than all others:', 'The conditions that these prisoners are kept in are second to none.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8949, 'section something off', 'to separate one part of an area from the rest of the area:', 'Security agents sectioned off the area where she shopped.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8950, 'see a man about a dog', 'You might say you have to see a man about a dog when you do not want to say what you are really doing, especially when going to the toilet:', 'I''ve just got to see a man about a dog. I''ll be back in a minute.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8951, 'see about something', 'to prepare for or deal with an action or event, or to arrange for something to be done:', 'It''s getting late - I''d better see about lunch.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8952, 'see eye to eye', 'If two people see eye to eye, they agree with each other:', 'My sisters don''t see eye to eye with me about the arrangements.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8953, 'see fit', 'If you see fit to do something, you think it is good or necessary to do it:', 'She saw fit to pull her son out of the school.', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8954, 'see fit (to do something)', 'to think it is good or necessary to do something:', 'You can leave it here or take it home with you, whichever you see fit.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8955, 'see in the New Year', 'to not go to bed on 31 December until after twelve o''clock at night in order to celebrate the start of a new year', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8956, 'see life', 'to experience many different and often unexpected things:', 'As a volunteer on the childcare project, I really saw life.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8957, 'see past something', 'to not be influenced or have your opinion changed by something :', 'He has been able to see past stereotypes and photographed the Cherokee as a dynamic presence in today''s world.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8958, 'see red', 'to become very angry:', 'People who don''t finish a job really make me see red.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8959, 'see sense/reason', 'to be reasonable and have good judgment:', 'We talked to her for an hour, but we couldn''t make her see sense.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8960, 'see someone in hell before ...', 'If you would see someone in hell before you would do something they have suggested, you are very determined not to do it:', 'I''d see her in hell before I''d agree to an arrangement like that.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8961, 'see someone off', 'to go to the place that someone is leaving from in order to say goodbye to them:', 'My parents saw me off at the airport.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8962, 'see someone off', 'to send away someone who is attacking you or who is not wanted, usually forcefully:', 'The caretaker ran out and saw off the boys who had been damaging the fence.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8963, 'see someone/something off', 'to defeat someone or something, or to deal with him, her, or it effectively so that that person or thing can no longer cause harm:', 'The company believes it has now seen off this unwelcome bid.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8964, 'see someone right', 'to make certain that someone is helped or treated well:', 'Ask Mrs Martin at the desk over there about the invoices - she''ll see you right.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8965, 'see someone through something', 'to support someone during a difficult time:', 'He was a real friend to see me through my long illness.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8966, 'see someone through something', 'to help or support someone during a difficult period in their life:', 'He was a prisoner of war for five years, but his courage saw him through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8967, 'see something through', 'to continue doing a job or activity until it is finished, especially when it is difficult:', 'The degree would take me three years to complete, but I was determined to see it through.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8968, 'see through someone/something', 'to realize that someone is trying to deceive you to get an advantage, or that someone''s behaviour is intended to deceive you, and to understand the truth about the situation:', 'They were very friendly, but it didn''t take long to see through them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8969, 'see someone''s true colors', 'to see someone''s real character for the first time, especially when it is unpleasant:', 'It was only when they started to work together that she began to see his true colors.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8970, 'see someone''s true colours', 'to see someone''s real character for the first time, especially when it is unpleasant:', 'It was only when they started to work together that she began to see his true colours.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8971, 'see something at a glance', 'know and understand almost immediately:', 'She could see at a glance that something was seriously wrong.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8972, 'see something coming', 'to expect something to happen:', 'No one else had expected the factory to close, but we saw it coming.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8973, 'see something in someone/something', 'to believe that someone or something has a particular quality:', 'Her teachers saw something special in her.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8974, 'see something out', 'to wait or last until the end of a difficult event or situation:', 'The besieged town doesn''t have enough food to see the month out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8975, 'see someone out', 'to go to the door of a building or room with someone who does not live or work there, when they are leaving:', 'My secretary will see you out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8976, 'see yourself out', 'to leave a building or room by yourself after visiting someone there:', 'It''s ok - I''ll see myself out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8977, 'see something with your own eyes', 'to see something yourself, especially when it is something that you would not believe to exist or be true if you did not see it:', 'They took all the money and left. I saw it with my own eyes.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8978, 'see stars', 'If you see stars, you are partly unconscious because you have been hit on the head.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8979, 'see the back of someone/something', 'If you are pleased to see the back of someone or something, you are pleased that you no longer have to be involved with him, her, or it:', 'The hotel staff were glad to see the back of such a difficult guest.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8980, 'see the colour of someone''s money', 'To see the colour of someone''s money is to make certain that a person is going to pay for something:', '"I''ll have one of those." "Let''s see the colour of your money first!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8981, 'see the joke', 'to understand something funny and find it funny yourself:', 'Everyone else laughed loudly, but I didn''t see the joke.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8982, 'see the last of something/someone', 'to not see something or someone again because that thing or person has gone away or has ended', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8983, 'see the light', 'If you see the light, you suddenly understand something you didn''t understand before.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8984, 'see the light of day', 'When something sees the light of day, it appears for the first time.', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8985, 'see the point of something', 'to understand the importance of or the reason for something:', 'They couldn''t see the point of more training.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8986, 'see things in black and white', 'to have a simple view of what is right and wrong, or good and bad', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8987, 'see to something/someone', 'to deal with a person or task that needs to be dealt with or is waiting to be dealt with:', '"These letters need posting." "I''ll see to them later."
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8988, 'see you (later)', 'goodbye', '', 'idiom', 'A1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8989, 'see you soon', 'used for saying goodbye to someone you are going to meet again soon:', 'I''ll see you soon!', 'idiom', 'A1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8990, 'see your way (clear) to doing something', 'to agree to do or allow something:', 'Could you see your way to letting us borrow the machine on Wednesday?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8991, 'see/catch you later!', 'a way of saying goodbye:', '"Bye." "See you later."', 'idiom', 'B1', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8992, 'seeing is believing', 'said to mean that if you see something yourself, you will believe it to exist or be true, despite the fact that it is extremely unusual or unexpected:', 'I never thought Mark would get out of bed before lunchtime on a Saturday, but seeing is believing!', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8993, 'seeing things', 'If you are seeing things, you are imagining that things are happening when they are not:', 'I could have sworn I saw Marie come in just now. I must have been seeing things.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8994, 'seek someone/something out', 'to look for someone or something, especially for a long time until you find him, her, or it:', 'While he was at the library, Steve decided to seek out some information on the history of the area.', 'phrasal verb', '', 'formal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8995, 'seize on/upon something', 'to use, accept, or take advantage of something quickly or enthusiastically:', 'The story was seized on by the tabloid press, who printed it under huge headlines.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8996, 'seize up', 'to stop being able to move or work in the normal way:', 'The washing machine totally seized up on Thursday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8997, 'sell into sth', 'to sell shares or bonds in a particular situation:', 'The Bank''s usual policy is to sell into a rising or stable market.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8998, 'sell out', 'to sell all of the supply that you have of something:', 'We sold out of the T-shirts in the first couple of hours.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (8999, 'sell out', 'If a supply of something sells out, there is no more of that thing to buy:', 'The first issue of the magazine sold out within two days.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9000, 'sell out', 'When a film, concert, etc. is sold out, all of the tickets for it have been sold:', 'We couldn''t get seats - the concert was sold out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9001, 'sell out', 'to sell your business or part of your business:', 'They decided to sell out to their competitors.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9002, 'sell (someone) out', 'to not do what you have promised someone you will do or what you should do because you will get more advantages for yourself if you do something else:', 'French farmers feel they''ve been sold out by their government in the negotiations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9003, 'sell someone a bill of goods', 'to deceive someone into buying or believing something that has no value', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9004, 'sell someone down the river', 'to put someone in a difficult or dangerous situation by not acting as you had promised to act, usually in order to win an advantage for yourself', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9005, 'sell someone on something', 'to persuade someone that something is good, valuable, or useful:', 'The filmmakers sold me on the idea that my book would work on the screen.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9006, 'sell someone/yourself/something short', 'to not consider someone or something to be as valuable or good as he, she, or it deserves:', 'Don''t sell yourself short - you''ve got the skills and the experience.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9007, 'sell something off', 'to charge a low price for something to encourage people to buy it:', 'They''re selling off last year''s stock at half price.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9008, 'sell something off', 'to sell all or part of a business:', 'The company announced that it would be selling off its hotel business.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9009, 'sell sth back to sb/sth', 'to sell something to the person you bought it from:', 'You can cash in your shares by selling them back to the mutual fund.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9010, 'sell sth forward', 'to make an arrangement to sell a commodity in the future at a fixed price:', 'The group sold forward a mammoth 3.5 million ounces of gold.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9011, 'sell through', 'to be sold to customers:', 'Even with best-sellers, you can''t just sit back and assume the run will sell through.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9012, 'sell up', 'to sell your house or company in order to go somewhere else or do something else:', 'They sold up and retired to the West Country.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9013, 'sell your soul (to the devil)', 'to be persuaded to do something, especially something bad, because of the money or other reward you will receive for doing it', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9014, 'send (off/away) for/to something', 'to write to an organization to ask them to send you something:', 'I''ve sent off for a catalogue.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9015, 'send a message', 'to make someone understand that a particular thing is right or true, or to make someone understand what your attitude is:', 'By taking this action, we are sending a message that bullying will not be tolerated.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9016, 'send a signal (to sb) that', 'to show or warn that something is true:', 'The change should send a signal to financial institutions that we are serious about tackling fraud.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9017, 'send away for something', 'to request something by mail:', 'Carson sent away for a magic kit.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9018, 'send chills down/up someone''s spine', 'to make someone feel very frightened:', 'His words sent a chill down her spine.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9019, 'send for someone', 'to send someone a message asking them to come to see you:', 'Do you think we should send for a doctor?', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9020, 'send out for something', 'to ask for something to be brought to you from another place, by using the phone or sending a message:', 'There''s not much to eat in the fridge. Should I send out for a pizza?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9021, 'send shivers down your spine', 'to feel very frightened or excited:', 'The thought of what might have happened to us sent shivers down my spine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9022, 'send shivers down/up someone''s spine', 'to make someone feel very frightened or excited:', 'The way he looked at me sent shivers down my spine.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9023, 'send shudders/a shudder down your spine', 'to cause you to feel extremely worried or frightened:', 'When I think of what might have happened in the accident, it sends shudders down my spine.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9024, 'send someone away with a flea in their ear', 'to angrily tell someone to go away:', 'A young kid came asking for money but I sent him away with a flea in his ear.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9025, 'send someone down', 'to send someone to prison:', 'He was sent down for armed robbery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9026, 'send someone down', 'to ask someone to leave a college or university before the end of the course because they have done something wrong:', 'She was sent down from Oxford for taking drugs.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9027, 'send someone packing', 'to ask someone to leave immediately:', 'There were some kids at the door asking for money but I sent them packing.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9028, 'send someone to Coventry', 'If a group of people send someone to Coventry, they refuse to speak to that person, usually as a punishment for having done something to upset the group.', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9029, 'send someone to eternity', 'to kill someone', '', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9030, 'send someone up', 'to send someone to prison:', 'He was sent up for armed robbery.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9031, 'send someone/something up', 'to make someone or something seem stupid by copying him, her, or it in a funny way:', 'The show was very funny - they were sending up sports commentators.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9032, 'send someone’s love (to someone)', 'to express someone''s good feelings to someone else:', 'Maggie sends her love to you and the kids.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9033, 'send something back', 'to return something to the person who sent it to you, especially because it is damaged or not suitable:', 'I had to send the shirt back because it didn''t fit me.', 'phrasal verb', 'B1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9034, 'send something in', 'to send something to an organization:', 'The magazine asked its readers to send in their comments about the new style of presentation.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9035, 'send someone in', 'to send soldiers, police, etc. to a place in order to deal with a dangerous situation:', 'UN troops were sent in as the situation got worse.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9036, 'send something off', 'to send a letter, document, or parcel by post:', 'Have you sent off your application form yet?', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9037, 'send someone off', 'to order a sports player to leave the playing area during a game because they have done something wrong:', 'He was sent off for swearing at the referee.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9038, 'send someone off', 'to express good wishes and say goodbye to someone who is leaving a place:', 'A buffet lunch was organized to send her off in style.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9039, 'send someone off', 'to show your respect and say goodbye to someone who has died, especially at a funeral:', 'The people there are famous for sending their dead off in style.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9040, 'send something on', 'to send something from someone''s old address to their new one:', 'Paul moved back to New York and he asked me to send on his letters.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9041, 'send something out', 'to produce something in a way that causes it to spread out from a central point:', 'The equipment sent out a regular high-pitched signal.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9042, 'send something out', 'to send something to a lot of different people, usually by post or email:', 'We sent out the wedding invitations about three weeks ago.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9043, 'send word', 'to send someone to give another person a message:', 'She sent word with her secretary that she would be unable to attend the meeting.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9044, 'send/give out (all) the wrong signals', 'to make people believe or think something that is not correct:', 'If the government refuses to provide aid, it would send out all the wrong signals to the rest of the world.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9045, 'separate the sheep from the goats', 'to make clear which people in a particular group are of a higher ability than the others:', 'The uphill stages of the race will really separate the sheep from the goats.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9046, 'separate the wheat from the chaff', 'to separate things or people that are of high quality or ability from those that are not:', 'The first round of interviews really separates the wheat from the chaff.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9047, 'serve out', 'in tennis, to serve in the last game of a set or match and win it:', 'Williams served out, taking the first set in 26 minutes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9048, 'serve something out', 'to share an amount of food or drink between people by giving some to each:', 'We began serving out food at 12 and it was all gone by 12:20.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9049, 'serve something out', 'to continue to work, hold a position, or stay somewhere for a period of time that has been decided:', 'Should Mr. Murphy simply serve out the rest of his contract?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9050, 'serve something out', 'in tennis, to serve in the last game of a set or match and win it:', 'Federer served out the second set at 5-4.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9051, 'serve someone right', 'If you say that something bad serves someone right, you mean that that person deserves it:', '"He hit me!" "It serves you right. You shouldn''t have been so mean to him."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9052, 'serve something up', 'to provide something or make something available to people :', 'We were served up with a list of titles that best matched what we were looking for.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9053, 'serve (something) up', 'to put food on plates for people to eat:', 'Come on everyone, I''m ready to serve up.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9054, 'set about something', 'to start to do or deal with something:', '[ + -ing verb ] I have no idea how to set about changing a tyre on a car.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9055, 'set about someone', 'to attack someone:', 'Her attacker set about her with a knife.', 'phrasal verb', '', 'literary', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9056, 'set an example', 'to behave in a way that other people should copy:', 'You should be setting a good example to your younger brother.', 'idiom', 'B2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9057, 'set fire to something/someone', 'to cause something or someone to start burning:', 'The protesters set fire to several vehicles.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9058, 'set foot in somewhere', 'to go to a place:', 'He refuses to set foot in an art gallery.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9059, 'set great, little, etc. store by something', 'to consider something to be of great, little, etc. importance or value:', 'She''s setting a lot of store by this job interview - I only hope she gets it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9060, 'set in', 'When something unpleasant sets in, it begins and seems likely to continue in a serious way:', 'This rain looks as if it has set in for the rest of the day.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9061, 'set in stone', 'to be very difficult or impossible to change:', 'The schedule isn’t set in stone, but we’d like to stick to it pretty closely.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9062, 'set in your ways', 'not liking change in your life:', 'They’re very set in their ways – they always eat dinner exactly at 6:00.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9063, 'set off/out', 'to start a journey:', 'What time will we have to set off for Grandma''s house tomorrow?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9064, 'set on/upon someone', 'to attack someone:', 'He was set upon by a vicious dog.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9065, 'set on/upon someone', 'to surround or catch someone and prevent them from escaping:', 'As he left the theatre, the singer was set upon by fans desperate for autographs.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9066, 'set out', 'to start an activity with a particular aim:', 'She set out with the aim of becoming the youngest ever winner of the championship.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9067, 'set out', 'to start a journey', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9068, 'set something out', 'to give the details of something or to explain it, especially in writing, in a clear, organized way:', 'The board has set out its goals/plans/proposals for the coming year.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9069, 'set something out', 'to arrange something, usually a number of things, in an attractive or organized way:', 'The farmers'' market was full of brightly coloured vegetables set out on stalls.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9070, 'set sail', 'to begin a trip on a ship or boat:', 'The ship set sail on January 2, 1589.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9071, 'set someone against someone', 'to cause one person to argue or fight with another person:', 'This war has set neighbour against neighbour.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9072, 'set something against something', 'to consider something in relation to another thing and compare their different qualities or effects:', 'You have to set the advantages of the plan against the disadvantages.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9073, 'set something against something', 'to use or record one thing, especially the cost of something, in order to reduce or remove the effect of another:', 'The cost of business travel and entertainment can be set against tax.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9074, 'set someone back (something)', 'to cost someone a large amount of money:', 'Buying that suit must have set you back.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9075, 'set something/someone back', 'to delay an event, process, or person:', 'The opening of the new swimming pool has been set back by a few weeks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9076, 'set something back', 'to reduce something to a weaker or less advanced state:', 'This defeat has set back their chances of winning the competition.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9077, 'set someone straight', 'to tell someone the true facts about a situation that the person had not understood:', 'I had to set him straight about what really happened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9078, 'set someone''s pulse racing', 'to make someone excited:', 'This is a movie that will set your pulse racing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9079, 'set someone''s teeth on edge', 'If something, especially a noise, sets your teeth on edge, it annoys you very much:', 'That DJ''s voice really sets my teeth on edge.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9080, 'set someone/something on someone', 'to make an animal or person attack someone:', 'The security guards set their dogs on the intruders.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9081, 'set something aside', 'to save something, usually money or time, for a special purpose:', 'He had some money in an account that he''d set aside for his kids.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9082, 'set something aside', 'If a judge or court sets aside a previous decision or judgment, they state that it does not now have any legal effect, usually because they consider it to have been wrong:', 'The Court of Appeal set aside his conviction.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9083, 'set something aside', 'to decide that you will not be influenced by your own feelings or opinions because they are not important at a particular time:', 'In times of war people tend to set aside political differences.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9084, 'set something aside', 'to ignore or not think about a particular fact or situation while considering a matter:', 'Setting aside the question of cost, what do you think of the idea in principle?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9085, 'set something down', 'to write or print something, especially to record it in a formal document:', 'The rules of the club are set down in the members'' handbook.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9086, 'set something down', 'to land an aircraft', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9087, 'set someone down', 'If a vehicle sets down a passenger, it stops so that the passenger can get out:', 'The cab set us down a long way from our hotel, and we had to walk.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9088, 'set something forth', 'formal for
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9089, 'set something in motion', 'to begin something:', 'Newly discovered evidence set a second investigation in motion.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9090, 'set something off', 'to cause an activity or event, often a series of events, to begin or happen:', 'The court''s initial verdict in the police officers'' trial set off serious riots.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9091, 'set something off', 'to cause a loud noise or explosion, such as that made by a bomb or an alarm (= a warning sound) to begin or happen:', 'Terrorists set off a bomb in the city centre.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9092, 'set something off', 'to make something look attractive by providing a contrast (= attractive difference) to it:', 'The new yellow cushions nicely set off the pale green of the chair covers.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9093, 'set someone off', 'to cause someone to start doing something:', '[ + -ing verb ] Every time I think about it, it sets me off laughing.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9094, 'set something to music', 'to write or provide music for a poem, story, or other words so that it can be performed:', 'The poem was set to music in 1888.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9095, 'set something up', 'to formally establish a new company, organization, system, way of working, etc.:', 'A committee has been set up to organize social events for the students.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9096, 'set something up', 'to arrange for an event or activity to happen:', 'We need to set up a meeting to discuss the proposals.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9097, 'set someone up', 'to establish someone or yourself in a business or position:', 'After he left college, his father set him up in the family business.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9098, 'set someone up', 'to provide the money that someone needs for an important task or activity that is expected to last a long time:', 'Winning the lottery has set them up for life.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9099, 'set someone up', 'to provide someone with the energy or health that you need for a particular period of time:', 'A good breakfast really sets you up for the day.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9100, 'set someone up', 'to trick someone in order to make them do something, or in order to make someone seem guilty of something that they have not done:', 'They claimed that they weren''t selling drugs, but that they''d been set up by the police.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9101, 'set something/someone up', 'to provide someone or something with all the necessary things for a particular activity or period of time:', 'I think we''re set up with everything we need for the journey.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9102, 'set (something) up', 'to prepare something for use, especially by putting the different parts of it together:', 'We only had a couple of hours to set up before the exhibition opened.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9103, 'set something/someone apart', 'If a quality or characteristic sets someone or something apart, it shows him, her, or it to be different from, and usually better than, others of the same type:', 'What set her apart from the other candidates for the job was that she had a lot of original ideas.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9104, 'set something/someone on fire', 'to cause something or someone to start burning:', 'A peace activist had set herself on fire in protest over the government''s involvement in the war.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9105, 'set sth (off) against sth', 'to use or record one thing, especially the cost of something, in order to reduce or remove the effect of another:', 'Costs of new equipment or machinery, such as a computer, can also be set against tax.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9106, 'set sth (off) against sth', 'to say that an amount of money should be considered a cost of your business and that therefore you should not pay tax on it:', 'You can set off anything you spend on computer equipment against tax.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9107, 'set the Thames on fire', 'to cause a lot of excitement or strong feelings:', 'His books sell fairly well, but they don''t exactly set the Thames on fire.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9108, 'set the agenda', 'to decide what subjects other people should discuss and deal with', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9109, 'set the bar high/low', 'to set a high/low standard for something:', 'They''ve set the bar high in terms of what people expect from them.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9110, 'set the heather on fire', 'to cause a lot of excitement or strong feelings:', 'The controversy, which sparked in Scotland, set the heather on fire and quickly spread to the House of Lords.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9111, 'set the scene', 'to describe a situation where something is about to happen:', 'First, let''s set the scene - it was a dark, wet night with a strong wind blowing.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9112, 'set the scene', 'to make something possible or likely to happen:', 'His resignation set the scene for a company crisis.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9113, 'set the scene/stage', 'used to mean that conditions have been made right for something to happen, or that something is likely to happen:', 'This weekend''s talks between the two leaders have set the scene for a peace agreement to be reached.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9114, 'set the stage (for something)', 'to make it possible for something else to happen:', 'The new evidence sets the stage for a long and interesting trial.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9115, 'set the tone (for something)', 'to establish a particular mood or character for something:', 'The governor''s speech set the tone for the whole conference.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9116, 'set the wheels in motion', 'to do something that will cause a series of actions to start:', 'I thought a phone call to the right person might set the wheels in motion.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9117, 'set to', 'to start working or dealing with something in an energetic and determined way:', 'If we all set to, we should be able to finish the job in a week.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9118, 'set to', 'to begin to fight', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9119, 'set up shop', 'to start your own business:', 'She set up shop back in 1965 with a very small restaurant in the Kings Road.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9120, 'set your heart on something/doing something', 'to want to get or achieve something very much:', 'She''s set her heart on having a pony.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9121, 'set your mind to something', 'to be determined to do or have something:', 'You can lose weight if you set your mind to it.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9122, 'set your sights on something', 'to decide to achieve something:', 'Jenny has set her sights on winning the competition.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9123, 'set yourself up as something', 'to say that you are a particular type of person:', 'He sets himself up as an expert on vegetable growing, but he doesn''t seem to me to know much about it.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9124, 'set/put someone''s mind at rest/ease', 'to stop someone from worrying about something:', 'Chris phoned to say they''d arrived safely, so that really put my mind at rest.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9125, 'set/put the record straight', 'to write or say something in order to make the true facts known:', 'She''s decided to write her memoirs to set the record straight once and for all.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9126, 'set/put the seal on something', 'to make the result of something certain:', 'The meeting set the seal on the negotiations.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9127, 'set/put your mind to something', 'to decide you are going to do something and to put a lot of effort into doing it:', 'If you''d just put your mind to it, I''m sure you could do it.', 'idiom', 'C1', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9128, 'settle a score', 'to punish someone for something wrong that they did to you in the past and that you cannot forgive:', 'Police believe the killer was a gang member settling a score with a rival gang.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9129, 'settle an (old) score', 'to harm someone because they have harmed you in the past:', 'The president used his speech to settle some old scores with his opponents.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9130, 'settle an account', 'to harm someone because they have harmed you in the past:', 'Police think that the killings may be a result of accounts being settled between local gangs.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9131, 'settle down', 'to become familiar with a place and to feel happy and confident in it:', 'She quickly settled down in her new house/job/school.', 'phrasal verb', 'B2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9132, 'settle down', 'to start living in a place where you intend to stay for a long time, usually with your partner:', 'Eventually I''d like to settle down and have a family, but not yet.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9133, 'settle (someone) down', 'to become quiet and calm, or to make someone become quiet and calm:', 'Come on all of you, stop talking and settle down please!
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9134, 'settle down to something', 'to give all of your attention to something you are doing:', 'When the work was done, we settled down to a home-cooked meal.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9135, 'settle for something', 'to accept or agree to something, or to decide to have something, although it is not exactly what you want or it is not the best:', 'They were hoping to sell their car for £2,000, but settled for £1,500.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9136, 'settle in', 'to become familiar with somewhere new, such as a new house, job, or school, and to feel comfortable and happy there:', 'Once we''ve settled in, we''ll have you over for dinner.', 'phrasal verb', 'C1', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9137, 'settle someone in', 'to help someone to become familiar with a new job or a new place where they will be living, working, or staying:', 'The nurse will be with you soon - she''s settling a new patient in at the moment.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9138, 'settle into somewhere/something', 'to become comfortable in a place or doing an activity:', 'Students settled into their desks and took out their notebooks.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9139, 'settle on something', 'to agree on a decision:', 'Have you settled on a name for the baby?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9140, 'settle something on someone', 'to formally give money or property to someone:', 'When he died, he settled his money on his children.', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9141, 'settle on/upon sth', 'to choose something or decide to do something after considering it carefully:', 'The committee have yet to settle on a site for the new premises.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9142, 'settle the score', 'do something to someone because that person did something harmful or insulting to you in the past:', 'After being embarrassed in front of the class, Dan was determined to settle the score.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9143, 'settle up', 'to pay someone the money that you owe them:', 'Would you like to settle up now, sir?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9144, 'settle your affairs', 'to decide what will happen to your possessions after your death, usually by making a legal document', '', 'idiom', '', 'formal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9145, 'settle your nerves', 'to make yourself feel calmer:', 'After the accident, he went for a walk to try to settle his nerves.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9146, 'settle your stomach', 'to make you feel less sick:', 'Drink this tea, it''ll help to settle your stomach.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9147, 'sew something up', 'to close or repair something by sewing the edges together:', 'Let me sew up that hole in your jeans.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9148, 'sew something up', 'If you have a competition or game sewn up, you are certain to win it or get control of it:', 'The Democratic candidate appears to have the election sewn up.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9149, 'sew something up', 'to complete all the arrangements for a successful business agreement:', 'It''s going to take another week or two to sew up this deal.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9150, 'sex something up', 'to make something seem more exciting or interesting:', 'How can we sex up science writing?', 'phrasal verb', '', 'specialized', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9151, 'shack up', 'to start living in the same house as sexual partners, without being married:', 'I hear Tony and Helen have shacked up together.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9152, 'shade something in', 'to make part of a picture darker', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9153, 'shades of gray', 'the fact of it not being clear in a situation what is right and wrong:', 'The movie presents a straightforward choice between good and evil, with no shades of gray.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9154, 'shades of grey', 'the fact of it not being clear in a situation what is right and wrong:', 'The film presents a straightforward choice between good and evil, with no shades of grey.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9155, 'shake a leg', 'used to tell someone to hurry or act more quickly:', 'Come on, Nick, shake a leg or we''ll never be ready in time.', 'idiom', '', 'old-fashioned, informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9156, 'shake like a leaf', 'to shake in a way that you cannot control because you are very nervous or frightened:', 'He had gone completely white and was shaking like a leaf.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9157, 'shake out', 'to change over a period of time before a final result is known:', 'We have to wait and see how it all shakes out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9158, 'shake something out', 'to hold something such as a piece of cloth at one end and shake it up and down to get rid of dirt or folds:', 'I was on the back doorstep shaking out a rug.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9159, 'shake something out', 'to shake your head to allow your hair to fall freely, after removing objects such as pins that were holding it in place:', 'She took off her hat and shook out her long curls.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9160, 'shake someone down', 'to get money from someone by using threats or tricks', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9161, 'shake someone/somewhere down', 'to search a person or place carefully, usually in order to find things that are stolen or illegal:', 'We can''t shake down the whole building - only the suspect''s apartment.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9162, 'shake down', 'to become organized or established after a period of change:', 'Give the new arrangements time to shake down - I''m sure they''ll be OK.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9163, 'shake someone out of something', 'to stop someone from feeling a particular way by shocking them, frightening them, or making them suddenly understand something:', 'A sudden noise shook him out of his daydream.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9164, 'shake someone up', 'If an unpleasant experience shakes someone up, it makes them feel shocked and upset:', 'I think she was pretty shaken up by the accident.', 'phrasal verb', 'C2', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9165, 'shake something up', 'to cause large changes in something such as an organization, usually in order to make improvements:', 'Technological changes have shaken up many industries.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9166, 'shake something off', 'to get rid of an illness:', 'I hope I can shake off this cold before the weekend.', 'phrasal verb', 'C2', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9167, 'shake someone/something off', 'to get away from someone or something that will not stop following you:', 'He drove through the red lights in an attempt to shake off the police car that was chasing him.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9168, 'shake someone/something off', 'to beat an opponent, or to free yourself from someone or something that is limiting you:', 'I have no doubt that we will be able to shake off the challenge from our rivals.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9169, 'shake/rock something to its foundations', 'to seriously damage, upset, or change an organization or someone''s beliefs:', 'The scandal has shaken the Democratic Party to its foundations.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9170, 'shame on you', 'you should feel ashamed of what you have done:', 'I can''t believe you lied to her - shame on you!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9171, 'shape up', 'to develop:', 'How are your plans shaping up?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9172, 'shape up', 'to improve your behaviour or performance:', 'I''ve been told that if I don''t shape up, I''ll lose my job.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9173, 'shape up or ship out!', 'said to tell someone that they must improve their performance or behaviour or they will have to leave', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9174, 'share a platform', 'to give speeches or to perform at the same public event:', 'It was the first time the opposing candidates had shared a platform.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9175, 'share and share alike', 'used to encourage everyone to have an equal amount of something:', 'Don''t keep all those chocolates to yourself - share and share alike.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9176, 'sharing is caring', 'used for saying that it is good or important to share things:', 'Sharing is caring: Eating pizza should be a communal experience, no matter what the menu says.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9177, 'sharpen (something) up', 'to perform better, or to improve the performance of something:', 'If the company doesn''t sharpen up soon, it will go out of business.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9178, 'sharpen up your act', 'to improve your behaviour or performance:', 'He really needs to sharpen up his act, or he''ll never get to university.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9179, 'shave something off something', 'to reduce something by the stated amount:', 'The new high speed trains will shave 25 minutes off the journey time.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9180, 'shave something off/from something', 'to cut a very thin piece from an object or surface:', 'She shaved a few millimetres off the bottom of the door, so that it would open more easily.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9181, 'shed light on sth', 'to provide information about something or to make something easier to understand:', 'Tracking technologies have shed light on the birds'' social nature.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9182, 'shell (something) out', 'to pay or give money for something, usually unwillingly:', 'Having shelled out €150 for the tickets, I wasn''t going to miss the show.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9183, 'shift (your) ground', 'to change your opinion:', 'He''s annoying to argue with because he keeps shifting his ground.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9184, 'shift for yourself', 'to earn your own income or buy and cook your own food, etc.:', 'He left home at 18 and had to shift for himself.', 'phrasal verb', '', 'old-fashioned', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9185, 'shift gears', 'to suddenly change what you are doing:', 'The first half is a comedy, but then the movie shifts gears.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9186, 'shifting/rearranging the deckchairs on the Titanic', 'used for saying that someone is wasting time dealing with things that are not important, and is ignoring a much more serious problem', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9187, 'shine out', 'If a quality shines out, it is strong and easy to see:', 'Her honesty and sincerity positively shine out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9188, 'shine through', 'If a quality shines through, it is strong and easy to see, usually in a particular situation:', 'Take off your make-up and let your natural beauty shine through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9189, 'ship out', 'to leave a situation:', 'The company sold up and shipped out of its Dublin base.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9190, 'ship sth out', 'to send something away from somewhere to somewhere else:', 'The timber is shipped out of the stockyard by truck.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9191, 'ship someone off', 'to send someone away somewhere:', 'The children were shipped off to their grandparents'' house for the holidays.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9192, 'shit a brick', 'to become very frightened:', 'We were all shitting bricks as the truck missed the car by inches.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9193, 'shit on someone', 'to treat someone very badly and unkindly:', 'He made his money by shitting on other people.', 'phrasal verb', '', 'offensive', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9194, 'shiver (up and) down your spine', 'a frightened or excited feeling:', 'At its most terrifying, his writing sends shivers up and down my spine.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9195, 'shock, horror!', 'an expression used when you are pretending to feel very shocked by a piece of news:', 'Shock, horror! Carl James was seen talking to a woman and it wasn''t his wife.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9196, 'shoot a glance at someone', 'to look at someone quickly:', 'She shot him a glance as he entered the room.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9197, 'shoot for something', 'to try to do something:', 'It''s worth taking chances when you''re shooting for a chance of fame and wealth.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9198, 'shoot for the moon', 'to ask for the best or the most you could hope for:', 'You might as well shoot for the moon and ask for a promotion as well as a raise.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9199, 'shoot from the hip', 'to speak in a very direct and honest way:', 'Jeff is a straight talker who always shoots from the hip.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9200, 'shoot from the hip', 'to react quickly, without thinking carefully about something:', 'We''re not going to shoot from the hip - we''re going to think things through.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9201, 'shoot it out', 'If opposing groups or people armed with guns shoot it out, they shoot at each other until one of the groups or people is dead or defeated.', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9202, 'shoot questions at someone', 'to ask someone a lot of questions very quickly, one after the other:', 'He shot questions at me so quickly that I didn''t even have time to answer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9203, 'shoot something down', 'to destroy an aircraft or make an aircraft, bird, etc. fall to the ground by shooting at it:', 'He was killed during the war when his plane was shot down.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9204, 'shoot someone down', 'to shoot and usually kill someone, showing no sympathy:', 'I saw Leonforte shoot him down like a dog in the street.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9205, 'shoot something off', 'to write and send a message quickly:', 'She immediately shot off an email in reply.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9206, 'shoot something/someone down (in flames)', 'to refuse to accept someone''s suggestion or idea and not consider it at all', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9207, 'shoot the breeze', 'to spend time talking about things that are not important:', 'We sat out on the porch, just shooting the breeze.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9208, 'shoot the works', 'to use all your money or make the greatest effort you can:', 'I emptied my bank account and shot the works on a trip to Mauritius.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9209, 'shoot through', 'to leave a place very quickly, especially in order to avoid having to do something', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9210, 'shoot up', 'to grow in size, or increase in number or level, very quickly:', 'David has really shot up since I saw him last.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9211, 'shoot up', 'to put illegal drugs into your blood using a special needle:', 'She saw a girl shooting up in the toilets.', 'phrasal verb', '', 'slang', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9212, 'shoot something up', 'to fire guns in a place, causing a lot of damage', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9213, 'shoot your mouth off', 'to talk too much in a loud and uncontrolled way:', 'It''s just like Richard to go shooting his mouth off about other people''s business.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9214, 'shoot yourself in the foot', 'to do something without intending to which spoils a situation for yourself', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9215, 'shop around', 'to compare the price and quality of the same or a similar object in different shops before you decide which one to buy:', 'When you''re buying a flight, you should always shop around for the best deal.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9216, 'shore something up', 'to stop a wall or a building from falling down by supporting it with building materials such as wood or metal:', 'Boundary walls have had to be shored up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9217, 'shore something up', 'to support or improve an organization, agreement, or system that is not working effectively or that is likely to fail:', 'The new public relations manager has the difficult task of shoring up the company''s troubled image.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9218, 'short and sweet', 'surprisingly short in a way that is pleasing:', 'This morning''s meeting was short and sweet.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9219, 'short for something', 'as a less long form of a word or name:', 'Their baby’s name is Libby, short for Elizabeth.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9220, 'short of something', 'not having enough of something:', 'I’m a little short of cash right now, so I can’t lend you anything.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9221, 'short of something', 'Short of something also means not including something:', 'There must be some punishment you can give him short of expelling him from school.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9222, 'short sharp shock', '(describing or relating to) punishment that is quick and effective:', 'He''s in favour of the short sharp shock treatment for young offenders.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9223, 'shorthand for something', 'a short, simple phrase that is used instead of a longer and more complicated phrase', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9224, 'shoulder to shoulder', 'If people are shoulder to shoulder, they are close together and next to each other:', 'The refugees were packed shoulder to shoulder on the boat.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9225, 'shout on someone', 'to get someone''s attention by shouting, especially when you want them to come to you or to do something:', 'Dinner''s ready - will you go and shout on her?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9226, 'shout someone down', 'to prevent someone who is speaking at a meeting from being heard, by shouting:', 'She was shouted down when she tried to speak on the issue of abortion.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9227, 'shout/proclaim something from the rooftops', 'to say something publicly:', 'I''m so in love I want to shout your name from the rooftops.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9228, 'shove it', 'a rude expression showing that you are angry about something that you have been offered or asked to do:', 'If they want me to do the same job for less money, they can shove it.', 'idiom', '', 'slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9229, 'shove off!', 'used to tell someone angrily to go away:', 'Just shove off, will you?', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9230, 'shove off', 'to leave land in a boat, usually by pushing against the land with your foot or an oar:', 'She jumped into the dinghy and shoved off.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9231, 'shove someone around', 'to push someone forcefully, in an unpleasant and threatening way:', 'The older boys at school are always shoving him around.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9232, 'shove someone around', 'to tell someone what to do, in a rude or threatening way:', 'Don''t let them shove you around. You''ve got to stand up for your rights.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9233, 'shove something down someone’s throat', 'to force someone to accept something unpleasant:', 'I’m tired of Dave shoving his opinions down our throats.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9234, 'shove/stick something up your ass!', 'a rude phrase used to tell someone angrily that you do not want or need something that they are offering you or telling you to do:', 'If she asks me to work over the weekend, I''ll tell her to shove it up her ass!', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9235, 'shovel something into your mouth', 'to put large quantities of food into your mouth very quickly:', 'He was sitting in front of the TV shovelling down a pizza.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9236, 'show (someone) the way', 'to do something original that others are likely to copy:', 'Sweden has shown the way forward on energy efficiency.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9237, 'show off', 'to behave in a way that is intended to attract attention or admiration, and that other people often find annoying:', 'She only bought that sports car to show off and prove she could afford one.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9238, 'show something/someone off', 'to show something or someone you are proud of to other people, so that they will admire it, him, or her:', 'She likes to wear short skirts to show off her legs.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9239, 'show someone around (something)', 'to go with someone to all parts, or the main parts, of a place that they have not visited before, so that they can see what it is like or learn about it:', 'Let me know when you''re coming to Cambridge and I''ll show you around.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9240, 'show someone in a bad light', 'to make someone seem to be a bad person:', 'He was concerned that the article had shown him in a bad light.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9241, 'show someone in their true colors', 'to show what someone''s real character is, especially when it is unpleasant', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9242, 'show someone in their true colours', 'to show what someone''s real character is, especially when it is unpleasant', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9243, 'show someone out', 'to go to the door of the building with someone who does not live or work there, when they are leaving:', 'If you come this way, I''ll show you out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9244, 'show yourself out', 'to leave a building in which you do not live or work, without anyone going to the door with you:', 'Don''t get up - I''ll show myself out.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9245, 'show someone over something', 'to lead someone around a place that they are visiting in a formal or official way, while telling them about it:', 'After lunch the VIPs will be shown over the new Arts Centre.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9246, 'show someone round (something)', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9247, 'show someone the door', 'to make it obvious that you do not want someone to be present and that they should leave:', 'When I told my bank that I wanted to borrow $100,000 they showed me the door.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9248, 'show up', 'to arrive somewhere in order to join a group of people, especially late or unexpectedly:', 'I invited him for eight o''clock, but he didn''t show up until 9.30.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9249, 'show someone up', 'to behave in a way that makes someone you are with feel ashamed or embarrassed:', 'I wish you wouldn''t show me up in front of my parents by getting so drunk.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9250, 'show your face', 'to appear somewhere when you are not expected to because you have done something bad:', 'How dare you show your face in here after saying all those awful things!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9251, 'show your hand', 'to allow people to know about intentions that you had previously kept secret:', 'Keep the names of the team secret - don''t show your hand until the day of the game.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9252, 'show/teach someone the ropes', 'to show someone how to do a job or activity:', 'Lynn spent an afternoon showing the new girl the ropes.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9253, 'shower someone with something', 'to give someone a lot of presents or praise:', 'She only sees her niece occasionally, so she showers her with presents when she does.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9254, 'shrink from something', 'to avoid doing something that is unpleasant or difficult:', 'We must not shrink from our responsibilities.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9255, 'shrug something off', 'to treat something as if it is not important or not a problem:', 'The stock market shrugged off the economic gloom and rose by 1.5 percent.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9256, 'shrug something off', 'to get rid of something unpleasant that you do not want:', 'I hope I can shrug off this cold before I go on holiday.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9257, 'shuck something off', 'to remove a piece of clothing, especially one that limits you:', 'The lifeguard shucked off his sweatshirt.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9258, 'shuck something off', 'to get rid of something that limits you or causes you problems:', 'They seem to be able to just shuck off guilt.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9259, 'shudder to a halt', 'If a system shudders to a halt, it suddenly stops working:', 'The economy has shuddered to a halt because of the civil war.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9260, 'shuffle off this mortal coil', 'to die:', 'My children can''t wait for me to shuffle off this mortal coil so they can get their hands on their inheritance.', 'idiom', '', 'humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9261, 'shuffle something off', 'to get rid of something unwanted, usually by giving it to someone else:', 'Not until this turbulent region can shuffle off the burdens of the past will it be able to settle peacefully into the community of nations.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9262, 'shut (someone) up', 'to stop talking or making a noise, or to make someone do this:', 'I wish you''d shut up for a moment and listen to what the rest of us have to say.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9263, 'shut (someone) up', 'to stop someone from talking about a particular subject or from complaining or asking for things:', 'The kids kept saying how hungry they were, so their father gave them some biscuits to shut them up.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9264, 'shut someone/something up', 'to keep a person or animal in a closed place:', 'She can''t spend her whole life shut up in her office.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9265, 'shut (something) up', 'to close a shop or other business for a period of time, usually when business is finished for the day:', 'By the time we got there, all the market traders were shutting up.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9266, 'shut (something) down', 'If a business or a large piece of equipment shuts down or someone shuts it down, it stops operating:', 'The company plans to shut down four factories and cut 10,000 jobs.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9267, 'shut (something) off', 'If a machine or system shuts off, or if someone or something shuts it off, it stops operating:', 'The engine shuts off automatically when the desired speed is reached.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9268, 'shut something off', 'to stop the supply of something:', 'Did you remember to shut off the water and gas before you left the house?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9269, 'shut something off', 'to prevent something from being reached or seen:', 'The music room is shut off from the rest of the house by a soundproof wall.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9270, 'shut yourself off', 'to stop speaking to other people or stop being involved with them:', 'When her husband died she seemed to shut herself off from her friends and family.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9271, 'shut someone away', 'to put a person in a place that they are not allowed or able to leave:', 'He was ten years old when he was shut away for stealing an apple.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9272, 'shut something away', 'to put something in a place where other people cannot see it or get it:', 'The diamonds are shut away in a bank vault somewhere.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9273, 'shut yourself away', 'to go into a place that you are unwilling to leave and where you do not want to be interrupted by other people:', 'Andy shuts himself away in his studio for hours on end when he''s recording a song.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9274, 'shut someone/something in (something)', 'to prevent someone or something from leaving a place, usually by closing or fastening a door or gate:', 'The cat was shut in the garage all night.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9275, 'shut something in something', 'to catch part of your body or an object inside a device or container when it closes:', 'Steve was off work for a week after he shut his hand in the car door.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9276, 'shut someone/something out', 'to stop someone or something from entering or getting back inside a house or other building:', 'The wind blew the door closed behind me and now I''m shut out (of the house).
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9277, 'shut someone/something out', 'to not include a person or organization in an activity:', 'Anna felt shut out of the conversation.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9278, 'shut something out', 'to stop yourself thinking about something that upsets you or feeling something that hurts you:', 'She finds it impossible to shut out the memory of the accident.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9279, 'shut something out', 'to prevent a sound or light from being heard or seen:', 'The double glazing shuts out most of the traffic noise.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9280, 'shut someone out', 'to prevent your opponent in a sports competition from scoring any points:', 'She had shut out two of her first four opponents.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9281, 'shut the front door!', 'used to show surprise:', '"She kissed Curtis." "Shut the front door!"', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9282, 'shut up shop', 'to end an activity, usually a business activity, either temporarily or permanently:', 'Many companies are considering shutting up shop in this country and transferring production to low wage economies.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9283, 'shut your eyes to something', 'to ignore something:', 'Until now the prime minister has shut his eyes to the homelessness problem.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9284, 'shut your mouth', '(infml)to stop talking:', 'Just shut your mouth and stop whining!', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9285, 'shut your mouth/face', 'a rude and angry way of telling someone to stop talking:', 'He told me to shut my mouth or there''d be trouble.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9286, 'shut/close the stable/barn door after the horse has bolted', 'to be so late in taking action to prevent something bad happening that the bad event has already happened', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9287, 'shy away from something', 'to avoid something that you dislike, fear, or do not feel confident about:', 'I''ve never shied away from hard work.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9288, 'shy of something', 'to lack something:', 'The bill was four votes shy of a majority.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9289, 'sic sth on sb', 'to order an animal, especially a dog, to attack someone:', 'The police will sic their dogs on you if they have to.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9290, 'sick (and tired) of someone/something', 'to have experienced too much of someone or something with the result that you are annoyed:', 'I’m sick of him whining about money.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9291, 'sick as a dog', 'vomiting a lot:', 'I was sick as a dog after last night''s meal.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9292, 'sick as a parrot', 'very disappointed:', 'He was sick as a parrot when his team lost the match.', 'idiom', '', 'humorous, slang', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9293, 'sick at heart', 'very unhappy:', 'David was sick at heart about having to leave his family behind.', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9294, 'sick something up', 'to vomit something:', 'The baby sicked up some milk on his aunt''s shoulder.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9295, 'sick to your stomach', 'likely to vomit:', 'I''m (feeling) sick to my stomach.', 'idiom', 'C2', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9296, 'sick to your stomach', 'feeling very upset, worried, or angry:', 'It makes me (feel) sick to my stomach when I remember my car accident.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9297, 'side by side', 'next to each other:', 'The children sat side by side .', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9298, 'side with someone', 'to support one person or group in an argument:', 'If ever there was any sort of argument, she''d always side with my father against me.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9299, 'sight unseen', 'without seeing or examining something:', 'I never buy anything sight unseen.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9300, 'sign (something) off', 'to give a final message at the end of a letter or when communicating by radio, or at the end of a television or radio programme:', 'She signed off (her show) by wishing her listeners a Happy New Year.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9301, 'sign off', 'to stop doing your work or a similar activity for a period of time:', 'As it''s Friday, I think I''ll sign off early today.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9302, 'sign off', 'to report to a government employment office that you now have a job and do not need to receive benefit (= money paid by the government)', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9303, 'sign for something', 'to sign a form to show that you have received something:', 'I had to sign for the parcel when I went to get it at the post office.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9304, 'sign for/with someone', '(in sport) to sign a formal agreement saying that you will play for a particular team', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9305, 'sign in', 'to sign your name in a book in order to be allowed to enter a building such as an office or hotel:', 'Students must sign in when they visit other dorms.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9306, 'sign in', 'to enter your personal details into a website, etc. so that you can use it:', 'You will need your username and password to sign in.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9307, 'sign someone in', 'to sign your name in a book next to the name of someone who is visiting you, in order for them to be allowed to enter a building such as an office or hotel:', 'He''s signed you in and is waiting for you inside.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9308, 'sign of the times', 'something that is typical of the (bad) way things are now:', 'These riots are a sign of the times.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9309, 'sign off (on something)', 'to approve something officially:', 'Both sides signed off on a legally binding agreement last month.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9310, 'sign on', 'to sign a form at a government office to say that you do not have a job and that you want to receive benefit (= money paid by the government)', '', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9311, 'sign on', 'to agree to become involved in an organized activity:', '[ + to infinitive ] mainly US I''ve signed on to help at the school fair.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9312, 'sign on', 'to sign a document saying that you will work for someone or do a particular job or activity:', 'She''s signed on with a temp agency.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9313, 'sign on the dotted line', 'to agree to do something, especially by signing an agreement:', 'If you want to join the gym, all you have to do is sign on the dotted line.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9314, 'sign out', 'to sign your name in a book when you leave a building such as an office or factory:', 'Don''t forget to sign out before you leave.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9315, 'sign out', 'to leave a website, etc. so that you have to enter your personal details again the next time you want to use it:', 'If you are using a public computer, sign out of email rather than just clicking out of the screen.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9316, 'sign someone out', 'to sign your name next to the name of someone who is leaving a building such as an office or factory:', 'Someone has to come down and sign you out.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9317, 'sign something out', 'to record when you take something away, usually by signing your name in a book:', 'You have to sign books out when you borrow them from the library.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9318, 'sign something away', 'to give up your rights to something by signing a legal document:', 'Under the treaty, both sides will sign away a third of their nuclear weapons.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9319, 'sign something over', 'to give the legal rights to own or do something to someone else by formally signing a document:', 'Two years before her death she signed her property over to her children.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9320, 'sign something over (to someone)', 'to give up something by signing a formal document that gives it to someone else:', 'He signed the land over to the city before he died.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9321, 'sign up', 'to agree to become involved in an organized activity:', '[ + to infinitive ] I''ve signed up to make the sandwiches for the party.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9322, 'sign with someone', 'to start working for an organization or become a member of a sports team:', 'Some teams have let players sign with other teams because they could not afford to keep them.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9323, 'sign your own death warrant', 'to do something that is harmful to your own position:', 'She signed her own death warrant by refusing to do what the boss demanded.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9324, 'signed and sealed', 'finished and official because all the necessary documents have been signed', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9325, 'silence is golden', 'said to mean it is often better to say nothing', '', 'idiom', '', 'saying', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9326, 'silly billy', 'a silly person, especially a child:', 'You''re being a silly billy, now stop it.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9327, 'silt (something) up', 'to become blocked with silt, or to cause something to become blocked with silt:', 'The harbour silted up many years ago.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9328, 'simmer down', 'to become less angry or excited about something:', 'Come on kids! Simmer down and get on with your work!', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9329, 'since when', 'used angrily in speech to ask someone why they believe a situation to be different from how it really is:', 'Since when do you have the right to tell me what to do?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9330, 'sinews of war', 'the money needed for weapons and supplies during a war', '', 'idiom', '', 'literary', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9331, 'sing along', 'to sing a piece of music while someone else is singing or playing it:', 'The radio station played a Billy Joel song, and I found myself singing along to it.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9332, 'sing for your supper', 'to do something for someone else in order to receive something in return, especially food:', 'Dan''s upstairs fixing my computer - I''m making him sing for his supper.', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9333, 'sing like a canary', 'to give someone, usually the authorities, a lot of secret information, especially about illegal activities:', 'He plays a mafia boss who''s about to sing like a canary and enter the witness relocation program.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9334, 'sing someone’s/something''s praises', 'to praise someone or something with enthusiasm:', 'The review in the paper sings the movie''s praises.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9335, 'sing the praises of someone/something', 'to praise someone or something:', 'The newspapers have been singing the praises of Italy''s new star player.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9336, 'single someone/something out', 'to choose one person or thing from a group for special attention, especially criticism or praise:', 'It''s not fair the way my sister is always singled out for special treatment.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9337, 'sink back', 'to move into a relaxed, comfortable position:', 'He sank back in his chair and closed his eyes.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9338, 'sink in', 'If an unpleasant or surprising fact or idea sinks in, you gradually start to believe it, understand it, or realize the effect it will have on you:', 'How many times do I have to tell you something before it sinks in?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9339, 'sink in/sink into something', 'If a liquid or soft substance sinks into something solid, it gradually passes into it through its surface:', 'You''d better wipe up that coffee you spilled on the carpet before it sinks in.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9340, 'sink into something', 'to slowly move your body into a sitting or lying position, in a relaxed or tired way:', 'I was so tired when I got home that all I wanted to do was sink into bed/an armchair/a hot bath.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9341, 'sink something into something', 'to spend a large amount of money on a business or other piece of work:', 'We sank all our money into my brother''s business.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9342, 'sink like a stone', 'to attract no support, attention, or interest:', 'My suggestion that we all play tennis sank like a stone.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9343, 'sink or swim', 'If you are left to sink or swim, you are given no help so that you succeed or fail completely by your own efforts:', 'My employer gave me no help when I started my new job - I was just left to sink or swim.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9344, 'sink to a whisper', 'to become very quiet:', 'The child''s voice sank to a whisper as she admitted that she had broken the window.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9345, 'sink to such a level/such depths', 'to do something so bad:', 'I can''t believe you would sink so low as to snitch on your best friends.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9346, 'sink without (a) trace', 'to be forgotten about completely, or to not attract any attention or interest:', 'Since his last book five years ago, he seems to have sunk without trace.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9347, 'sink your differences', 'to forget your disagreements:', 'Paul and Mark agreed to sink their differences and be friends.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9348, 'sink your teeth into something', 'to become completely involved in something:', 'It was a story you could really sink your teeth into.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9349, 'sinking fast', '(of a person''s health) getting much worse quickly so that death is likely:', 'Mrs Jones is sinking fast, and the doctor doesn''t think she''ll live much longer.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9350, 'sinking feeling', 'a feeling that something bad is going to happen:', 'I had a sinking feeling when I picked up the bill.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9351, 'sinking ship', 'a company or other organization that is failing:', 'He''d seen the accounts, realized he was on a sinking ship, and decided to get off.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9352, 'siphon something off', 'to dishonestly take money from an organization or other supply, and use it for a purpose for which it was not intended:', 'He lost his job when it was discovered that he had been siphoning off money from the company for his own use.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9353, 'sister from another mister', 'a female friend that you know very well and have a very good relationship with:', 'I call her “my sister from another mister” because I''ve never had a sister and Emma is like one to me.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9354, 'sister under the skin', 'a man who supports women''s action to improve their rights:', 'John is a true sister under the skin.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9355, 'sit (around) on your backside', 'to do nothing:', 'I do all the work, while all you do is sit around on your backside all day.', 'idiom', '', 'slang, disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9356, 'sit (someone) up', 'to move into a sitting position after you have been lying down, or to help someone else to do this:', 'Let me sit you up in the bed so you''ll be more comfortable.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9357, 'sit up', 'to sit with a straight back:', 'How many times do I have to tell you to sit up straight?', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9358, 'sit up', 'to stay awake and not go to bed although it is late:', '[ + -ing verb ] The book was so interesting that I sat up all night reading it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9359, 'sit up', 'to show interest or surprise:', 'The news that he was getting married really made her sit up.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9360, 'sit around', 'to spend time sitting down and doing very little:', 'We sat around most of the evening, waiting for Jake and drinking beer.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9361, 'sit at the feet of someone', 'to be a very admiring student of someone important', '', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9362, 'sit back', 'to sit comfortably with your back against the back of a chair', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9363, 'sit back', 'to wait for something to happen without making any effort to do anything yourself:', 'You can''t just sit back and wait for job offers to come to you.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9364, 'sit by', 'to fail to take action to stop something wrong from happening:', 'I can''t just sit by and watch you waste all our money.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9365, 'sit down', 'to move your body so that the lower part of it is resting on a seat or on the ground:', 'I sat down on the sofa next to Barbara.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9366, 'sit down and do something', 'to spend time discussing a problem in order to solve it or make a decision:', 'I think we should sit down and talk about this.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9367, 'sit in', 'to go as a group into a public building and refuse to leave or to allow normal activities to continue there until a situation that you are complaining about is changed', '', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9368, 'sit in', 'to be present in a meeting or class, watching it but not taking part in it:', 'There will be a school inspector sitting in on your class this morning.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9369, 'sit in for someone', 'to take the place of someone who would normally do a particular job or go to a particular meeting:', 'Mr Baker is ill today, so Miss Dixon is sitting in for him (as your teacher).', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9370, 'sit in judgment on/over someone', 'to make a judgment on someone especially when you have no right to do so:', 'I don''t know why he thinks he can sit in judgment over us like that.', 'idiom', '', 'disapproving', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9371, 'sit on someone''s stomach', 'Food that sits on your stomach makes you feel uncomfortably full.', '', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9372, 'sit on something', 'to delay taking action about something:', 'The company has been sitting on my letter for weeks without dealing with my complaint.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9373, 'sit on something', 'to prevent people from knowing a piece of information:', 'The city council will presumably sit on the report until after the election.', 'phrasal verb', '', 'disapproving', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9374, 'sit on someone', 'to force someone to be silent or not to do something:', 'The boss is going to sit on him to make sure he says nothing.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9375, 'sit on the fence', 'to delay making a decision:', 'You can''t sit on the fence any longer - you have to decide whose side you''re on.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9376, 'sit on your arse', 'to do nothing, especially when you should be doing something:', 'She just sits on her arse all day, while I do all the work.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9377, 'sit on your ass', 'to do nothing, especially when you should be doing something:', 'She just sits on her ass all day, while I do all the work.', 'idiom', '', 'offensive', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9378, 'sit on your hands', 'to do nothing about a problem or a situation that needs dealing with:', 'Every day the crisis worsens and yet the government seems content to sit on its hands.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9379, 'sit right/well (with someone)', 'to be something that you agree or are pleased with:', 'Their decision/answer didn''t sit well with the Board of Directors.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9380, 'sit round', '→ 
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9381, 'sit something out', 'to not take part in a physical activity such as a dance or a game, because you are tired or injured:', 'I''m feeling rather tired, so I think I''ll sit out the next dance.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9382, 'sit something out', 'to wait for an unpleasant situation or event to finish, without leaving or taking some other action:', 'The company''s management is prepared to sit out the strike rather than agree to union demands.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9383, 'sit through something', 'to stay until the end of an event such as a meeting or performance that is very long or boring:', 'We had to sit through two hours of speeches.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9384, 'sit tight', 'to stay where you are:', 'You''d better sit tight and I''ll call the doctor.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9385, 'sit tight', 'to refuse to change your mind:', 'My parents tried to persuade me not to go alone, but I sat tight.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9386, 'sit under someone', 'to receive teaching from someone:', 'He sat under the most influential teacher in his field.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9387, 'sit up and take notice', 'to show interest or surprise:', 'She sat up and took notice when she heard he was getting married.', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9388, 'sit with someone', 'to be considered by someone:', 'When someone calls you "a woman of letters," how does that sit with you?
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9389, 'sitting pretty', 'in a good situation:', 'Our apartment isn’t expensive, so we’re sitting pretty.', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9390, 'six of one and half a dozen of the other', 'said when you think that neither of two choices is better than the other:', '"Shall we give her chocolates or flowers?" "I don''t know, it''s six of one and half a dozen of the other."', 'idiom', '', 'informal', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9391, 'six of the best', 'a beating, usually of six hits with a stick', '', 'idiom', '', 'old-fashioned', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9392, 'size something/someone up', 'to examine something or someone carefully and decide what you think about it, him, or her:', 'Voters are still sizing up the candidates.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9393, 'skate over/around something', 'to avoid dealing completely with something or to fail to pay enough attention to it:', 'Providing homeless people with somewhere to stay when the weather is cold only skates around the problem, it doesn''t solve it.
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
