INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9396, 'sketch something in', 'to give more details about something:', 'He sketched in a few more facts about the case.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9397, 'sketch something out', 'to give a short description of something, containing few details:', 'She sketched out the plan in a few brief sentences.', 'phrasal verb', 'C2', '', 'unknown', 3);
