INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9399, 'skim someone/something off', 'to secretly take money that is in your care or that belongs to an organization or business you work for :', 'He got caught skimming off funds from the charity.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9400, 'skin and bones', 'extremely thin:', 'Your brother is just skin and bones - has he been sick?', 'idiom', '', '', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9401, 'skin someone alive', 'to punish or tell someone off severely:', 'My mother will skin me alive for being so late home.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9402, 'skin to skin', 'with people''s bodies or parts of bodies touching directly, without clothing between them:', 'Healthy full-term babies carried skin to skin by their moms reap the same benefits as premature babies.
