INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9406, 'slack off', 'to work less hard or to be less than is usual or necessary:', 'Workers tend to slack off on Mondays and Fridays.', 'phrasal verb', '', '', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9407, 'slag someone off', 'to criticize someone:', 'I hate the way Dan is always slagging people off behind their backs.', 'phrasal verb', '', 'informal', 'unknown', 3);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9408, 'slap and tickle', 'sexual activity, especially when it involves playing or joking:', 'I think there''s a bit of slap and tickle going on in the back of that car over there.', 'idiom', '', 'informal, humorous', 'unknown', 2);
INSERT INTO dbo.Lexicon (LexiconId, Word, Definition, Example, PartOfSpeech, Level, Registers, Difficulty, TypeId) VALUES
  (9409, 'slap someone around', 'to hit someone repeatedly or often:', 'Her husband has been slapping her around, but she''s afraid to go to the police.', 'phrasal verb', '', 'informal', 'unknown', 3);
